/**
 * Static formatting, image manipulation, clog tier, and account helpers.
 */
final class ClogHelper
{
	static final String[] CLOG_TIERS = {
		"bronze", "iron", "steel", "black", "mithril", "adamant", "rune", "dragon", "gilded"
	};

	static final String[] CLOG_GROUP_NAMES = {"Bosses", "Raids", "Clues", "Minigames", "Other"};

	static final int[] CLOG_TIER_THRESHOLDS = {100, 300, 500, 700, 900, 1000, 1100, 1200};

	private ClogHelper()
	{
	}

	// Not-synced popup config shared by every clog cell system.

	/**
	 * Configure an ImgTooltip for a player who has not synced any collection log.
	 * Keeps native hiscore rows when the player has any signal (kc or rank);
	 * otherwise shows the muted "Obtained: --/Y" preview. Every category item
	 * draws dimmed either way so wiki links remain explorable.
	 */
	static boolean configureNotSynced(ImgTooltip tip, TooltipData data, ItemManager itemManager,
		boolean showKc)
	{
		if (data == null || data.allItemIds == null || data.allItemIds.isEmpty())
		{
			return false;
		}
		tip.setTitle(data.name);
		// A raid's hard mode is the player's signal too: a raider of Expert alone keeps that line and rank.
		if (data.statValue >= 0 || data.rank > 0 || data.hardKc >= 0 || data.hardRank > 0)
		{
			if (data.statLabel != null && showKc)
			{
				tip.setInfoLine(data.statLabel, countText(data.statValue), NativeTooltip.valueColor);
			}
			addHardModeLine(tip, data, showKc, false);
		}
		else
		{
			// No player signal behind this grid: preview the shape and count
			// the slots instead of painting dashes for stats nobody has.
			tip.setObtainedPlaceholder(data.allItemIds.size());
		}
		tip.setItems(data.totalItems, data.allItemIds, Collections.emptySet(),
			Collections.emptyMap(), data.itemNames, itemManager);
		return true;
	}

	/** A raid's hard mode on the line under the raid's own KC and PB, by the name the Combat Summary pairs it by. */
	static void addHardModeLine(TitleTooltip tip, TooltipData data, boolean showKc, boolean showPb)
	{
		if (data.hardLabel == null)
		{
			return;
		}
		if (data.hardKc >= 0 && showKc)
		{
			tip.addInfoLine(data.hardLabel + ": ", formatKc(data.hardKc), NativeTooltip.valueColor);
			if (data.hardPb != null && showPb)
			{
				tip.setInfoLinePair(pbLabel(data.hardPb), pbTime(data.hardPb), NativeTooltip.valueColor);
			}
		}
		else if (data.hardPb != null && showPb)
		{
			tip.addInfoLine(data.hardLabel + " " + pbLabel(data.hardPb), pbTime(data.hardPb), NativeTooltip.valueColor);
		}
	}

	/** "PB: ", or a team size's "PB (5 players): " ({@link PersonalBests#labeled}). */
	static String pbLabel(String pb)
	{
		return pb.startsWith("(") ? "PB " + pb.substring(0, pb.indexOf(')') + 1) + ": " : "PB: ";
	}

	static String pbTime(String pb)
	{
		return pb.substring(pb.indexOf(')') + 1).trim();
	}

	// Clog data helpers.

	/** Missing entries on a loaded leaderboard are unranked, not failed lookups. */
	static void configureRank(TitleTooltip tip, TooltipData data, HiscoreResult result, boolean showRank)
	{
		if (showRank && result != null && result.isRankDataAvailable()
			&& data != null && data.rankTracked
			&& (data.obtainedCount >= 0 || data.statValue >= 0 || data.rank > 0 || data.hardKc >= 0 || data.hardRank > 0))
		{
			tip.setRank(data.rank);
			if (data.hardLabel != null)
			{
				tip.setRankPair(data.hardLabel + ": ", data.hardRank);
			}
		}
	}

	static Set<Integer> getObtainedIds(String category, ClogResult clogResult)
	{
		if (clogResult == null) return new HashSet<>();
		Set<Integer> ids = new HashSet<>();
		List<ClogResult.ClogItem> obtained = clogResult.getObtainedItems().get(category);
		if (obtained != null)
		{
			for (ClogResult.ClogItem item : obtained) ids.add(item.getId());
		}
		return ids;
	}

	static int countObtained(List<Integer> allItems, Set<Integer> obtainedIds)
	{
		int count = 0;
		for (int id : allItems) if (obtainedIds.contains(id)) count++;
		return count;
	}

	/**
	 * Obtained trophy items from anywhere in the log, in the order the ids
	 * are listed. Items the player does not own are left out entirely.
	 */
	static List<ClogResult.ClogItem> obtainedSpecialItems(int[] specialIds, ClogResult clogResult)
	{
		List<ClogResult.ClogItem> found = new ArrayList<>();
		if (clogResult == null)
		{
			return found;
		}
		for (int specialId : specialIds)
		{
			for (List<ClogResult.ClogItem> items : clogResult.getObtainedItems().values())
			{
				ClogResult.ClogItem match = null;
				for (ClogResult.ClogItem item : items)
				{
					if (item.getId() == specialId)
					{
						match = item;
						break;
					}
				}
				if (match != null)
				{
					found.add(match);
					break;
				}
			}
		}
		return found;
	}

	// The Rare shelf's row, as killclog.com's profile card lays it: more rares wrap to the next.
	static final int RARES_PER_ROW = 6;

	/**
	 * The Collection Log card's Rare shelf, filled as killclog.com's profile card fills it: every trophy, then every
	 * 3rd age piece in the game's order, then every megarare (2.7.2: six at most hid most of a big 3rd age log).
	 */
	static List<ClogResult.ClogItem> rareItems(ClogResult clog)
	{
		List<ClogResult.ClogItem> rares = new ArrayList<>();
		Set<Integer> seen = new HashSet<>();
		for (int[] ids : new int[][]{PanelData.SPECIAL_ITEM_IDS, PanelData.THIRD_AGE_ITEMS, PanelData.MEGARARE_ITEM_IDS})
		{
			for (ClogResult.ClogItem item : obtainedSpecialItems(ids, clog))
			{
				if (seen.add(item.getId()))
				{
					rares.add(item);
				}
			}
		}
		return rares;
	}

	static int[] clogCounts(String category, ClogResult clogResult)
	{
		if (clogResult == null) return null;
		List<Integer> items = clogResult.getCategoryItems().get(category);
		if (items == null || items.isEmpty()) return null;
		Set<Integer> obtained = getObtainedIds(category, clogResult);
		return new int[]{countObtained(items, obtained), items.size()};
	}

	/** A hiscore total does not imply knowledge of the player's individual items. */
	static int[] summaryTotals(ClogResult clog, HiscoreResult hiscore, ClogResult catalog)
	{
		if (clog != null) return sumClogTotals(clog);
		int count = hiscore != null ? hiscore.getActivityScore(HiscoreSkill.COLLECTIONS_LOGGED.getName()) : -1;
		int total = catalog != null ? sumClogTotals(catalog)[1] : -1;
		return new int[]{count, total > 0 ? total : -1};
	}

	static int[] sumClogTotals(ClogResult result)
	{
		return sumClogTotals(result, IntUnaryOperator.identity());
	}

	static int[] sumClogTotals(ClogResult result, IntUnaryOperator canonicalizer)
	{
		Set<Integer> allItems = new HashSet<>();
		Set<Integer> allObtained = new HashSet<>();
		for (Map.Entry<String, List<Integer>> entry : result.getCategoryItems().entrySet())
		{
			for (int itemId : entry.getValue())
			{
				allItems.add(canonicalizer.applyAsInt(itemId));
			}
			List<ClogResult.ClogItem> obtained = result.getObtainedItems().get(entry.getKey());
			if (obtained != null)
			{
				for (ClogResult.ClogItem item : obtained)
				{
					allObtained.add(canonicalizer.applyAsInt(item.getId()));
				}
			}
		}
		int obtained = result.getUniqueObtained() > 0
			? result.getUniqueObtained() : allObtained.size();
		int total = result.getUniqueTotal() > 0
			? result.getUniqueTotal() : allItems.size();
		return new int[]{obtained, total};
	}

	// Clog tier logic.

	static Color clogColor(int obtained, int total, KillClogConfig config)
	{
		if (obtained == total) return config.completedClogColor();
		if (obtained == total - 1 && total > 1) return config.missing1Color();
		if (obtained == 0) return config.emptyClogColor();
		return config.inProgressClogColor();
	}

	/** Where a tier starts. Gilded, the last, floats at 90% of the log in steps of 25. */
	static int tierThreshold(int tier, int totalSlots)
	{
		return tier < CLOG_TIER_THRESHOLDS.length
			? CLOG_TIER_THRESHOLDS[tier] : (int) (totalSlots * 0.9) / 25 * 25;
	}

	/** The tier a count has reached, as an index into CLOG_TIERS; -1 below bronze. */
	static int tierIndex(int obtained, int totalSlots)
	{
		for (int i = CLOG_TIERS.length - 1; i >= 0; i--)
		{
			if (obtained >= tierThreshold(i, totalSlots)) return i;
		}
		return -1;
	}

	static String getClogTierName(int obtained, int totalSlots)
	{
		int tier = tierIndex(obtained, totalSlots);
		return tier >= 0 ? CLOG_TIERS[tier] : null;
	}

	/**
	 * Every tier's readout, e.g. "Rune: 1,100-1,199"; gilded is open-ended.
	 * A tier still ahead of the player also says how far off it is.
	 */
	static String[] tierLabels(int obtained, int totalSlots)
	{
		String[] labels = new String[CLOG_TIERS.length];
		int tier = tierIndex(obtained, totalSlots);
		for (int i = 0; i < labels.length; i++)
		{
			int start = tierThreshold(i, totalSlots);
			labels[i] = StringUtils.capitalize(CLOG_TIERS[i]) + ": "
				+ QuantityFormatter.formatNumber(start)
				+ (i == labels.length - 1 ? "+"
				: "-" + QuantityFormatter.formatNumber(tierThreshold(i + 1, totalSlots) - 1))
				+ (i > tier
				? " (" + QuantityFormatter.formatNumber(start - obtained) + " more)" : "");
		}
		return labels;
	}

	// Account helpers. GIM badge state lives in GimBadgeLoader.

	/** A solo Ironman's badge, its board's icon; none otherwise (GIM badges come from game modicons through AccountBadgeResolver). */
	static String accountBadgeResource(AccountType type)
	{
		RankLeaderboard board = RankLeaderboard.of(type);
		return board != RankLeaderboard.NORMAL ? board.icon : null;
	}

	static String accountLabel(AccountType type)
	{
		return type != null && type != AccountType.REGULAR ? type.displayName() : null;
	}

	// Swing text treatment.

	/**
	 * The panel-wide ClearType fix: text antialiasing on any Swing text
	 * component that sets a foreground. The one implementation of the
	 * convention every panel label follows.
	 */
	static void antialias(JComponent component)
	{
		component.putClientProperty(
			java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
			java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
	}

	// Formatting.

	static String pad(String text)
	{
		return StringUtils.leftPad(text, 4);
	}

	static String formatKc(int kc)
	{
		if (kc >= 1_000_000) return kc / 1_000_000 + "m";
		if (kc >= 10_000) return kc / 1_000 + "k";
		return String.valueOf(kc);
	}

	/** A count as every cell and card shows one: shortened past 10k, or "--" when there is none. */
	static String countText(int count)
	{
		return count > 0 ? formatKc(count) : "--";
	}

	// Image utilities.

	static BufferedImage iconToImage(ImageIcon icon)
	{
		if (icon == null) return null;
		BufferedImage img = new BufferedImage(
			icon.getIconWidth(), icon.getIconHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		icon.paintIcon(null, g, 0, 0);
		g.dispose();
		return img;
	}

	static BufferedImage createDimmedImage(ImageIcon icon)
	{
		BufferedImage original = iconToImage(icon);
		BufferedImage dimmed = new BufferedImage(
			original.getWidth(), original.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g2 = dimmed.createGraphics();
		g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.3f));
		g2.drawImage(original, 0, 0, null);
		g2.dispose();
		return dimmed;
	}

	/** Paints a 12x10 hamburger icon. */
	/** Paints a 15x15 split-color magnifying glass. */
	static BufferedImage makeCompareIcon(Color left, Color right, float brightness)
	{
		BufferedImage img = new BufferedImage(15, 15, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = lens(img);
		// Lens circle: center (7,5), radius 4
		int cx = 7, cy = 5, r = 4;
		// Left half: blue.
		g.setClip(0, 0, cx, 15);
		g.setColor(brighten(left, brightness));
		g.drawOval(cx - r, cy - r, r * 2, r * 2);
		// Blue handle.
		g.drawLine(cx - 3, cy + 3, cx - 6, cy + 6);
		// Right half: red.
		g.setClip(cx, 0, 15, 15);
		g.setColor(brighten(right, brightness));
		g.drawOval(cx - r, cy - r, r * 2, r * 2);
		// Red handle.
		g.drawLine(cx + 3, cy + 3, cx + 6, cy + 6);
		g.setClip(null);
		g.dispose();
		return img;
	}

	/** Paints a 15x15 single-color magnifying glass for compact icon buttons. */
	static BufferedImage makeSearchIcon(Color color, float brightness)
	{
		BufferedImage img = new BufferedImage(15, 15, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = lens(img);
		g.setColor(brighten(color, brightness));
		int cx = 7, cy = 5, r = 4;
		g.drawOval(cx - r, cy - r, r * 2, r * 2);
		g.drawLine(cx + 3, cy + 3, cx + 6, cy + 6);
		g.dispose();
		return img;
	}

	/** A magnifying glass's canvas: antialiased, with its 1.5 px stroke. */
	private static Graphics2D lens(BufferedImage img)
	{
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new java.awt.BasicStroke(1.5f));
		return g;
	}

	private static Color brighten(Color c, float factor)
	{
		int r = Math.min(255, (int) (c.getRed() * factor));
		int g = Math.min(255, (int) (c.getGreen() * factor));
		int b = Math.min(255, (int) (c.getBlue() * factor));
		return new Color(r, g, b, c.getAlpha());
	}

	static void styleSearchBar(Container container)
	{
		for (Component c : container.getComponents())
		{
			if (c instanceof JButton)
			{
				JButton btn = (JButton) c;
				btn.setOpaque(false);
				btn.setContentAreaFilled(false);
				btn.setBorderPainted(false);
			}
			else if (c instanceof Container)
			{
				styleSearchBar((Container) c);
			}
		}
	}

	/**
	 * True when RuneLite's core Virtual Levels plugin is switched on.
	 */
	private static boolean virtualLevelsPluginEnabled(ConfigManager configManager)
	{
		return Boolean.parseBoolean(
			configManager.getConfiguration("runelite", "virtuallevelsplugin"));
	}

	/**
	 * The level a skill summary cell shows: the hiscore level normally, the
	 * xp-derived virtual level (cap 126) when Kill Clog's setting is on.
	 * Unranked skills (no xp) keep the hiscore value either way.
	 */
	static int displayLevel(int hiscoreLevel, long xp, boolean virtualLevels)
	{
		if (!virtualLevels || xp <= 0)
		{
			return hiscoreLevel;
		}
		return Experience.getLevelForXp((int) xp);
	}

	/**
	 * True when the Virtual Levels plugin is on AND its "virtual total level"
	 * sub-setting is too (their default: on). Mirrors the vanilla skill tab's
	 * total exactly.
	 */
	static boolean virtualTotalLevelEnabled(ConfigManager configManager)
	{
		if (!virtualLevelsPluginEnabled(configManager))
		{
			return false;
		}
		String v = configManager.getConfiguration("virtuallevels", "virtualTotalLevel");
		return v == null || Boolean.parseBoolean(v);
	}

	/**
	 * Total level for display: the hiscore total normally, the sum of
	 * xp-derived virtual levels when the vanilla virtual-total setting is on.
	 * Skills the hiscores hide (unranked) contribute their hiscore value via
	 * the max guard, so a partially-ranked account never shows a virtual
	 * total below its real one. Never used for maxed detection - identity
	 * logic stays on real levels.
	 */
	static int displayTotalLevel(HiscoreResult result, boolean virtualTotal)
	{
		int real = result.getTotalLevel();
		if (!virtualTotal)
		{
			return real;
		}
		int total = 0;
		for (Skill skill : Skill.values())
		{
			String key = skill.getName().toLowerCase();
			int level = result.getSkillLevel(key);
			if (level <= 0)
			{
				continue;
			}
			total += displayLevel(level, result.getSkillXp(key), true);
		}
		return Math.max(total, real);
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.client.game.ItemManager;

/**
 * The collection log catalog parsed from the running game build's own enums.
 *
 * <p>Parsed on the client thread; published whole as an immutable-by-convention
 * snapshot through a volatile field, the same contract as {@link CaCatalog}.
 * Consumers on other threads (chat command executor, EDT) read one complete
 * parse or none; the maps are never mutated after publication.
 */
@Slf4j
final class ClogIndex
{
	static final int ENUM_CLOG_TABS = 2102;
	private static final int ENUM_CLOG_DUPE_REMAP = 3721;
	private static final int PARAM_TAB_NAME = 682;
	private static final int PARAM_SUBTAB_ENUM = 683;
	private static final int PARAM_CATEGORY_NAME = 689;
	private static final int PARAM_CATEGORY_ITEMS = 690;
	private static final Map<Integer, Integer> FALLBACK_ITEM_REMAPS = fallbackItemRemaps();
	private static final ClogItemCanonicalizer FALLBACK_CANONICALIZER =
		new ClogItemCanonicalizer(Collections.emptyMap(), FALLBACK_ITEM_REMAPS);

	/** One parse product; replaced whole, never mutated. */
	private static final class Snapshot
	{
		final Map<String, List<Integer>> categoryItems;
		final Map<String, List<String>> tabCategoryKeys;
		final Map<Integer, List<String>> itemCategoryKeys;
		final Map<String, List<Integer>> itemNameIds;
		final Map<Integer, String> itemNames;
		final Map<String, String> categoryNames;
		final ClogItemCanonicalizer canonicalizer;

		Snapshot(Map<String, List<Integer>> categoryItems,
			Map<String, List<String>> tabCategoryKeys,
			Map<Integer, List<String>> itemCategoryKeys,
			Map<String, List<Integer>> itemNameIds,
			Map<Integer, String> itemNames,
			Map<String, String> categoryNames,
			ClogItemCanonicalizer canonicalizer)
		{
			this.categoryItems = categoryItems;
			this.categoryNames = categoryNames;
			this.tabCategoryKeys = tabCategoryKeys;
			this.itemCategoryKeys = itemCategoryKeys;
			this.itemNameIds = itemNameIds;
			this.itemNames = itemNames;
			this.canonicalizer = canonicalizer;
		}
	}

	private volatile Snapshot snapshot;
	// A failed read is tried again on the next login or logout; it warns once until a read succeeds.
	private boolean warned;

	boolean ensureParsed(Client client, ItemManager itemManager)
	{
		if (snapshot != null)
		{
			return true;
		}

		try
		{
			Map<String, List<Integer>> nextCategoryItems = new HashMap<>();
			Map<String, List<String>> nextTabCategoryKeys = new LinkedHashMap<>();
			Map<Integer, List<String>> nextItemCategoryKeys = new HashMap<>();
			Map<String, List<Integer>> nextItemNameIds = new HashMap<>();
			Map<Integer, String> nextItemNames = new HashMap<>();
			Map<String, String> nextCategoryNames = new HashMap<>();
			Map<Integer, Integer> nextCanonicalItemIds = readCanonicalItemIds(client);

			EnumComposition tabs = client.getEnum(ENUM_CLOG_TABS);
			int tabPosition = 0;
			for (int tabKey : tabs.getKeys())
			{
				int tabStructId = tabs.getIntValue(tabKey);
				StructComposition tabStruct = client.getStructComposition(tabStructId);
				String tabName = resolveTabName(
					tabStruct.getStringValue(PARAM_TAB_NAME), tabPosition++);
				int subtabEnumId = tabStruct.getIntValue(PARAM_SUBTAB_ENUM);

				EnumComposition subtabs = client.getEnum(subtabEnumId);
				for (int subKey : subtabs.getKeys())
				{
					int catStructId = subtabs.getIntValue(subKey);
					StructComposition catStruct = client.getStructComposition(catStructId);

					String name = catStruct.getStringValue(PARAM_CATEGORY_NAME);
					int itemsEnumId = catStruct.getIntValue(PARAM_CATEGORY_ITEMS);
					if (name == null || itemsEnumId <= 0)
					{
						// A page read half-way fails the whole read: a smaller log is never shown or shared.
						throw new IllegalStateException("Unreadable Collection Log page " + catStructId);
					}

					String categoryKey = ClogService.bossToCategory(name);
					nextCategoryNames.put(categoryKey, name);
					if (tabName != null)
					{
						nextTabCategoryKeys.computeIfAbsent(tabName, k -> new ArrayList<>())
							.add(categoryKey);
					}
					EnumComposition itemsEnum = client.getEnum(itemsEnumId);
					LinkedHashSet<Integer> itemIds = new LinkedHashSet<>();
					for (int itemKey : itemsEnum.getKeys())
					{
						int rawItemId = itemsEnum.getIntValue(itemKey);
						int itemId = canonicalItemId(rawItemId, nextCanonicalItemIds);
						itemIds.add(itemId);
						List<String> itemCategories = nextItemCategoryKeys.computeIfAbsent(
							itemId, k -> new ArrayList<>());
						if (!itemCategories.contains(categoryKey))
						{
							itemCategories.add(categoryKey);
						}
						indexItemName(nextItemNameIds, nextItemNames, itemManager,
							rawItemId, itemId);
					}
					nextCategoryItems.put(categoryKey, new ArrayList<>(itemIds));
				}
			}

			injectSynthetic(nextCategoryItems, nextItemCategoryKeys, nextItemNameIds, nextItemNames,
				itemManager, "mimic", new int[]{PanelData.THIRD_AGE_RING_ITEM_ID});
			injectSynthetic(nextCategoryItems, nextItemCategoryKeys, nextItemNameIds, nextItemNames,
				itemManager, PanelData.CLOG_THIRD_AGE, PanelData.THIRD_AGE_ITEMS);
			injectSynthetic(nextCategoryItems, nextItemCategoryKeys, nextItemNameIds, nextItemNames,
				itemManager, PanelData.CLOG_GILDED, PanelData.GILDED_ITEMS);

			ClogItemCanonicalizer canonicalizer = new ClogItemCanonicalizer(
				nextCategoryItems, nextCanonicalItemIds);
			Snapshot parsed = new Snapshot(nextCategoryItems, nextTabCategoryKeys,
				nextItemCategoryKeys,
				nextItemNameIds, nextItemNames, nextCategoryNames, canonicalizer);
			snapshot = parsed;
			warned = false;
			log.debug("Parsed clog enums: {} tabs, {} categories, {} items, {} names, "
				+ "{} remaps, {} variants",
				parsed.tabCategoryKeys.size(), parsed.categoryItems.size(),
				parsed.itemCategoryKeys.size(), parsed.itemNameIds.size(),
				canonicalizer.declaredAliasCount(), canonicalizer.catalogVariantCount());
			return true;
		}
		catch (Exception e)
		{
			if (!warned)
			{
				log.warn("Failed to parse clog enums", e);
			}
			warned = true;
			snapshot = null;
			return false;
		}
	}

	void clear()
	{
		snapshot = null;
	}

	/** A log laid on the game's own pages, whichever source sent it; as sent before the client has read the log. */
	@Nullable
	ClogResult laid(@Nullable ClogResult clog)
	{
		return clog != null && isParsed() ? clog.onPages(categoryItems(), this::canonicalItemId) : clog;
	}

	boolean isParsed()
	{
		return snapshot != null;
	}

	List<Integer> itemIdsForName(String itemKey)
	{
		Snapshot s = snapshot;
		return s != null ? s.itemNameIds.get(itemKey) : null;
	}

	List<String> categoryKeysForItem(int itemId)
	{
		Snapshot s = snapshot;
		return s != null ? s.itemCategoryKeys.get(canonicalItemId(itemId)) : null;
	}

	int canonicalItemId(int itemId)
	{
		Snapshot s = snapshot;
		return s != null
			? s.canonicalizer.canonicalItemId(itemId) : fallbackCanonicalItemId(itemId);
	}

	List<ClogResult.ClogItem> canonicalizeItems(List<ClogResult.ClogItem> items)
	{
		Snapshot s = snapshot;
		return s != null ? s.canonicalizer.canonicalizeItems(items)
			: FALLBACK_CANONICALIZER.canonicalizeItems(items);
	}

	static int fallbackCanonicalItemId(int itemId)
	{
		return canonicalItemId(itemId, FALLBACK_ITEM_REMAPS);
	}

	@Nullable
	/** Every log item's name, from the game cache; empty until the log's catalog is parsed. Read-only. */
	Map<Integer, String> itemNames()
	{
		Snapshot s = snapshot;
		return s != null ? Collections.unmodifiableMap(s.itemNames) : Collections.emptyMap();
	}

	String itemName(ClogResult result, int itemId)
	{
		String direct = result.getItemName(itemId);
		if (direct != null)
		{
			return direct;
		}
		Snapshot s = snapshot;
		if (s != null)
		{
			return s.itemNames.get(itemId);
		}
		return null;
	}

	Set<String> categoryKeys()
	{
		Snapshot s = snapshot;
		return s != null ? s.categoryItems.keySet() : Collections.emptySet();
	}

	Map<String, List<Integer>> categoryItems()
	{
		Snapshot s = snapshot;
		return s != null ? s.categoryItems : Collections.emptyMap();
	}

	/** The game's tabs in order, each with its pages' keys in order; empty when unparsed. */
	Map<String, List<String>> tabPages()
	{
		Snapshot s = snapshot;
		return s != null ? Collections.unmodifiableMap(s.tabCategoryKeys) : Collections.emptyMap();
	}

	/** A page's name as the game shows it, or null. */
	@Nullable
	String pageName(String key)
	{
		Snapshot s = snapshot;
		return s != null ? s.categoryNames.get(key) : null;
	}

	/**
	 * A player's progress per collection-log tab, in game order. Slots come from
	 * the game's own catalog, so every provider is measured against the same log,
	 * and an item counts once per tab however many pages list it. The rows sit
	 * under the log's total and must agree with it: a partial sync itemizes a
	 * handful of items under the account's full count, and a log without a
	 * denominator has nothing to measure against, so neither gets counts: their
	 * rows stay to browse, each at -1 obtained.
	 */
	Map<String, int[]> tabProgress(ClogResult clog, int[] totals)
	{
		Map<String, int[]> progress = new LinkedHashMap<>();
		Snapshot s = snapshot;
		if (s == null)
		{
			return progress;
		}
		Set<Integer> obtained = new HashSet<>();
		for (List<ClogResult.ClogItem> items : clog.getObtainedItems().values())
		{
			for (ClogResult.ClogItem item : items)
			{
				obtained.add(s.canonicalizer.canonicalItemId(item.getId()));
			}
		}
		boolean partial = totals[1] <= 0 || obtained.size() * 10L < totals[0] * 9L;
		for (Map.Entry<String, List<String>> tab : s.tabCategoryKeys.entrySet())
		{
			Set<Integer> slots = new HashSet<>();
			for (String category : tab.getValue())
			{
				for (int itemId : s.categoryItems.getOrDefault(category, Collections.emptyList()))
				{
					slots.add(s.canonicalizer.canonicalItemId(itemId));
				}
			}
			int total = slots.size();
			slots.retainAll(obtained);
			progress.put(tab.getKey(), new int[]{partial ? -1 : slots.size(), total});
		}
		return progress;
	}

	Map<String, List<Integer>> copyCategoryItems()
	{
		return ClogResult.copyPages(categoryItems());
	}

	/**
	 * Identity of the current parse, for callers caching structures derived
	 * from it; null when unparsed. Reference-compare only.
	 */
	@Nullable
	Object generation()
	{
		return snapshot;
	}

	/**
	 * One coherent copy of the whole catalog: category items and item names
	 * captured from the same parse, so a concurrent clear or reparse can
	 * never pair pieces of two generations. Null when unparsed.
	 */
	@Nullable
	CatalogCopy copyCatalog()
	{
		Snapshot s = snapshot;
		if (s == null)
		{
			return null;
		}
		return new CatalogCopy(s, ClogResult.copyPages(s.categoryItems), new HashMap<>(s.itemNames));
	}

	/** Test seam: publish a parse with the given categories and item names. */
	/* package */ void publishForTest(Map<String, List<Integer>> categoryItems,
		Map<Integer, String> itemNames)
	{
		publishForTest(categoryItems, itemNames, Collections.emptyMap(), Collections.emptyMap());
	}

	/** Test seam for the Jagex tab taxonomy and runtime-provided duplicate item remaps. */
	/* package */ void publishForTest(Map<String, List<Integer>> categoryItems,
		Map<Integer, String> itemNames, Map<String, List<String>> tabCategoryKeys,
		Map<Integer, Integer> canonicalItemIds)
	{
		publishForTest(categoryItems, itemNames, tabCategoryKeys, canonicalItemIds, Collections.emptyMap());
	}

	/** Test seam with the pages' own names, for the structure the sync shares. */
	/* package */ void publishForTest(Map<String, List<Integer>> categoryItems,
		Map<Integer, String> itemNames, Map<String, List<String>> tabCategoryKeys,
		Map<Integer, Integer> canonicalItemIds, Map<String, String> categoryNames)
	{
		Map<Integer, Integer> remaps = new HashMap<>(FALLBACK_ITEM_REMAPS);
		remaps.putAll(canonicalItemIds);
		snapshot = new Snapshot(new HashMap<>(categoryItems), new LinkedHashMap<>(tabCategoryKeys),
			itemCategoryKeys(categoryItems), new HashMap<>(), new HashMap<>(itemNames),
			new HashMap<>(categoryNames), new ClogItemCanonicalizer(categoryItems, remaps));
	}

	private static Map<Integer, List<String>> itemCategoryKeys(
		Map<String, List<Integer>> categoryItems)
	{
		Map<Integer, List<String>> itemCategories = new HashMap<>();
		for (Map.Entry<String, List<Integer>> category : categoryItems.entrySet())
		{
			for (int itemId : category.getValue())
			{
				itemCategories.computeIfAbsent(itemId, ignored -> new ArrayList<>())
					.add(category.getKey());
			}
		}
		return itemCategories;
	}

	/** A coherent catalog copy plus the identity of the parse it came from. */
	static final class CatalogCopy
	{
		final Object generation;
		final Map<String, List<Integer>> categoryItems;
		final Map<Integer, String> itemNames;

		private CatalogCopy(Object generation, Map<String, List<Integer>> categoryItems,
			Map<Integer, String> itemNames)
		{
			this.generation = generation;
			this.categoryItems = categoryItems;
			this.itemNames = itemNames;
		}
	}

	int categoryCount()
	{
		Snapshot s = snapshot;
		return s != null ? s.categoryItems.size() : 0;
	}

	private void injectSynthetic(Map<String, List<Integer>> categoryItems,
		Map<Integer, List<String>> itemCategoryKeys, Map<String, List<Integer>> itemNameIds,
		Map<Integer, String> itemNames,
		ItemManager itemManager, String key, int[] itemIds)
	{
		List<Integer> ids = new ArrayList<>(itemIds.length);
		for (int id : itemIds)
		{
			ids.add(id);
			itemCategoryKeys.computeIfAbsent(id, k -> new ArrayList<>()).add(key);
			indexItemName(itemNameIds, itemNames, itemManager, id, id);
		}
		categoryItems.put(key, ids);
	}

	private void indexItemName(Map<String, List<Integer>> itemNameIds,
		Map<Integer, String> itemNames, ItemManager itemManager, int sourceItemId,
		int canonicalItemId)
	{
		String itemName = itemManager.getItemComposition(sourceItemId).getName();
		String itemKey = ClogUnlockParser.normalizeItemName(itemName);
		if (!itemKey.isEmpty() && !"null".equals(itemKey))
		{
			String canonicalName = itemManager.getItemComposition(canonicalItemId).getName();
			itemNames.putIfAbsent(canonicalItemId,
				canonicalName != null && !"null".equalsIgnoreCase(canonicalName)
					? canonicalName : itemName);
			List<Integer> ids = itemNameIds.computeIfAbsent(itemKey, k -> new ArrayList<>());
			if (!ids.contains(canonicalItemId))
			{
				ids.add(canonicalItemId);
			}
		}
	}

	private static Map<Integer, Integer> readCanonicalItemIds(Client client)
	{
		Map<Integer, Integer> remaps = new HashMap<>(FALLBACK_ITEM_REMAPS);
		try
		{
			EnumComposition runtime = client.getEnum(ENUM_CLOG_DUPE_REMAP);
			int[] sourceIds = runtime.getKeys();
			int[] canonicalIds = runtime.getIntVals();
			for (int i = 0; i < sourceIds.length && i < canonicalIds.length; i++)
			{
				remaps.put(sourceIds[i], canonicalIds[i]);
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to read clog item remaps; using known aliases", e);
		}
		return remaps;
	}

	private static int canonicalItemId(int itemId, Map<Integer, Integer> remaps)
	{
		return remaps.getOrDefault(itemId, itemId);
	}

	static String resolveTabName(@Nullable String parsedName, int position)
	{
		if (parsedName != null && !parsedName.isBlank()
			&& !"null".equalsIgnoreCase(parsedName))
		{
			return parsedName;
		}
		return position >= 0 && position < ClogHelper.CLOG_GROUP_NAMES.length
			? ClogHelper.CLOG_GROUP_NAMES[position] : null;
	}

	private static Map<Integer, Integer> fallbackItemRemaps()
	{
		Map<Integer, Integer> remaps = new HashMap<>();
		for (String[] row : CatalogTsv.rows(ClogIndex.class, "item-aliases.tsv", 3))
		{
			remaps.put(Integer.parseInt(row[0]), Integer.parseInt(row[1]));
		}
		return Collections.unmodifiableMap(remaps);
	}

	/** The other ids whose names stand in for a counted item's own when it has none, in order (item-aliases.tsv). */
	/**
	 * An item's name on any card, by one rule: the player's log names it, or the game's own Collection Log, or else
	 * one of the item's alias forms does (a log can hold an item only by its alias, the skill pages' shards).
	 */
	@Nullable
	static String itemNameOrAlias(@Nullable ClogIndex index, ClogResult result, int itemId)
	{
		String name = index != null ? index.itemName(result, itemId) : result.getItemName(itemId);
		if (name != null)
		{
			return name;
		}
		for (int alias : nameAliases(itemId))
		{
			String aliased = result.getItemName(alias);
			if (aliased != null)
			{
				return aliased;
			}
		}
		return null;
	}

	static List<Integer> nameAliases(int canonicalItemId)
	{
		List<String[]> rows = new ArrayList<>();
		for (String[] row : CatalogTsv.rows(ClogIndex.class, "item-aliases.tsv", 3))
		{
			if (!row[2].isEmpty() && Integer.parseInt(row[1]) == canonicalItemId)
			{
				rows.add(row);
			}
		}
		rows.sort(Comparator.comparingInt(row -> Integer.parseInt(row[2])));
		List<Integer> aliases = new ArrayList<>();
		for (String[] row : rows)
		{
			aliases.add(Integer.parseInt(row[0]));
		}
		return aliases;
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.game.ItemVariationMapping;

/** Maps observed item forms onto unambiguous slots in the live Collection Log catalog. */
final class ClogItemCanonicalizer
{
	private final Map<Integer, Integer> declaredAliases;
	private final Map<Integer, Integer> catalogVariants;

	ClogItemCanonicalizer(Map<String, List<Integer>> categoryItems,
		Map<Integer, Integer> declaredAliases)
	{
		this.declaredAliases = Collections.unmodifiableMap(new HashMap<>(declaredAliases));
		catalogVariants = buildCatalogVariants(categoryItems, declaredAliases);
	}

	int canonicalItemId(int itemId)
	{
		int declared = declaredAliases.getOrDefault(itemId, itemId);
		return catalogVariants.getOrDefault(declared, declared);
	}

	List<ClogResult.ClogItem> canonicalizeItems(List<ClogResult.ClogItem> items)
	{
		Map<Integer, ClogResult.ClogItem> canonical = new LinkedHashMap<>();
		if (items != null)
		{
			for (ClogResult.ClogItem item : items)
			{
				int itemId = canonicalItemId(item.getId());
				ClogResult.ClogItem prior = canonical.get(itemId);
				canonical.put(itemId, prior == null ? item.withId(itemId)
					: item.filledFrom(prior).withId(itemId).withCount(Math.max(prior.getCount(), item.getCount())));
			}
		}
		return new ArrayList<>(canonical.values());
	}

	int declaredAliasCount()
	{
		return declaredAliases.size();
	}

	int catalogVariantCount()
	{
		return catalogVariants.size();
	}

	private static Map<Integer, Integer> buildCatalogVariants(
		Map<String, List<Integer>> categoryItems, Map<Integer, Integer> declaredAliases)
	{
		Set<Integer> catalogIds = new HashSet<>();
		for (List<Integer> items : categoryItems.values())
		{
			catalogIds.addAll(items);
		}

		Map<Integer, Set<Integer>> candidates = new HashMap<>();
		for (int itemId : catalogIds)
		{
			addCandidates(candidates, itemId, itemId);
		}
		for (Map.Entry<Integer, Integer> alias : declaredAliases.entrySet())
		{
			if (catalogIds.contains(alias.getValue()))
			{
				addCandidates(candidates, alias.getKey(), alias.getValue());
			}
		}

		Map<Integer, Integer> variants = new HashMap<>();
		for (Map.Entry<Integer, Set<Integer>> candidate : candidates.entrySet())
		{
			if (!catalogIds.contains(candidate.getKey())
				&& !declaredAliases.containsKey(candidate.getKey())
				&& candidate.getValue().size() == 1)
			{
				variants.put(candidate.getKey(), candidate.getValue().iterator().next());
			}
		}
		return Collections.unmodifiableMap(variants);
	}

	private static void addCandidates(Map<Integer, Set<Integer>> candidates,
		int sourceItemId, int canonicalItemId)
	{
		for (int variantId : ItemVariationMapping.getVariations(sourceItemId))
		{
			candidates.computeIfAbsent(variantId, ignored -> new HashSet<>())
				.add(canonicalItemId);
		}
	}

}

package com.killclog;

import java.util.function.Consumer;
import javax.inject.Provider;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.menus.MenuManager;
import net.runelite.client.util.Text;

final class ClogLookupMenu
{
	// OSRS player right-click menu reserves indexes 4-7 for plugins (4 slots total).
	private static final int FIRST_PLUGIN_PLAYER_SLOT = 4;
	private static final int LAST_PLUGIN_PLAYER_SLOT_EXCLUSIVE = 8;

	// Right-click menu option strings used to filter Kill Clog lookup entries.
	private static final String OPT_ADD_FRIEND = "Add friend";
	private static final String OPT_ADD_IGNORE = "Add ignore";
	private static final String OPT_REMOVE_FRIEND = "Remove friend";
	private static final String OPT_REMOVE_IGNORE = "Remove ignore";
	private static final String OPT_DELETE = "Delete";
	private static final String OPT_MESSAGE = "Message";

	private String menuOption = "Kill Clog";
	private boolean playerMenuSlotWarned;

	void start(KillClogConfig config, Provider<MenuManager> menuManager)
	{
		menuOption = config.menuLabel().getLabel();
		setPlayerMenuItemEnabled(config, menuManager, config.playerMenuLookup());
	}

	void stop(KillClogConfig config, Provider<MenuManager> menuManager)
	{
		setPlayerMenuItemEnabled(config, menuManager, false);
		playerMenuSlotWarned = false;
	}

	void refresh(KillClogConfig config, Provider<MenuManager> menuManager)
	{
		menuManager.get().removePlayerMenuItem(menuOption);
		menuOption = config.menuLabel().getLabel();
		setPlayerMenuItemEnabled(config, menuManager, config.playerMenuLookup());
	}

	void warnIfPlayerMenuSlotUnavailable(Client client, KillClogConfig config,
		KillClogChatNotifier chatNotifier)
	{
		if (playerMenuSlotWarned || !config.playerMenuLookup() || !config.menuOnPlayers())
		{
			return;
		}

		String[] options = client.getPlayerOptions();
		if (options == null || options.length < LAST_PLUGIN_PLAYER_SLOT_EXCLUSIVE)
		{
			return;
		}
		for (int i = FIRST_PLUGIN_PLAYER_SLOT; i < LAST_PLUGIN_PLAYER_SLOT_EXCLUSIVE; i++)
		{
			if (menuOption.equals(options[i]))
			{
				return;
			}
		}

		playerMenuSlotWarned = true;
		chatNotifier.send(ChatNotice.WARNING,
			"Right-click menu is full. Use the side panel or right-click names in chat instead.");
	}

	void addLookupEntry(MenuEntryAdded event, Client client, KillClogConfig config,
		Consumer<String> lookup)
	{
		if (!config.playerMenuLookup())
		{
			return;
		}

		if (event.getType() != MenuAction.CC_OP.getId()
			&& event.getType() != MenuAction.CC_OP_LOW_PRIORITY.getId())
		{
			return;
		}

		int componentId = event.getActionParam1();
		int groupId = WidgetUtil.componentToInterface(componentId);

		if (!isLookupEligible(config, groupId, componentId, event.getOption()))
		{
			return;
		}

		String target = event.getTarget();
		if (target == null)
		{
			return;
		}
		String name = Text.toJagexName(Text.removeTags(target).trim());
		client.getMenu().createMenuEntry(-2)
			.setOption(menuOption)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.setIdentifier(event.getIdentifier())
			.onClick(e -> lookup.accept(name));
	}

	void handlePlayerLookup(MenuOptionClicked event, KillClogConfig config,
		Consumer<String> lookup)
	{
		if (event.getMenuAction() != MenuAction.RUNELITE_PLAYER
			|| !event.getMenuOption().equals(menuOption)
			|| !config.menuOnPlayers())
		{
			return;
		}

		Player player = event.getMenuEntry().getPlayer();
		if (player == null || player.getName() == null)
		{
			return;
		}

		lookup.accept(Text.toJagexName(player.getName()));
	}

	private void setPlayerMenuItemEnabled(KillClogConfig config,
		Provider<MenuManager> menuManager, boolean enabled)
	{
		if (enabled && config.menuOnPlayers())
		{
			menuManager.get().addPlayerMenuItem(menuOption);
		}
		else
		{
			menuManager.get().removePlayerMenuItem(menuOption);
		}
	}

	private boolean isLookupEligible(KillClogConfig config, int groupId, int componentId, String option)
	{
		// Clan player lists live in two different interfaces; match by componentId, not groupId.
		if (componentId == InterfaceID.ClansSidepanel.PLAYERLIST)
		{
			return config.menuOnClanList()
				&& (OPT_ADD_IGNORE.equals(option) || OPT_REMOVE_FRIEND.equals(option));
		}
		if (componentId == InterfaceID.ClansGuestSidepanel.PLAYERLIST)
		{
			return config.menuOnGuestClanList()
				&& (OPT_ADD_IGNORE.equals(option) || OPT_REMOVE_FRIEND.equals(option));
		}
		switch (groupId)
		{
			case InterfaceID.FRIENDS:
				return config.menuOnFriendsList() && OPT_DELETE.equals(option);
			case InterfaceID.IGNORE:
				return config.menuOnIgnoreList() && OPT_DELETE.equals(option);
			case InterfaceID.CHATCHANNEL_CURRENT:
				return config.menuOnChatChannels()
					&& (OPT_ADD_IGNORE.equals(option) || OPT_REMOVE_FRIEND.equals(option));
			case InterfaceID.CHATBOX:
				return config.menuOnChat()
					&& (OPT_ADD_IGNORE.equals(option) || OPT_MESSAGE.equals(option));
			case InterfaceID.PM_CHAT:
				return config.menuOnPrivateMessages()
					&& (OPT_ADD_IGNORE.equals(option) || OPT_MESSAGE.equals(option));
			case InterfaceID.GIM_SIDEPANEL:
				return config.menuOnGroupIronman()
					&& (OPT_ADD_FRIEND.equals(option)
						|| OPT_REMOVE_FRIEND.equals(option)
						|| OPT_REMOVE_IGNORE.equals(option));
			default:
				return false;
		}
	}
}

package com.killclog;

import java.awt.Component;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToolTip;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
