		this.tabs = tabs;
	}

	/** Called with the tab's name when the player presses its row; without it the rows only read. */
	void setOnOpenTab(@Nullable BiConsumer<MouseEvent, String> onOpenTab)
	{
		this.onOpenTab = onOpenTab;
	}

	@Override
	protected String obtainedLabel()
	{
		return "Total: ";
	}

	private boolean hasTotals()
	{
		return obtained >= 0 && totalSlots > 0;
	}

	String completionText()
	{
		return String.format(Locale.US, "%.1f%%", Math.min(obtained, totalSlots) * 100.0 / totalSlots);
	}

	private static int legendWidth()
	{
		int tiers = ClogHelper.CLOG_TIERS.length;
		return tiers * ICON_SIZE + (tiers - 1) * ICON_GAP;
	}

	public void setSyncData(String dateText, boolean stale)
	{
		this.syncDate = dateText;
		this.syncStale = stale;
	}

	/**
	 * Every site that holds this player's log, whichever one's log the card shows (Dylan, 2026-10-12): one this lookup
	 * heard from, or one known to hold them by RuneProfile's profile, Temple's last answer or Kill Clog's sync list, since
	 * a request can be skipped (your own log) or time out. Your own log read from the game is Kill Clog's when you sync.
	 */
	void setClogSources(ClogResult result, boolean onTemple, boolean onRuneProfile, boolean onKillclog)
	{
		boolean killclog = result.isFromKillclog() || onKillclog;
		sourcesPlayer = result.getPlayerName();
		setClogSources(result.isFromTemple() || onTemple, result.isFromRuneProfile() || onRuneProfile,
			killclog, result.isFromLocal() && !killclog);
	}

	/** Record contributing sources, including Kill Clog's local game capture. */
	void setClogSources(boolean temple, boolean runeProfile, boolean killclog, boolean local)
	{
		clogSources.clear();
		if (killclog || local)
		{
			clogSources.add(new ClogSource(
				local ? LOCAL_SOURCE : KILLCLOG_SOURCE,
				KillClogIcons.killClogSourceIcon(SOURCE_ICON_SIZE), local ? null : link(TooltipItemLink::killclogUrl)));
		}
		if (temple)
		{
			clogSources.add(new ClogSource(
				TEMPLE_SOURCE, KillClogIcons.templeSourceIcon(SOURCE_ICON_SIZE), link(TooltipItemLink::templeUrl)));
		}
		if (runeProfile)
		{
			clogSources.add(new ClogSource(
				RUNEPROFILE_SOURCE, KillClogIcons.runeProfileSourceIcon(SOURCE_ICON_SIZE), link(TooltipItemLink::runeProfileUrl)));
		}
		itemHover.clear();
		itemHover.setHitBoxes(Collections.emptyList());
		revalidate();
		repaint();
	}

	@Nullable
	private String link(java.util.function.UnaryOperator<String> page)
	{
		return sourcesPlayer != null && !sourcesPlayer.isEmpty() ? page.apply(sourcesPlayer) : null;
	}

	public void setNotice(String notice)
	{
		firstTimeSetup = false;
		this.notice = notice;
		setTitle(TITLE);
	}

	public void setFirstTimeSetup()
	{
		firstTimeSetup = true;
		notice = null;
		setTitle("First Time Setup");
	}

	public void setRecentItems(List<ClogResult.ClogItem> recentItems, ClogResult clog,
		ItemManager itemManager)
	{
		recent = shelf(recentItems, clog, itemManager, true);
	}

	public void setRareItems(List<ClogResult.ClogItem> rareItems, ClogResult clog,
		ItemManager itemManager)
	{
		rare = shelf(rareItems, clog, itemManager, false);
	}

	private Shelf shelf(List<ClogResult.ClogItem> items, ClogResult clog, ItemManager itemManager, boolean dated)
	{
		int count = items.size();
		if (count == 0)
		{
			return null;
		}
		int[] ids = new int[count];
		String[] names = new String[count];
		int[] counts = new int[count];
		String[] dates = dated ? new String[count] : null;
		for (int i = 0; i < count; i++)
		{
			ClogResult.ClogItem item = items.get(i);
			ids[i] = item.getId();
			names[i] = clog != null ? clog.getItemName(item.getId()) : null;
			counts[i] = item.getCount();
			if (dated)
			{
				dates[i] = shortDate(item.getDate());
			}
		}
		return new Shelf(TooltipItemSprites.load(TooltipData.itemList(ids), null, itemManager, id -> 1, this),
			ids, names, counts, dates);
	}

	/** A stored UTC date becomes the player's own day, "Jul 4"; anything else is dropped. */
	static String shortDate(String date)
	{
		java.time.LocalDateTime day = ClogDates.here(date);
		return day == null ? null : MONTHS[day.getMonthValue() - 1] + " " + day.getDayOfMonth();
	}

	static int sourceRowWidth(int count)
	{
		return count > 0 ? count * SOURCE_ICON_SIZE + (count - 1) * SOURCE_ICON_GAP : 0;
	}

	static int sourceRowStartX(int tooltipWidth, int count)
	{
		return (tooltipWidth - sourceRowWidth(count)) / 2;
	}

	@Override
	protected CardBody body()
	{
		CardBody body = new CardBody();
		if (firstTimeSetup)
		{
			return body.add(CardBody.text(SETUP_OPEN_LINE, NOTICE_COLOR, true))
				.add(CardBody.text(SETUP_SEARCH_LINE, NOTICE_COLOR, true))
				.add(CardBody.text(SETUP_CHAT_LINE, NOTICE_COLOR, true));
		}
		if (notice != null)
		{
			return body.add(CardBody.text(notice, NOTICE_COLOR, true));
		}

		// The current tier sits large in the header's corner. Completion, the tier ladder and the tabs stand under the
		// header; any tier's, item's or source's name shows in the band under the progress bars, and the shelves and
		// footer scroll below it.
		CardBody card = new CardBody().add(headerCorner(hasTotals(), hasTotals() ? tierSprite : null, null));
		if (hasTotals())
		{
			// The completion heads the tab rows, read the same way: a row that opens nothing.
			card.add(tabRow(-1, "Completion", completionText(), NativeTooltip.valueColor))
				.add(bar(obtained, totalSlots))
				.add(tierLadder());
		}

		if (!tabs.isEmpty())
		{
			// The tabs need no heading of their own: the card is the Collection Log. A divider parts them from
			// the completion above it.
			if (hasTotals())
			{
				card.add(CardBody.separator(SEPARATOR_PAD));
			}
			int row = 0;
			for (Map.Entry<String, int[]> tab : tabs.entrySet())
			{
				int[] count = tab.getValue();
				if (row > 0)
				{
					card.add(CardBody.gap(TAB_GAP));
				}
				card.add(tabRow(row, tab.getKey(), count[0] < 0 ? progressPlaceholderText(count[1])
					: progressCountText(count[0], count[1]), count[0] < 0 ? MUTED_GRAY : completionColor(count[0], count[1])))
					.add(bar(count[0], count[1]));
				row++;
			}
		}
		card.add(hasTotals() || !tabs.isEmpty() ? CardBody.hoverBand() : CardBody.headerHoverBand());

		// The Rare shelf, present only when earned, then recent unlocks.
		shelf(body, RARE_SECTION, "Rare", rare, ClogHelper.RARES_PER_ROW);
		shelf(body, RECENT_SECTION, "Recent", recent, Integer.MAX_VALUE);

		// The footer: when it last changed and who supplied it, under one rule.
		if (syncDate != null || !clogSources.isEmpty())
		{
			body.add(CardBody.separator(SEPARATOR_PAD));
		}
		if (syncDate != null)
		{
			body.add(CardBody.line("Last update: ", syncDate, syncStale ? STALE_RED : CLOG_GREEN));
		}
		if (!clogSources.isEmpty())
		{
			body.add(sources());
		}
		return card.add(CardBody.scroll(scroll, body.asPart()));
	}

	@Override
	CardBody.Scroll scroll()
	{
		return scroll;
	}

	/**
	 * A tab's row, a size up from the card's text, its count at the right like the PvP rows': it opens the tab's
	 * pages, answering hover in white like the Clue Summary's rares.
	 */
	private CardBody.Part tabRow(int row, String label, String value, Color color)
	{
		FontMetrics fm = getFontMetrics(TAB_FONT);
		ToIntFunction<CardBody.Ctx> width = c -> fm.stringWidth(label) + TAB_VALUE_GAP + fm.stringWidth(value);
		CardBody.RowPainter painter = (c, y, hovered) ->
		{
			Font font = c.g.getFont();
			c.g.setFont(TAB_FONT);
			int baseline = y + fm.getAscent();
			c.g.setColor(hovered ? NativeTooltip.valueColor : labelColor);
			c.g.drawString(label, c.inset(), baseline);
			c.g.setColor(color);
			c.g.drawString(value, c.w - c.inset() - fm.stringWidth(value), baseline);
			c.g.setFont(font);
		};
		return row < 0 || onOpenTab == null ? CardBody.row(fm.getHeight(), width, (c, y) -> painter.paint(c, y, false))
			: CardBody.clickRow(tabRows, row, fm.getHeight(), width, painter);
	}

	/** A thin rail under a count: the share at a glance, the number still primary. */
	private static CardBody.Part bar(int obtained, int total)
	{
		return CardBody.row(BAR_HEIGHT + BAR_GAP, c -> 0, (c, y) ->
		{
			int width = c.w - 2 * c.inset();
			c.g.setColor(NativeTooltip.railTrack(BAR_TRACK));
			c.g.fillRect(c.inset(), y, width, BAR_HEIGHT);
			if (obtained > 0 && total > 0)
			{
				c.g.setColor(completionColor(obtained, total));
				c.g.fillRect(c.inset(), y, Math.max(1, width * Math.min(obtained, total) / total), BAR_HEIGHT);
			}
		});
	}

	/** Every tier's icon, dimmed until reached; hovering one reads its range below. */
	private CardBody.Part tierLadder()
	{
		String[] labels = ClogHelper.tierLabels(obtained, totalSlots);
		return CardBody.row(ICON_SIZE, c -> legendWidth(), (c, y) ->
		{
			int x = (c.w - legendWidth()) / 2;
			Composite solid = c.g.getComposite();
			for (int i = 0; i < labels.length; i++)
			{
				boolean reached = i <= tier;
				BufferedImage icon = tierIcons != null ? tierIcons.get(ClogHelper.CLOG_TIERS[i]) : null;
				if (icon != null)
				{
					c.g.setComposite(reached ? solid : AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.3f));
					c.g.drawImage(icon, x, y, null);
				}
				c.hits.add(new TooltipItemHover.HitBox(TIER_SECTION, 0, labels[i],
					new Rectangle(x, y, ICON_SIZE, ICON_SIZE), reached));
				x += ICON_SIZE + ICON_GAP;
			}
			c.g.setComposite(solid);
		});
	}

	/**
	 * A shelf under its subheader: sprites from the left in rows of at most this many, dates below, then its hover
	 * line. Recent is one row; the Rare shelf wraps.
	 */
	private void shelf(CardBody body, int section, String title, Shelf shelf, int perRow)
	{
		if (shelf == null)
		{
			return;
		}
		int count = shelf.ids.length;
		int cols = Math.min(count, perRow);
		int rows = (count + cols - 1) / cols;
		int size = CardBody.GRID_SPRITE;
		Map<Integer, String> named = CardBody.byId(shelf.ids, i -> shelf.names[i]);
		Map<Integer, Integer> held = CardBody.byId(shelf.ids, i -> shelf.counts[i]);
		List<Integer> ids = TooltipData.itemList(shelf.ids);
		body.titled(title).add(CardBody.part(
			c -> cols * shelf.cellWidth(c.fm) + (cols - 1) * RECENT_PAD,
			c -> rows * size + (rows - 1) * RECENT_PAD + (shelf.dated() ? DATE_GAP + c.fm.getHeight() : 0), (c, y) ->
			{
				// Every shelved item is held: the grids' painter draws them, each centered over its date.
				int cellWidth = shelf.cellWidth(c.fm);
				// Shelves start at the left, as killclog.com's do.
				int startX = c.inset();
				c.hits.addAll(TooltipItemSprites.paintGrid(c.g, shelf.sprites, named, section, ids, new HashSet<>(ids),
					held, startX + (cellWidth - size) / 2, y, cols, size, cellWidth + RECENT_PAD));
				for (int i = 0; i < count; i++)
				{
					String date = shelf.dates != null ? shelf.dates[i] : null;
					if (date != null)
					{
						int cellX = startX + i * (cellWidth + RECENT_PAD);
						c.g.setColor(MUTED_GRAY);
						c.g.drawString(date, cellX + (cellWidth - c.fm.stringWidth(date)) / 2,
							y + size + DATE_GAP + c.fm.getAscent());
					}
				}
			}));
	}

	/** Who supplied the log: each source's icon, its name on hover. */
	private CardBody.Part sources()
	{
		return CardBody.part(c ->
		{
			int width = Math.max(c.fm.stringWidth(SOURCE_LABEL), sourceRowWidth(clogSources.size()));
			for (ClogSource source : clogSources)
			{
				width = Math.max(width, c.fm.stringWidth(source.name));
			}
			return width;
		}, c -> c.fm.getHeight() + SOURCE_LABEL_GAP + SOURCE_ICON_SIZE, (c, y) ->
		{
			c.g.setColor(MUTED_GRAY);
			c.g.drawString(SOURCE_LABEL, (c.w - c.fm.stringWidth(SOURCE_LABEL)) / 2, y + c.fm.getAscent());
			y += c.fm.getHeight() + SOURCE_LABEL_GAP;
			int sourceX = sourceRowStartX(c.w, clogSources.size());
			for (int i = 0; i < clogSources.size(); i++)
			{
				ClogSource source = clogSources.get(i);
				int iconX = sourceX + i * (SOURCE_ICON_SIZE + SOURCE_ICON_GAP);
				if (source.icon != null)
				{
					c.g.drawImage(source.icon, iconX, y, null);
				}
				c.hits.add(new TooltipItemHover.HitBox(SOURCE_SECTION, 0, source.name,
					new Rectangle(iconX - SOURCE_HIT_PAD, y - SOURCE_HIT_PAD,
						SOURCE_ICON_SIZE + SOURCE_HIT_PAD * 2, SOURCE_ICON_SIZE + SOURCE_HIT_PAD * 2), true, source.url));
			}
		});
	}

	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class ClogSource
	{
		private final String name;
		private final BufferedImage icon;
		@Nullable
		private final String url;
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.event.MouseEvent;
import java.util.function.ObjIntConsumer;
import javax.annotation.Nullable;

/**
 * One Collection Log tab, opened from the Collection Log card where it was: the tab's progress and the way back,
 * then every page in the game's order with the player's count. A page opens its own popup. A tab
 * more than a notch past {@link #VISIBLE_ROWS} pages scrolls with the mouse wheel, a thin rail showing where.
 */
public class ClogTabTooltip extends TitleTooltip
{
	static final int VISIBLE_ROWS = CardBody.WINDOW / LINE_HEIGHT;
	private static final int COUNT_GAP = 12;

	private String[] names = new String[0];
	private int[] obtained = new int[0];
	private int[] total = new int[0];
	@Nullable
	private KillClogConfig progress;
	// Three pages a notch.
	private final CardBody.Scroll scroll = new CardBody.Scroll(this, CardBody.WINDOW, 3 * LINE_HEIGHT);
	@Nullable
	private ObjIntConsumer<MouseEvent> onOpenPage;
	private final CardBody.ClickRows pageRows = new CardBody.ClickRows(this, (e, page) ->
	{
		if (onOpenPage != null)
		{
			onOpenPage.accept(e, page);
			e.consume();
		}
	});

	/** The tab and the player's progress through it; null progress shows the tab's size alone. */
	void setTab(String tab, @Nullable int[] progress, int tabTotal)
	{
		setTitle(tab);
		if (progress != null && progress[0] >= 0)
		{
			setObtained(progress[0], progress[1]);
		}
		else
		{
			setObtainedPlaceholder(tabTotal);
		}
	}

	/**
	 * Each page's name and count in the game's order; a negative count is unknown and shows its size. With
	 * {@code progress}, a known page's name and count wear its progression color from those settings.
	 */
	void setPages(String[] names, int[] obtained, int[] total, @Nullable KillClogConfig progress)
	{
		this.names = names;
		this.obtained = obtained;
		this.total = total;
		this.progress = progress;
	}

	/** Called with the page's index when the player presses its row. */
	void setOnOpenPage(@Nullable ObjIntConsumer<MouseEvent> onOpenPage)
	{
		this.onOpenPage = onOpenPage;
	}

	@Override
	CardBody.Scroll scroll()
	{
		return scroll;
	}

	private boolean scrolls()
	{
		return scroll.scrolls(names.length * LINE_HEIGHT);
	}

	private int shown()
	{
		return scrolls() ? VISIBLE_ROWS : names.length;
	}

	private String countText(int page)
	{
		return obtained[page] >= 0 ? progressCountText(obtained[page], total[page])
			: progressPlaceholderText(total[page]);
	}

	@Override
	protected CardBody body()
	{
		return new CardBody().add(pageList());
	}

	/** The pages in view: names on the left, counts right-aligned, the rail beside them when the tab scrolls. */
	private CardBody.Part pageList()
	{
		return CardBody.part(c ->
		{
			int nameWidth = 0;
			int countWidth = 0;
			for (int i = 0; i < names.length; i++)
			{
				nameWidth = Math.max(nameWidth, c.fm.stringWidth(names[i]));
				countWidth = Math.max(countWidth, c.fm.stringWidth(countText(i)));
			}
			return nameWidth + COUNT_GAP + countWidth + (scrolls() ? CardBody.RAIL_GAP + CardBody.RAIL_WIDTH : 0);
		}, c -> shown() * LINE_HEIGHT, (c, y) ->
		{
			// Only the pages in view answer; the page under a still mouse is hovered as the list moves.
			int offset = scroll.follow((names.length - shown()) * LINE_HEIGHT) / LINE_HEIGHT;
			pageRows.clear();
			for (int i = 0; i < shown(); i++)
			{
				pageRows.span(y + i * LINE_HEIGHT, offset + i);
			}
			pageRows.rehover();
			int right = c.w - c.inset() - (scrolls() ? CardBody.RAIL_GAP + CardBody.RAIL_WIDTH : 0);
			for (int i = 0; i < shown(); i++)
			{
				int page = offset + i;
				int textY = y + i * LINE_HEIGHT + c.fm.getAscent();
				// With the highlighter on, a page's row wears its progression color whole, as the boss list's rows do.
				Color count = obtained[page] < 0 ? MUTED_GRAY : progress != null
					? ClogHelper.clogColor(obtained[page], total[page], progress) : completionColor(obtained[page], total[page]);
				c.g.setColor(pageRows.hovered() == page ? NativeTooltip.valueColor
					: progress != null && obtained[page] >= 0 ? count : labelColor);
				c.g.drawString(names[page], c.inset(), textY);
				c.g.setColor(count);
				drawRightAligned(c.g, c.fm, countText(page), right, textY);
			}
			if (scrolls())
			{
				CardBody.rail(c, scroll, y, shown() * LINE_HEIGHT, VISIBLE_ROWS, names.length, offset, names.length - VISIBLE_ROWS);
			}
		});
	}
}

package com.killclog;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import net.runelite.client.util.Text;

final class ClogUnlockParser
{
	private static final String COLLECTION_LOG_UNLOCK_PREFIX =
		"New item added to your collection log:";

	// Clan broadcast form: "<player> received a new collection log item:
	// <item> (1186/1706)". Players whose notification setting is popup-only
	// never get the personal game message, so the broadcast is the only chat
	// signal their own unlock produces. The trailing counts are the live
	// obtained/total pair, fresher than a possibly lagging varp read.
	private static final Pattern CLAN_BROADCAST_UNLOCK = Pattern.compile(
		"^(.+?) received a new collection log item: (.+?)(?: \\((\\d+)/(\\d+)\\))?$");

	// Vanilla kill-count message, RuneLite's canonical shape: covers kill,
	// harvest, lap, completion, success, and subdued variants with their
	// color tags. Fires the same tick as a clog unlock from that kill, so a
	// recent match supplies the "obtained at N kc" provenance.
	private static final Pattern KILLCOUNT_MESSAGE = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? "
			+ "(?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?"
			+ "<col=[0-9a-f]{6}>(?<kc>[0-9,]+)</col>");

	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	static final class KillContext
	{
		final String boss;
		final int kc;

	}

	static KillContext parseKillCount(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = KILLCOUNT_MESSAGE.matcher(message);
		if (!m.find())
		{
			return null;
		}
		try
		{
			int kc = Integer.parseInt(m.group("kc").replace(",", ""));
			String boss = Text.removeTags(m.group("boss")).replace((char) 160, ' ').trim();
			return boss.isEmpty() || kc <= 0 ? null : new KillContext(boss, kc);
		}
		catch (NumberFormatException ignored)
		{
			return null;
		}
	}

	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	static final class BroadcastUnlock
	{
		final String playerName;
		final String itemName;
		final int obtained;
		final int total;

	}

	private ClogUnlockParser()
	{
	}

	static BroadcastUnlock parseClanBroadcast(String message)
	{
		if (message == null)
		{
			return null;
		}

		String cleaned = Text.removeTags(message).replace((char) 160, ' ').trim();
		Matcher m = CLAN_BROADCAST_UNLOCK.matcher(cleaned);
		if (!m.matches())
		{
			return null;
		}

		String itemName = m.group(2).trim();
		while (itemName.endsWith("."))
		{
			itemName = itemName.substring(0, itemName.length() - 1).trim();
		}
		if (itemName.isEmpty())
		{
			return null;
		}

		int obtained = -1;
		int total = -1;
		try
		{
			if (m.group(3) != null && m.group(4) != null)
			{
				obtained = Integer.parseInt(m.group(3));
				total = Integer.parseInt(m.group(4));
			}
		}
		catch (NumberFormatException ignored)
		{
		}

		return new BroadcastUnlock(m.group(1).trim(), itemName, obtained, total);
	}

	static String parseItemName(String message)
	{
		if (message == null)
		{
			return null;
		}

		String cleaned = Text.removeTags(message).replace((char) 160, ' ').trim();
		String lower = cleaned.toLowerCase(Locale.ROOT);
		String prefix = COLLECTION_LOG_UNLOCK_PREFIX.toLowerCase(Locale.ROOT);
		int prefixIndex = lower.indexOf(prefix);
		if (prefixIndex < 0)
		{
			return null;
		}

		String itemName = cleaned.substring(prefixIndex + COLLECTION_LOG_UNLOCK_PREFIX.length()).trim();
		while (itemName.endsWith("."))
		{
			itemName = itemName.substring(0, itemName.length() - 1).trim();
		}
		return itemName.isEmpty() ? null : itemName;
	}

	static String normalizeItemName(String itemName)
	{
		if (itemName == null)
		{
			return "";
		}
		return Text.removeTags(itemName)
			.replace((char) 160, ' ')
			.trim()
			.toLowerCase(Locale.ROOT)
			.replaceAll("\\s+", " ");
	}
}

package com.killclog;

import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.function.ObjIntConsumer;
import javax.annotation.Nullable;
import lombok.Setter;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * Clue Summary on the Clues cell. Eight lines, All through Mimic, each with its
 * score and rank and, for the six tiers and Mimic, collection progress. Below
 * them the rare collections, each a row that opens its own modal. The six tiers
 * and Mimic open theirs the same way (Dylan, 2026-10-17: every clue reached from
 * the summary as from its own cell, and nothing passed over without answering).
 */
public class ClueSummaryTooltip extends TitleTooltip
{
	private static final int ICON_SIZE = 13;
	private static final int ICON_GAP = 4;
	private static final int COL_GAP = 6;
	static final int MIMIC = 7;

	private static final HiscoreSkill[] CLUE_TIERS = {
		HiscoreSkill.CLUE_SCROLL_ALL,
		HiscoreSkill.CLUE_SCROLL_BEGINNER, HiscoreSkill.CLUE_SCROLL_EASY,
		HiscoreSkill.CLUE_SCROLL_MEDIUM, HiscoreSkill.CLUE_SCROLL_HARD,
		HiscoreSkill.CLUE_SCROLL_ELITE, HiscoreSkill.CLUE_SCROLL_MASTER,
	};

	private static final String[] LABELS = {
		"All", "Beginner", "Easy", "Medium",
		"Hard", "Elite", "Master", "Mimic",
	};

	static final String[] RARE_LABELS = {
		"3rd Age", "Gilded", "Hard Rare", "Elite Rare", "Master Rare",
	};

	private final int[] scores = new int[8];
	private final int[] ranks = new int[8];
	// Collection progress per line; -1 obtained means none is shown.
	private final int[] obtained = new int[8];
	private final int[] total = new int[8];
	private final int[] rareObtained = new int[RARE_LABELS.length];
	private final int[] rareTotal = new int[RARE_LABELS.length];

	@Setter
	private BufferedImage[] icons;
	@Setter
	private BufferedImage[] rareIcons;
	@Nullable
	private ObjIntConsumer<MouseEvent> onOpenRare;
	private final CardBody.ClickRows rareRows = new CardBody.ClickRows(this, (e, row) ->
	{
		if (onOpenRare != null)
		{
			onOpenRare.accept(e, row);
			e.consume();
		}
	});
	@Nullable
	private ObjIntConsumer<MouseEvent> onOpenLine;
	private final CardBody.ClickRows lineRows = new CardBody.ClickRows(this, (e, line) ->
	{
		if (onOpenLine != null)
		{
			onOpenLine.accept(e, line);
			e.consume();
		}
	});

	public ClueSummaryTooltip()
	{
		Arrays.fill(scores, -1);
		Arrays.fill(ranks, -1);
		Arrays.fill(obtained, -1);
		Arrays.fill(rareObtained, -1);
	}

	/** A null result renders the full tier ladder with "--" scores: the empty state. */
	public void setData(HiscoreResult hiscoreResult, boolean showRank)
	{
		setTitle("Clue Summary");
		if (hiscoreResult == null)
		{
			return;
		}

		for (int i = 0; i < CLUE_TIERS.length; i++)
		{
			String name = CLUE_TIERS[i].getName();
			scores[i] = hiscoreResult.getActivityScore(name);
			ranks[i] = hiscoreResult.getActivityRank(name);
		}
		scores[MIMIC] = hiscoreResult.getKc("Mimic");
		ranks[MIMIC] = hiscoreResult.getRank("Mimic");

		if (showRank && hiscoreResult.isRankDataAvailable())
		{
			setRank(ranks[0]);
		}
	}

	/** Collection progress for a line (1 to 6 the tiers, 7 Mimic); null counts leave it bare. */
	void setProgress(int line, @Nullable int[] counts)
	{
		obtained[line] = counts != null ? counts[0] : -1;
		total[line] = counts != null ? counts[1] : 0;
	}

	/** One rare collection row; null counts show the row without progress. */
	void setRare(int row, @Nullable int[] counts)
	{
		rareObtained[row] = counts != null ? counts[0] : -1;
		rareTotal[row] = counts != null ? counts[1] : 0;
	}

	/** Called with the line (1 to 6 the tiers, 7 Mimic) when the player presses one. */
	void setOnOpenLine(@Nullable ObjIntConsumer<MouseEvent> onOpenLine)
	{
		this.onOpenLine = onOpenLine;
	}

	/** Called with the rare row index when the player presses one. */
	void setOnOpenRare(@Nullable ObjIntConsumer<MouseEvent> onOpenRare)
	{
		this.onOpenRare = onOpenRare;
	}

	@Override
	protected CardBody body()
	{
		// Ranks ride in their own column, so they stay aligned down the card.
		int[] shownRanks = new int[ranks.length];
		for (int i = 0; i < ranks.length; i++)
		{
			shownRanks[i] = scores[i] > 0 && ranks[i] > 0 ? ranks[i] : 0;
		}
		CardBody body = new CardBody()
			.add(CardBody.table(icons, LABELS, scores, obtained, total, shownRanks, ICON_SIZE, ICON_GAP, COL_GAP,
				lineRows, line -> line > 0))
			.titled("Rare Collections");
		for (int i = 0; i < RARE_LABELS.length; i++)
		{
			body.add(rareRow(i));
		}
		return body;
	}

	/** One rare collection; the row opens its own modal, its progress right-aligned. */
	private CardBody.Part rareRow(int row)
	{
		return CardBody.clickRow(rareRows, row, c -> ICON_SIZE + ICON_GAP + widest(c.fm, RARE_LABELS)
			+ progressWidth(c.fm, rareObtained, rareTotal), (c, y, hovered) ->
		{
			int textY = y + c.fm.getAscent();
			paintIcon(c.g, rareIcons, row, c.inset(), y);
			// No pointer cursor in this UI: the hovered row answers in white instead.
			c.g.setColor(hovered ? NativeTooltip.valueColor : labelColor);
			c.g.drawString(RARE_LABELS[row], c.inset() + ICON_SIZE + ICON_GAP, textY);
			if (rareObtained[row] >= 0)
			{
				int width = wrappedProgressCountWidth(c.fm, rareObtained[row], rareTotal[row]);
				paintWrappedProgressCount(c.g, c.fm, c.w - c.inset() - width, textY, rareObtained[row], rareTotal[row]);
			}
		});
	}

	private static void paintIcon(Graphics2D g2, @Nullable BufferedImage[] set, int index, int x, int y)
	{
		BufferedImage icon = set != null && index < set.length ? set[index] : null;
		if (icon != null)
		{
			g2.drawImage(icon, x, y + (LINE_HEIGHT - ICON_SIZE) / 2, null);
		}
	}

	private static int progressWidth(FontMetrics fm, int[] obtained, int[] total)
	{
		int width = 0;
		for (int i = 0; i < obtained.length; i++)
		{
			if (obtained[i] >= 0)
			{
				width = Math.max(width, wrappedProgressCountWidth(fm, obtained[i], total[i]));
			}
		}
		return width;
	}

	private static int widest(FontMetrics fm, String[] labels)
	{
		int width = 0;
		for (String label : labels)
		{
			width = Math.max(width, fm.stringWidth(label));
		}
		return width;
	}
}

package com.killclog;


final class ColosseumGlory
{
	static final String BOSS_NAME = "Sol Heredit";
	static final String ACTIVITY_NAME = "Colosseum Glory";
	static final String LABEL = "Glory: ";

	private ColosseumGlory()
	{
	}

	static boolean replacesKc(String bossName)
	{
		return BOSS_NAME.equals(bossName);
	}

	static int score(HiscoreResult result)
	{
		return result != null ? result.getActivityScore(ACTIVITY_NAME) : -1;
	}

	/**
	 * Whether a boss card leads with Glory instead of kills: Sol Heredit, once the player has Glory, on either side
	 * of a comparison, synced log or not, as the game's own hiscores show it.
	 */
	static boolean leadsCard(String bossName, HiscoreResult result)
	{
		return replacesKc(bossName) && isVisible(score(result));
	}

	static boolean isVisible(int glory)
	{
		return glory > 0;
	}

	static String format(int glory)
	{
		return isVisible(glory) ? TitleTooltip.grouped(glory) : "--";
	}

	static boolean hasHeaderScore(int glory, int kc)
	{
		return isVisible(glory) || kc >= 0;
	}

	static String headerLabel(int glory)
	{
		return isVisible(glory) ? LABEL : "KC: ";
	}

	static String headerValue(int glory, int kc)
	{
		return isVisible(glory) ? format(glory) : ClogHelper.formatKc(kc);
	}
}

package com.killclog;

import java.util.EnumMap;
import java.util.Map;
import lombok.AccessLevel;
import lombok.Getter;

/**
 * Immutable Combat Achievement lookup result from per-tier task counts.
 *
 * <p>Tier math runs against the current catalog: live task counts from
 * {@link CaCatalog} when captured, else the fallback constants. Completed
 * counts never revoke, so a provider snapshot taken before a Combat
 * Achievement release still carries true counts; only the denominators move.
 * Computing against the live catalog therefore reproduces the game's own
 * demotion semantics on release day, before the player has re-synced.
 */
final class CombatAchievementResult
{
	private final Map<CombatAchievementTier, Integer> completed;
	private final Map<CombatAchievementTier, Integer> providerTotal;
	private final Map<CombatAchievementTier, Integer> currentTotals;
	private final boolean liveCatalog;
	@Getter(AccessLevel.PACKAGE)
	private final int totalPoints;
	// Highest unlocked tier, or null if below Easy.
	@Getter(AccessLevel.PACKAGE)
	private final CombatAchievementTier tier;

	private CombatAchievementResult(Map<CombatAchievementTier, Integer> completed,
									Map<CombatAchievementTier, Integer> providerTotal,
									Map<CombatAchievementTier, Integer> liveTotals)
	{
		this.completed = completed;
		this.providerTotal = providerTotal;
		this.liveCatalog = liveTotals != null && !liveTotals.isEmpty();

		Map<CombatAchievementTier, Integer> totals = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier loopTier : CombatAchievementTier.values())
		{
			Integer live = liveCatalog ? liveTotals.get(loopTier) : null;
			totals.put(loopTier, live != null ? live : loopTier.totalTasks());
		}
		this.currentTotals = totals;

		int points = 0;
		for (Map.Entry<CombatAchievementTier, Integer> entry : completed.entrySet())
		{
			points += entry.getValue() * entry.getKey().pointsPerTask();
		}
		this.totalPoints = points;
		this.tier = isAllComplete()
			? CombatAchievementTier.GRANDMASTER
			: CombatAchievementTier.highestForPoints(points, currentTotals);
	}

	/** True when every task in every tier is completed against the current catalog. */
	boolean isAllComplete()
	{
		for (CombatAchievementTier loopTier : CombatAchievementTier.values())
		{
			int done = completed.getOrDefault(loopTier, 0);
			int need = currentTotals.getOrDefault(loopTier, loopTier.totalTasks());
			if (done < need)
			{
				return false;
			}
		}
		return true;
	}

	/** Build from per-tier completed/total counts; null maps are treated as empty. */
	static CombatAchievementResult of(Map<CombatAchievementTier, Integer> completed,
									Map<CombatAchievementTier, Integer> total)
	{
		return of(completed, total, null);
	}

	/**
	 * Build with the live catalog's task counts. When present they own both the
	 * tier math and the displayed denominators, because provider snapshots and
	 * the fallback constants can trail a Combat Achievement release.
	 */
	static CombatAchievementResult of(Map<CombatAchievementTier, Integer> completed,
									Map<CombatAchievementTier, Integer> total,
									Map<CombatAchievementTier, Integer> liveTotals)
	{
		Map<CombatAchievementTier, Integer> c = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> t = new EnumMap<>(CombatAchievementTier.class);
		if (completed != null)
		{
			c.putAll(completed);
		}
		if (total != null)
		{
			t.putAll(total);
		}
		return new CombatAchievementResult(c, t, liveTotals);
	}

	/**
	 * This result recomputed against the given live totals; returns this
	 * instance when the math already used them. Cached results are built once
	 * and served for their TTL, so a verdict computed before a catalog capture
	 * (or across a threshold change) heals on read instead of surviving stale.
	 */
	CombatAchievementResult rebasedOn(Map<CombatAchievementTier, Integer> liveTotals)
	{
		if (liveTotals == null || liveTotals.isEmpty())
		{
			return this;
		}
		if (liveCatalog && currentTotals.equals(liveTotals))
		{
			return this;
		}
		return new CombatAchievementResult(completed, providerTotal, liveTotals);
	}

	/** The Combat Summary tier row's reward sprite for the held tier, or null when no tier is held. */
	CombatAchievementReward getReward()
	{
		return tier == null ? null : tier.reward();
	}
}

