	private NavigationButton navButton;
	private PlayerClans playerClans;
	// Who is logged in, decided in this one place; the stores, the panel and the publication flow follow it.
	private final SessionTracker sessions = new SessionTracker();
	@Inject
	private Gson gson;
	// Opens a League's own store; a test seam.
	private java.util.function.Function<String, LocalClogCache> leagueCacheFactory = id ->
	{
		Filepath folder = localClogCache.folder().getNow(null);
		return new LocalClogCache(gson, folder == null ? null : folder.join("leagues", id));
	};
	// The store the collection log walk started with; a different one means start over.
	private LocalClogCache walkCache;
	private final WorldSession world = new WorldSession(
		() -> client.getGameState() == GameState.LOGGED_IN
			? GameMode.of(client.getWorldType(), killclogService.activeLeague()) : null,
		() -> killclogService.activeLeague(), () -> localClogCache, id -> leagueCacheFactory.apply(id),
		store ->
		{
			store.setFirstPartyChangedListener(() -> firstPartyChanged(store));
			store.serve(sessions.current());
		});
	private final AdvLogPbs.Watch advLog = new AdvLogPbs.Watch();
	// The account takes up its own log once per login and per store, latched when the open store says so (its folder
	// and the account's log arrive on later ticks than the login).
	private boolean accountActivated;
	// Whether this login has been on the main game: the main store keeps it from then on (serveMainStore).
	private boolean mainReached;

	private final ClogSessionState sessionState = new ClogSessionState();
	private final ClogIndex clogIndex = new ClogIndex();
	private final LiveClogSync liveClogSync = new LiveClogSync();
	private final ManualClogSync manualClogSync = new ManualClogSync();
	private final LocalCaReader localCaReader = new LocalCaReader();
	private final CaCatalog caCatalog = new CaCatalog();
	private final ClogLookupMenu lookupMenu = new ClogLookupMenu();
	private PublicationCoordinator publication;
	private SyncSettings syncSettings;
	private ClogPbs clogPbs;
	private KillLog killLog;

	@Provides
	KillClogConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(KillClogConfig.class);
	}

	@Override
	protected void startUp()
	{
		// Saved settings take their current shape before anything reads them, the panel first.
		ConfigMigrations.run(configManager);
		// Built once: RuneLite reuses this instance across disable and enable, and the publication flow keeps it.
		if (panel == null)
		{
			panel = panelProvider.get();
		}
		// RuneLite moves the 2.4 folder in on first use. The store opens it on its
		// own disk thread; a folder that cannot open keeps this session in memory.
		localClogCache.open(this::getPluginDirectory);
		localClogCache.folder().thenAccept(folder -> localCaCache.open(folder == null ? null : folder.join("ca")));

		navButton = NavigationButton.builder()
			.tooltip("Kill Clog")
			.icon(getIcon())
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		panel.setNameAutocompleter(nameAutocompleter);
		panel.setClogIndex(clogIndex);
		playerClans = new PlayerClans(client, chatIconManager, runeProfileService, world::mainSettled, config::shareClan);
		panel.setClans(playerClans);
		syncService.setClans(playerClans);
		hiscoreService.setHardcoreTable(killclogService::hardcoreHiscores);

		lookupMenu.start(config, menuManager);

		// One coordinator for the life of this plugin instance: RuneLite reuses
		// the instance across disable and enable, and the sync gate, its queued
		// intent and a request still in the air must survive that, or a re-enabled
		// plugin would run a second sync beside the old one.
		if (publication == null)
		{
			publication = new PublicationCoordinator(config, configManager, clientThread, executor,
				sessions, syncService, profileAppearanceService, chatNotifier, panel,
				() -> world.mainSettled() ? getLocalAccountType() : null, world::mode,
				() -> world.hardcoreXp(client.getWorldType(), client::getOverallExperience), world::cacheFor,
				killclogService::leagueProfileType);
			sessions.addListener(this::sessionChanged);
		}
		syncSettings = new SyncSettings(config, configManager);
		clogPbs = new ClogPbs(configManager);
		killLog = new KillLog(configManager);
		syncSettings.enforce();
		panel.setKillclogSyncHandler(publication::manualSync);
		panel.setCharacterPublishHandler(publication::publishCharacter);
		panel.setCharacterDeleteHandler(publication::deleteCharacter);
		panel.setFirstPartyLockedHandler(() -> clientThread.invokeLater(() -> chatNotifier.send(ChatNotice.SYNC_HELP,
			"Kill Clog syncs from your first Collection Log item. Open your Collection Log so Kill Clog can read it:"
				+ " the chalice and the character button unlock once it holds an item.")));
		panel.setSelfPbs(this::selfPbs);
		// The first tick hands the panel and chat this world's game again.
		world.showAgain();
		panel.setSyncArrowEnabled(config.killclogSync());
		panel.setCharacterPublishEnabled(publication.characterPublishingEnabled());
		// The sync trigger lives at the data seam: any path that lands a
		// first-party observation (bulk page capture, Collection Log Search,
		// live unlock) schedules a debounced push.
		localClogCache.setFirstPartyChangedListener(() -> firstPartyChanged(localClogCache));

		kclogCommand.setClogIndex(clogIndex);
		syncService.setClogIndex(clogIndex);
		killclogService.setClogIndex(clogIndex);
		clogService.setClogIndex(clogIndex);
		localCaCache.setCaCatalog(caCatalog);
		runeProfileService.setCaCatalog(caCatalog);
		kclogCommand.commands().forEach(chatCommandManager::registerCommandAsync);

		// If installed mid-session, run login init on the client thread
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() ->
			{
				sessions.update(client);
				enterLoggedInState(false);
			});
		}
		else if (client.getGameState() == GameState.LOGIN_SCREEN)
		{
			// The game's Collection Log is readable at the login screen: lookups made there open every page.
			clientThread.invokeLater(() ->
			{
				clogIndex.ensureParsed(client, itemManager);
			});
		}

		log.debug("Kill Clog plugin started");
	}

	@Override
	protected void shutDown()
	{
		// The real appearance the game last sent is kept, like the other data, so a re-enable mid-login can publish
		// without a gear change: logout, a hop or a lost connection drops it, and a publish checks it against the
		// worn gear.
		clientToolbar.removeNavigation(navButton);
		lookupMenu.stop(config, menuManager);
		kclogCommand.commands().keySet().forEach(chatCommandManager::unregisterCommand);
		localClogCache.shutdown();
		world.close();
		localCaCache.shutdown();
		manualClogSync.reset();
		clogIndex.clear();
		localCaCache.setCaCatalog(null);
		runeProfileService.setCaCatalog(null);
		caCatalog.clear();
		sessionState.reset();
		liveClogSync.resetFirstSyncWarning();
		nameAutocompleter.clearClientSnapshot();
		localClogCache.setFirstPartyChangedListener(null);
		publication.cancelCharacterPublish();
		publication.cancelSync();
		SwingUtilities.invokeLater(() -> panel.shutdown());
		// The login dies with the plugin: a surviving one would carry the old account into whoever logs in next.
		sessions.end();
		log.debug("Kill Clog plugin stopped");
	}

	private void enterLoggedInState(boolean requestLocalReads)
	{
		if (requestLocalReads)
		{
			sessionState.requestLocalReads();
		}

		killclogService.refreshIndex();
		Session session = sessions.current();
		LocalClogCache cache = world.captureCache();
		if (session.loggedIn() && cache != null)
		{
			String name = session.getName();
			AccountType acctType = getLocalAccountType();
			boolean localClogReady = cache.serve(session);
			SwingUtilities.invokeLater(() -> panel.setLoggedInPlayer(name, acctType));
			if (!requestLocalReads)
			{
				sessionState.requestLocalReads();
			}
			if (localClogReady)
			{
				ownLogServing(cache, name);
			}
			else
			{
				panel.setFirstParty(PanelStatusRow.FirstParty.HIDDEN);
			}
		}

		nameAutocompleter.refreshClientSnapshot();
		GimBadgeLoader.load(client);
		clogIndex.ensureParsed(client, itemManager);
		caCatalog.capture(client);
		sessionState.requestAutoLookup(config.autoLookupOnLogin());
		lookupMenu.warnIfPlayerMenuSlotUnavailable(client, config, chatNotifier);
		reconcileClogTotalsFromVarps();
	}

	/**
	 * True-live total bump with no chat dependency: the client pushes the
	 * collection log counts as varps, so any unlock (and the login flood)
	 * moves them regardless of the player's notification settings. Upward
	 * only; full log refresh stays the downward authority. Runs on the client
	 * thread (varbit events and enterLoggedInState both arrive there).
	 */
	private void reconcileClogTotalsFromVarps()
	{
		String name = sessions.current().getName();
		if (!world.mainSettled() || name == null)
		{
			return;
		}
		if (!localClogCache.hasDataFor(name))
		{
			return;
		}
		int obtained = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (localClogCache.updateTotalsUpward(name, obtained, total))
		{
			SwingUtilities.invokeLater(() -> panel.onBulkCaptureComplete(name));
		}
	}

	// Run before Fashionscape (0) and Weapon/Gear/Anim Replacer (1).
	@Subscribe(priority = 2)
	public void onPlayerChanged(PlayerChanged event)
	{
		profileAppearanceService.captureOriginalAppearance(event.getPlayer());
	}

	/**
	 * The store serves this login's own log: the chalice and the character button say whether it holds one, and a log
	 * that does is pushed once. That catch-up closes a hole: a debounced push that fired after logout (or mid world-hop)
	 * aborted with nothing to relaunch it, so a session's last capture stayed unpublished; the server merge no-ops when
	 * nothing changed.
	 */
	private void ownLogServing(LocalClogCache cache, String name)
	{
		boolean hasLocalClog = cache.hasFirstPartyDataFor(name);
		panel.setFirstParty(firstParty(hasLocalClog));
		if (hasLocalClog)
		{
			publication.scheduleAutomaticSync();
		}
	}

	/**
	 * The main store serves this login once it has been on the main game, and while its world's game is still unknown;
	 * a League world, even one learned a few ticks after the login (the running League arrives with the sync index),
	 * leaves it serving no one until a hop reaches the main game. So looking yourself up in Main game stats there reads
	 * the providers until your own main log is here, and a hop from the main game to a League keeps it, as 2.6.6 does.
	 * Asked again whenever the login or its world's game changes.
	 */
	private void serveMainStore()
	{
		String game = world.mode();
		mainReached |= GameMode.MAIN.equals(game);
		Session now = sessions.current();
		localClogCache.serve(mainReached || game == null ? now : Session.none(now.getNumber()));
	}

	/**
	 * Who is logged in changed: the stores take up the new login (or none), the previous account's hiscore row is
	 * refetched next time, and work from the previous login stands down. On the client thread, before anything else
	 * sees the new session.
	 */
	private void sessionChanged(Session previous, Session now)
	{
		mainReached = false;
		serveMainStore();
		world.serve(now);
		localCaCache.serve(now);
		accountActivated = false;
		if (previous.loggedIn())
		{
			hiscoreService.markDirty(previous.getName());
			publication.cancelCharacterPublish();
			publication.cancelSync();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		sessions.update(client);
		if (event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING
			|| event.getGameState() == GameState.CONNECTION_LOST)
		{
			profileAppearanceService.clearOriginalAppearance();
		}
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			accountActivated = false;
			SwingUtilities.invokeLater(panel::reloadTooltipSprites);
			clogService.clearTempleFailures();
			runeProfileService.clearFailures();
			killclogService.clearFailures();
			enterLoggedInState(true);
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			SwingUtilities.invokeLater(panel::reloadTooltipSprites);
			// Logged out, your name is anyone's: its lookup reads every site, character and clan included.
			SwingUtilities.invokeLater(() -> panel.setLoggedInPlayer(null, null));
			// The sync affordance belongs to the account that just ended. Hiding
			// it also fences a success callback queued during the logout handoff.
			panel.setFirstParty(PanelStatusRow.FirstParty.HIDDEN);
			panel.resetSyncFeedback();
			manualClogSync.reset();
			// Read the game's own structure again at once, for lookups made before the next login.
			clogIndex.clear();
			clogIndex.ensureParsed(client, itemManager);
			sessionState.resetAutoLookupSession();
			liveClogSync.resetFirstSyncWarning();
			nameAutocompleter.clearClientSnapshot();
			playerClans.clearClientSnapshot();
			killLog.reset();
			// The login itself ended in the tracker, first: its stores, its account, its hiscore row and its work.
			followWorld();
		}
		else if (event.getGameState() == GameState.HOPPING)
		{
			markLocalHiscoresDirty();
			// A walk never spans two worlds: the next one may be a different game.
			manualClogSync.reset();
		}
		// A region load stays on the same world; everything else may change it.
		if (event.getGameState() != GameState.LOGGED_IN && event.getGameState() != GameState.LOADING)
		{
			unsettleWorld();
		}

		// The owner claim is scoped to one POH visit, exactly as vanilla
		// scopes it: any region load or hop drops it, so a friend's log can
		// never linger and gate (or worse, misattribute) a later harvest.
		if (event.getGameState() == GameState.LOADING
			|| event.getGameState() == GameState.HOPPING)
		{
			advLog.dropOwner();
		}
	}

	// Jagex republishes the local player's hiscore row on logout and world
	// hop; the cached self-row predates it, so the next self-search refetches.
	private void markLocalHiscoresDirty()
	{
		String name = sessions.current().getName();
		if (name != null)
		{
			hiscoreService.markDirty(name);
		}
	}

	// Live collection-log unlock messages update local cache immediately.
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (config.showChatEmojis())
		{
			chatEmoji.rewrite(event);
		}

		// !kc <item name> provenance reveal. Boss arguments stay with the
		// built-in plugin's own "!kc" registration; the handler ignores them.
		LocalClogCache kcCache = world.captureCache();
		if (kcCache != null)
		{
			kclogCommand.handleKcItem(event, clogIndex, kcCache);
		}

		// RuneLite keeps one registered handler per command string, so claiming
		// !log here would replace RuneProfile's handler. Read the raw chat line
		// only as a fallback when RuneProfile itself is not enabled.
		String message = event.getMessage();
		if (KillClogChatCommand.isCompatibleLogCommand(event.getType(), message)
			&& !isRuneProfileActive())
		{
			executor.execute(() -> kclogCommand.handleLogCompatibility(event, message));
		}

		killLog.chat(client, event.getType(), event.getMessage(), client.getTickCount());

		// Kill-count messages land the same tick as the clog unlock they
		// caused; remembering the freshest one lets the unlock carry its
		// "obtained at N kc" provenance. SPAM covers filtered game messages.
		if (event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
		{
			ClogUnlockParser.KillContext kill = ClogUnlockParser.parseKillCount(event.getMessage());
			if (kill != null)
			{
				liveClogSync.rememberKill(kill, client.getTickCount());
			}
		}

		if (event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			String unlockName = ClogUnlockParser.parseItemName(event.getMessage());
			if (unlockName != null)
			{
				clientThread.invokeLater(() -> handleCollectionLogUnlock(unlockName, -1, -1));
			}
		}

		// Players whose notification setting is popup-only never produce the
		// personal game message; their own clan broadcast is the only chat
		// signal of the unlock, and it carries the fresh obtained/total pair.
		if (event.getType() == ChatMessageType.CLAN_MESSAGE)
		{
			ClogUnlockParser.BroadcastUnlock broadcast =
				ClogUnlockParser.parseClanBroadcast(event.getMessage());
			if (broadcast != null && RsnInputPolicy.sameName(broadcast.playerName, sessions.current().getName()))
			{
				clientThread.invokeLater(() -> handleCollectionLogUnlock(
					broadcast.itemName, broadcast.obtained, broadcast.total));
			}
		}
	}

	private void handleCollectionLogUnlock(String itemName, int broadcastObtained, int broadcastTotal)
	{
		LocalClogCache cache = world.captureCache();
		if (cache == null)
		{
			return;
		}
		liveClogSync.handleUnlock(itemName, broadcastObtained, broadcastTotal, client,
			itemManager, clogIndex, cache, chatNotifier,
			panel::onBulkCaptureComplete, world.settled());
	}

	// Keep local CA current when a task completes mid-session, and the live
	// catalog current when the game moves a tier threshold (a CA release).
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (localCaReader.isCaVarbit(event.getVarbitId())
			|| CaCatalog.isThresholdVarbit(event.getVarbitId()))
		{
			sessionState.requestCaRead();
		}

		if (event.getVarpId() == VarPlayerID.COLLECTION_COUNT || event.getVarpId() == VarPlayerID.COLLECTION_COUNT_MAX)
		{
			reconcileClogTotalsFromVarps();
		}
		clogPbs.varpChanged(client, event.getVarpId());
		if (event.getVarbitId() == VarbitID.IRONMAN)
		{
			unsettleWorld();
		}
	}

	/** Until the world settles again the game hasn't said your clan, so a sync leaves it out (2.6.3). */
	private void unsettleWorld()
	{
		world.unsettle();
		if (playerClans != null)
		{
			playerClans.clearClientSnapshot();
		}
	}

	/** Read per-tier CA completed counts from game varbits and persist them for the active player. */
	private boolean captureLocalCa()
	{
		if (!world.mainSettled())
		{
			return false;
		}
		caCatalog.capture(client);
		return localCaReader.capture(client, sessions.current(), localCaCache);
	}

	private boolean isRuneProfileActive()
	{
		return pluginManager.getPlugins().stream()
			.anyMatch(plugin -> RUNEPROFILE_PLUGIN_NAME.equals(plugin.getName())
				&& pluginManager.isPluginActive(plugin));
	}

	/** A logged-in account whose own log has loaded: locked until it holds an item. */
	private static PanelStatusRow.FirstParty firstParty(boolean hasLocalClog)
	{
		return hasLocalClog ? PanelStatusRow.FirstParty.READY : PanelStatusRow.FirstParty.LOCKED;
	}

	private void firstPartyChanged(LocalClogCache cache)
	{
		// A capture only counts once the payload is genuinely non-empty:
		// an empty first walk must neither reveal the chalice nor
		// schedule a push that would fail with nothing to send.
		if (cache.hasFirstPartyDataForActive())
		{
			panel.setFirstParty(PanelStatusRow.FirstParty.READY);
			publication.scheduleAutomaticSync();
		}
	}

	/** A League world reads its League in the panel and chat; every other world, or none, the main game. */
	private void followWorld()
	{
		world.follow((league, leagueLog, active) ->
		{
			serveMainStore();
			kclogCommand.readLeague(league, leagueLog);
			SwingUtilities.invokeLater(() -> panel.followWorld(league, leagueLog, active));
		});
	}

	/**
	 * Your PBs for panel bosses in one game: the main game's profiles, or the League's announced one. RuneLite lists
	 * every saved profile on each ask, so the grid asks once for all its bosses.
	 */
	private java.util.function.UnaryOperator<String> selfPbs(String league)
	{
		java.util.List<String> keys = PersonalBests.profileKeys(configManager.getRSProfiles(), sessions.current().getAccountHash(),
			league == null ? RuneScapeProfileType.STANDARD.name() : killclogService.leagueProfileType(league));
		PersonalBests pbs = new PersonalBests(configManager, keys);
		return pbs::pbText;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The names only feed the search box's autofill, so a refresh every three seconds is fresh enough.
		if (client.getTickCount() % 5 == 0)
		{
			nameAutocompleter.refreshClientSnapshot();
		}
		playerClans.refreshClientSnapshot();
		sessions.update(client);
		boolean settledNow = world.tick();
		if (settledNow)
		{
			// Counters and CA tiers read before the world settled were skipped: take them now.
			reconcileClogTotalsFromVarps();
			sessionState.requestCaRead();
		}
		followWorld();
		long hardcoreXp = world.hardcoreXp(client.getWorldType(), client::getOverallExperience);

		// The account takes up its own log, following any name change (the
		// server migrates its own copy on the next sync). Memory only; the
		// store says no until its folder has loaded, and this retries.
		LocalClogCache activeCache = world.captureCache();
		Session session = sessions.current();
		if (!accountActivated && activeCache != null && activeCache.serve(session))
		{
			accountActivated = true;
			ownLogServing(activeCache, session.getName());
		}
		String hardcoreName = session.getName();
		if (hardcoreXp > 0 && localClogCache.startOverOnReset(hardcoreName, hardcoreXp, settledNow))
		{
			chatNotifier.send(ChatNotice.SYNC_RESULT, "Kill Clog started your collection log over for your new run.");
			ownLogServing(localClogCache, hardcoreName);
			SwingUtilities.invokeLater(() -> panel.onBulkCaptureComplete(hardcoreName));
		}
		String previousName = localClogCache.consumeRenameNotice();
		if (previousName != null)
		{
			chatNotifier.send(ChatNotice.SYNC_RESULT,
				"Kill Clog followed your name change from '" + previousName
				+ "' - your collection log came along.");
			String renameName = session.getName();
			if (renameName != null)
			{
				SwingUtilities.invokeLater(() -> panel.onBulkCaptureComplete(renameName));
			}
		}

		if (sessionState.pendingAcctTypeRecheck())
		{
			String name = session.getName();
			if (name != null)
			{
				sessionState.clearAcctTypeRecheck();
				AccountType acctType = getLocalAccountType();
				SwingUtilities.invokeLater(() -> panel.setLoggedInPlayer(name, acctType));
			}
		}

		if (sessionState.pendingCaRead())
		{
			sessionState.setPendingCaRead(!captureLocalCa());
		}

		if (sessionState.pendingAutoLookup())
		{
			String name = session.getName();
			if (name != null)
			{
				// A world with no known game still shows the main log, as it always has.
				LocalClogCache cache = world.captureCache() != null ? world.captureCache() : localClogCache;
				if (cache.serve(session))
				{
					sessionState.markAutoLookupStarted();
					// The login transition often fires before the player's name is
					// readable. This tick path waits for identity arbitration too,
					// so a resident name-slot file can never become the self view.
					panel.setFirstParty(firstParty(cache.hasFirstPartyDataFor(name)));
					captureLocalCa();
					AccountType acctType = getLocalAccountType();
					SwingUtilities.invokeLater(() ->
					{
						panel.setLoggedInPlayer(name, acctType);

						// Do not overwrite the user's research. LOGGED_IN fires on
						// every world hop, so skip auto-lookup when viewing someone else.
						String displayed = panel.getDisplayedRsn();
						if (displayed != null && !RsnInputPolicy.sameName(displayed, name))
						{
							return;
						}

						panel.setPlayerName(name);
						panel.doLookup();
					});
				}
			}
		}

		LocalClogCache cache = world.captureCache();
		if (cache != walkCache)
		{
			manualClogSync.reset();
			walkCache = cache;
		}
		if (cache != null)
		{
			manualClogSync.onGameTick(client, clogIndex, cache,
				chatNotifier, liveClogSync::resetFirstSyncWarning,
				panel::onBulkCaptureComplete);
		}

		advLog.onTick(client, configManager);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.COLLECTION)
		{
			// Request a full Search walk after the player's log has initialized.
			// Ordinary visible-category scripts cannot establish a full capture.
			manualClogSync.onCollectionLogOpened(client);
		}

		advLog.onWidgetLoaded(event.getGroupId());
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		ScriptEvent script = event.getScriptEvent();
		if (script == null)
		{
			return;
		}

		// Native Search can run without a MenuOptionClicked event. Observe its
		// opening callback before it emits the full obtained-item stream.
		if (isCollectionLogSearchScript(event.getScriptId(), script))
		{
			onCollectionLogSearch();
		}

		manualClogSync.captureScriptArguments(client, event.getScriptId(),
			script.getArguments(), client.getTickCount());
	}

	// The log drew a page: its Personal Best line, the game's own record, when it has one.
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == net.runelite.api.ScriptID.COLLECTION_DRAW_LIST)
		{
			clogPbs.pageDrawn(client);
		}
	}

	private boolean isCollectionLogSearchScript(int scriptId, ScriptEvent script)
	{
		if (scriptId != CLOG_SEARCH_TOGGLE_SCRIPT)
		{
			return false;
		}
		Widget source = script.getSource();
		Object[] args = script.getArguments();
		if (source == null || source.getId() >>> 16 != InterfaceID.COLLECTION || source.isHidden()
			|| args == null || args.length < 2 || !(args[1] instanceof Integer) || (int) args[1] != 0)
		{
			return false;
		}
		// 4084 calls toggle procedure 4085: an already visible Search or a
		// force-close argument closes it. Neither is a new full-log capture.
		Widget search = client.getWidget(InterfaceID.Collection.CONTENT_SEARCH);
		return search != null && search.isSelfHidden();
	}

	/** A pack or theme that replaced a sprite the cards wear redraws them in it, however long it took to apply. */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (NativeTooltip.wornSpritesChanged(client))
		{
			SwingUtilities.invokeLater(panel::reloadTooltipSprites);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("killclog"))
		{
			return;
		}

		if (MENU_CONFIG_KEYS.contains(event.getKey()))
		{
			// Refresh the menu option when its label or locations change.
			lookupMenu.refresh(config, menuManager);
		}

		if ("killclogSync".equals(event.getKey()))
		{
			// The opt-in pushes the log of the login and era it was made in: a logout can land while this runs.
			int optedInEra = publication.syncEra();
			Session optedIn = sessions.current();
			panel.setSyncArrowEnabled(config.killclogSync());
			if (config.killclogSync())
			{
				syncSettings.syncTurnedOn();
				characterPublishFollowsSettings();
				// Opting in mid-session pushes the already-captured log right
				// away; nothing else fires until the next capture or unlock.
				publication.pushNow(optedIn, optedInEra, true);
			}
			else
			{
				syncSettings.enforce();
				characterPublishFollowsSettings();
				publication.cancelSync();
			}
		}
		else if ("silentAutomaticSync".equals(event.getKey()))
		{
			panel.refreshSyncFeedbackSettings();
		}
		else if ("automaticSync".equals(event.getKey()))
		{
			syncSettings.enforce();
			if (!config.automaticSync())
			{
				publication.cancelAutomaticSync();
			}
		}
		else if ("characterModel".equals(event.getKey()))
		{
			syncSettings.enforce();
			characterPublishFollowsSettings();
		}
		else if ("shareClan".equals(event.getKey()) && config.killclogSync())
		{
			// Share Clan takes effect at once, either way: off, killclog.com stops naming the clan now rather than at
			// the next sync, which with Automatic Sync off waits for a press. The push is the opt-in's, on this login.
			publication.pushNow(sessions.current(), publication.syncEra(), true);
		}

		SwingUtilities.invokeLater(() -> panel.onConfigChanged(event.getKey()));
	}

	/** The character button follows sync and the character setting together; turning either off withdraws it. */
	private void characterPublishFollowsSettings()
	{
		boolean enabled = publication.characterPublishingEnabled();
		panel.setCharacterPublishEnabled(enabled);
		if (!enabled)
		{
			publication.cancelCharacterPublish();
		}
	}

	private void openPanelAndLookup(String name)
	{
		SwingUtilities.invokeLater(() ->
		{
			clientToolbar.openPanel(navButton);
			panel.setPlayerName(name);
			panel.doLookup();
		});
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		lookupMenu.addLookupEntry(event, client, config, this::openPanelAndLookup);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (isCollectionLogSearchClick(event.getMenuOption(), event.getMenuEntry().getParam1()))
		{
			// Arm before the game's Search action runs script 4100 for every
			// obtained entry. Opening the interface itself is too early: its
			// visible category can run the same script and is not a full log.
			onCollectionLogSearch();
		}
		lookupMenu.handlePlayerLookup(event, config, this::openPanelAndLookup);
	}

	private void onCollectionLogSearch()
	{
		clogIndex.ensureParsed(client, itemManager);
		LocalClogCache cache = world.captureCache();
		if (cache != null)
		{
			manualClogSync.onCollectionLogSearch(client, clogIndex, cache, chatNotifier);
		}
	}

	static boolean isCollectionLogSearchClick(String option, int widgetId)
	{
		return option != null
			&& "Search".equalsIgnoreCase(Text.removeTags(option).trim())
			&& widgetId >>> 16 == InterfaceID.COLLECTION;
	}

	private AccountType getLocalAccountType()
	{
		return AccountType.fromRuneLiteVarbit(client.getVarbitValue(VarbitID.IRONMAN));
	}

	private BufferedImage getIcon()
	{
		return KillClogIcons.pluginIconOrCollectionLog(itemManager);
	}
}

package com.killclog;

import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * Kill Clog's own record of the kills it sees. A kill-count message and its time pair only within two ticks of each
 * other (the Grotesque Guardians' time waits up to ten for its count), so a time can never land on a later kill as
 * RuneLite's leftover one can. What it keeps is the PB the game
 * states at the kill, keyed by the team size the game gives (the raids, the Nightmare) or the players in the instance
 * (Royal Titans, Yama, The Fractured Archive), with the timer and, from a kill that set a new PB, the raid level and kill count. The sync
 * sends it as source "live".
 */
final class KillLog
{
	/* package */ static final String KEY_PREFIX = "livepb.";
	/* package */ static final String TAG_PREFIX = "livepbtag.";
	// RuneLite's window: a kill count and its time arrive on the same tick, now and then a tick or two apart.
	private static final int PAIR_TICKS = 2;
	// The Grotesque Guardians' kill count waits out Dusk's death animation, seconds after the time (none of 362 stored
	// Guardians times came from a kill, 10/22), so their time waits up to ten ticks for it, as Dink's pairing does.
	private static final int LATE_COUNT_TICKS = 10;
	private static final String LATE_COUNT_BOSS = "grotesque guardians";
	// No half of a kill seen: outside every window, so nothing pairs with it.
	private static final int NONE = -LATE_COUNT_TICKS - PAIR_TICKS - 1;
	private static final String TIME = "\\d+(?::\\d{2})+(?:\\.\\d+)?";
	private static final Pattern KILL_COUNT = Pattern.compile("Your (?:completion count for |subdued |completed )?"
		+ "(?<boss>.+?) (?:(?:kill|harvest|lap|completion|success) )?(?:count )?is: ?(?<kc>[0-9,]+)");
	private static final Pattern DURATION = Pattern.compile("(?i)(?:Team size: (?<team>Solo|\\d+(?:\\+|-\\d+)? players?) )?"
		+ "(?:(?:fight |challenge |corrupted challenge )?duration:|subdued in"
		+ "|(?<record>the fractured archive: )?(?<total>total )?completion time:) "
		+ "(?<time>" + TIME + ")(?:\\.? personal best: (?<pb>" + TIME + ")| \\(new personal best\\))");
	private static final int[] TOB_PARTY = {VarbitID.TOB_CLIENT_P0, VarbitID.TOB_CLIENT_P1, VarbitID.TOB_CLIENT_P2,
		VarbitID.TOB_CLIENT_P3, VarbitID.TOB_CLIENT_P4};
	private static final int[] TOA_PARTY = {VarbitID.TOA_CLIENT_P0, VarbitID.TOA_CLIENT_P1, VarbitID.TOA_CLIENT_P2,
		VarbitID.TOA_CLIENT_P3, VarbitID.TOA_CLIENT_P4, VarbitID.TOA_CLIENT_P5, VarbitID.TOA_CLIENT_P6,
		VarbitID.TOA_CLIENT_P7};
	// The encounters with no team size in their message: the most players the instance counts toward one.
	private static final Map<String, Integer> INSTANCE_TEAMS = Map.of("royal titans", 2, "yama", 2, "fractured archive", 8);

	private final ConfigManager configManager;
	private String boss;
	private int kc;
	private int kcTick = NONE;
	private double pb;
	private boolean fresh;
	private String team;
	private int pbTick = NONE;
	// What the game showed when the time arrived: the raid parties and level, and the players in the instance. A party
	// that changed before the kill count leaves the time without a team size (the site keeps such a time hidden).
	private int tobAtTime;
	private int toaAtTime;
	private int toaLevelAtTime;
	private int playersAtTime;
	// The account the half-seen kill belongs to: another account's message never pairs with it.
	private long account = -1;

	KillLog(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/** A chat message; client thread. */
	void chat(Client client, ChatMessageType type, String message, int tick)
	{
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}
		long you = client.getAccountHash();
		if (you != account)
		{
			reset();
			account = you;
		}
		String text = Text.removeTags(message.replace("<br>", " ")).replaceAll("@[a-z_]+@", "");
		// A raid's total time counts its waiting too; the challenge time in the message before it is the record. The
		// Fractured Archive's total is its record, as RuneLite keeps it.
		Matcher duration = DURATION.matcher(text);
		if (duration.find() && (duration.group("total") == null || duration.group("record") != null))
		{
			fresh = duration.group("pb") == null;
			pb = AdvLogPbs.timeToSeconds(duration.group(fresh ? "time" : "pb"));
			team = duration.group("team");
			pbTick = tick;
			tobAtTime = party(client, TOB_PARTY);
			toaAtTime = party(client, TOA_PARTY);
			toaLevelAtTime = client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL);
			playersAtTime = instancePlayers(client);
		}
		Matcher count = KILL_COUNT.matcher(text);
		if (count.find() && !count.group("boss").contains("(Echo)"))
		{
			boss = count.group("boss").replace(":", "").toLowerCase(Locale.ROOT);
			kc = Integer.parseInt(count.group("kc").replace(",", ""));
			kcTick = tick;
		}
		// A count arriving after its time can come late; a time after its count can't (the count must be this tick's).
		int window = LATE_COUNT_BOSS.equals(boss) ? LATE_COUNT_TICKS : PAIR_TICKS;
		if (Math.abs(kcTick - pbTick) <= window && tick - kcTick <= PAIR_TICKS)
		{
			record(client);
			kcTick = pbTick = NONE;
		}
	}

	private void record(Client client)
	{
		boolean tob = boss.startsWith("theatre of blood");
		boolean toa = boss.startsWith("tombs of amascut");
		Integer most = INSTANCE_TEAMS.get(boss);
		boolean instanced = most != null;
		// These keep one PB at any team size, so only a kill that set a new one says which size set it.
		if (instanced && !fresh)
		{
			return;
		}
		String size = team;
		if (tob || toa || instanced)
		{
			int atTime = tob ? tobAtTime : toa ? toaAtTime : Math.min(most, playersAtTime);
			int now = tob ? party(client, TOB_PARTY) : toa ? party(client, TOA_PARTY) : Math.min(most, instancePlayers(client));
			size = now == atTime ? teamLabel(atTime) : null;
			if (size == null && instanced)
			{
				return;
			}
		}
		String key = size != null ? boss + " " + size.toLowerCase(Locale.ROOT) : boss;
		// A raid's kill states its team size's record, even when the party changed too late to say which size.
		retirePageReading(size != null || tob || toa);
		Double kept = configManager.getRSProfileConfiguration(AdvLogPbs.CONFIG_GROUP, KEY_PREFIX + key, double.class);
		// With precise timing off the game states the same record without its tenths: the kept time and its kill
		// count stay. A whole second kept and a tenths time stated is the same record told more exactly: kept anew.
		if (!fresh && kept != null && (kept == pb || pb == Math.rint(pb) && PbRecord.sameRecord(kept, pb)))
		{
			return;
		}
		String exact = size == null ? "" : size.equals("Solo") ? "1" : size.matches("\\d+ players?") ? size.split(" ")[0] : "";
		String timer = tob || toa ? "challenge"
			: boss.startsWith("chambers of xeric") || boss.equals("fractured archive") ? "overall" : "kill";
		// The same record told more exactly keeps the labels its kept time had: the kill count and raid level that set it.
		PbRecord before = !fresh && kept != null && PbRecord.sameRecord(kept, pb)
			? PbRecord.live(kept, configManager.getRSProfileConfiguration(AdvLogPbs.CONFIG_GROUP, TAG_PREFIX + key)) : null;
		String scale = fresh && toa ? String.valueOf(toaLevelAtTime) : label(before == null ? null : before.scale);
		String setAt = fresh ? String.valueOf(kc) : label(before == null ? null : before.kc);
		configManager.setRSProfileConfiguration(AdvLogPbs.CONFIG_GROUP, KEY_PREFIX + key, pb);
		configManager.setRSProfileConfiguration(AdvLogPbs.CONFIG_GROUP, TAG_PREFIX + key, PbRecord.tag(pb, exact,
			scale, timer, setAt));
	}

	private static String label(@Nullable Integer value)
	{
		return value == null ? "" : String.valueOf(value);
	}

	/**
	 * A kill states the game's record as it is now, a new PB or the one already held. A log page reading that differs
	 * from it is older (a PB set since, or set while the page was closed, on another client or in a release that kept
	 * no such rule), so it gives way until the page is next opened; it would otherwise win over this kill
	 * (PbRecord.pick). The same record shown without its tenths is the same record. A team size's kill states only
	 * that size's record, while the page shows the fastest of any size (a raid's, Dylan 10/21), so only a faster one
	 * makes the page's older.
	 */
	private void retirePageReading(boolean teamSized)
	{
		String page = ClogPbs.KEY_PREFIX + PersonalBests.encounter(boss);
		Double read = configManager.getRSProfileConfiguration(AdvLogPbs.CONFIG_GROUP, page, double.class);
		if (read != null && !PbRecord.sameRecord(read, pb) && (!teamSized || pb < read))
		{
			configManager.unsetRSProfileConfiguration(AdvLogPbs.CONFIG_GROUP, page);
		}
	}

	/** Drops a kill half seen: at logout, and when another account's messages arrive. */
	void reset()
	{
		kcTick = pbTick = NONE;
		boss = null;
		team = null;
	}

	private static int instancePlayers(Client client)
	{
		WorldView view = client.getTopLevelWorldView();
		return view == null ? 0 : (int) view.players().stream().count();
	}

	private static int party(Client client, int[] slots)
	{
		int count = 0;
		for (int slot : slots)
		{
			count += Math.min(client.getVarbitValue(slot), 1);
		}
		return count;
	}

	@Nullable
	private static String teamLabel(int players)
	{
		return players < 1 ? null : players == 1 ? "Solo" : players + " players";
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import net.runelite.api.clan.ClanTitle;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;

/**
 * First-party collection log provider: reads back what players published
 * through their own Kill Clog sync. Two requests, both against killclog.com:
 * <ol>
 *   <li><strong>Sync index</strong> -- the membership list of synced players,
 *       fetched once per interval. A lookup of a never-synced name is answered
 *       from this in-memory set and costs ZERO extra HTTP.</li>
 *   <li><strong>Proof view</strong> ({@link #lookupClog}) -- one GET against
 *       {@code /api/player/{rsn}/proof-view}, parsed into a {@link ClogResult}.
 *       The response is first-party cargo only (the player's own pushed log,
 *       personal bests, and game counters); provider data never rides it.</li>
 * </ol>
 *
 * <p>Freshness model mirrors {@link RuneProfileService}: success TTL, not-found
 * TTL, transient failure cooldown, in-flight dedup, and a circuit breaker.
 * A previous success is still returned while cached, so a server-side blip
 * cannot blank known-good data mid-session.
 *
 * <p>Personal bests are the read leg's defining cargo: no public provider
 * serves them. Each successful proof-view fetch caches the player's pb map
 * (keyed by panel boss name, exactly as the sync payload publishes them) so
 * boss tooltips can show PB lines for looked-up synced players.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class KillclogService
{
	private static final String PROOF_SUFFIX = "/proof-view";

	/** A page's items: the game's own when the client has read the log, else the provider catalog. */
	@Nullable
	private List<Integer> pageItems(String key)
	{
		ClogIndex index = clogIndex;
		List<Integer> ids = index != null ? index.categoryItems().get(key) : null;
		return ids != null || clogService == null ? ids : clogService.getCategoryCatalogIds(key);
	}

	/** Every page a lookup is measured against: the game's own once read, else the provider catalog's. */
	private Set<String> pageKeys()
	{
		ClogIndex index = clogIndex;
		if (index != null && index.isParsed())
		{
			return new java.util.HashSet<>(index.categoryKeys());
		}
		return clogService != null ? clogService.getCatalogCategoryKeys() : Collections.emptySet();
	}

	private static final long INDEX_TTL_MS = 10 * 60 * 1000;      // 10 min -- membership list
	// A name the list doesn't hold may have synced since it was fetched: a lookup that misses asks again once the
	// list is a minute old, so a player's first sync shows within a minute, not ten (10/23).
	private static final long MISS_RECHECK_MS = 60 * 1000;

	private final CircuitBreaker breaker = new CircuitBreaker("killclog.com");

	// Plausibility ceiling for the game's unique counters: the real log sits
	// around 1.7k slots, so anything past this is a corrupt or hostile value
	// and must not be allowed to decide a coverage race.
	private static final int MAX_PLAUSIBLE_UNIQUE = 50_000;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ClogService clogService;
	// The game's own pages once the client has read the log; the provider catalog stands in before then.
	@Setter
	@Nullable
	private ClogIndex clogIndex;

	// Membership index: normalized names of players with first-party proof.
	// Null until the first successful fetch; a null index degrades to "skip the
	// killclog leg entirely" so providers keep serving when killclog.com is down.
	@Nullable private volatile Set<String> syncIndex;
	private volatile long indexFetchedAt = 0;
	private volatile long indexFailedAt = 0;
	private final Map<String, CompletableFuture<Set<String>>> indexInFlight = new ConcurrentHashMap<>();

	// Proof-view cache, keyed by lowercase rsn. Same TTL trio as the providers.
	private final HttpUtil.Lane<ClogResult> clogs = new HttpUtil.Lane<>(breaker);

	// Personal bests per player, filled by every successful proof-view fetch
	// regardless of which provider wins the clog pick. Keys are panel boss
	// names -- the sync payload publishes them that way (gatherPersonalBests
	// keys by HiscoreSkill name), so lookups need no key translation.
	private final Map<String, Map<String, Double>> pbCache = new ConcurrentHashMap<>();

	/** A player's PB-cache and sync-index key: the shared name key (RsnInputPolicy.key), every spelling Jagex accepts. */
	private static String pbKey(String playerName)
	{
		return RsnInputPolicy.key(playerName);
	}

	/** Cache key for one player in one mode, also accepted by {@link #pbText}; main keeps the plain name. */
	static String modeKey(String mode, String playerName)
	{
		return GameMode.MAIN.equals(mode) ? pbKey(playerName) : mode + "/" + pbKey(playerName);
	}

	/** Clear transient failure cooldowns immediately (called on login); TTLs auto-expire otherwise. */
	public void clearFailures()
	{
		clogs.failed.clear();
		indexFailedAt = 0;
		breaker.reset();
	}

	/**
	 * Look up first-party collection log data. Resolves to null when the player
	 * has never synced (index miss -- zero HTTP), when killclog.com is
	 * unreachable with nothing cached, or on opt-out. LookupFanout combines
	 * this with the providers; fullest result leads, ties prefer first-party.
	 */
	public CompletableFuture<ClogResult> lookupClog(String playerName)
	{
		return lookupClog(playerName, GameMode.MAIN);
	}

	/** One mode's first-party log: main, or a League from that League's own proof view. */
	CompletableFuture<ClogResult> lookupClog(String playerName, String mode)
	{
		String key = modeKey(mode, playerName);
		// The canonical catalog supplies category denominators; until it
		// warms (a brief startup window), a fresh first-party result would
		// render dishonest totals, so the leg waits it out. Providers keep
		// serving, and nothing is recorded against the breaker.
		if (clogs.hold(key) || clogService != null && !clogService.hasCatalog())
		{
			return CompletableFuture.completedFuture(clogs.values.get(key));
		}

		return ensureIndex().thenCompose(index -> index == null || index.contains(pbKey(playerName))
			? CompletableFuture.completedFuture(index) : ensureIndex(MISS_RECHECK_MS)).thenCompose(index ->
		{
			// Unknown membership (index never fetched, server unreachable):
			// keep whatever is cached rather than guessing either way.
			if (index == null)
			{
				return CompletableFuture.completedFuture(clogs.values.get(key));
			}
			// A real index miss is authoritative absence: never synced, or
			// synced-then-withdrawn (opt-out purge, unbind). Cached data and
			// pbs are evicted so withdrawal is honored within one index
			// refresh, never held for a cache TTL.
			if (!index.contains(pbKey(playerName)))
			{
				evictFirstParty(key);
				return CompletableFuture.completedFuture(null);
			}
			return HttpUtil.singleFlightLookup(clogs.inFlight, key, () -> startProofViewLookup(playerName, key, mode));
		});
	}

	/** Drop every first-party trace of a player: clog result, freshness, pbs. */
	private void evictFirstParty(String key)
	{
		clogs.values.remove(key);
		clogs.fetched.remove(key);
		pbCache.remove(key);
	}

	/**
	 * Formatted personal best for a looked-up synced player, or null when none
	 * is cached. Synchronous cache read -- safe from the EDT at tooltip-build
	 * time; the map fills during the same fetch that produced the clog result.
	 */
	@Nullable
	public String pbText(@Nullable String playerName, String panelBossName)
	{
		if (playerName == null)
		{
			return null;
		}
		// A League's key (modeKey) is its id, then a slash, then the name; only the name is a player's to fold.
		int slash = playerName.indexOf('/');
		Map<String, Double> pbs = pbCache.get(slash < 0 ? pbKey(playerName)
			: playerName.substring(0, slash + 1) + pbKey(playerName.substring(slash + 1)));
		if (pbs == null)
		{
			return null;
		}
		Double best = pbs.get(panelBossName);
		return best != null && best > 0 ? PersonalBests.formatSeconds(best)
			: PersonalBests.labeled(PersonalBests.variantSeconds(pbs, panelBossName), panelBossName);
	}

	private CompletableFuture<Set<String>> ensureIndex()
	{
		return ensureIndex(INDEX_TTL_MS);
	}

	/** The sync list, fetched again when the one held is older than {@code maxAgeMs}. */
	private CompletableFuture<Set<String>> ensureIndex(long maxAgeMs)
	{
		long now = System.currentTimeMillis();
		Set<String> cached = syncIndex;
		if (cached != null && now - indexFetchedAt < maxAgeMs)
		{
			return CompletableFuture.completedFuture(cached);
		}
		if (indexFailedAt > 0 && now - indexFailedAt < HttpUtil.Lane.FAILURE_TTL_MS)
		{
			return CompletableFuture.completedFuture(cached);
		}
		return HttpUtil.singleFlightLookup(indexInFlight, "index", this::startIndexFetch);
	}

	private CompletableFuture<Set<String>> startIndexFetch()
	{
		return HttpUtil.httpGet(httpClient,
			KillClogEndpoint.apiBaseUrl() + "/player/sync-index").thenApply(resp ->
		{
			Set<String> parsed = resp.code == 200 && resp.body != null ? parseSyncIndex(resp.body) : null;
			if (parsed == null)
			{
				indexFailedAt = System.currentTimeMillis();
				breaker.failure();
				return syncIndex;
			}
			syncIndex = parsed;
			indexFetchedAt = System.currentTimeMillis();
			indexFailedAt = 0;
			breaker.success();
			return parsed;
		});
	}

	// The League the server takes syncs for and the RuneLite profile type holding its PBs,
	// announced together with the index and replaced together. The id names a folder and a
	// path segment, so anything but a plain slug is ignored.
	private volatile String[] activeLeague = new String[2];
	private static final java.util.regex.Pattern LEAGUE_ID = java.util.regex.Pattern.compile("[a-z0-9]+(-[a-z0-9]+){0,5}");
	// Hardcore Worlds' hiscores table, once killclog.com names it (Jagex hadn't before launch).
	private volatile String hardcoreHiscores;
	private static final java.util.regex.Pattern HISCORE_TABLE = java.util.regex.Pattern.compile("hiscore_oldschool_[a-z_]{1,40}");

	@Nullable
	String hardcoreHiscores()
	{
		return hardcoreHiscores;
	}

	@Nullable
	String activeLeague()
	{
		return activeLeague[0];
	}

	/** This League's RuneLite profile type, or null while RuneLite files its PBs under another League. */
	@Nullable
	String leagueProfileType(String league)
	{
		String[] active = activeLeague;
		return league.equals(active[0]) ? active[1] : null;
	}

	/** Whether this player syncs to Kill Clog, by the sync list held now; false before the first one arrives. */
	boolean isSynced(@Nullable String playerName)
	{
		Set<String> index = syncIndex;
		return playerName != null && index != null && index.contains(pbKey(playerName));
	}

	/** Login: learn the active League even when no lookup needs the index. */
	void refreshIndex()
	{
		ensureIndex();
	}

	@Nullable
	Set<String> parseSyncIndex(String json)
	{
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			if (root == null || !root.has("names") || !root.get("names").isJsonArray())
			{
				return null;
			}
			Set<String> names = ConcurrentHashMap.newKeySet();
			for (JsonElement el : root.getAsJsonArray("names"))
			{
				if (el.isJsonPrimitive() && el.getAsJsonPrimitive().isString())
				{
					names.add(RsnInputPolicy.key(el.getAsString()));
				}
			}
			JsonElement league = root.get("active_league");
			JsonElement profile = root.get("active_league_profile");
			String id = league != null && league.isJsonPrimitive() ? league.getAsString() : "";
			activeLeague = id.length() <= 40 && LEAGUE_ID.matcher(id).matches() && !GameMode.MAIN.equals(id)
				? new String[]{id, profile != null && profile.isJsonPrimitive() ? profile.getAsString() : null} : new String[2];
			JsonElement hardcore = root.get("hardcore_hiscores");
			String table = hardcore != null && hardcore.isJsonPrimitive() ? hardcore.getAsString() : "";
			hardcoreHiscores = HISCORE_TABLE.matcher(table).matches() ? table : null;
			return names;
		}
		catch (Exception e)
		{
			log.debug("Failed to parse killclog sync index: {}", e.getMessage());
			return null;
		}
	}

	private CompletableFuture<ClogResult> startProofViewLookup(String playerName, String key, String mode)
	{
		String url = KillClogEndpoint.apiBaseUrl() + "/player/" + HttpUtil.pathSegment(playerName) + PROOF_SUFFIX
			+ (GameMode.MAIN.equals(mode) ? "" : "/" + mode);
		return HttpUtil.httpGet(httpClient, url).thenApply(resp -> onProofViewResponse(resp.code, resp.body, playerName, key));
	}

	/**
	 * Cache-state transition for a proof-view response; package-private so
	 * tests can drive the eviction paths without HTTP.
	 *
	 * <p>404 (never synced / purged) and 451 (opted out) are authoritative
	 * absence: every cached first-party trace is EVICTED, not merely aged --
	 * withdrawal must not be served for a cache TTL. Transient failures keep
	 * stale data, because a server blip should not blank known-good results.
	 * One response at a time, so a player's PBs and clog result are stored
	 * and trimmed together.
	 */
	@Nullable
	synchronized ClogResult onProofViewResponse(int code, @Nullable String body, String playerName, String key)
	{
		if (code == 404 || code == 451)
		{
			evictFirstParty(key);
			clogs.missing(key);
			return null;
		}
		ClogResult result = code == 200 && body != null ? parseProofView(playerName, body, key) : null;
		if (result == null)
		{
			return clogs.fail(key);
		}
		breaker.success();
		clogs.ok(key, result);
		// A player's PBs live exactly as long as the clog result they came with.
		pbCache.keySet().retainAll(clogs.values.keySet());
		return result;
	}

	/**
	 * Parse a proof-view response into a {@link ClogResult}. Response shape:
	 * <pre>{@code
	 * { exists, rsn, updated_at, last_changed, unique_obtained, unique_total,
	 *   pbs: { "Boss Name": seconds },
	 *   clog: { items_by_category: { cat: [{ item_id, quantity, last_seen_at }] },
	 *           total_obtained, capitalized_name } }
	 * }</pre>
	 * Category keys round-trip the plugin's own canon (they were pushed from
	 * it), so no category normalization is applied. Only acquisition dates are
	 * read; server-observed sync timestamps remain separate.
	 */
	@Nullable
	ClogResult parseProofView(String playerName, String json, String key)
	{
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			if (root == null || !root.has("clog") || !root.get("clog").isJsonObject())
			{
				return null;
			}
			JsonObject clog = root.getAsJsonObject("clog");
			if (!clog.has("items_by_category") || !clog.get("items_by_category").isJsonObject())
			{
				return null;
			}

			Map<String, List<ClogResult.ClogItem>> obtainedItems = new HashMap<>();
			Map<String, List<Integer>> categoryItems = new HashMap<>();
			JsonObject byCategory = clog.getAsJsonObject("items_by_category");
			for (Map.Entry<String, JsonElement> entry : byCategory.entrySet())
			{
				if (!entry.getValue().isJsonArray())
				{
					continue;
				}
				List<ClogResult.ClogItem> obtained = new ArrayList<>();
				for (JsonElement itemEl : entry.getValue().getAsJsonArray())
				{
					if (!itemEl.isJsonObject())
					{
						continue;
					}
					JsonObject item = itemEl.getAsJsonObject();
					int id = intField(item, "item_id");
					int qty = intField(item, "quantity");
					if (id <= 0 || qty < 1)
					{
						// A missing or invalid id must not fabricate item 0,
						// and a missing or nonpositive quantity must not
						// fabricate an obtained item into the coverage race.
						continue;
					}
					obtained.add(new ClogResult.ClogItem(id, qty,
						ClogDates.local(stringField(item, "obtained_at"))));
				}
				if (obtained.isEmpty())
				{
					continue;
				}
				obtainedItems.put(entry.getKey(), obtained);
				// The category's full item list comes from the plugin's own
				// canonical catalog, never from the obtained ids: obtained-only
				// "catalogs" would render every category as complete and hide
				// what's missing. Categories the catalog doesn't know yet are
				// simply left without a denominator.
				List<Integer> catalogIds = pageItems(entry.getKey());
				if (catalogIds != null)
				{
					categoryItems.put(entry.getKey(), catalogIds);
				}
			}
			// An empty log is DATA, not damage: the server serves a valid
			// empty shape for players whose sync carried pbs or counters but
			// no itemized clog yet. Malformed bodies were rejected above;
			// flowing through here seeds full catalog denominators (every
			// category 0-of-N) and still caches the pbs below. Returning
			// null would book a healthy response as a server fault and
			// charge the breaker.

			// Never-logged categories are absent from a first-party payload,
			// but absence is data: the player owns none of that catalog. Seed
			// them with catalog denominators so a first-party-won lookup
			// renders every boss as 0-of-N with a dimmed grid instead of the
			// generic unsynced shape.
			if (clogService != null || clogIndex != null)
			{
				for (String catalogKey : pageKeys())
				{
					if (!categoryItems.containsKey(catalogKey))
					{
						List<Integer> ids = pageItems(catalogKey);
						if (ids != null)
						{
							categoryItems.put(catalogKey, ids);
						}
					}
				}
			}

			String displayName = stringField(root, "rsn");
			if (displayName == null)
			{
				displayName = stringField(clog, "capitalized_name");
			}
			ClogResult result = new ClogResult(
				displayName != null ? displayName : playerName,
				obtainedItems,
				categoryItems,
				null,   // item names resolve client-side through ItemManager
				ClogDates.local(stringField(root, "last_changed")),
				AccountType.fromProviderValue(stringField(root, "account_type"))
			);
			// The obtained counter decides coverage races, so it needs the
			// full plausibility chain: a valid total under the ceiling AND
			// obtained within it. Obtained without a credible total is
			// dropped and coverage falls back to counting distinct parsed
			// items; a lone plausible total still serves as a denominator.
			int uniqueObtained = intField(root, "unique_obtained");
			int uniqueTotal = intField(root, "unique_total");
			boolean totalPlausible = uniqueTotal > 0 && uniqueTotal <= MAX_PLAUSIBLE_UNIQUE;
			if (totalPlausible)
			{
				result.setUniqueTotal(uniqueTotal);
				if (uniqueObtained > 0 && uniqueObtained <= uniqueTotal)
				{
					result.setUniqueObtained(uniqueObtained);
				}
			}
			// This footer describes collection-log provenance, not merely account
			// presence on killclog.com. PB-only proof views intentionally parse
			// and cache as healthy empty results, but do not earn a clog source.
			if (!obtainedItems.isEmpty())
			{
				result = result.withSources(false, false, true);
			}
			// The clan the player's own sync named (2.6.3), or null for none: once present, the Player Summary reads it
			// instead of RuneProfile's. Absent until their sync has said.
			result.setSyncedClanKnown(root.has("clan"));
			JsonObject clan = root.has("clan") && root.get("clan").isJsonObject() ? root.getAsJsonObject("clan") : null;
			if (clan != null && stringField(clan, "name") != null)
			{
				result.setSyncedClan(stringField(clan, "name"));
				result.setSyncedClanTitle(clan.get("title_id") != null && clan.get("title_id").isJsonPrimitive()
					? new ClanTitle(intField(clan, "title_id"), stringField(clan, "title")) : null);
			}

			pbCache.put(key, parsePbs(root));
			return result;
		}
		catch (Exception e)
		{
			log.debug("Failed to parse killclog proof view: {}", e.getMessage());
			return null;
		}
	}

	private static Map<String, Double> parsePbs(JsonObject root)
	{
		if (!root.has("pbs") || !root.get("pbs").isJsonObject())
		{
			return Collections.emptyMap();
		}
		Map<String, Double> pbs = new HashMap<>();
		for (Map.Entry<String, JsonElement> entry : root.getAsJsonObject("pbs").entrySet())
		{
			JsonElement value = entry.getValue();
			if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber())
			{
				double seconds = value.getAsDouble();
				if (seconds > 0)
				{
					pbs.put(entry.getKey(), seconds);
				}
			}
		}
		// A group encounter's times come only by team size, under the game's store keys beside the names above.
		JsonElement detailed = root.get("pbs_detailed");
		for (Map.Entry<String, JsonElement> entry : detailed != null && detailed.isJsonObject()
			? detailed.getAsJsonObject().entrySet() : Collections.<Map.Entry<String, JsonElement>>emptySet())
		{
			JsonElement seconds = entry.getValue().isJsonObject() ? entry.getValue().getAsJsonObject().get("seconds") : null;
			if (seconds != null && seconds.isJsonPrimitive() && seconds.getAsJsonPrimitive().isNumber() && seconds.getAsDouble() > 0)
			{
				pbs.put(entry.getKey(), seconds.getAsDouble());
			}
		}
		return pbs;
	}

	private static int intField(JsonObject obj, String field)
	{
		return obj.has(field) && !obj.get(field).isJsonNull() && obj.get(field).isJsonPrimitive()
			? obj.get(field).getAsInt() : 0;
	}

	@Nullable
	private static String stringField(JsonObject obj, String field)
	{
		return obj.has(field) && !obj.get(field).isJsonNull() && obj.get(field).isJsonPrimitive()
			? obj.get(field).getAsString() : null;
	}
}

package com.killclog;

import java.util.function.BinaryOperator;
import java.util.function.Supplier;

/**
 * The killclog.com sync's one slot: one attempt in the air at a time, numbered, until its round trip completes; the
 * push asked for meanwhile, held whole (several go as one, by the push's own rule) and handed over once the slot frees;
 * and the era that an opt-out, a logout or a shutdown moves on, so anything begun before can never claim the slot,
 * commit its request or speak; and Automatic sync's own era, which turning it off moves, so an automatic push asked
 * before can never claim, stay live or commit either. Every release names its attempt, so a stale one can never free
 * a newer one's slot.
 * Its own lock, so the final request enqueue and a cancellation have one total order.
 */
final class KillclogSyncGate<P>
{
	static final int BUSY = -1;
	static final int STALE = -2;

	// How two pushes waiting go as one.
	private final BinaryOperator<P> merge;
	private int era;
	private int automaticEra;
	private int attempts;
	// The attempt in the air (0 for none), its eras (the automatic one NONE for a deliberate push) and its push.
	private int inFlight;
	private int inFlightEra;
	private int inFlightAutomaticEra;
	private P queued;
	static final int DELIBERATE = -1;

	KillclogSyncGate(BinaryOperator<P> merge)
	{
		this.merge = merge;
	}

	/** The era now; a push carries the one it was asked in. */
	synchronized int era()
	{
		return era;
	}

	/** Automatic sync's era now; an automatic push carries the one it was asked in. */
	synchronized int automaticEra()
	{
		return automaticEra;
	}

	/**
	 * Claim the slot for a push asked in {@code pushEra} and, for an automatic one, {@code pushAutomaticEra}
	 * ({@link #DELIBERATE} for a click's or a character's): the attempt's number, or {@link #STALE} when an era it was
	 * asked in has passed (it is dropped), or {@link #BUSY} while another attempt is in the air (it waits, merged with
	 * any already waiting).
	 */
	synchronized int begin(P push, int pushEra, int pushAutomaticEra)
	{
		if (pushEra != era || pushAutomaticEra != DELIBERATE && pushAutomaticEra != automaticEra)
		{
			return STALE;
		}
		if (inFlight != 0)
		{
			queued = queued == null ? push : merge.apply(queued, push);
			return BUSY;
		}
		inFlight = ++attempts;
		inFlightEra = era;
		inFlightAutomaticEra = pushAutomaticEra;
		return inFlight;
	}

	/** Whether this attempt is the one in the air, in its eras: its work may go on. */
	synchronized boolean live(int attempt)
	{
		return attempt == inFlight && inFlightEra == era
			&& (inFlightAutomaticEra == DELIBERATE || inFlightAutomaticEra == automaticEra);
	}

	/**
	 * Commit the final non-blocking request enqueue only while this attempt is live. One lock with {@link #cancel()},
	 * so an opt-out has one total order with the enqueue: before means no request; after means the request already
	 * enqueued stays silent on completion.
	 */
	synchronized <T> T commitIfCurrent(int attempt, Supplier<T> commit)
	{
		return live(attempt) ? commit.get() : null;
	}

	/** Whether an attempt holds the slot. */
	synchronized boolean busy()
	{
		return inFlight != 0;
	}

	/**
	 * The attempt's round trip is over, or it never went: its slot frees, if it is still the one holding it. True when
	 * it was live (its outcome may be acted on and said).
	 */
	synchronized boolean release(int attempt)
	{
		if (attempt != inFlight)
		{
			return false;
		}
		boolean wasLive = live(attempt);
		inFlight = 0;
		return wasLive;
	}

	/** The push that waited for the slot, no longer waiting; null for none. */
	synchronized P takeQueued()
	{
		P push = queued;
		queued = null;
		return push;
	}

	/**
	 * Automatic sync off: its era moves, so no automatic push asked before claims, stays live or commits; one waiting
	 * for the slot is refused when it comes to claim it. The automatic attempt this silenced, or 0.
	 */
	synchronized int withdrawAutomatic()
	{
		boolean quieted = inFlight != 0 && inFlightAutomaticEra == automaticEra;
		automaticEra++;
		return quieted ? inFlight : 0;
	}

	/** Opt-out, logout, shutdown: the era moves on, so nothing begun before claims, commits or speaks; the new era. */
	synchronized int cancel()
	{
		queued = null;
		return ++era;
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;

@Slf4j
final class LiveClogSync
{
	// A kill message within this many ticks of the unlock message is treated
	// as its cause; beyond it the unlock stays provenance-less rather than
	// guessing (skilling clogs, chest opens, and pet drops have no kc).
	private static final int KILL_CONTEXT_MAX_TICKS = 5;

	private boolean needsFirstSyncWarned;
	private ClogUnlockParser.KillContext lastKill;
	private int lastKillTick = -1;

	void rememberKill(ClogUnlockParser.KillContext kill, int tick)
	{
		lastKill = kill;
		lastKillTick = tick;
	}

	void handleUnlock(String itemName, int broadcastObtained, int broadcastTotal,
		Client client, ItemManager itemManager,
		ClogIndex clogIndex, LocalClogCache localClogCache,
		KillClogChatNotifier chatNotifier,
		Consumer<String> panelRefresh, boolean countersSettled)
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}

		if (!clogIndex.ensureParsed(client, itemManager))
		{
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Kill Clog could not read your Collection Log. Open it to update it.");
			return;
		}

		String playerName = local.getName();
		if (!localClogCache.serving(playerName))
		{
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Kill Clog is still checking this account. Open your Collection Log to update it.");
			return;
		}
		if (!localClogCache.hasDataFor(playerName))
		{
			warnFirstSync(chatNotifier);
			return;
		}

		List<Integer> missingItemIds = missingItemIds(itemName, playerName, clogIndex, localClogCache, chatNotifier);
		if (missingItemIds == null)
		{
			return;
		}

		// Attach the causing kill when one landed just before the unlock.
		ClogUnlockParser.KillContext kill = null;
		if (lastKill != null && lastKillTick >= 0
			&& client.getTickCount() - lastKillTick <= KILL_CONTEXT_MAX_TICKS)
		{
			kill = lastKill;
		}

		boolean changed = false;
		for (int itemId : missingItemIds)
		{
			changed |= localClogCache.mergeObtainedItem(playerName, itemId,
				clogIndex.categoryKeysForItem(itemId), clogIndex.categoryItems(),
				kill != null ? kill.kc : 0, kill != null ? kill.boss : null);
		}

		// Game counters own the scalar; unlock messages only add item history.
		// A lagging varp must not undo a newer broadcast count, and right after a
		// hop the varps may still hold the last world's. Full log refresh remains
		// the downward authority.
		int liveObtained = Math.max(countersSettled ? client.getVarpValue(VarPlayerID.COLLECTION_COUNT) : 0, broadcastObtained);
		int liveTotal = Math.max(countersSettled ? client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX) : 0, broadcastTotal);
		localClogCache.updateTotalsUpward(playerName, liveObtained, liveTotal);

		if (changed)
		{
			resetFirstSyncWarning();
			chatNotifier.send(ChatNotice.NEW_DROP,
				"Added " + itemName + " to Kill Clog");
			SwingUtilities.invokeLater(() -> panelRefresh.accept(playerName));
		}
	}

	void resetFirstSyncWarning()
	{
		needsFirstSyncWarned = false;
	}

	private void warnFirstSync(KillClogChatNotifier chatNotifier)
	{
		if (!needsFirstSyncWarned)
		{
			needsFirstSyncWarned = true;
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Open your Collection Log to set up Kill Clog automatically.");
		}
	}

	private List<Integer> missingItemIds(String itemName, String playerName,
		ClogIndex clogIndex, LocalClogCache localClogCache,
		KillClogChatNotifier chatNotifier)
	{
		String itemKey = ClogUnlockParser.normalizeItemName(itemName);
		List<Integer> itemIds = clogIndex.itemIdsForName(itemKey);
		if (itemIds == null || itemIds.isEmpty())
		{
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Could not match " + itemName + ". Open your Collection Log to update it.");
			log.debug("Live clog sync could not match item '{}'", itemName);
			return null;
		}

		List<Integer> missingItemIds = new ArrayList<>();
		for (int itemId : itemIds)
		{
			if (!localClogCache.hasObtainedItem(playerName, itemId, clogIndex.categoryKeysForItem(itemId)))
			{
				missingItemIds.add(itemId);
			}
		}
		if (missingItemIds.size() > 1)
		{
			localClogCache.rememberPendingUnlock(playerName, missingItemIds);
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Could not match " + itemName + " exactly. Open your Collection Log to update it.");
			log.debug("Live clog sync found ambiguous item '{}' ({})", itemName, missingItemIds);
			return null;
		}
		return missingItemIds;
	}
}

package com.killclog;

import com.google.gson.Gson;
import java.io.IOException;
import java.time.Instant;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.stream.Stream;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Multi-account, disk-backed Combat Achievement cache for this PC's own accounts.
 *
 * <p>Self CA is read straight from the game (per-tier completed counts via
 * varbits) and kept per account in {@code ca/<hash>.json}. It is the
 * authoritative source for the logged-in player and needs no RuneProfile;
 * other players come from {@link RuneProfileService}'s API. The folder loads
 * whole on this cache's disk thread when it opens.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
public class LocalCaCache
{
	// Captures by own-log file name, which carries the account hash.
	private final Map<String, CaData> accounts = new ConcurrentHashMap<>();
	private final Gson gson;
	// ca/ in the plugin's folder; null keeps captures in memory for the session.
	@Nullable
	private volatile Filepath folder;
	private volatile String activePlayer;
	// The logged-in account's file, known from its first capture this session.
	private volatile String activeFile;
	private final ExecutorService diskWriter;

	// Plugin-owned live catalog, set at startup like the panel's ClogIndex.
	@Nullable private volatile CaCatalog caCatalog;

	@Inject
	public LocalCaCache(Gson gson)
	{
		this(gson, newDiskWriter());
	}

	/** Load ca/ on the disk thread; saves queued behind it land in the same folder. */
	void open(@Nullable Filepath folder)
	{
		diskWriter.execute(() ->
		{
			if (folder != null && folder.isDirectory())
			{
				try (Stream<Filepath> walk = folder.walk(1))
				{
					walk.filter(f -> f.getFileName().matches("[0-9a-f]{16}\\.json")).forEach(file ->
					{
						CaData data = StoreFiles.read(gson, file, CaData.class);
						if (data != null && data.completed != null && !data.completed.isEmpty())
						{
							accounts.putIfAbsent(file.getFileName(), data);
						}
					});
				}
				catch (IOException | RuntimeException e)
				{
					log.warn("Kill Clog could not read its CA folder: {}", e.getMessage());
				}
			}
			this.folder = folder;
		});
	}

	public void setCaCatalog(@Nullable CaCatalog caCatalog)
	{
		this.caCatalog = caCatalog;
	}

	private static ExecutorService newDiskWriter()
	{
		// One queue across enable/disable cycles. The daemon exits when idle,
		// so a disabled singleton does not retain a worker thread.
		return new ThreadPoolExecutor(0, 1, 30, TimeUnit.SECONDS,
			new LinkedBlockingQueue<>(), r ->
		{
			Thread t = new Thread(r, "kill-clog-ca-disk");
			t.setDaemon(true);
			return t;
		});
	}

	/** Accepted writes drain in order, including across an immediate re-enable. */
	public void shutdown()
	{
		activePlayer = null;
		activeFile = null;
		caCatalog = null;
	}

	/** The login whose tiers this store serves, from the session tracker. */
	public void serve(Session session)
	{
		String name = session.getName();
		if (name == null || !isActivePlayer(name))
		{
			activeFile = null;
		}
		activePlayer = name;
	}

	public boolean isActivePlayer(String name)
	{
		return RsnInputPolicy.sameName(activePlayer, name);
	}

	public boolean hasDataFor(String name)
	{
		return active(name) != null;
	}

	@Nullable
	private CaData active(String name)
	{
		String file = activeFile;
		return file != null && isActivePlayer(name) ? accounts.get(file) : null;
	}

	/** Store per-tier completed counts for an account (sourced from game varbits) and persist. */
	public synchronized void cacheResult(String name, long accountHash, Map<CombatAchievementTier, Integer> completed)
	{
		if (name == null || completed == null || accountHash == -1)
		{
			return;
		}
		String file = StoreFiles.ownFileName(Long.toString(accountHash));
		activeFile = file;
		Map<String, Integer> completedByTier = new LinkedHashMap<>();
		for (Map.Entry<CombatAchievementTier, Integer> entry : completed.entrySet())
		{
			completedByTier.put(entry.getKey().name(), entry.getValue());
		}
		CaData existing = accounts.get(file);
		if (existing != null && !existing.saveFailed && completedByTier.equals(existing.completed)
			&& name.equals(existing.playerName))
		{
			return;
		}

		CaData data = new CaData();
		data.playerName = name;
		data.lastUpdated = Instant.now().toString();
		data.completed = completedByTier;
		accounts.put(file, data);
		try
		{
			diskWriter.execute(() ->
			{
				Filepath folder = this.folder;
				try
				{
					if (folder == null)
					{
						// A memory-only session holds CA in memory: nothing to save, and nothing failed.
						return;
					}
					folder.createDirectories();
					StoreFiles.write(gson, folder, folder.join(file), data);
				}
				catch (IOException | RuntimeException e)
				{
					data.saveFailed = true;
					log.warn("Failed to save CA cache for '{}': {}", name, e.getMessage());
				}
			});
		}
		catch (RejectedExecutionException ignored)
		{
			data.saveFailed = true;
			log.debug("CA disk write rejected (executor shutting down)");
		}
	}

	/** Stored CA for the logged-in player as a {@link CombatAchievementResult}, or null if none is held. */
	public CombatAchievementResult getCached(String name)
	{
		CaData data = active(name);
		if (data == null || data.completed == null || data.completed.isEmpty())
		{
			return null;
		}
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		for (Map.Entry<String, Integer> entry : data.completed.entrySet())
		{
			CombatAchievementTier tier = CombatAchievementTier.fromName(entry.getKey());
			if (tier != null && entry.getValue() != null)
			{
				completed.put(tier, entry.getValue());
			}
		}
		if (completed.isEmpty())
		{
			return null;
		}
		Map<CombatAchievementTier, Integer> totals = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			totals.put(tier, tier.totalTasks());
		}
		CaCatalog catalog = caCatalog;
		return CombatAchievementResult.of(completed, totals,
			catalog != null ? catalog.totals() : null);
	}

	static class CaData
	{
		transient volatile boolean saveFailed;
		String playerName;
		String lastUpdated;
		Map<String, Integer> completed;
	}
}

package com.killclog;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

final class LocalCaReader
{
	boolean isCaVarbit(int id)
	{
		// Each varbit's change arrives with its own id; a plain varp change (id -1) is never a CA total.
		return id == VarbitID.CA_TOTAL_TASKS_COMPLETED_EASY
			|| id == VarbitID.CA_TOTAL_TASKS_COMPLETED_MEDIUM
			|| id == VarbitID.CA_TOTAL_TASKS_COMPLETED_HARD
			|| id == VarbitID.CA_TOTAL_TASKS_COMPLETED_ELITE
			|| id == VarbitID.CA_TOTAL_TASKS_COMPLETED_MASTER
			|| id == VarbitID.CA_TOTAL_TASKS_COMPLETED_GRANDMASTER;
	}

	/** The logged-in player's tiers as the game counts them now, kept for this login. */
	boolean capture(Client client, Session session, LocalCaCache localCaCache)
	{
		if (!session.loggedIn())
		{
			return false;
		}
		localCaCache.cacheResult(session.getName(), session.getAccountHash(), completed(client));
		return true;
	}

	private Map<CombatAchievementTier, Integer> completed(Client client)
	{
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		completed.put(CombatAchievementTier.EASY, client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_EASY));
		completed.put(CombatAchievementTier.MEDIUM, client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_MEDIUM));
		completed.put(CombatAchievementTier.HARD, client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_HARD));
		completed.put(CombatAchievementTier.ELITE, client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_ELITE));
		completed.put(CombatAchievementTier.MASTER, client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_MASTER));
		completed.put(CombatAchievementTier.GRANDMASTER,
			client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_GRANDMASTER));
		return completed;
	}
}

package com.killclog;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.attribute.FileTime;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.Callable;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Multi-account, disk-backed collection log store.
 *
 * <p>Each account that captures on this PC has one own log, {@code <hash>.json},
 * written only by the client logged into that account; other players' lookups
 * live apart in {@code lookups/<name>.json} and can never ship. The folder is
 * opened on this store's disk thread: RuneLite's own move, then every own log
 * and the newest lookups load into memory ({@link StoreFiles} reads and writes
 * them). Until that finishes the store is not ready and serves nothing; after
 * it, reads and writes are memory-only and disk only receives debounced saves,
 * except that each login reads its account's own log fresh, on the disk thread:
 * another client on this PC may have played that account since this one loaded it.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
public class LocalClogCache
{
	// Lookups kept, in memory and on disk: an instant repaint of a name looked up again, and a fallback while Temple is
	// down. A lookup fetches fresh either way, so this is a convenience, sized for it.
	private static final int LOOKUP_CAP = 64;
	private static final long DEBOUNCE_MS = 500;
	// A name two local accounts both carry maps to nothing.
	private static final String AMBIGUOUS = "";

	private final Gson gson;
	private final ScheduledExecutorService diskWriter;
	private final CompletableFuture<Filepath> opened = new CompletableFuture<>();
	// The opened folder; null keeps the store in memory.
	@Nullable
	private volatile Filepath logs;
	private volatile boolean ready;

	// Own logs by account hash, and the advisory name index over them.
	private final Map<String, PlayerClogData> own = new HashMap<>();
	private final Map<String, String> ownerByName = new HashMap<>();
	private final Map<String, PlayerClogData> lookups = new LinkedHashMap<String, PlayerClogData>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, PlayerClogData> eldest)
		{
			if (size() <= LOOKUP_CAP)
			{
				return false;
			}
			forgetLookupFile(eldest.getValue().playerName);
			return true;
		}
	};

	// The login this store serves, as the session tracker hands it over.
	private volatile Session session = Session.none(0);
	// The logged-in account, set once its own log is serving.
	private volatile String activeHashKey;
	private final AtomicReference<String> pendingRenameNotice = new AtomicReference<>();
	// The accounts whose own log this session has read fresh from disk, and those being read.
	private final java.util.Set<String> readThisSession = ConcurrentHashMap.newKeySet();
	private final java.util.Set<String> reading = ConcurrentHashMap.newKeySet();

	// Debounced saves by file: bursts of category navigation collapse to one write.
	private final Map<String, Runnable> pendingByFile = new ConcurrentHashMap<>();
	private final Map<String, PlayerClogData> unsavedFiles = new ConcurrentHashMap<>();

	@Setter
	private volatile Runnable firstPartyChangedListener;

	@Inject
	public LocalClogCache(Gson gson)
	{
		this(gson, newDiskWriter());
	}

	/** A League's own store, opened at once in that League's folder. */
	LocalClogCache(Gson gson, @Nullable Filepath folder)
	{
		this(gson, newDiskWriter());
		open(() -> folder);
	}

	private static ScheduledExecutorService newDiskWriter()
	{
		ScheduledThreadPoolExecutor writer = new ScheduledThreadPoolExecutor(1, r ->
		{
			Thread t = new Thread(r, "kill-clog-disk");
			t.setDaemon(true);
			return t;
		});
		writer.setKeepAliveTime(30, TimeUnit.SECONDS);
		writer.allowCoreThreadTimeOut(true);
		return writer;
	}

	private static String cacheKey(String playerName)
	{
		return RsnInputPolicy.key(playerName);
	}

	/**
	 * Resolve the folder and load it, all on the disk thread. A folder that
	 * cannot be opened keeps this session in memory; the next start retries.
	 */
	void open(Callable<Filepath> folder)
	{
		diskWriter.execute(() ->
		{
			Filepath resolved;
			try
			{
				resolved = folder.call();
			}
			catch (Exception e)
			{
				resolved = null;
				log.warn("Kill Clog data folder unavailable this session: {}", e.getMessage());
			}
			load(resolved);
		});
	}

	/** The opened folder, once the store is ready; null for a memory-only session. */
	CompletableFuture<Filepath> folder()
	{
		return opened;
	}

	private void load(@Nullable Filepath folder)
	{
		Map<String, PlayerClogData> loadedOwn = new HashMap<>();
		List<PlayerClogData> loadedLookups = new ArrayList<>();
		if (folder != null)
		{
			try
			{
				// RuneLite makes plugin-data, not this folder: a fresh install's first start has none yet.
				folder.createDirectories();
				for (Filepath file : StoreFiles.list(folder))
				{
					if (!file.getFileName().matches("[0-9a-f]{16}\\.json"))
					{
						continue;
					}
					PlayerClogData data = readRecord(file);
					if (data == null || !file.getFileName().equals(ownFile(data.ownerHash)))
					{
						// Damaged bytes are kept aside, never overwritten by the next save. A second client starting
						// on this folder may move them first; either way the rest still loads, so no account's log is
						// left unread and then saved over.
						setAside(folder, file);
						continue;
					}
					loadedOwn.put(data.ownerHash, data);
				}
				Filepath lookupDir = folder.join(StoreFiles.LOOKUPS);
				if (lookupDir.isDirectory())
				{
					List<Filepath> files = StoreFiles.list(lookupDir);
					files.sort(Comparator.comparing(LocalClogCache::modified).reversed());
					for (Filepath file : files.subList(0, Math.min(LOOKUP_CAP, files.size())))
					{
						PlayerClogData data = readRecord(file);
						if (data != null && data.playerName != null)
						{
							loadedLookups.add(0, data);
						}
					}
					// The cap holds on disk too: every name looked up, or seen running a chat command, left a file
					// for good, about 76 KB each.
					for (Filepath file : files.subList(Math.min(LOOKUP_CAP, files.size()), files.size()))
					{
						file.deleteIfExists();
					}
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Kill Clog could not read its folder: {}", e.getMessage());
			}
		}
		synchronized (this)
		{
			// Anything written while loading is newer and stays.
			loadedOwn.forEach(own::putIfAbsent);
			for (PlayerClogData data : loadedLookups)
			{
				lookups.putIfAbsent(cacheKey(data.playerName), data);
			}
			ownerByName.clear();
			own.forEach((hash, data) -> index(data.playerName, hash));
			logs = folder;
			ready = true;
		}
		opened.complete(folder);
	}

	/** An own log's file name, or null for a stamp that is not an account hash. */
	@Nullable
	static String ownFile(String hashKey)
	{
		try
		{
			return StoreFiles.ownFileName(hashKey);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static FileTime modified(Filepath file)
	{
		try
		{
			return file.getLastModifiedTime();
		}
		catch (IOException e)
		{
			return FileTime.fromMillis(0);
		}
	}

	private PlayerClogData readRecord(Filepath file)
	{
		PlayerClogData data = StoreFiles.read(gson, file, PlayerClogData.class);
		if (data == null || data.categories == null)
		{
			return null;
		}
		// Gson builds plain maps; cache writes and EDT reads share these.
		data.categories = new ConcurrentHashMap<>(data.categories);
		data.obtained = data.obtained != null ? new ConcurrentHashMap<>(data.obtained) : new ConcurrentHashMap<>();
		// Files written before live unlocks bumped lastChanged can hold items
		// newer than the stamp; heal on load so the notice never trails the shelf.
		bumpLastChanged(data, newestObtainedDate(data.obtained));
		return data;
	}

	private void index(String name, String hash)
	{
		if (name != null)
		{
			ownerByName.merge(cacheKey(name), hash, (a, b) -> a.equals(b) ? a : AMBIGUOUS);
		}
	}

	/** An account's log under the name it wears now: a name it wore before no longer points at it. */
	private void reindex(String name, String hash)
	{
		ownerByName.values().removeIf(hash::equals);
		index(name, hash);
	}

	/**
	 * The login this store serves, from the session tracker, and the account taking up its own log: false until the
	 * store is ready and the log has been read fresh for this login, so the plugin asks again each tick. A different
	 * stored name is a name change: the log follows the account, and one chat line says so. A new session ends the
	 * last one first: its account, its fresh reads and any notice still queued.
	 */
	public synchronized boolean serve(Session next)
	{
		if (next.getNumber() != session.getNumber())
		{
			activeHashKey = null;
			readThisSession.clear();
			pendingRenameNotice.set(null);
		}
		session = next;
		if (!ready || !next.loggedIn())
		{
			return false;
		}
		String hash = Long.toString(next.getAccountHash());
		if (logs != null && !readThisSession.contains(hash))
		{
			readFresh(hash);
			return false;
		}
		if (hash.equals(activeHashKey))
		{
			return true;
		}
		String name = next.getName();
		activeHashKey = hash;
		PlayerClogData data = own.get(activeHashKey);
		if (data != null && data.playerName != null && !cacheKey(data.playerName).equals(cacheKey(name)))
		{
			pendingRenameNotice.set(data.playerName);
			data.playerName = name;
			reindex(name, activeHashKey);
			submitSave(activeHashKey, true, data);
		}
		return true;
	}

	/**
	 * Reads an account's own log from disk on the disk thread, behind any save this client still has queued for it, so
	 * the newest copy serves: another client may have played the account since this one loaded the folder, and an
	 * older copy here would save over what it captured, a drop's date and kill count included. A copy this client
	 * has not saved yet is its own newest and stays.
	 */
	private void readFresh(String hash)
	{
		if (!reading.add(hash))
		{
			return;
		}
		long number = session.getNumber();
		Runnable read = () ->
		{
			try
			{
				String file = ownFile(hash);
				Filepath folder = logs;
				Filepath path = folder != null && file != null ? folder.join(file) : null;
				boolean onDisk = path != null && !unsavedFiles.containsKey(file) && path.isFile();
				PlayerClogData data = onDisk ? readRecord(path) : null;
				if (onDisk && (data == null || !hash.equals(data.ownerHash)))
				{
					// Damaged since the folder loaded: kept aside as load() keeps it, and the copy in memory serves.
					setAside(folder, path);
				}
				synchronized (this)
				{
					if (data != null && hash.equals(data.ownerHash) && !unsavedFiles.containsKey(file))
					{
						own.put(hash, data);
						// Renamed on another client: the log names the account as it is now.
						reindex(data.playerName, hash);
					}
				}
			}
			finally
			{
				reading.remove(hash);
				if (session.getNumber() == number)
				{
					readThisSession.add(hash);
				}
			}
		};
		try
		{
			diskWriter.execute(read);
		}
		catch (RejectedExecutionException e)
		{
			// A store closing for good serves what it holds.
			reading.remove(hash);
			readThisSession.add(hash);
		}
	}

	/** One chat line per name change, consumed by the plugin's tick. */
	public String consumeRenameNotice()
	{
		return pendingRenameNotice.getAndSet(null);
	}

	/** The sync pre-flight: this store still serves that login, with its account's own log. */
	public synchronized boolean servesAccount(Session expected)
	{
		return expected.getNumber() == session.getNumber() && serving(expected.getName())
			&& Long.toString(expected.getAccountHash()).equals(activeHashKey);
	}

	/** A side effect that happens only while that login is the one served, under the same monitor as {@link #serve}. */
	public synchronized <T> T commitIfSessionCurrent(Session expected, Supplier<T> commit)
	{
		return expected.getNumber() == session.getNumber() ? commit.get() : null;
	}

	/** Flush accepted saves on the same queue; a new session cannot overtake them. */
	public void shutdown()
	{
		diskWriter.execute(() -> new ArrayList<>(pendingByFile.keySet()).forEach(this::flush));
	}

	/** A League store that is done for good: flush its saves, then let its writer end. */
	public void close()
	{
		shutdown();
		diskWriter.shutdown();
	}

	/** Whether this name is the logged-in player's, whose captures this store takes. */
	public boolean isActivePlayer(String name)
	{
		return RsnInputPolicy.sameName(session.getName(), name);
	}

	/** Whether this name's own log is the one serving: the logged-in player's, taken up for this login. */
	public synchronized boolean serving(String name)
	{
		return ready && activeHashKey != null && isActivePlayer(name);
	}

	/** The serving account's own log, when this name is the one it serves. */
	private PlayerClogData ownLog(String name)
	{
		return serving(name) ? own.get(activeHashKey) : null;
	}

	/** What a read serves: your own log for the logged-in name, else a lookup, else a local alt's own log. */
	private PlayerClogData record(String name)
	{
		if (!ready || name == null)
		{
			return null;
		}
		if (isActivePlayer(name))
		{
			return ownLog(name);
		}
		String key = cacheKey(name);
		PlayerClogData lookup = lookups.get(key);
		if (lookup != null)
		{
			return lookup;
		}
		String hash = ownerByName.get(key);
		return hash != null ? own.get(hash) : null;
	}

	/**
	 * Provider-lane write (Temple/RuneProfile snapshots for looked-up names).
	 * Never marks first-party and never fires the sync trigger: provider data
	 * lands in the display cache but can never ride a killclog.com push.
	 */
	public synchronized void cacheResult(ClogResult result)
	{
		cacheResult(result, false);
	}

	/**
	 * First-party bulk-capture landing (the Collection Log Search walk). Marks every
	 * obtained item as client-observed and fires the sync trigger - the
	 * largest payload of all must schedule a push like any other capture.
	 */
	public synchronized void cacheFirstPartyResult(ClogResult result)
	{
		cacheResult(result, true);
	}

	private synchronized void cacheResult(ClogResult result, boolean firstParty)
	{
		if (result == null || result.getPlayerName() == null || !ready)
		{
			return;
		}

		String name = result.getPlayerName();
		if (firstParty && !serving(name))
		{
			// Captures wait for the account's own log, as they always waited for its identity.
			return;
		}
		// Only an account's own captures enter its own log; provider results, the
		// logged-in player's included, stay lookups. That is the whole trust rule.
		Map<String, PlayerClogData> store = firstParty ? own : lookups;
		String slot = firstParty ? activeHashKey : cacheKey(name);

		// Preserve varp-sourced totals if they are higher than public providers report.
		PlayerClogData existing = store.get(slot);

		PlayerClogData data = existing != null ? shallowCopy(existing) : new PlayerClogData();
		data.playerName = name;
		data.lastUpdated = Instant.now().toString();
		data.uniqueObtained = result.getUniqueObtained();
		data.uniqueTotal = result.getUniqueTotal();
		if (firstParty && data.uniqueTotal <= 0 && existing != null)
		{
			// Zero is not a settled catalog size; retain the last known total.
			data.uniqueTotal = existing.uniqueTotal;
		}
		if (existing != null && !firstParty)
		{
			if (existing.uniqueObtained > data.uniqueObtained)
			{
				data.uniqueObtained = existing.uniqueObtained;
			}
			if (existing.uniqueTotal > data.uniqueTotal)
			{
				data.uniqueTotal = existing.uniqueTotal;
			}
		}
		// Upward-only, like the totals above: a provider snapshot must not
		// drag the last-updated notice behind a live merge stamped moments ago.
		bumpLastChanged(data, result.getLastChanged());
		if (result.getProviderAccountType() != null)
		{
			data.providerAccountType = result.getProviderAccountType();
		}
		// A provider result builds on what the lookup held; a capture replaces it whole.
		boolean builds = !firstParty && existing != null;
		data.obtained = builds ? new ConcurrentHashMap<>(data.obtained) : new ConcurrentHashMap<>();
		data.categories = builds ? new ConcurrentHashMap<>(data.categories) : new ConcurrentHashMap<>();

		for (Map.Entry<String, List<ClogResult.ClogItem>> entry
			: result.getObtainedItems().entrySet())
		{
			String cat = entry.getKey();
			data.obtained.put(cat, preserveItemMetadata(entry.getValue(),
				existing != null ? existing.obtained.get(cat) : null));
		}
		// Page lists are the catalog's, shared and never changed in place.
		data.categories.putAll(result.getCategoryItems());

		if (firstParty)
		{
			data.firstPartySetupComplete = true;
			data.pendingUnlocks = PendingClogUnlock.reconcile(data.pendingUnlocks, data.obtained, activeHashKey);
			bumpLastChanged(data, newestObtainedDate(data.obtained));
		}
		// An unchanged full walk needs neither a disk write nor a web-sync signal.
		if (firstParty && sameCapture(data, existing))
		{
			if (unsavedFiles.containsKey(fileKey(slot, true, name)))
			{
				submitSave(slot, true, existing);
			}
			return;
		}
		store.put(slot, data);
		if (firstParty && existing == null)
		{
			data.ownerHash = slot;
			index(name, slot);
		}
		submitSave(slot, firstParty, data);
		log.debug("Cached clog data for '{}' ({} categories)", name, data.obtained.size());
		if (firstParty)
		{
			notifyFirstPartyChanged();
		}
	}

	private static boolean sameCapture(PlayerClogData data, PlayerClogData prior)
	{
		if (prior == null || data.uniqueObtained != prior.uniqueObtained
			|| data.uniqueTotal != prior.uniqueTotal
			|| !Objects.equals(data.playerName, prior.playerName)
			|| !Objects.equals(data.ownerHash, prior.ownerHash)
			|| data.providerAccountType != prior.providerAccountType
			|| !Objects.equals(data.lastChanged, prior.lastChanged)
			|| !Objects.equals(data.pendingUnlocks, prior.pendingUnlocks)
			|| data.firstPartySetupComplete != prior.firstPartySetupComplete
			|| !Objects.equals(data.categories, prior.categories))
		{
			return false;
		}
		return Objects.equals(data.obtained, prior.obtained);
	}



	// Fires after any in-client observation lands (bulk page capture, live
	// unlock), whatever path delivered it - the killclog.com sync trigger
	// lives here at the data seam so no capture route can be forgotten.
	// The listener only schedules a debounced task; it must stay cheap and
	// must not call back into this cache.
	private void notifyFirstPartyChanged()
	{
		Runnable listener = firstPartyChangedListener;
		if (listener != null)
		{
			listener.run();
		}
	}


	/**
	 * Replace an obtained list while carrying forward per-item metadata the
	 * incoming entries lack. Widget captures and provider results rebuild
	 * items bare (no date, no obtained-at kc), and a resync must never cost
	 * a drop its provenance. Incoming values win whenever present.
	 */
	private static List<ClogResult.ClogItem> preserveItemMetadata(
		List<ClogResult.ClogItem> incoming, List<ClogResult.ClogItem> existing)
	{
		if (incoming == null)
		{
			return new ArrayList<>();
		}
		if (existing == null || existing.isEmpty())
		{
			return new ArrayList<>(incoming);
		}
		Map<Integer, ClogResult.ClogItem> priorById = new HashMap<>();
		for (ClogResult.ClogItem item : existing)
		{
			priorById.putIfAbsent(item.getId(), item);
		}
		List<ClogResult.ClogItem> merged = new ArrayList<>(incoming.size());
		for (ClogResult.ClogItem item : incoming)
		{
			merged.add(item.filledFrom(priorById.get(item.getId())));
		}
		return merged;
	}

	void rememberPendingUnlock(String playerName, List<Integer> candidates)
	{
		rememberPendingUnlock(playerName, candidates, liveUnlockDate());
	}

	synchronized void rememberPendingUnlock(String playerName, List<Integer> candidates, String date)
	{
		if (candidates == null || candidates.size() < 2 || candidates.size() > 256) return;
		// Missing candidates need a completed local baseline on the serving account.
		PlayerClogData data = ownLog(playerName);
		if (data == null || !data.firstPartySetupComplete) return;
		String validDate = ClogDates.local(date);
		if (validDate == null) return;
		PendingClogUnlock event = new PendingClogUnlock(candidates, validDate, activeHashKey);
		List<PendingClogUnlock> pending = data.pendingUnlocks != null
			? new ArrayList<>(data.pendingUnlocks) : new ArrayList<>();
		pending.removeIf(prior -> prior == null || !activeHashKey.equals(prior.ownerHash)
			|| ClogDates.iso(prior.date) == null);
		// Personal and clan notifications describe the same still-unresolved unlock.
		for (PendingClogUnlock prior : pending)
		{
			if (prior != null && event.candidates.equals(prior.candidates)) return;
		}
		while (pending.size() >= 32) pending.remove(0);
		pending.add(event);
		data.pendingUnlocks = pending;
		submitSave(activeHashKey, true, data);
	}

	public synchronized boolean mergeObtainedItem(String playerName, int itemId,
		List<String> categoryKeys, Map<String, List<Integer>> categoryItems,
		int obtainedAtKc, String obtainedFrom)
	{
		PlayerClogData data = ownLog(playerName);
		if (data == null || categoryKeys == null || categoryItems == null)
		{
			return false;
		}

		// Record item history here; game counters update the unique total separately.
		boolean changed = false;
		for (String categoryKey : categoryKeys)
		{
			List<Integer> allItems = categoryItems.get(categoryKey);
			if (allItems == null || !allItems.contains(itemId))
			{
				continue;
			}

			data.categories.put(categoryKey, new ArrayList<>(allItems));
			List<ClogResult.ClogItem> obtained = new ArrayList<>(
				data.obtained.getOrDefault(categoryKey, Collections.emptyList()));
			boolean alreadyObtained = false;
			for (ClogResult.ClogItem item : obtained)
			{
				if (item.getId() == itemId)
				{
					alreadyObtained = true;
					break;
				}
			}
			if (!alreadyObtained)
			{
				// Dated at the moment it happens: undated items are invisible
				// to the recents shelf. Format matches the provider date strings
				// so sorting and display stay uniform.
				String unlockDate = liveUnlockDate();
				obtained.add(new ClogResult.ClogItem(itemId, 1, unlockDate, obtainedAtKc, obtainedFrom));
				data.obtained.put(categoryKey, obtained);
				// The summary's last-updated notice reads lastChanged; a live
				// unlock is exactly such a change.
				bumpLastChanged(data, unlockDate);
				changed = true;
			}
		}

		if (changed)
		{
			data.lastUpdated = Instant.now().toString();
			submitSave(activeHashKey, true, data);
			log.debug("Merged live clog item {} for '{}'", itemId, playerName);
			notifyFirstPartyChanged();
		}
		return changed;
	}

	private static final DateTimeFormatter LIVE_UNLOCK_DATE_FMT =
		DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

	private static String liveUnlockDate()
	{
		return LocalDateTime.now(ZoneOffset.UTC).format(LIVE_UNLOCK_DATE_FMT);
	}

	// Upward-only. Every date here shares the yyyy-MM-dd HH:mm:ss shape, so
	// string order is chronological order.
	private static void bumpLastChanged(PlayerClogData data, String date)
	{
		data.lastChanged = later(data.lastChanged, date);
	}

	/** The later of two dates, either of which may be missing. */
	private static String later(String a, String b)
	{
		return a == null || (b != null && b.compareTo(a) > 0) ? b : a;
	}

	/** Newest obtained-item date across all categories, or null when none carry one. */
	/* package */ static String newestObtainedDate(Map<String, List<ClogResult.ClogItem>> obtained)
	{
		String newest = null;
		for (List<ClogResult.ClogItem> items : obtained.values())
		{
			for (ClogResult.ClogItem item : items)
			{
				newest = later(newest, item.getDate());
			}
		}
		return newest;
	}

	/**
	 * Overlay provider dates onto cached items that have none. Membership and
	 * counts never change here: the chalice and live merges own those. This
	 * heals the recents shelf for items merged before live-unlock dating
	 * existed, or obtained while the plugin was off.
	 */
	public synchronized boolean mergeProviderDates(String playerName,
		Map<String, List<ClogResult.ClogItem>> providerItems)
	{
		if (playerName == null || providerItems == null || providerItems.isEmpty() || !ready)
		{
			return false;
		}
		boolean self = serving(playerName);
		String slot = self ? activeHashKey : cacheKey(playerName);
		PlayerClogData data = self ? own.get(slot) : lookups.get(slot);
		if (data == null)
		{
			return false;
		}

		// A Hardcore Worlds run's log takes no date from before its reset: the provider may still hold the ended run's,
		// in an answer asked before the reset too (Sol 10/27).
		String runStart = ClogDates.iso(data.runStartedAt);
		Map<Integer, String> providerDates = new HashMap<>();
		for (List<ClogResult.ClogItem> items : providerItems.values())
		{
			for (ClogResult.ClogItem item : items)
			{
				String when = runStart == null ? item.getDate() : ClogDates.iso(item.getDate());
				if (when != null && (runStart == null || Instant.parse(when).compareTo(Instant.parse(runStart)) >= 0))
				{
					providerDates.putIfAbsent(item.getId(), item.getDate());
				}
			}
		}
		if (providerDates.isEmpty())
		{
			return false;
		}

		boolean changed = false;
		for (Map.Entry<String, List<ClogResult.ClogItem>> entry : data.obtained.entrySet())
		{
			List<ClogResult.ClogItem> items = new ArrayList<>(entry.getValue());
			boolean listChanged = false;
			for (int i = 0; i < items.size(); i++)
			{
				ClogResult.ClogItem item = items.get(i);
				String date = item.getDate() == null ? providerDates.get(item.getId()) : null;
				if (date != null)
				{
					items.set(i, item.withDate(date));
					listChanged = true;
					// A healed date can outrank the notice's current stamp; the shelf
					// and the last-updated line must tell the same story.
					bumpLastChanged(data, date);
				}
			}
			if (listChanged)
			{
				data.obtained.put(entry.getKey(), items);
				changed = true;
			}
		}

		if (changed)
		{
			data.lastUpdated = Instant.now().toString();
			submitSave(slot, self, data);
			log.debug("Merged provider dates into local clog cache for '{}'", playerName);
		}
		return changed;
	}

	public synchronized boolean hasObtainedItem(String playerName, int itemId, List<String> categoryKeys)
	{
		PlayerClogData data = record(playerName);
		if (data == null || categoryKeys == null)
		{
			return false;
		}
		for (String categoryKey : categoryKeys)
		{
			List<ClogResult.ClogItem> obtained = data.obtained.get(categoryKey);
			if (obtained == null)
			{
				continue;
			}
			for (ClogResult.ClogItem item : obtained)
			{
				if (item.getId() == itemId)
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * The obtained item carrying obtained-at-kc provenance for this player, or
	 * null when the item is unobtained or its kc was never captured. Provenance
	 * is recorded from live unlocks on this client, so only accounts played
	 * here can resolve.
	 */
	public synchronized ClogResult.ClogItem provenancedItem(String playerName, List<Integer> itemIds)
	{
		PlayerClogData data = record(playerName);
		if (data == null || itemIds == null)
		{
			return null;
		}
		for (List<ClogResult.ClogItem> obtained : data.obtained.values())
		{
			for (ClogResult.ClogItem item : obtained)
			{
				if (item.getObtainedAtKc() > 0 && itemIds.contains(item.getId()))
				{
					return item;
				}
			}
		}
		return null;
	}

	/**
	 * Live-unlock totals update: raises only. The unlock-time varp read can
	 * lag the chat message by a tick, and lowering here would revert the
	 * unique bump the merge just made. Chalice sync stays the downward
	 * authority.
	 */
	public synchronized boolean updateTotalsUpward(String playerName, int obtained, int total)
	{
		PlayerClogData data = ownLog(playerName);
		if (data == null)
		{
			return false;
		}
		// Zero is no signal; without this guard a partial cache with -1 totals
		// would report 0 > -1 as a change and trigger a redundant full panel lookup.
		boolean changed = false;
		if (obtained > 0 && obtained > data.uniqueObtained)
		{
			data.uniqueObtained = obtained;
			changed = true;
		}
		if (total > 0 && total > data.uniqueTotal)
		{
			data.uniqueTotal = total;
			changed = true;
		}
		if (changed)
		{
			submitSave(activeHashKey, true, data);
			log.debug("Updated clog totals for '{}': {}/{}", playerName, data.uniqueObtained, data.uniqueTotal);
		}
		return changed;
	}

	public synchronized boolean hasDataFor(String playerName)
	{
		return record(playerName) != null;
	}

	/** Whether this player completed the full local Collection Log Search walk. */
	public synchronized boolean hasCompletedFirstPartySetupFor(String playerName)
	{
		PlayerClogData data = record(playerName);
		return data != null && data.firstPartySetupComplete;
	}

	public synchronized ClogResult toClogResult(String playerName, Map<Integer, String> itemNames)
	{
		PlayerClogData data = record(playerName);
		return data != null ? result(data, itemNames != null ? itemNames : new HashMap<>(), false) : null;
	}

	/** Defensive copies, since callers may mutate their maps. A sync payload drops empty categories. */
	private static ClogResult result(PlayerClogData data, Map<Integer, String> itemNames, boolean sync)
	{
		Map<String, List<ClogResult.ClogItem>> obtainedCopy = new HashMap<>();
		for (Map.Entry<String, List<ClogResult.ClogItem>> entry : data.obtained.entrySet())
		{
			if (!sync || !entry.getValue().isEmpty())
			{
				obtainedCopy.put(entry.getKey(), new ArrayList<>(entry.getValue()));
			}
		}
		ClogResult result = new ClogResult(data.playerName, obtainedCopy, ClogResult.copyPages(data.categories), itemNames,
			data.lastChanged, data.providerAccountType);
		// A sync sends a counted zero; the panel shows only a real count.
		if (data.uniqueObtained > (sync ? -1 : 0))
		{
			result.setUniqueObtained(data.uniqueObtained);
		}
		if (data.uniqueTotal > (sync ? -1 : 0))
		{
			result.setUniqueTotal(data.uniqueTotal);
		}
		result.setRunStartedAt(data.runStartedAt);
		result.setRunStartXp(data.runStartXp);
		return result;
	}

	/**
	 * Hardcore Worlds: a reset sends the character back to Tutorial Island with nothing, so its total XP falls. The
	 * own log then starts over, dated, and the game's own Collection Log fills it again; true when it did. Read only
	 * once the world has settled, so a login's stats are all in; {@code save} keeps a higher reading on disk (once a
	 * login), so a reset across a relog is still seen.
	 */
	public synchronized boolean startOverOnReset(String playerName, long overallXp, boolean save)
	{
		PlayerClogData data = ownLog(playerName);
		if (data == null || overallXp <= 0)
		{
			return false;
		}
		boolean reset = overallXp < data.overallXp;
		if (reset)
		{
			PlayerClogData fresh = new PlayerClogData();
			fresh.playerName = data.playerName;
			fresh.ownerHash = data.ownerHash;
			fresh.uniqueTotal = data.uniqueTotal;
			fresh.categories = new HashMap<>();
			fresh.obtained = new HashMap<>();
			fresh.runStartedAt = Instant.now().toString();
			fresh.runStartXp = overallXp;
			fresh.lastUpdated = fresh.runStartedAt;
			own.put(activeHashKey, fresh);
			data = fresh;
		}
		long before = data.overallXp;
		data.overallXp = overallXp;
		// Saved on a reset, once a login on the settle tick when the XP rose, and for the first reading a log gets: a
		// log set up after its world settled kept 0 on disk, so a reset across the next relog went unseen (Sol 10/27).
		if (reset || overallXp > before && (save || before == 0))
		{
			submitSave(activeHashKey, true, data);
		}
		return reset;
	}

	/**
	 * Whether this player's own log holds anything a sync would carry. Lookups
	 * and empty first walks both answer false: the sync chalice and the
	 * automatic sync triggers key off this, never off mere cache presence.
	 */
	public synchronized boolean hasFirstPartyDataFor(String playerName)
	{
		PlayerClogData data = record(playerName);
		return data != null && (isActivePlayer(playerName) || data != lookups.get(cacheKey(playerName)))
			&& data.obtained.values().stream().anyMatch(items -> !items.isEmpty());
	}

	/** {@link #hasFirstPartyDataFor} for the logged-in player. */
	public boolean hasFirstPartyDataForActive()
	{
		return hasFirstPartyDataFor(session.getName());
	}

	/**
	 * The sync payload: the serving account's own log, which by construction
	 * holds only what this client captured.
	 */
	public synchronized ClogResult toFirstPartySyncResult(String playerName)
	{
		PlayerClogData data = ownLog(playerName);
		return data != null ? result(data, new HashMap<>(), true) : null;
	}

	// Disk I/O, always on the diskWriter thread.

	private String fileKey(String slot, boolean ownLog, String name)
	{
		return ownLog ? StoreFiles.ownFileName(slot) : StoreFiles.LOOKUPS + "/" + fileName(name);
	}

	/**
	 * Queue a debounced save of a snapshot. An own log's slot is its account
	 * hash and its file is fixed when queued, so a save can never land in
	 * another account's file whoever is logged in when the debounce fires.
	 */
	private void submitSave(String slot, boolean ownLog, PlayerClogData data)
	{
		Filepath folder = logs;
		PlayerClogData snapshot = shallowCopy(data);
		String file = fileKey(slot, ownLog, snapshot.playerName);
		unsavedFiles.put(file, snapshot);
		if (folder == null)
		{
			return;
		}
		Filepath dest = folder.join(file);
		submitDiskWrite(file, () ->
		{
			try
			{
				dest.getParent().createDirectories();
				StoreFiles.write(gson, folder, dest, snapshot);
				// An older write must not clear a newer pending snapshot.
				unsavedFiles.remove(file, snapshot);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Kill Clog could not save '{}': {}", file, e.getMessage());
			}
		});
	}

	/** A damaged log, moved aside under a name no load reads, so no save writes over the evidence. */
	private static void setAside(Filepath folder, Filepath file)
	{
		try
		{
			atomicMove(file, folder.join(".unreadable-" + file.getFileName() + "-" + System.currentTimeMillis() + ".json"));
		}
		catch (IOException e)
		{
			log.debug("Kill Clog could not set aside '{}': {}", file.getFileName(), e.getMessage());
		}
	}

	/**
	 * The cap holds on disk within a session too, not only at the next start: a lookup that falls out of memory
	 * takes its file with it, on the disk thread and in place of any save still queued for it.
	 */
	private void forgetLookupFile(String name)
	{
		Filepath folder = logs;
		if (folder == null || name == null)
		{
			return;
		}
		String file = fileKey(null, false, name);
		unsavedFiles.remove(file);
		Filepath dest = folder.join(file);
		submitDiskWrite(file, () ->
		{
			try
			{
				dest.deleteIfExists();
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Kill Clog could not remove '{}': {}", file, e.getMessage());
			}
		});
	}

	/**
	 * Submit a disk write for a file, coalescing bursts within DEBOUNCE_MS into a single write.
	 * The latest snapshot wins, including during the nonblocking shutdown flush.
	 */
	private void submitDiskWrite(String file, Runnable task)
	{
		boolean wasFirst = pendingByFile.put(file, task) == null;
		if (!wasFirst)
		{
			return;
		}
		try
		{
			diskWriter.schedule(() -> flush(file), DEBOUNCE_MS, TimeUnit.MILLISECONDS);
		}
		catch (RejectedExecutionException ignored)
		{
			// A writer that has shut down takes nothing more; the file stays unsaved and the next capture resaves it.
			pendingByFile.remove(file, task);
			log.debug("Disk write rejected (executor shutting down)");
		}
	}

	/** Runs a file's latest queued write, if one is still waiting. */
	private void flush(String file)
	{
		Runnable latest = pendingByFile.remove(file);
		if (latest != null)
		{
			latest.run();
		}
	}

	/** Genuinely atomic where the filesystem allows it; plain replace as the
	 *  documented fallback (some filesystems refuse ATOMIC_MOVE). */
	static void atomicMove(Filepath from, Filepath to) throws IOException
	{
		try
		{
			from.moveTo(to, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			from.moveTo(to, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	/**
	 * A lookup's file name: lowercased, spaces as underscores, [a-z0-9_-] only.
	 * RuneLite refuses Windows device names (con, aux, nul...) with any
	 * extension, so those take a leading '+' that no real name can produce.
	 */
	static String fileName(String playerName)
	{
		String stem = cacheKey(playerName).replace(' ', '_').replaceAll("[^a-z0-9_-]", "");
		return (stem.matches("con|prn|aux|nul|(com|lpt)[1-9]") ? "+" : "") + stem + ".json";
	}

	/** Shallow copy sufficient for async disk write. */
	private static PlayerClogData shallowCopy(PlayerClogData src)
	{
		PlayerClogData copy = new PlayerClogData();
		copy.playerName = src.playerName;
		copy.lastUpdated = src.lastUpdated;
		copy.lastChanged = src.lastChanged;
		copy.ownerHash = src.ownerHash;
		copy.providerAccountType = src.providerAccountType;
		copy.uniqueObtained = src.uniqueObtained;
		copy.uniqueTotal = src.uniqueTotal;
		copy.categories = new HashMap<>(src.categories);
		copy.obtained = new HashMap<>(src.obtained);
		copy.firstPartySetupComplete = src.firstPartySetupComplete;
		copy.pendingUnlocks = src.pendingUnlocks != null ? new ArrayList<>(src.pendingUnlocks) : null;
		copy.overallXp = src.overallXp;
		copy.runStartedAt = src.runStartedAt;
		copy.runStartXp = src.runStartXp;
		return copy;
	}
}

package com.killclog;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.swing.SwingUtilities;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

/**
 * Shared transport for player lookups. Every remote fetch the panel makes
 * rides one version-stamped, EDT-bridged, timeout-bounded pipeline; the
 * primary and comparison controllers own separate instances (separate version
 * spaces) and keep their own presentation. What they can no longer do is
 * disagree about transport policy: timeouts, stale-result gating, and thread
 * bridging live here once.
 *
 * <p>Threading: fetches are started on the EDT; service futures resolve on
 * background threads and every callback is bridged back through
 * {@link SwingUtilities#invokeLater} behind a version check. The volatile
 * version and in-flight fields make the guards observable across threads.
 */
@Slf4j
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class LookupFanout
{
	static final int CA_TIMEOUT_SECONDS = 10;
	// Tests shorten it.
	static int hiscoreTimeoutSeconds = 15;

	private final HiscoreService hiscoreService;
	private final ClogService clogService;
	private final RuneProfileService runeProfileService;
	private final KillclogService killclogService;

	/** Monotonic counter. Each {@link #begin} increments; callbacks compare their stamp against it. */
	private volatile int version = 0;

	/** True while a fetch generation is unresolved (or until superseded). */
	@Getter(AccessLevel.PACKAGE)
	private volatile boolean inFlight = false;

	// EDT-owned: the League these lookups read (null: the main game) and the player's own
	// open log for it. League reads come from League Hiscores and Kill Clog only.
	@Getter(AccessLevel.PACKAGE)
	@Nullable private String league;
	@Nullable private LocalClogCache leagueLog;
	// The game's own pages once the client has read the log: every log a lookup shows is laid on them.
	@Setter(AccessLevel.PACKAGE)
	@Nullable private volatile ClogIndex clogIndex;

	void readLeague(@Nullable String league, @Nullable LocalClogCache leagueLog)
	{
		this.league = league;
		this.leagueLog = leagueLog;
	}

	/**
	 * Whether this client keeps this player's log for the game read here: the main game's while the main store serves
	 * them (not yet on a login made straight onto a League world), or the League's on its own world.
	 */
	boolean readsOwnLog(String player)
	{
		return league == null ? clogService.keepsOwnLog(player) : leagueLog != null;
	}

	/** Your own log for the game these lookups read, as it is now. */
	@Nullable
	ClogResult ownLog(String player)
	{
		return onGamePages(league == null ? clogService.getCachedResult(player)
			: leagueLog != null ? clogService.localResult(leagueLog, player) : null);
	}

	/** Whether this player syncs to Kill Clog, by its sync list. */
	boolean onKillclog(String player)
	{
		return killclogService.isSynced(player);
	}

	/** A log on the game's own pages ({@link ClogIndex#laid}). */
	@Nullable
	ClogResult onGamePages(@Nullable ClogResult clog)
	{
		ClogIndex index = clogIndex;
		return index != null ? index.laid(clog) : clog;
	}

	/** Open a new fetch generation and return its version stamp. */
	int begin()
	{
		inFlight = true;
		return ++version;
	}

	/** The current generation resolved; the next {@link #begin} is accepted. */
	void settle()
	{
		inFlight = false;
	}

	/** Invalidate every outstanding callback, including optional legs after settlement. */
	void invalidate()
	{
		version++;
		inFlight = false;
	}

	int version()
	{
		return version;
	}

	/** True when the stamp still names the current generation. */
	boolean current(int stamp)
	{
		return stamp == version;
	}

	/**
	 * CA tier fetch through RuneProfile (or the local cache for self).
	 * Delivered on the EDT behind the version guard; failures and timeouts log
	 * and deliver nothing, the caller simply keeps no CA surface.
	 */
	void fetchCa(String player, int stamp, Consumer<CombatAchievementResult> onResult)
	{
		if (league != null)
		{
			return;
		}
		runeProfileService.lookup(player)
			.copy()
			.orTimeout(CA_TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.thenAccept(ca -> onEdtIfCurrent(stamp, () -> onResult.accept(ca)))
			.exceptionally(ex ->
			{
				log.warn("CA lookup failed", ex);
				return null;
			});
	}

	/**
	 * Hiscore fetch. A null result means the player was not found; the caller
	 * owns that presentation. Errors unwrap to {@code onError}, also on the
	 * EDT behind the guard.
	 */
	void fetchHiscore(String player, @Nullable AccountType knownType, int stamp,
		Consumer<HiscoreResult> onResult, Consumer<Throwable> onError)
	{
		(league != null ? hiscoreService.lookupLeague(player)
			: hiscoreService.lookup(player, knownType))
			.copy()
			.orTimeout(hiscoreTimeoutSeconds, TimeUnit.SECONDS)
			.thenAccept(result -> onEdtIfCurrent(stamp, () -> onResult.accept(result)))
			.exceptionally(ex ->
			{
				onEdtIfCurrent(stamp, () -> onError.accept(ex));
				return null;
			});
	}

	/**
	 * All clog sources in parallel: the public provider pair races on
	 * recency, then the player's own killclog.com sync joins on coverage
	 * (fullest leads, ties prefer first-party). Self lookups skip both
	 * remote-self legs because local widget data is authoritative.
	 * {@code onError} runs on the EDT behind the guard when present; null
	 * means log-and-drop. The primary path uses it to release a held hiscore.
	 */
	void fetchClog(String player, boolean isSelf, int stamp,
		Consumer<ClogResult> onResult, @Nullable Runnable onError)
	{
		// Your own log stands in for the remote sites only where this client keeps it.
		boolean own = isSelf && readsOwnLog(player);
		ClogProviderFanout.Answers answers = league == null ? ClogProviderFanout.answers(own,
			() -> clogService.lookup(player), () -> runeProfileService.lookupClog(player),
			() -> killclogService.lookupClog(player)) : null;
		CompletableFuture<Void> delivered = (answers != null ? answers.first
			: ClogProviderFanout.bounded(own ? clogService.lookupLocal(leagueLog, player)
			: killclogService.lookupClog(player, league)))
			.thenApply(this::onGamePages)
			.thenAccept(result -> onEdtIfCurrent(stamp, () -> onResult.accept(result)))
			.exceptionally(ex ->
			{
				log.warn("Clog lookup failed", ex);
				if (onError != null)
				{
					onEdtIfCurrent(stamp, onError);
				}
				return null;
			});
		if (answers != null)
		{
			// A late TempleOSRS answer lands in the open lookup after the first, never before it.
			delivered.thenCompose(done -> answers.late).thenApply(this::onGamePages).thenAccept(late ->
			{
				if (late != null)
				{
					onEdtIfCurrent(stamp, () -> onResult.accept(late));
				}
			});
		}
	}

	private void onEdtIfCurrent(int stamp, Runnable action)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (current(stamp))
			{
				action.run();
			}
		});
	}
}

package com.killclog;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.Skill;
import net.runelite.client.hiscore.HiscoreSkill;

/** Pure query helpers on HiscoreResult and ClogResult. */
final class LookupQueries
{
	private LookupQueries()
	{
	}

	static int sumBossKills(HiscoreResult result)
	{
		if (result == null) return 0;
		int total = 0;
		for (int kc : result.getBossKills().values())
		{
			if (kc > 0) total += kc;
		}
		return total;
	}

	/** A player's EHB: TempleOSRS's rates over their kills, as their account type's rates. -1 without hiscores. */
	static double ehb(@Nullable HiscoreResult hiscore, @Nullable ClogResult clog)
	{
		return EhbRates.compute(hiscore, accountType(hiscore, clog));
	}

	/** The bosses a player's count is out of: the panel's list, and the raid while its row stands beside it. */
	static int bossTotal(HiscoreResult result)
	{
		boolean beside = result != null && result.hasBossRow(PanelData.TFA_HISCORE) && !PanelData.tfaListed();
		return PanelData.bossCount() + (beside ? 1 : 0);
	}

	static int countBossesWithKc(HiscoreResult result)
	{
		if (result == null) return 0;
		int count = 0;
		for (int kc : result.getBossKills().values())
		{
			if (kc > 0) count++;
		}
		return count;
	}

	static String getMostKilledBoss(HiscoreResult result)
	{
		if (result == null) return null;
		String best = null;
		int bestKc = 0;
		for (Map.Entry<String, Integer> entry : result.getBossKills().entrySet())
		{
			if (entry.getValue() > bestKc)
			{
				bestKc = entry.getValue();
				best = entry.getKey();
			}
		}
		return best;
	}

	static int getMostKilledKc(HiscoreResult result)
	{
		if (result == null) return 0;
		int best = 0;
		for (int kc : result.getBossKills().values())
		{
			if (kc > best) best = kc;
		}
		return best;
	}

	static int countBossesCompleted(Map<HiscoreSkill, TooltipData> tooltipDataMap, Set<HiscoreSkill> bossKeys)
	{
		int count = 0;
		for (HiscoreSkill skill : bossKeys)
		{
			TooltipData data = tooltipDataMap.get(skill);
			if (data != null && data.totalItems > 0 && data.obtainedCount >= data.totalItems)
			{
				count++;
			}
		}
		return count;
	}

	static int countBossesWithClog(Map<HiscoreSkill, TooltipData> tooltipDataMap, Set<HiscoreSkill> bossKeys)
	{
		int count = 0;
		for (HiscoreSkill skill : bossKeys)
		{
			TooltipData data = tooltipDataMap.get(skill);
			if (data != null && data.totalItems > 0) count++;
		}
		return count;
	}

	static List<ClogResult.ClogItem> getRecentItems(ClogResult result, int limit)
	{
		List<ClogResult.ClogItem> all = new ArrayList<>();
		if (result == null)
		{
			return all;
		}
		for (List<ClogResult.ClogItem> items : result.getObtainedItems().values())
		{
			for (ClogResult.ClogItem item : items)
			{
				if (item.getDate() != null)
				{
					all.add(item);
				}
			}
		}
		all.sort((a, b) -> b.getDate().compareTo(a.getDate()));
		List<ClogResult.ClogItem> unique = new ArrayList<>();
		Set<Integer> seen = new HashSet<>();
		for (ClogResult.ClogItem item : all)
		{
			if (seen.add(item.getId()) && unique.size() < limit)
			{
				unique.add(item);
			}
		}
		return unique;
	}

	static int getClogItemCount(ClogResult result, String category, int itemId)
	{
		if (result == null) return 0;
		List<ClogResult.ClogItem> obtained = result.getObtainedItems().get(category);
		if (obtained == null) return 0;
		for (ClogResult.ClogItem item : obtained)
		{
			if (item.getId() == itemId) return item.getCount();
		}
		return 0;
	}

	static AccountType accountType(HiscoreResult result, ClogResult clog)
	{
		AccountType providerType = clog != null ? clog.getProviderAccountType() : null;
		AccountType hiscoreType = result != null ? result.getAccountType() : null;
		return AccountType.displayType(hiscoreType, providerType);
	}

	static AccountDisplay accountDisplay(HiscoreResult result, ClogResult clog)
	{
		return AccountDisplay.of(accountType(result, clog),
			result != null ? result.getHiscoreTable() : HiscoreTable.STANDARD);
	}

	/** 200m, the per-skill xp cap. */
	private static final long MAX_SKILL_XP = 200_000_000L;

	static boolean maxed(HiscoreResult result)
	{
		return result.getTotalLevel() >= PanelData.MAX_TOTAL_LEVEL;
	}

	/** An infernal cape: a TzKal-Zuk kill. */
	static boolean infernal(HiscoreResult result)
	{
		return result.getKc("TzKal-Zuk") > 0;
	}

	static String getPrestige(HiscoreResult result)
	{
		if (result == null) return null;
		boolean titan = isTitan(result);
		boolean maxed = maxed(result);
		boolean infernal = infernal(result);
		if (titan && infernal) return "Titan Infernal";
		if (titan) return "Titan";
		if (maxed && infernal) return "Maxed Infernal";
		if (maxed) return "Maxed";
		if (infernal) return "Infernal";
		return null;
	}

	/**
	 * 200m in every skill the game has - 4.8b as of Sailing. The summit Lynx
	 * Titan invented and Fast 07 first reached; the bar rises by itself when
	 * Jagex adds a skill because the check walks the current skill list.
	 */
	private static boolean isTitan(HiscoreResult result)
	{
		for (Skill skill : Skill.values())
		{
			if (result.getSkillXp(skill.getName().toLowerCase()) != MAX_SKILL_XP)
			{
				return false;
			}
		}
		return true;
	}

	/** Each obtained pet's count by item id, a duplicate's as the log holds it. */
	static Map<Integer, Integer> getObtainedPetCounts(ClogResult result)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		List<ClogResult.ClogItem> pets = result != null ? result.getObtainedItems().get("all_pets") : null;
		if (pets != null)
		{
			for (ClogResult.ClogItem item : pets)
			{
				counts.merge(item.getId(), item.getCount(), Integer::max);
			}
		}
		return counts;
	}

	/** The last update on the player's own clock (sources send UTC), and how many days ago. */
	static String syncLine(String lastChanged, boolean stale)
	{
		LocalDateTime syncTime = ClogDates.here(lastChanged);
		if (syncTime == null) return null;
		String date = syncTime.format(DateTimeFormatter.ofPattern(stale ? "MMM d ''yy" : "MMM d"));
		// Elapsed real time, not wall-clock time: a daylight-saving change never shifts it by an hour.
		long days = java.time.Duration.between(Instant.parse(ClogDates.iso(lastChanged)), Instant.now()).toDays();
		return days < 1 ? date : date + " (" + days + "d ago)";
	}

	static boolean isSyncStale(String lastChanged, int days)
	{
		String iso = ClogDates.iso(lastChanged);
		return iso == null || Instant.parse(iso).isBefore(Instant.now().minus(java.time.Duration.ofDays(days)));
	}
}

/*
 * Copyright (c) 2026, 420 kc <dyl@420kc.dev>
 * Owns the primary lookup lifecycle for Kill Clog: cache check, reveal
 * pacing, and listener choreography. The transport underneath (parallel
 * hiscore, clog, and CA fetches with version gating, EDT bridging, and
 * timeouts) is {@link LookupFanout}, shared with the comparison side. UI is
 * downstream via {@link Listener}; never widget code here.
 */
package com.killclog;

import java.util.function.UnaryOperator;
import javax.annotation.Nullable;
import javax.swing.Timer;
import lombok.Getter;

/**
 * One player's lookup lifecycle. Subscribers receive typed events through
 * {@link Listener}; this class never touches the UI. The owned
 * {@link LookupFanout} version-stamps every fetch so an in-flight call
 * superseded by a newer {@link #start} cannot overwrite it.
 *
 * <p>Threading: {@link #start} runs on the EDT, and every listener callback
 * arrives on the EDT (the reveal {@link Timer} fires there; service futures
 * bridge through the fanout).
 */
public class LookupSession
{
	/**
	 * Receives lifecycle events from a {@link LookupSession}. All methods
	 * are invoked on the EDT.
	 */
	public interface Listener
	{
		/** Lookup begun: UI should reset row state, set loading indicator, post a search-status line. */
		void onLookupStart(String player, boolean isSelf, boolean isFirstSelfGreeting);

		/** Cache hit: hiscore and possibly clog returned from service caches without an API call. */
		void onCachedResult(String player, HiscoreResult hiscore, @Nullable ClogResult clog,
			@Nullable AccountType knownType);

		/** Live hiscore result arrived from the API. */
		void onHiscoreResult(String player, HiscoreResult hiscore, @Nullable AccountType knownType);

		/**
		 * Live clog result arrived from the API (independent of hiscore timing).
		 * {@code clog} is null when the clog service returned no data for the
		 * player; the listener is responsible for the not-found UI (sync notice
		 * for self, blank notice otherwise) and for any follow-up RSN fetch.
		 */
		void onClogResult(String player, @Nullable ClogResult clog, boolean isSelf, int lookupVersion);

		/**
		 * CA tier result arrived from local cache or RuneProfile (independent of hiscore/clog timing).
		 * {@code ca} is null when the player has no CA data (not synced, or the provider was
		 * unavailable); the listener simply omits the CA surface in that case.
		 */
		void onCaResult(String player, @Nullable CombatAchievementResult ca, boolean isSelf, int lookupVersion);

		/** The hiscore service returned a null result (player not found). */
		void onNotFound(String player);

		/** A service call threw. The error parameter is the unwrapped cause where possible. */
		void onError(String player, Throwable error);
	}

	// Deps
	private final HiscoreService hiscoreService;
	private final ClogService clogService;
	private final KillClogConfig config;
	private final Listener listener;
	private final LookupFanout fanout;
	@Nullable private NameAutocompleter nameAutocompleter;

	// State
	@Nullable private HiscoreResult hiscoreResult;
	@Nullable private ClogResult clogResult;
	@Getter
	@Nullable private CombatAchievementResult caResult;
	@Getter
	@Nullable private String currentLookupRsn;
	private int localClogRevision;
	private UnaryOperator<HiscoreResult> rankView = UnaryOperator.identity();

	/** Longest a finished hiscore waits for its clog before showing uncoloured. */
	static final int CLOG_HOLD_MS = 2500;
	private boolean clogSettled;
	@Nullable private Runnable heldReveal;
	/** The lookup the held reveal belongs to; -1 while nothing is held. */
	private int heldLookup = -1;
	@Nullable private Timer holdTimer;

	public LookupSession(HiscoreService hiscoreService, ClogService clogService,
		RuneProfileService runeProfileService, KillclogService killclogService,
		KillClogConfig config, Listener listener)
	{
		this.hiscoreService = hiscoreService;
		this.clogService = clogService;
		this.config = config;
		this.listener = listener;
		this.fanout = new LookupFanout(hiscoreService, clogService, runeProfileService, killclogService);
	}

	/** Which game the next lookups read: a League, or null for the main game. */
	void readLeague(@Nullable String league, @Nullable LocalClogCache leagueLog)
	{
		fanout.readLeague(league, leagueLog);
	}

	/** Whether this player syncs to Kill Clog, by its sync list. */
	boolean onKillclog(String player)
	{
		return fanout.onKillclog(player);
	}

	/** The game's own pages, which every log these lookups show is laid on. */
	void setClogIndex(@Nullable ClogIndex clogIndex)
	{
		fanout.setClogIndex(clogIndex);
	}

	@Nullable
	String league()
	{
		return fanout.getLeague();
	}

	/** Setup applies only to a log this client keeps; a League read from another world has none here. */
	boolean readsOwnLog(@Nullable String player)
	{
		return player != null && fanout.readsOwnLog(player) && !frozen(getHiscoreResult());
	}

	/** Setup is offered for your own name's log, when this client keeps it. */
	boolean offersSetup(@Nullable String localRsn, @Nullable String name)
	{
		return RsnInputPolicy.sameName(localRsn, name) && readsOwnLog(name);
	}

	/** Wire (or rewire) the autocompleter that records search history on each successful lookup. */
	public void setNameAutocompleter(@Nullable NameAutocompleter nameAutocompleter)
	{
		this.nameAutocompleter = nameAutocompleter;
	}

	// Lifecycle

	/**
	 * Begin a lookup for {@code player}, in place of any still in flight: its stamp goes stale, so nothing it fetched
	 * paints (a right-click lookup on someone new never shows the last name's results under the new one). No-op for
	 * an empty name. Otherwise: cache check with a reveal-on-delay if fresh, or a full parallel hiscore + public clog
	 * provider fan-out if stale or missing.
	 *
	 * <p>Caller must invoke on the EDT. All listener callbacks are also on the
	 * EDT.
	 */
	public void start(String player, @Nullable String localRsn, @Nullable AccountType localAccountType)
	{
		if (player.isEmpty())
		{
			return;
		}

		currentLookupRsn = player;
		hiscoreResult = null;
		clogResult = null;
		caResult = null;
		clearHold();
		clogSettled = false;
		final int thisLookup = fanout.begin();
		final boolean isSelf = RsnInputPolicy.sameName(localRsn, player);
		final boolean isFirstSelfGreeting = isSelf && !config.seenSelfGreeting();

		listener.onLookupStart(player, isSelf, isFirstSelfGreeting);

		// CA tier fetch runs in parallel with the hiscore/clog fan-out (and through the cache
		// path), independent of either. RuneProfileService owns its own freshness + dedup.
		fanout.fetchCa(player, thisLookup, ca ->
		{
			caResult = ca;
			listener.onCaResult(player, ca, isSelf, thisLookup);
		});

		// Self-lookups know their own account type; cascade only matters for
		// other players. GIMs only ever appear on the regular hiscores, so the
		// hiscore service must be told to skip the cascade for them.
		final AccountType knownType = isSelf ? localAccountType : null;

		// The shared cache holds main-game rows only.
		final HiscoreResult cachedHiscore = fanout.getLeague() == null ? hiscoreService.getCached(player) : null;
		final ClogResult cachedClog = fanout.onGamePages(clogService.getCachedResult(player));
		if (cachedHiscore != null && !hiscoreService.isStale(player))
		{
			startClogLookup(player, isSelf, thisLookup);
			Timer revealTimer = new Timer(600, e ->
			{
				if (!fanout.current(thisLookup))
				{
					return;
				}
				fanout.settle();
				revealWithClog(thisLookup, cachedClog != null, () ->
				{
					showHiscore(player, cachedHiscore);
					ClogResult displayClog = clogResult;
					if (displayClog == null && cachedClog != null)
					{
						clogResult = cachedClog;
						displayClog = cachedClog;
					}
					listener.onCachedResult(player, cachedHiscore, displayClog, knownType);
				});
			});
			revealTimer.setRepeats(false);
			revealTimer.start();
			return;
		}

		final AccountType hiscoreType = knownType != null && knownType.isGroupIronman()
			? AccountType.REGULAR : knownType;
		fanout.fetchHiscore(player, hiscoreType, thisLookup, result ->
		{
			if (result == null)
			{
				// Invalidate the still-in-flight clog/CA lanes: a not-found
				// must not paint partial data afterwards.
				adoptState(null, null, null, null);
				listener.onNotFound(player);
				return;
			}
			// Settled now, so a new search is never blocked by the hold below.
			fanout.settle();
			revealWithClog(thisLookup, false, () ->
			{
				showHiscore(player, result);
				listener.onHiscoreResult(player, result, knownType);
			});
		}, ex ->
		{
			adoptState(null, null, null, null);
			listener.onError(player, ex);
		});

		startClogLookup(player, isSelf, thisLookup);
	}

	/** Whether this player's log hasn't loaded yet, rather than isn't there ({@link ClogService#templeUnanswered}). */
	boolean logUnanswered(@Nullable String player)
	{
		return clogService.templeUnanswered(player);
	}

	/** The hiscore this lookup shows, its name kept in the search history. */
	private void showHiscore(String player, HiscoreResult result)
	{
		hiscoreResult = result;
		if (nameAutocompleter != null)
		{
			nameAutocompleter.addToSearchHistory(player);
		}
	}

	/**
	 * Clog fan-out via the shared transport; failures keep the surface empty.
	 * Every outcome settles the clog, so a held hiscore is never left waiting.
	 */
	private void startClogLookup(String player, boolean isSelf, int thisLookup)
	{
		final int revisionAtFire = localClogRevision;
		fanout.fetchClog(player, isSelf, thisLookup, result ->
		{
			// A completed local capture supersedes a result already in flight.
			if (isSelf && revisionAtFire != localClogRevision)
			{
				result = fanout.ownLog(player);
				if (result == null || !result.isFromLocal())
				{
					settleClog(thisLookup);
					return;
				}
			}
			clogResult = result;
			settleClog(thisLookup);
			listener.onClogResult(player, result, isSelf, thisLookup);
		}, () -> settleClog(thisLookup));
	}

	/**
	 * Show a finished hiscore together with its clog, so cells never paint
	 * white and recolour a moment later. A slow provider delays the reveal by
	 * at most {@link #CLOG_HOLD_MS}; after that the hiscore shows on its own
	 * and the clog colours it on arrival, as it always could.
	 */
	private void revealWithClog(int thisLookup, boolean clogReady, Runnable reveal)
	{
		if (clogSettled || clogReady)
		{
			reveal.run();
			return;
		}
		heldReveal = reveal;
		heldLookup = thisLookup;
		holdTimer = new Timer(CLOG_HOLD_MS, e -> releaseHold(thisLookup));
		holdTimer.setRepeats(false);
		holdTimer.start();
	}

	/** The clog lane resolved, with data or without: release a held hiscore first. */
	private void settleClog(int thisLookup)
	{
		clogSettled = true;
		releaseHold(thisLookup);
	}

	private void releaseHold(int thisLookup)
	{
		// A late release from an earlier lookup must leave the next one's hold alone.
		if (heldLookup != thisLookup)
		{
			return;
		}
		Runnable reveal = heldReveal;
		clearHold();
		if (fanout.current(thisLookup))
		{
			reveal.run();
		}
	}

	private void clearHold()
	{
		if (holdTimer != null)
		{
			holdTimer.stop();
		}
		holdTimer = null;
		heldReveal = null;
		heldLookup = -1;
	}

	/** Update the displayed self log on the EDT without restarting any lookup lanes. */
	void refreshLocalClog(String player, @Nullable String localRsn)
	{
		if (!RsnInputPolicy.sameName(localRsn, player) || !RsnInputPolicy.sameName(currentLookupRsn, player)) return;
		ClogResult local = fanout.ownLog(player);
		if (local == null || !local.isFromLocal()) return;
		localClogRevision++;
		clogResult = local;
		settleClog(fanout.version());
		listener.onClogResult(player, local, true, fanout.version());
	}

	/**
	 * Abandon any in-flight lookup so the next {@link #start} is accepted.
	 * Bumps the version stamp so already-spawned async callbacks see
	 * themselves as stale and short-circuit.
	 */
	public void cancelInFlight()
	{
		clearHold();
		fanout.invalidate();
	}

	/**
	 * Adopt already-loaded results as the current lookup state, bypassing the
	 * async pipeline. Also clears all state on failure or shutdown.
	 */
	public void adoptState(@Nullable HiscoreResult hiscore, @Nullable ClogResult clog,
		@Nullable CombatAchievementResult ca, @Nullable String name)
	{
		// Invalidate any still-in-flight callbacks from the player being
		// replaced: their clog/CA lanes can outlive the hiscore result, and
		// without this bump a late arrival would overwrite the adopted state.
		clearHold();
		fanout.invalidate();
		this.hiscoreResult = hiscore;
		this.clogResult = clog;
		this.caResult = ca;
		this.currentLookupRsn = name;
	}

	/** Quietly discard the session before panel shutdown or reuse. */
	public void reset()
	{
		adoptState(null, null, null, null);
	}

	// Read-only state
	@Nullable
	public HiscoreResult getHiscoreResult()
	{
		return rankView(hiscoreResult);
	}

	HiscoreResult getNativeHiscoreResult()
	{
		return hiscoreResult;
	}

	void setRankView(UnaryOperator<HiscoreResult> rankView)
	{
		this.rankView = rankView;
	}

	HiscoreResult rankView(HiscoreResult result)
	{
		return result != null ? rankView.apply(result) : null;
	}

	/** None beside a frozen row: today's log would read as earned by the stats of then. */
	@Nullable
	public ClogResult getClogResult()
	{
		return frozen(getHiscoreResult()) ? null : clogResult;
	}

	/** When the shown log last changed, as its provider dates it. */
	@Nullable
	String getClogLastChanged()
	{
		return clogResult != null ? clogResult.getLastChanged() : null;
	}

	ClogResult getNativeClogResult()
	{
		return clogResult;
	}

	static boolean frozen(@Nullable HiscoreResult view)
	{
		return view != null && view.isFrozen();
	}

	public int getLookupVersion()
	{
		return fanout.version();
	}

	public boolean isLookupInFlight()
	{
		return fanout.isInFlight();
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Slf4j
final class ManualClogSync
{
	private static final int CLOG_ITEM_SCRIPT = 4100;
	private static final int CAPTURE_TIMEOUT_TICKS = 100;

	private final BulkCaptureState bulk = new BulkCaptureState();
	private String openingPlayer;
	private int openingTick;
	private String capturePlayer;
	private boolean firstCapture;

	void reset()
	{
		bulk.reset();
		openingPlayer = null;
		capturePlayer = null;
		firstCapture = false;
	}

	void onGameTick(Client client, ClogIndex clogIndex, LocalClogCache localClogCache,
		KillClogChatNotifier chatNotifier,
		Runnable captureComplete, Consumer<String> panelRefresh)
	{
		int tickCount = client.getTickCount();
		if (bulk.isActive() && !captureStillValid(client))
		{
			reset();
			return;
		}
		if ((openingPlayer != null || bulk.isActive()) && isHostLog(client))
		{
			reset();
			return;
		}
		if (openingPlayer != null && tickCount > openingTick)
		{
			requestOpeningCapture(client, clogIndex, localClogCache, chatNotifier);
		}
		bulk.deferEmptyFinalizationIfItemsReported(
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT));
		if (bulk.readyToFinalize(tickCount))
		{
			finalizeBulkCapture(client, clogIndex, localClogCache,
				chatNotifier, captureComplete, panelRefresh);
		}
		else if (bulk.timedOut(tickCount, CAPTURE_TIMEOUT_TICKS))
		{
			reset();
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Collection Log update timed out. Reopen the log or choose Search to retry.");
		}
	}

	void captureScriptArguments(Client client, int scriptId, Object[] args, int tickCount)
	{
		if (scriptId != CLOG_ITEM_SCRIPT)
		{
			return;
		}
		if (isHostLog(client) || bulk.isActive() && !captureStillValid(client))
		{
			reset();
			return;
		}
		if (bulk.isActive())
		{
			bulk.captureScriptArguments(args, tickCount);
		}
	}

	void onCollectionLogOpened(Client client)
	{
		if (isHostLog(client))
		{
			reset();
			return;
		}
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null || bulk.isActive())
		{
			return;
		}

		// WidgetLoaded precedes interface initialization. Request the full walk
		// on the next tick, once the interface is available.
		if (local.getName().equals(openingPlayer))
		{
			return;
		}
		openingPlayer = local.getName();
		openingTick = client.getTickCount();
	}

	private void requestOpeningCapture(Client client, ClogIndex clogIndex,
		LocalClogCache localClogCache, KillClogChatNotifier chatNotifier)
	{
		String name = openingPlayer;
		openingPlayer = null;
		Player local = client.getLocalPlayer();
		Widget root = client.getWidget(InterfaceID.Collection.FRAME);
		if (bulk.isActive() || local == null || !name.equals(local.getName())
			|| root == null || root.isHidden())
		{
			return;
		}
		Widget search = client.getWidget(InterfaceID.Collection.CONTENT_SEARCH);
		if (search == null || !search.isSelfHidden())
		{
			// Never toggle an already-open Search back or accept a partial walk.
			sendSearchHelp(chatNotifier);
			return;
		}
		beginCapture(client, clogIndex, localClogCache, chatNotifier);
		if (!bulk.isActive())
		{
			return;
		}
		try
		{
			// This specific Collection Log sync use was approved by Riktenx:
			// https://github.com/runelite/plugin-hub/pull/12380#issuecomment-4773784134
			// Arm before requesting data; the native callback must not restart it.
			client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE,
				MenuAction.CC_OP, 1, -1, "Search", null);
			// Restore the normal view, as in RuneProfile's approved retrieval flow.
			client.runScript(2240);
		}
		catch (RuntimeException ex)
		{
			reset();
			log.warn("Could not request automatic Collection Log update", ex);
			sendSearchHelp(chatNotifier);
		}
	}

	private boolean captureStillValid(Client client)
	{
		Player local = client.getLocalPlayer();
		Widget root = client.getWidget(InterfaceID.Collection.FRAME);
		return local != null && capturePlayer != null && capturePlayer.equals(local.getName())
			&& root != null && !root.isHidden() && !isHostLog(client);
	}

	static boolean isHostLog(Client client)
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) != 0;
	}

	private static void sendSearchHelp(KillClogChatNotifier chatNotifier)
	{
		chatNotifier.send(ChatNotice.SYNC_HELP,
			"To update your Collection Log, right-click the top of the log and choose Search.");
	}

	/**
	 * Search starts a full capture before script 4100 streams the obtained
	 * entries. Automatic and manual requests share the same completeness checks.
	 */
	void onCollectionLogSearch(Client client, ClogIndex clogIndex,
		LocalClogCache localClogCache, KillClogChatNotifier chatNotifier)
	{
		beginCapture(client, clogIndex, localClogCache, chatNotifier);
	}

	private void beginCapture(Client client, ClogIndex clogIndex,
		LocalClogCache localClogCache, KillClogChatNotifier chatNotifier)
	{
		if (isHostLog(client))
		{
			reset();
			return;
		}
		if (bulk.isActive())
		{
			return;
		}

		if (!clogIndex.isParsed())
		{
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Collection Log is still loading - choose Search again in a moment.");
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}

		// A completed cache can be refreshed by the same full-catalog walk.
		firstCapture = !localClogCache.hasCompletedFirstPartySetupFor(local.getName());
		capturePlayer = local.getName();
		// A manual request or another plugin's Search supersedes the queued open.
		openingPlayer = null;

		bulk.arm(client.getTickCount(),
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT),
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX));
		// Leave room for unsettled counters and delayed item scripts, including
		// empty logs, which produce no item events at all.
		bulk.scheduleEmptySearchFinalization(client.getTickCount());

		if (firstCapture)
		{
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Kill Clog is reading your Collection Log for First Time Setup...");
		}

		log.debug("Armed full clog capture from Collection Log Search "
			+ "(game reports {} obtained)", bulk.clogCount);
	}

	private void finalizeBulkCapture(Client client, ClogIndex clogIndex,
		LocalClogCache localClogCache, KillClogChatNotifier chatNotifier,
		Runnable captureComplete,
		Consumer<String> panelRefresh)
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			reset();
			return;
		}

		String name = local.getName();
		if (!localClogCache.serving(name))
		{
			reset();
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Still checking this account. Reopen your Collection Log in a moment.");
			return;
		}

		// The collection-log counters can settle after the Search menu click.
		// Re-read them before accepting the stream so an early zero cannot make
		// a partial walk look like a valid empty or one-item first capture.
		int reportedCount = Math.max(bulk.clogCount,
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT));
		int reportedTotal = Math.max(bulk.clogTotal,
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX));

		// Group obtained items by category.
		Map<String, List<ClogResult.ClogItem>> obtainedByCategory = new HashMap<>();

		// Include empty categories so cacheResult stores the full catalog.
		for (String cat : clogIndex.categoryKeys())
		{
			obtainedByCategory.put(cat, new ArrayList<>());
		}

		// Count logical slots, so two forms cannot hide a missing obtained item.
		List<ClogResult.ClogItem> capturedItems = clogIndex.canonicalizeItems(bulk.obtained);
		int mappedCount = 0;
		for (ClogResult.ClogItem item : capturedItems)
		{
			List<String> cats = clogIndex.categoryKeysForItem(item.getId());
			if (cats != null && !cats.isEmpty())
			{
				mappedCount++;
				for (String cat : cats)
				{
					obtainedByCategory.get(cat).add(item);
				}
			}
		}

		Map<String, List<Integer>> categoryItemsCopy = clogIndex.copyCategoryItems();

		// Guard against partial captures (e.g., player closed clog mid-sync).
		if (reportedCount < 0 || (reportedCount == 0 && !capturedItems.isEmpty())
			|| mappedCount < reportedCount || mappedCount != capturedItems.size())
		{
			log.warn("Bulk capture incomplete: {} mapped, {} canonical, {} reported; discarding",
				mappedCount, capturedItems.size(), reportedCount);
			reset();
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"Collection Log update interrupted. Your saved log is unchanged. Reopen the log or choose Search to retry.");
			return;
		}

		ClogResult result = new ClogResult(name, obtainedByCategory, categoryItemsCopy,
			new HashMap<>(), null, null);
		result.setUniqueObtained(reportedCount);
		if (reportedTotal > 0)
		{
			result.setUniqueTotal(reportedTotal);
		}
		localClogCache.cacheFirstPartyResult(result);
		captureComplete.run();

		// Prefer Jagex's logical-slot count; distinct item forms can share a slot.
		int displayCount = reportedCount > 0 ? reportedCount : bulk.obtained.size();
		log.debug("Bulk clog capture complete: {} items across {} categories for '{}' ({} streamed)",
			displayCount, clogIndex.categoryCount(), name, bulk.obtained.size());

		// Setup guidance and confirmation are always visible, even when routine
		// sync-result chat messages are disabled in config.
		if (firstCapture)
		{
			chatNotifier.send(ChatNotice.SYNC_HELP,
				"First Time Setup complete - " + displayCount + " items saved to Kill Clog.");
		}

		reset();

		SwingUtilities.invokeLater(() -> panelRefresh.accept(name));
	}
}

