	// Clue tier -> collection-log category key, derived from the enum name:
	// CLUE_SCROLL_BEGINNER -> beginner_treasure_trails.
	static final Map<HiscoreSkill, String> CLUE_CATEGORIES = new LinkedHashMap<>();
	static
	{
		for (HiscoreSkill tier : CLUE_TIERS)
		{
			CLUE_CATEGORIES.put(tier, tier.name()
				.substring("CLUE_SCROLL_".length()).toLowerCase(Locale.US)
				+ "_treasure_trails");
		}
	}

	/** A clue tier's scroll article on the wiki, as a boss card's title opens the boss's: "Clue scroll (beginner)". */
	static String clueWikiPage(HiscoreSkill tier)
	{
		return tier.getName().replace("Clue Scrolls", "Clue scroll");
	}

	// Clog tier trophy item IDs, bronze through gilded.
	static final int[] CLOG_TIER_ITEM_IDS = itemIds("clog_tier_items");

	// Collection log book item, used for chat icons and plugin icon fallbacks.
	static final int COLLECTION_LOG_ITEM_ID = 22711;

	static final HiscoreSkill[] PVP_ACTIVITIES = {
		HiscoreSkill.LAST_MAN_STANDING,
		HiscoreSkill.SOUL_WARS_ZEAL,
		HiscoreSkill.PVP_ARENA_RANK,
		HiscoreSkill.BOUNTY_HUNTER_HUNTER,
		HiscoreSkill.BOUNTY_HUNTER_ROGUE,
	};

	static final String GOTR_CATEGORY = "guardians_of_the_rift";
	static final String RIFTS_CLOSED_ACTIVITY = "Rifts closed";

	static final String SLAYER_CATEGORY = "slayer";
	static final int IMBUED_HEART_ITEM_ID = 20724;
	static final int ETERNAL_GEM_ITEM_ID = 21270;
	static final int[] SUPERIOR_ITEMS = {IMBUED_HEART_ITEM_ID, ETERNAL_GEM_ITEM_ID};

	// The raids and their hard modes. A hard mode shares its raid's log, so it reads on the raid's own card:
	// its cell opens that card, where its KC and PB are a second row under the name the Combat Summary pairs it by.
	static final HiscoreSkill[] RAIDS = {HiscoreSkill.CHAMBERS_OF_XERIC, HiscoreSkill.THEATRE_OF_BLOOD,
		HiscoreSkill.TOMBS_OF_AMASCUT};
	static final HiscoreSkill[] RAID_HARD_MODES = {HiscoreSkill.CHAMBERS_OF_XERIC_CHALLENGE_MODE,
		HiscoreSkill.THEATRE_OF_BLOOD_HARD_MODE, HiscoreSkill.TOMBS_OF_AMASCUT_EXPERT};
	static final String[] RAID_HARD_LABELS = {"CM", "HM", "Expert"};

	// The Fractured Archive (Raids 4, 2026-10-20) is the fourth raid row, with no hard mode.
	static final String TFA_HISCORE = "The Fractured Archive"; // the live hiscore name
	static final String TFA_CATEGORY = "the_fractured_archive"; // the game's log page key
	/** The raid's popup once the running client's enum carries it; null before, and its row opens nothing. */
	@Nullable
	static final HiscoreSkill TFA = skillNamed("FRACTURED_ARCHIVE"); // RuneLite's enum name (HiscoreSkill, 1.13.3)

	/**
	 * Whether a hiscore row is The Fractured Archive's: the guess, or the name with or without "The". Nothing more,
	 * so a mode or a boss of its own whose row also names the archive can never stand in for its completions.
	 */
	static boolean isTfaRow(String name)
	{
		return name.equalsIgnoreCase(TFA_HISCORE)
			|| name.trim().toLowerCase(Locale.ROOT).replaceFirst("^the ", "").equals("fractured archive");
	}

	/**
	 * True once the panel's boss list carries the raid (its tile, popup and boss count), which the launch-day
	 * update adds. Before that its row is the Combat Summary's alone: it opens nothing and counts beside the list.
	 */
	static boolean tfaListed()
	{
		return listed(TFA) != null;
	}

	/** The boss when the panel's list carries it (its tile, popup and count), else null. */
	@Nullable
	static HiscoreSkill listed(@Nullable HiscoreSkill boss)
	{
		return boss != null && Arrays.asList(BOSSES).contains(boss) ? boss : null;
	}

	/** The card a boss cell opens: its own, or for a raid's hard mode, the raid's. */
	static HiscoreSkill card(HiscoreSkill boss)
	{
		int i = Arrays.asList(RAID_HARD_MODES).indexOf(boss);
		return i >= 0 ? RAIDS[i] : boss;
	}

	/** A raid's hard mode, null for anything else. */
	@Nullable
	static HiscoreSkill hardMode(HiscoreSkill raid)
	{
		int i = Arrays.asList(RAIDS).indexOf(raid);
		return i >= 0 ? RAID_HARD_MODES[i] : null;
	}

	/** The name a raid's hard mode goes by beside the raid: CM, HM or Expert. */
	static String hardLabel(HiscoreSkill raid)
	{
		return RAID_HARD_LABELS[Arrays.asList(RAIDS).indexOf(raid)];
	}

	// Each raid's log and the megarare drop that headlines the Mega Rares row.
	static final String COX_CATEGORY = "chambers_of_xeric";
	static final int TWISTED_BOW_ITEM_ID = 20997;
	static final String TOB_CATEGORY = "theatre_of_blood";
	static final int SCYTHE_ITEM_ID = 22486;
	static final String TOA_CATEGORY = "tombs_of_amascut";
	static final int SHADOW_ITEM_ID = 27277;

	static final int OBLIGATOR_ITEM_ID = 34717; // uncharged, the raid's log slot
	static final int[] MEGARARE_ITEM_IDS = {TWISTED_BOW_ITEM_ID, SCYTHE_ITEM_ID, SHADOW_ITEM_ID, OBLIGATOR_ITEM_ID};

	// Hover names for the fixed pvm-summary sprites. Static because the pvm
	// summary renders these rows with or without a synced clog result; display
	// names use their full display form; TitleTooltip ellipsizes them when a
	// narrow summary cannot fit the whole hover title.
	static final String[] MEGARARE_ITEM_NAMES = {
		"Twisted Bow", "Scythe of Vitur", "Tumeken's Shadow", "Obligator",
	};
	static final String[] SUPERIOR_ITEM_NAMES = {"Imbued heart", "Eternal gem"};

	// Clog-summary trophy items, first on the Rare shelf when obtained. An unobtained
	// special never renders; the shelf holds trophies, not a checklist.
	static final int STALE_BAGUETTE_ITEM_ID = 20590;
	static final int HELMET_OF_THE_MOON_ITEM_ID = 30111;
	static final int[] SPECIAL_ITEM_IDS = {STALE_BAGUETTE_ITEM_ID, HELMET_OF_THE_MOON_ITEM_ID};

	// Prestige capes shown beside the player summary account line.
	static final int MAX_CAPE_ITEM_ID = 13280;
	static final int INFERNAL_CAPE_ITEM_ID = 21295;
	static final int INFERNAL_MAX_CAPE_ITEM_ID = 21284;
	/** Bundled panel-catalog rows of this kind; the parity test pins contents. */
	private static List<String> catalogValues(String kind)
	{
		return CatalogTsv.values(PanelData.class, "panel-catalog.tsv", kind);
	}

	private static HiscoreSkill[] bosses()
	{
		// A name the running client's enum does not carry yet is skipped, not
		// fatal: one missing boss beats a dead panel. The parity test still
		// compiles every expected constant, so drift fails the build.
		List<HiscoreSkill> bosses = new ArrayList<>();
		for (String name : catalogValues("boss"))
		{
			HiscoreSkill boss = skillNamed(name);
			if (boss != null)
			{
				bosses.add(boss);
			}
		}
		return bosses.toArray(new HiscoreSkill[0]);
	}

	/** The running client's enum entry by name, or null when this client build doesn't carry it yet. */
	@Nullable
	private static HiscoreSkill skillNamed(String name)
	{
		try
		{
			return HiscoreSkill.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static int[] itemIds(String kind)
	{
		List<String> values = catalogValues(kind);
		if (values.isEmpty())
		{
			return new int[0];
		}
		String[] fields = values.get(0).split(",");
		int[] itemIds = new int[fields.length];
		for (int i = 0; i < itemIds.length; i++)
		{
			itemIds[i] = Integer.parseInt(fields[i].trim());
		}
		return itemIds;
	}

}

package com.killclog;

import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.swing.ImageIcon;
import javax.swing.SwingUtilities;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class PanelIconCache
{
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final SpriteManager spriteManager;
	private final Map<String, ImageIcon> clogTierIcons = new LinkedHashMap<>();

	private BufferedImage maxCapeTip;
	private BufferedImage infernalCapeTip;
	private BufferedImage infernalMaxCapeTip;

	/** The log tier's icon for obtained and total slots, or none before the total is known. */
	ImageIcon clogTierIcon(int[] totals)
	{
		return totals[1] > 0 ? clogTierIcons.get(ClogHelper.getClogTierName(totals[0], totals[1])) : null;
	}

	Map<String, BufferedImage> clogTierImages()
	{
		Map<String, BufferedImage> icons = new LinkedHashMap<>();
		for (Map.Entry<String, ImageIcon> entry : clogTierIcons.entrySet())
		{
			icons.put(entry.getKey(), ClogHelper.iconToImage(entry.getValue()));
		}
		return icons;
	}

	BufferedImage capeFor(@Nullable HiscoreResult result)
	{
		if (result == null)
		{
			return null;
		}
		boolean maxed = LookupQueries.maxed(result);
		boolean infernal = LookupQueries.infernal(result);
		if (maxed && infernal)
		{
			return infernalMaxCapeTip;
		}
		if (maxed)
		{
			return maxCapeTip;
		}
		if (infernal)
		{
			return infernalCapeTip;
		}
		return null;
	}

	void loadRuntimeIcons(Cells cells, CaRewardSprites caRewardSprites)
	{
		// Cape, CA reward, and clog tier icons via ItemManager.
		clientThread.invokeLater(() ->
		{
			// Tooltip cape icons - native aspect ratio, taller.
			loadItemImage(itemManager, PanelData.MAX_CAPE_ITEM_ID, img -> maxCapeTip = img);
			loadItemImage(itemManager, PanelData.INFERNAL_CAPE_ITEM_ID, img -> infernalCapeTip = img);
			loadItemImage(itemManager, PanelData.INFERNAL_MAX_CAPE_ITEM_ID, img -> infernalMaxCapeTip = img);

			caRewardSprites.preloadAll();

			for (int i = 0; i < ClogHelper.CLOG_TIERS.length; i++)
			{
				final String tier = ClogHelper.CLOG_TIERS[i];
				final int itemId = PanelData.CLOG_TIER_ITEM_IDS[i];
				loadItemIcon(itemId, 13, 13, icon ->
					clogTierIcons.put(tier, icon));
			}

			// Clue summary tooltip icons: 1-6=tier scrolls, 7=Mimic (0=All loaded via spriteManager below).
			for (int i = 0; i < PanelData.CLUE_TIER_ITEM_IDS.length; i++)
			{
				final int idx = i + 1;
				loadItemImage(itemManager, PanelData.CLUE_TIER_ITEM_IDS[i], img ->
					cells.getClueIcons()[idx] = cellIcon(img, 13));
			}
			loadItemImage(itemManager, 23184, img ->
				cells.getClueIcons()[7] = cellIcon(img, 13));
			for (int i = 0; i < PanelData.RARE_ICON_ITEM_IDS.length; i++)
			{
				final int idx = i;
				loadItemImage(itemManager, PanelData.RARE_ICON_ITEM_IDS[i], img ->
					cells.getRareIcons()[idx] = cellIcon(img, 13));
			}
		});

		loadClueAllIcon(cells);
	}

	private void loadClueAllIcon(Cells cells)
	{
		// Clue All icon via spriteManager (game sprite, not item).
		int allSpriteId = HiscoreSkill.CLUE_SCROLL_ALL.getSpriteId();
		if (allSpriteId != -1)
		{
			cellSprite(spriteManager, allSpriteId, 13, icon -> cells.getClueIcons()[0] = icon);
		}
	}

	/** An item image resized into an icon, delivered on the Swing thread once it has loaded. */
	private void loadItemIcon(int itemId, int w, int h, Consumer<ImageIcon> setter)
	{
		loadItemImage(itemManager, itemId, img -> setter.accept(new ImageIcon(ImageUtil.resizeImage(img, w, h))));
	}

	/** An item's image, handed over on the Swing thread once the game has loaded it. */
	static void loadItemImage(ItemManager itemManager, int itemId, Consumer<BufferedImage> setter)
	{
		BufferedImage img = itemManager.getImage(itemId, 1, false);
		if (img instanceof AsyncBufferedImage)
		{
			((AsyncBufferedImage) img).onLoaded(() ->
				SwingUtilities.invokeLater(() -> setter.accept(img)));
		}
		else
		{
			SwingUtilities.invokeLater(() -> setter.accept(img));
		}
	}

	/** A game sprite at cell size ({@link #cellIcon}), handed over on the Swing thread once loaded; a missing one is skipped. */
	static void cellSprite(SpriteManager spriteManager, int spriteId, int size, Consumer<BufferedImage> sink)
	{
		spriteManager.getSpriteAsync(spriteId, 0, sprite ->
			SwingUtilities.invokeLater(() ->
			{
				if (sprite != null)
				{
					sink.accept(cellIcon(sprite, size));
				}
			}));
	}

	/** A game icon centred on the 25 px cell canvas, then scaled to the size shown. */
	static BufferedImage cellIcon(BufferedImage icon, int size)
	{
		return ImageUtil.resizeImage(ImageUtil.resizeCanvas(icon, 25, 25), size, size);
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.BooleanSupplier;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ColorUtil;

final class PanelInfoBar
{
	// The menu button lifts the bar it sits on toward white, at rest and hovered, so it reads on any background: on
	// RuneLite's grey 40 these are the 70 and 96 it always drew (30 and 56 of the 215 steps to white).
	private static final double HAMBURGER_TINT = 30 / 215.0;
	private static final double HAMBURGER_HOVER_TINT = 56 / 215.0;

	private PanelInfoBar()
	{
	}

	static JPanel build(JLabel playerName, JLabel clogInfoLabel,
		TooltipController tooltipController,
		BooleanSupplier comparisonMode, Runnable toggleBossView)
	{
		JPanel infoRow = new JPanel(null)
		{
			@Override
			public void doLayout()
			{
				if (getComponentCount() < 3)
				{
					return;
				}

				int width = getWidth();
				int height = getHeight();
				int gap = 4;
				Component left = getComponent(0);
				Component center = getComponent(1);
				Component right = getComponent(2);
				Dimension centerSize = center.getPreferredSize();
				int centerW = centerSize.width;
				int centerH = Math.min(height, centerSize.height);
				int centerX = Math.max(0, (width - centerW) / 2);
				int centerY = Math.max(0, (height - centerH) / 2);
				int rightX = Math.min(width, centerX + centerW + gap);

				left.setBounds(0, 0, Math.max(0, centerX - gap), height);
				center.setBounds(centerX, centerY, centerW, centerH);
				right.setBounds(rightX, 0, Math.max(0, width - rightX), height);
			}
		};
		infoRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		infoRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		infoRow.setPreferredSize(new Dimension(0, 18));

		configureBarLabel(playerName, JLabel.LEFT);
		playerName.setBorder(new EmptyBorder(0, 4, 0, 0));
		playerName.setMinimumSize(new Dimension(0, 0));

		configureBarLabel(clogInfoLabel, JLabel.RIGHT);
		clogInfoLabel.setBorder(new EmptyBorder(0, 0, 0, 4));
		clogInfoLabel.setMinimumSize(new Dimension(0, 0));

		installInfoClicks(playerName, infoRow, tooltipController);
		installInfoClicks(clogInfoLabel, infoRow, tooltipController);
		for (JLabel barLabel : new JLabel[]{playerName, clogInfoLabel})
		{
			HoverLabel.installHover(barLabel,
				() -> barLabel.getToolTipText() != null || comparisonMode.getAsBoolean());
		}

		infoRow.add(playerName);
		infoRow.add(buildViewToggle(toggleBossView));
		infoRow.add(clogInfoLabel);
		return infoRow;
	}

	private static void configureBarLabel(JLabel label, int alignment)
	{
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setHorizontalAlignment(alignment);
		label.setVerticalAlignment(JLabel.CENTER);
		label.setVerticalTextPosition(JLabel.CENTER);
		label.setIconTextGap(3);
		ClogHelper.antialias(label);
	}

	private static void installInfoClicks(JLabel label, JPanel infoRow,
		TooltipController tooltipController)
	{
		tooltipController.trackTooltipComponent(label);
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (label.getToolTipText() != null)
				{
					tooltipController.pinTooltipFromPress(label, infoRow, e);
				}
			}
		});
	}

	/**
	 * The hamburger: switches the boss area between grid and list views. Its three bars are painted from the bar it
	 * sits on each time, so they follow that bar's colour whatever it is now.
	 */
	private static JLabel buildViewToggle(Runnable toggleBossView)
	{
		JLabel viewToggle = new JLabel();
		boolean[] hovered = {false};
		viewToggle.setIcon(new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
				Color bar = c.getParent() != null ? c.getParent().getBackground() : ColorScheme.DARK_GRAY_COLOR;
				g.setColor(ColorUtil.colorLerp(bar, Color.WHITE, hovered[0] ? HAMBURGER_HOVER_TINT : HAMBURGER_TINT));
				for (int line = 0; line < 3; line++)
				{
					g.fillRect(x + 1, y + line * 4, 10, 2);
				}
			}

			@Override
			public int getIconWidth()
			{
				return 12;
			}

			@Override
			public int getIconHeight()
			{
				return 10;
			}
		});
		viewToggle.setHorizontalAlignment(JLabel.CENTER);
		viewToggle.setVerticalAlignment(JLabel.CENTER);
		viewToggle.setPreferredSize(new Dimension(18, 18));
		viewToggle.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				toggleBossView.run();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				hovered[0] = true;
				viewToggle.repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hovered[0] = false;
				viewToggle.repaint();
			}
		});
		return viewToggle;
	}
}

package com.killclog;

import java.awt.Color;
