final class PanelSearchBox
{
	/** The search bar's height, which the boss list's own search row matches. */
	static final int HEIGHT = 30;

	private PanelSearchBox()
	{
	}

	static void configureStatus(JLabel searchStatus, Color textColor)
	{
		searchStatus.setFont(FontManager.getRunescapeSmallFont());
		searchStatus.setForeground(textColor);
		searchStatus.setAlignmentX(Component.LEFT_ALIGNMENT);
		// Top inset 4 pairs with the panel's reduced top border: the label
		// grows the status row upward while the text itself stays put.
		searchStatus.setBorder(new EmptyBorder(4, 4, 2, 0));
		ClogHelper.antialias(searchStatus);
	}

	static JTextField configureSearchBar(IconTextField searchBar)
	{
		searchBar.setIcon(IconTextField.Icon.SEARCH);
		searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchBar.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchBar.setPreferredSize(new Dimension(0, HEIGHT));
		searchBar.setAlignmentX(Component.LEFT_ALIGNMENT);

		ClogHelper.styleSearchBar(searchBar);
		JTextField searchTextField = null;
		for (Component c : searchBar.getComponents())
		{
			if (c instanceof FlatTextField)
			{
				JTextField tf =
					((FlatTextField) c).getTextField();
				searchTextField = tf;
				tf.setFont(FontManager.getRunescapeFont());
				tf.setForeground(Color.WHITE);
				tf.setCaretColor(Color.WHITE);
				ClogHelper.antialias(tf);
			}
			else if (c instanceof Container)
			{
				ClogHelper.styleSearchBar((Container) c);
			}
		}
		return searchTextField;
	}

	static JPanel buildSearchRow(IconTextField searchBar, JLabel leagueSwitch, JLabel compareLabel, IntSupplier compareWidth)
	{
		JPanel searchRow = new JPanel(null)
		{
			@Override
			public void doLayout()
			{
				int w = getWidth(), h = getHeight();
				int compareW = compareWidth.getAsInt();
				int leagueW = leagueSwitch.isVisible() ? 22 : 0;
				searchBar.setBounds(0, 0, w - compareW - leagueW, h);
				leagueSwitch.setBounds(w - compareW - leagueW, 0, leagueW, h);
				compareLabel.setBounds(w - compareW, 0, compareW, h);
			}
		};
		searchRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		searchRow.setPreferredSize(new Dimension(0, HEIGHT));
		searchRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		searchRow.setOpaque(false);
		searchRow.add(compareLabel);
		searchRow.add(leagueSwitch);
		searchRow.add(searchBar);
		return searchRow;
	}
}

package com.killclog;

import com.killclog.StatusMessage.Kind;
import com.killclog.StatusMessage.Owner;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import lombok.AccessLevel;
import lombok.Setter;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ImageUtil;

/**
 * The status line above the search bar and the killclog.com one-click
 * controls that share it. Every occupant is a {@link StatusMessage}: lookup
 * text arrives through {@link #setSearchStatus}, sync and character feedback
 * through the show/reset methods. Feedback only lands while the row is free
 * or already its owner's, and an expiry only ever clears the message it was
 * started for. Widgets are touched on the EDT only.
 */
final class PanelStatusRow
{
	private static final String SYNC_HOVER_TEXT = "sync collection log";
	private static final String SYNC_FAILURE_HOVER_TEXT = "sync failed - click to retry";
	private static final String CHARACTER_HOVER_TEXT = "publish character";
	private static final String CHARACTER_DELETE_HOVER_TEXT = "delete character model";
	private static final String CHARACTER_FAILURE_HOVER_TEXT = "character failed - click to retry";
	private static final String CHARACTER_DELETE_FAILURE_HOVER_TEXT = "delete failed - click to retry";
	private static final String LOCKED_HOVER_TEXT = "Unavailable until first collection";
	private static final int SYNC_EXPIRY_MS = 2500;
	private static final int CHARACTER_EXPIRY_MS = 3000;
	// k1: the brand lime. Status chrome, not data coloring, so it does not
	// route through the user-themable completion color.
	private static final Color SYNC_K1 = new Color(78, 240, 21);
	private static final ImageIcon SYNC_CHALICE_DIM = chaliceTinted(0.45f, null);
	private static final ImageIcon SYNC_CHALICE_LIT = chaliceTinted(1f, null);
	private static final ImageIcon SYNC_CHALICE_SYNCED = chaliceTinted(1f, SYNC_K1);
	// Locked: grey and fainter than at rest, and hovering never lights it.
	private static final Color LOCKED_GREY = new Color(150, 150, 150);
	private static final ImageIcon SYNC_CHALICE_LOCKED = chaliceTinted(0.35f, LOCKED_GREY);

	private final JPanel row;
	private final JLabel searchStatus = new JLabel(" ");
	private final JLabel syncArrow = new JLabel();
	private final JLabel characterPublish = new JLabel();
	private final Color textDim;
	private final SpriteManager spriteManager;
	private final TooltipController tooltipController;
	private final FirstPartyFeedback syncFeedback;
	private final FirstPartyFeedback characterFeedback;
	private String characterNoticeText;
	private String characterNoticeDetail;
	/** What the row shows now; null while blank. */
	private StatusMessage current;

	/**
	 * Whether this account's own log lets the chalice and the character work: hidden while nobody is logged in or
	 * the log is still loading, locked (grey, with a hover line and a chat explanation) until it holds its first
	 * item, ready after.
	 */
	enum FirstParty
	{
		HIDDEN,
		LOCKED,
		READY
	}

	private boolean syncArrowEnabled;
	private FirstParty firstParty = FirstParty.HIDDEN;
	// A click on either control while locked: the chat explains, nothing is sent.
	@Setter(AccessLevel.PACKAGE)
	private Runnable lockedHandler;
	private boolean characterPublishEnabled;
	@Setter(AccessLevel.PACKAGE)
	private Runnable killclogSyncHandler;
	@Setter(AccessLevel.PACKAGE)
	private Runnable characterPublishHandler;
	// Shift-click on the character deletes it from killclog.com; while shift is held on it, its hover line says so.
	@Setter(AccessLevel.PACKAGE)
	private Runnable characterDeleteHandler;
	private boolean characterShift;
	// Whether the character's last request was a delete, so its failure is offered back on shift, not on a plain click.
	private boolean characterDeleteRequest;
	private BufferedImage characterBase;
	private boolean syncChaliceHovered;
	// Each control's success glow: the chalice's after a sync, the character's after a publish.
	private final Glow syncGlow = new Glow(() -> refreshSyncChalice(this.syncChaliceHovered));
	private final Glow characterGlow = new Glow(() -> refreshCharacterIcon(this.characterHovered));
	private boolean characterHovered;

	PanelStatusRow(KillClogConfig config, SpriteManager spriteManager,
		TooltipController tooltipController, Color textDim)
	{
		this.spriteManager = spriteManager;
		this.tooltipController = tooltipController;
		this.textDim = textDim;
		this.syncFeedback = new FirstPartyFeedback(config,
			(kind, text, autoClear) -> showFeedback(Owner.SYNC, kind, text, autoClear),
			this::flashSyncSuccess, "sync failed");
		this.characterFeedback = new FirstPartyFeedback(config,
			(kind, text, autoClear) -> showFeedback(Owner.CHARACTER, kind, text, autoClear),
			this::flashCharacterSuccess, CharacterStatus.FAILED.text);
		PanelSearchBox.configureStatus(searchStatus, textDim);
		this.row = build();
	}

	JPanel component()
	{
		return row;
	}

	String statusText()
	{
		return searchStatus.getText();
	}

	/**
	 * Lookup text from the panel. The panel manages lookup lifetimes itself:
	 * text holds the row until the panel replaces it, and blank hands the row
	 * back. The controls only show while the row is free, so search progress
	 * and player-not-found lines naturally park them.
	 */
	void setSearchStatus(String text, Color color)
	{
		if (text == null || text.trim().isEmpty())
		{
			clear();
		}
		else
		{
			show(new StatusMessage(Owner.LOOKUP, Kind.RESULT, text, color));
		}
	}

	/** Blank hands the row back to whoever writes next. */
	void clearSearchStatus()
	{
		clear();
	}

	/** Lookup text that clears itself after the delay, unless something else has replaced it by then. */
	void flashSearchStatus(String text, Color color, int expiryMs)
	{
		StatusMessage message = new StatusMessage(Owner.LOOKUP, Kind.RESULT, text, color);
		show(message);
		expireIfCurrent(message, expiryMs);
	}

	/** A shift-click copied the card it opened, or the clipboard would not take it. */
	void flashCardCopy(boolean copied)
	{
		flashSearchStatus(copied ? "card copied!" : "card copy failed", copied ? SYNC_K1 : KillClogPanel.NOT_FOUND,
			CHARACTER_EXPIRY_MS);
	}

	/** The rank board's notice, which only the board clears ({@link #clearBoardStatus}). */
	void setBoardStatus(String text)
	{
		show(new StatusMessage(Owner.BOARD, Kind.RESULT, text, textDim));
	}

	void clearBoardStatus()
	{
		if (ownedBy(Owner.BOARD))
		{
			clear();
		}
	}

	private void expireIfCurrent(StatusMessage message, int expiryMs)
	{
		message.expireAfter(expiryMs, () ->
		{
			if (current == message)
			{
				clear();
			}
		});
	}

	// ── occupancy ──────────────────────────────────────────────────────

	/** Replacing a message retires it: its expiry can never fire on a successor. */
	private void show(StatusMessage message)
	{
		if (current != null)
		{
			current.cancelExpiry();
		}
		current = message;
		searchStatus.setText(message.text);
		searchStatus.setForeground(message.color);
		refreshFirstPartyVisibility();
	}

	private void clear()
	{
		if (current != null)
		{
			current.cancelExpiry();
			current = null;
		}
		searchStatus.setText(" ");
		searchStatus.setForeground(textDim);
		refreshFirstPartyVisibility();
	}

	/** Blank, hover lines and notices leave the row free for the next writer. */
	private boolean free()
	{
		return current == null || current.yields();
	}

	private boolean ownedBy(Owner owner)
	{
		return current != null && current.owner == owner;
	}

	/** A control's own hover line or notice clears when the pointer leaves it. */
	private void clearYielding(Owner owner)
	{
		if (ownedBy(owner) && current.yields())
		{
			clear();
		}
	}

	// ── layout ─────────────────────────────────────────────────────────

	/**
	 * The chalice's and the character's mouse: hovering lights the control, puts its tooltip up and its hover line
	 * in the status, leaving takes them down, and a left press runs its handler while it shows.
	 */
	private MouseAdapter controlMouse(JLabel control, Owner owner, Consumer<Boolean> hover,
		Supplier<String> tooltip, Supplier<String> hoverText, Supplier<Runnable> handler)
	{
		return new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (control.isVisible())
				{
					hover.accept(true);
					tooltipController.setTooltipText(control, tooltip.get());
					show(new StatusMessage(owner, Kind.HOVER, hoverText.get(), hoverColor()));
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover.accept(false);
				tooltipController.setTooltipText(control, null);
				clearYielding(owner);
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				Runnable run = handler.get();
				if (SwingUtilities.isLeftMouseButton(e) && control.isVisible() && run != null)
				{
					run.run();
				}
			}
		};
	}

	/** What a click here does now: a failure is offered back only on the action that failed. */
	private String characterHoverText()
	{
		if (firstParty == FirstParty.LOCKED)
		{
			return LOCKED_HOVER_TEXT;
		}
		if (characterShift)
		{
			return characterDeleteRequest
				? characterFeedback.hoverText(CHARACTER_DELETE_HOVER_TEXT, CHARACTER_DELETE_FAILURE_HOVER_TEXT)
				: CHARACTER_DELETE_HOVER_TEXT;
		}
		return characterNoticeText != null ? characterNoticeText : characterDeleteRequest ? CHARACTER_HOVER_TEXT
			: characterFeedback.hoverText(CHARACTER_HOVER_TEXT, CHARACTER_FAILURE_HOVER_TEXT);
	}

	/** A control's hover line: k1 green for what a click does, the not-found red while it is locked. */
	private Color hoverColor()
	{
		return firstParty == FirstParty.LOCKED ? KillClogPanel.NOT_FOUND : SYNC_K1;
	}

	/** Shift held or let go on the character, as the pointer's last event there says: its hover line follows. */
	private void setCharacterShift(boolean down)
	{
		if (down == characterShift)
		{
			return;
		}
		characterShift = down;
		if (characterHovered && ownedBy(Owner.CHARACTER) && current.kind == Kind.HOVER)
		{
			show(new StatusMessage(Owner.CHARACTER, Kind.HOVER, characterHoverText(), hoverColor()));
		}
	}

	/** The character control's notice, failure, hover and glow, gone. */
	private void clearCharacterState()
	{
		characterFeedback.reset();
		characterNoticeText = null;
		characterNoticeDetail = null;
		characterHovered = false;
		characterDeleteRequest = false;
		characterGlow.clear();
	}

	private JPanel build()
	{
		syncArrow.setIcon(SYNC_CHALICE_DIM);
		tooltipController.trackTooltipComponent(syncArrow);
		tooltipController.trackTooltipComponent(characterPublish);
		characterPublish.setBorder(BorderFactory.createEmptyBorder(0, 3, 6, 2));
		characterPublish.setVerticalAlignment(JLabel.CENTER);
		characterPublish.setVisible(false);
		// Added first, so shift is known before the hover line and the press are read.
		characterPublish.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				characterShift = e.isShiftDown();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				characterShift = false;
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				characterShift = e.isShiftDown();
			}
		});
		characterPublish.addMouseMotionListener(new MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				setCharacterShift(e.isShiftDown());
			}
		});
		characterPublish.addMouseListener(controlMouse(characterPublish, Owner.CHARACTER, hovered ->
		{
			characterHovered = hovered;
			refreshCharacterIcon(hovered);
		}, () -> firstParty == FirstParty.LOCKED ? null : characterTooltipText(characterNoticeDetail != null
			? characterNoticeDetail : characterFeedback.lastFailure()), this::characterHoverText,
			() -> firstParty == FirstParty.LOCKED ? lockedHandler
				: characterShift ? characterDeleteHandler : characterPublishHandler));
		requestCharacterIcon();

		// Sits vertically centered in the band between the panel top and the
		// search bar: the bottom inset biases the icon upward within the
		// taller status row so its center lands on the band's center.
		syncArrow.setBorder(BorderFactory.createEmptyBorder(0, 4, 6, 5));
		syncArrow.setVerticalAlignment(JLabel.CENTER);
		syncArrow.setVisible(false);
		syncArrow.addMouseListener(controlMouse(syncArrow, Owner.SYNC, hovered ->
		{
			syncChaliceHovered = hovered;
			refreshSyncChalice(hovered);
		}, () -> firstParty == FirstParty.LOCKED ? null : syncFeedback.lastFailure(),
			() -> firstParty == FirstParty.LOCKED ? LOCKED_HOVER_TEXT
				: syncFeedback.hoverText(SYNC_HOVER_TEXT, SYNC_FAILURE_HOVER_TEXT),
			() -> firstParty == FirstParty.LOCKED ? lockedHandler : killclogSyncHandler));

		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		// The parent column is BoxLayout: children must agree on alignment or
		// the whole stack shears sideways.
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		reserveStatusRowHeight(row, searchStatus.getPreferredSize().height);
		row.add(searchStatus, BorderLayout.CENTER);
		JPanel actions = new JPanel();
		actions.setLayout(new BoxLayout(actions, BoxLayout.X_AXIS));
		actions.setOpaque(false);
		actions.add(characterPublish);
		actions.add(syncArrow);
		row.add(actions, BorderLayout.EAST);
		return row;
	}

	static void reserveStatusRowHeight(JPanel row, int labelHeight)
	{
		int height = Math.max(labelHeight, 14) + 2;
		row.setMinimumSize(new Dimension(0, height));
		row.setPreferredSize(new Dimension(0, height));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
	}

	// ── icons ──────────────────────────────────────────────────────────

	/**
	 * The sync control wears the Kill Clog chalice itself: dim at rest,
	 * full red on hover, k1 green briefly after a successful sync.
	 */
	private static BufferedImage chaliceBase()
	{
		BufferedImage src = ImageUtil.loadImageResource(KillClogPlugin.class, "icon.png");
		int h = 13;
		int w = Math.max(1, src.getWidth() * h / src.getHeight());
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(src, 0, 0, w, h, null);
		g.dispose();
		return out;
	}

	private static ImageIcon chaliceTinted(float alpha, Color tint)
	{
		return imageTinted(chaliceBase(), alpha, tint);
	}

	private static ImageIcon imageTinted(BufferedImage base, float alpha, Color tint)
	{
		BufferedImage out = new BufferedImage(
			base.getWidth(), base.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < base.getHeight(); y++)
		{
			for (int x = 0; x < base.getWidth(); x++)
			{
				int argb = base.getRGB(x, y);
				int a = (argb >>> 24);
				if (a == 0)
				{
					continue;
				}
				int r = (argb >> 16) & 0xFF;
				int gch = (argb >> 8) & 0xFF;
				int b = argb & 0xFF;
				if (tint != null)
				{
					// Luminance drives the tint so the source keeps its shading.
					int lum = Math.min(255, (int) (0.299 * r + 0.587 * gch + 0.114 * b) + 90);
					r = tint.getRed() * lum / 255;
					gch = tint.getGreen() * lum / 255;
					b = tint.getBlue() * lum / 255;
				}
				int na = Math.min(255, Math.round(a * alpha));
				out.setRGB(x, y, (na << 24) | (r << 16) | (gch << 8) | b);
			}
		}
		return new ImageIcon(out);
	}

	private void refreshSyncChalice(boolean hovered)
	{
		syncArrow.setIcon(firstParty == FirstParty.LOCKED ? SYNC_CHALICE_LOCKED : syncGlow.lit() ? SYNC_CHALICE_SYNCED
			: hovered ? SYNC_CHALICE_LIT : SYNC_CHALICE_DIM);
	}

	/** Any thread; also re-run after a sprite reload so a resource pack swap redraws the icon. */
	void requestCharacterIcon()
	{
		spriteManager.getSpriteAsync(SpriteID.SideiconsNew.EQUIPMENT, 0, sprite ->
		{
			if (sprite == null)
			{
				return;
			}
			int height = 14;
			int width = Math.max(1, sprite.getWidth() * height / sprite.getHeight());
			BufferedImage resized = ImageUtil.resizeImage(sprite, width, height);
			SwingUtilities.invokeLater(() ->
			{
				characterBase = resized;
				refreshCharacterIcon(false);
				refreshFirstPartyVisibility();
			});
		});
	}

	private void refreshCharacterIcon(boolean hovered)
	{
		if (characterBase == null)
		{
			characterPublish.setIcon(null);
			return;
		}
		boolean locked = firstParty == FirstParty.LOCKED;
		characterPublish.setIcon(imageTinted(characterBase,
			locked ? 0.35f : characterGlow.lit() || hovered ? 1f : 0.45f,
			locked ? LOCKED_GREY : characterGlow.lit() ? SYNC_K1 : null));
	}

	private void refreshFirstPartyVisibility()
	{
		boolean visible = firstParty != FirstParty.HIDDEN && free();
		syncArrow.setVisible(syncArrowEnabled && visible);
		characterPublish.setVisible(characterPublishEnabled && characterBase != null && visible);
	}

	private static String characterTooltipText(String detail)
	{
		if (detail == null) return null;
		return "<html><div style='width:220px'>" + detail.replace("&", "&amp;")
			.replace("<", "&lt;").replace(">", "&gt;") + "</div></html>";
	}

	// ── plugin-facing controls ─────────────────────────────────────────

	/** The plugin flips this with the sync checkbox; off hides the arrow. */
	void setSyncArrowEnabled(boolean enabled)
	{
		SwingUtilities.invokeLater(() ->
		{
			syncArrowEnabled = enabled;
			if (!enabled)
			{
				syncChaliceHovered = false;
				syncFeedback.reset();
				tooltipController.setTooltipText(syncArrow, null);
				syncGlow.clear();
			}
			refreshFirstPartyVisibility();
		});
	}

	/**
	 * The chalice and the character earn their use: locked until this player's local Collection Log holds at least
	 * one first-party capture, so a fresh account sees why it cannot sync yet and can never send nothing.
	 */
	void setFirstParty(FirstParty state)
	{
		SwingUtilities.invokeLater(() ->
		{
			firstParty = state;
			if (state != FirstParty.READY)
			{
				syncChaliceHovered = false;
				syncGlow.clear();
			}
			refreshSyncChalice(syncChaliceHovered);
			refreshCharacterIcon(characterHovered);
			refreshFirstPartyVisibility();
		});
	}

	void setCharacterPublishEnabled(boolean enabled)
	{
		SwingUtilities.invokeLater(() ->
		{
			characterPublishEnabled = enabled;
			if (!enabled)
			{
				clearCharacterState();
				tooltipController.setTooltipText(characterPublish, null);
			}
			refreshFirstPartyVisibility();
		});
	}

	void showSyncProgress(boolean manual, String text, boolean autoClear)
	{
		syncFeedback.progress(manual, text, autoClear);
	}

	/** Silent results still retain failures for the control's next deliberate hover. */
	void showSyncResult(boolean manual, boolean ok, String message)
	{
		syncFeedback.complete(manual, ok, message);
	}

	/**
	 * Drop account-scoped sync feedback without disturbing lookup or character
	 * status: only a sync-owned message, and with it its expiry, is cleared.
	 */
	void resetSyncFeedback()
	{
		SwingUtilities.invokeLater(() ->
		{
			syncFeedback.reset();
			tooltipController.setTooltipText(syncArrow, null);
			syncChaliceHovered = false;
			syncGlow.clear();
			if (ownedBy(Owner.SYNC))
			{
				clear();
			}
		});
	}

	/**
	 * The status carries its meaning: CLEAR withdraws the character's message,
	 * PUBLISHED or FAILED completes the request, and the rest show as their
	 * kind, a notice repeating its detail on hover.
	 */
	void showCharacterPublishStatus(CharacterStatus status, boolean autoClear, String detail)
	{
		runFeedbackOnEdt(() ->
		{
			characterNoticeText = null;
			characterNoticeDetail = null;
			if (status == CharacterStatus.CLEAR)
			{
				characterFeedback.reset();
				tooltipController.setTooltipText(characterPublish, null);
				characterGlow.clear();
				if (ownedBy(Owner.CHARACTER))
				{
					clear();
				}
			}
			else if (status.kind == null)
			{
				characterFeedback.complete(true, status == CharacterStatus.PUBLISHED, detail != null
					? detail : "Character failed. Click to retry.");
			}
			else
			{
				characterFeedback.reset();
				if (status.kind == Kind.PROGRESS)
				{
					characterDeleteRequest = status == CharacterStatus.DELETING;
				}
				if (status.kind == Kind.NOTICE)
				{
					characterNoticeText = (status == CharacterStatus.PENDING ? CharacterStatus.UNKNOWN : status).text;
					characterNoticeDetail = detail;
				}
				characterFeedback.show(true, status.kind, status.text, autoClear);
			}
			if (characterHovered)
			{
				tooltipController.setTooltipText(characterPublish,
					characterTooltipText(characterNoticeDetail != null ? characterNoticeDetail : characterFeedback.lastFailure()));
			}
		});
	}

	void refreshSyncFeedbackSettings()
	{
		runFeedbackOnEdt(() ->
		{
			// Changing feedback preferences clears existing transient chrome;
			// the next callback reads the new settings. Failure history remains.
			if (ownedBy(Owner.SYNC) || ownedBy(Owner.CHARACTER))
			{
				clear();
			}
			syncGlow.clear();
			characterGlow.clear();
		});
	}

	/** Stops every timer and hides the controls; the row stays reusable afterwards. */
	void shutdown()
	{
		if (current != null)
		{
			current.cancelExpiry();
		}
		syncArrowEnabled = false;
		firstParty = FirstParty.HIDDEN;
		syncChaliceHovered = false;
		syncFeedback.reset();
		characterShift = false;
		clearCharacterState();
		syncGlow.clear();
		refreshFirstPartyVisibility();
	}

	// ── feedback internals ─────────────────────────────────────────────

	private static void runFeedbackOnEdt(Runnable action)
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			action.run();
		}
		else
		{
			SwingUtilities.invokeLater(action);
		}
	}

	/**
	 * Sync and character feedback share the row on equal terms: a message
	 * only lands while the row is free or already its owner's, so lookup text
	 * is never stomped. Progress speaks in k1; notices and results stay dim.
	 * An auto-clearing message expires on its own timer, and that expiry
	 * clears nothing else. Any thread.
	 */
	private void showFeedback(Owner owner, Kind kind, String text, boolean autoClear)
	{
		runFeedbackOnEdt(() ->
		{
			if (!free() && !ownedBy(owner))
			{
				return;
			}
			if (owner == Owner.SYNC)
			{
				syncGlow.clear();
			}
			else
			{
				characterGlow.clear();
			}
			StatusMessage message = new StatusMessage(owner, kind, text,
				kind == Kind.PROGRESS ? SYNC_K1 : textDim);
			show(message);
			if (autoClear)
			{
				expireIfCurrent(message, owner == Owner.SYNC ? SYNC_EXPIRY_MS : CHARACTER_EXPIRY_MS);
			}
		});
	}

	/**
	 * Successful sync feedback is icon-only so the shared status row never
	 * moves. It flashes over a blank row or the sync's own text, never over
	 * lookup or character text.
	 */
	private void flashSyncSuccess()
	{
		runFeedbackOnEdt(() ->
		{
			if (!syncArrowEnabled || firstParty != FirstParty.READY
				|| current != null && !ownedBy(Owner.SYNC))
			{
				return;
			}
			if (ownedBy(Owner.SYNC))
			{
				clear();
			}
			syncGlow.flash();
		});
	}

	private void flashCharacterSuccess()
	{
		if (!characterPublishEnabled || firstParty != FirstParty.READY
			|| !free() && !ownedBy(Owner.CHARACTER))
		{
			return;
		}
		if (ownedBy(Owner.CHARACTER))
		{
			clear();
		}
		characterGlow.flash();
	}

	/** A control's success glow: lit at once, out again on its own after 2.5 s, its icon redrawn each way. */
	private static final class Glow
	{
		private final Runnable redraw;
		private Timer timer;
		private boolean lit;

		Glow(Runnable redraw)
		{
			this.redraw = redraw;
		}

		boolean lit()
		{
			return lit;
		}

		void flash()
		{
			stop();
			lit = true;
			redraw.run();
			timer = new Timer(2500, e -> clear());
			timer.setRepeats(false);
			timer.start();
		}

		void clear()
		{
			stop();
			lit = false;
			redraw.run();
		}

		private void stop()
		{
			if (timer != null)
			{
				timer.stop();
				timer = null;
			}
		}
	}
}

package com.killclog;

import java.util.Locale;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;

/**
 * One variant-keyed PB, where this client saw it and, from a kill Kill Clog saw, what the game showed at that kill.
 * Which record wins for a key is decided here and nowhere else.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class PbRecord
{
	/** Where a time came from. RuneLite's file is the one that isn't the game's own record. */
	enum Source
	{
		STORE, ADVLOG, CLOG, LIVE;

		String wire()
		{
			return name().toLowerCase(Locale.ROOT);
		}
	}

	final double seconds;
	final Source source;
	Integer team;
	Integer scale;
	String timer;
	Integer kc;

	/** A kill's labels as KillLog keeps them beside its time. */
	static String tag(double seconds, String team, String scale, String timer, String kc)
	{
		return seconds + "|" + team + "|" + scale + "|" + timer + "|" + kc;
	}

	/** This live time with the labels a kept tag gives it, when the tag is for this same time and reads. */
	static PbRecord live(double seconds, @Nullable String tag)
	{
		PbRecord pb = new PbRecord(seconds, Source.LIVE);
		String[] parts = tag != null ? tag.split("\\|", -1) : new String[0];
		try
		{
			if (parts.length == 5 && Double.parseDouble(parts[0]) == seconds)
			{
				pb.team = number(parts[1]);
				pb.scale = number(parts[2]);
				pb.timer = parts[3];
				pb.kc = number(parts[4]);
			}
		}
		catch (NumberFormatException e)
		{
			// A label that doesn't read is skipped: the time still syncs, unlabeled.
			return new PbRecord(seconds, Source.LIVE);
		}
		return pb;
	}

	boolean labeled()
	{
		return timer != null;
	}

	/**
	 * The record that wins a key. The collection log's line is the game's current record, read from the server
	 * exactly, so it wins whenever this client has read it: an older, faster time elsewhere can't outlast a record
	 * the game has since changed. RuneLite's file fills only what nothing has, the profile RuneLite chose first. A
	 * game record replaces the file's even when slower. Between game records, faster wins and the later takes a tie.
	 * A whole second the game stated and a time with tenths it rounds from are one record told two ways (Dylan,
	 * 2026-10-23): it keeps the tenths and goes as the game's, so a kill or the adventure log with precise timing off
	 * still confirms the file's exact time; told by a kill and the adventure log, it goes as the kill, with its labels,
	 * whichever came first.
	 */
	static PbRecord pick(@Nullable PbRecord kept, PbRecord seen)
	{
		if (kept == null)
		{
			return seen;
		}
		if ((kept.source == Source.CLOG) != (seen.source == Source.CLOG))
		{
			return kept.source == Source.CLOG ? kept : seen;
		}
		if (seen.source == Source.STORE)
		{
			return sameTimeInTenths(seen.seconds, kept.seconds) ? kept.at(seen.seconds) : kept;
		}
		if (kept.source == Source.STORE)
		{
			return sameTimeInTenths(kept.seconds, seen.seconds) ? seen.at(kept.seconds) : seen;
		}
		if (sameTimeInTenths(kept.seconds, seen.seconds))
		{
			return teller(kept, seen).at(kept.seconds);
		}
		if (sameTimeInTenths(seen.seconds, kept.seconds))
		{
			return teller(kept, seen).at(seen.seconds);
		}
		return seen.seconds <= kept.seconds ? seen : kept;
	}

	/** Of two game records of one time, the one it goes as: a kill over the adventure log, else the later. */
	private static PbRecord teller(PbRecord kept, PbRecord seen)
	{
		return kept.source == Source.LIVE && seen.source != Source.LIVE ? kept : seen;
	}

	/** This record told with its tenths: the same source and labels, at the exact time. */
	private PbRecord at(double exact)
	{
		PbRecord pb = new PbRecord(exact, source);
		pb.team = team;
		pb.scale = scale;
		pb.timer = timer;
		pb.kc = kc;
		return pb;
	}

	/** Whether two times are one record: the same, or one of them the other shown without its tenths. */
	static boolean sameRecord(double a, double b)
	{
		return a == b || sameTimeInTenths(a, b) || sameTimeInTenths(b, a);
	}

	/**
	 * Whether a whole second is this tenths time as the game shows it with precise timing off: rounded to the nearest
	 * second, half up (its formatter, client script 2410), so a time on the 0.6 s tick grid is never more than 0.4 s
	 * from what it shows. "0:32" is 31.8 or 32.4; 32.6 shows as "0:33".
	 */
	private static boolean sameTimeInTenths(double tenths, double whole)
	{
		return whole == Math.rint(whole) && tenths != Math.rint(tenths) && Math.abs(tenths - whole) < 0.45;
	}

	@Nullable
	private static Integer number(String text)
	{
		return text.isEmpty() ? null : Integer.valueOf(text);
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.EqualsAndHashCode;

/** Unresolved live evidence, stored with its owning player's cache. */
@EqualsAndHashCode
final class PendingClogUnlock
{
	final List<Integer> candidates;
	final String date;
	final String ownerHash;

	PendingClogUnlock(List<Integer> candidates, String date, String ownerHash)
	{
		this.candidates = new ArrayList<>(new java.util.TreeSet<>(candidates));
		this.date = date;
		this.ownerHash = ownerHash;
	}

	/** Reconcile only a unique candidate. Multiple matches cannot establish order. */
	static List<PendingClogUnlock> reconcile(List<PendingClogUnlock> pending,
		Map<String, List<ClogResult.ClogItem>> obtained, String ownerHash)
	{
		// A session transition cannot consume evidence without its account anchor.
		// Preserve null too, so an unchanged capture stays unchanged after upgrade.
		if (pending == null || obtained == null || ownerHash == null) return pending;
		List<PendingClogUnlock> remaining = new ArrayList<>();
		Set<Integer> ids = new HashSet<>();
		for (List<ClogResult.ClogItem> items : obtained.values())
		{
			for (ClogResult.ClogItem item : items) ids.add(item.getId());
		}
		Map<Integer, String> resolved = new HashMap<>();
		for (PendingClogUnlock event : pending)
		{
			if (event == null || event.candidates == null) continue;
			if (!ownerHash.equals(event.ownerHash)) continue;
			String iso = ClogDates.iso(event.date);
			if (iso == null) continue;
			List<Integer> matches = new ArrayList<>();
			for (int id : event.candidates) if (ids.contains(id)) matches.add(id);
			if (matches.isEmpty()) remaining.add(event);
			else if (matches.size() == 1)
			{
				resolved.merge(matches.get(0), ClogDates.local(iso),
					(a, b) -> a.compareTo(b) <= 0 ? a : b);
			}
		}
		for (Map.Entry<String, List<ClogResult.ClogItem>> category : obtained.entrySet())
		{
			List<ClogResult.ClogItem> updated = new ArrayList<>();
			for (ClogResult.ClogItem item : category.getValue())
			{
				String date = resolved.get(item.getId());
				updated.add(item.getDate() == null && date != null ? item.withDate(date) : item);
			}
			category.setValue(updated);
		}
		return remaining;
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;

/**
 * A player's personal bests from the four places this client keeps them: RuneLite's own store ("personalbest",
 * which its chat commands write) and Kill Clog's three lanes, the adventure log, the collection log's line and the
 * kills seen. Each key is a boss's name with an optional team size, each value seconds; they exist for the local
 * player only.
 *
 * <p>The keys a profile holds are listed, never guessed, so a team size or a spelling nobody predicted is still
 * read. Every lane's spelling of a boss reaches one name ({@link #encounter}), so a time any lane filed is read
 * under its boss. The sync names a time as it always has ({@link #syncBase}), so the server's keys never move.
 */
final class PersonalBests
{
	// A team size, as RuneLite and the adventure log append one: " solo", " 3 players", " 24+ players", " 11-15 players".
	private static final Pattern VARIANT = Pattern.compile("^(.+?)( (?:solo|\\d+(?:\\+|-\\d+)? players?))?$");
	private static final Pattern DIGITS = Pattern.compile("\\d+");
	// Spellings that differ beyond case, a mode's colon and a leading "The", each to the name every lane reaches.
	private static final Map<String, String> ALIASES = new HashMap<>();

	static
	{
		for (String[] row : CatalogTsv.rows(PersonalBests.class, "pb-names.tsv", 2))
		{
			ALIASES.put(row[0], row[1]);
		}
	}

	/** Where each lane keeps its times, and what the sync calls the lane. */
	private enum Lane
	{
		STORE("personalbest", "", PbRecord.Source.STORE),
		ADVLOG(AdvLogPbs.CONFIG_GROUP, AdvLogPbs.KEY_PREFIX, PbRecord.Source.ADVLOG),
		CLOG(AdvLogPbs.CONFIG_GROUP, ClogPbs.KEY_PREFIX, PbRecord.Source.CLOG),
		LIVE(AdvLogPbs.CONFIG_GROUP, KillLog.KEY_PREFIX, PbRecord.Source.LIVE);

		final String group;
		final String prefix;
		final PbRecord.Source source;

		Lane(String group, String prefix, PbRecord.Source source)
		{
			this.group = group;
			this.prefix = prefix;
			this.source = source;
		}
	}

	/** One kept time: its lane, the profile and key it sits under (the lane's prefix off), and its team size. */
	private static final class Kept
	{
		final Lane lane;
		final String profile;
		final String key;
		final String variant;
		final double seconds;

		Kept(Lane lane, String profile, String key, String variant, double seconds)
		{
			this.lane = lane;
			this.profile = profile;
			this.key = key;
			this.variant = variant;
			this.seconds = seconds;
		}
	}

	// The plain key first, then solo, then team sizes by players: on a tie, the later variant names the time.
	private static final Comparator<String> VARIANT_ORDER = Comparator.comparingInt(PersonalBests::players)
		.thenComparing(Comparator.naturalOrder());

	@Nullable
	private final ConfigManager configManager;
	private final List<String> profileKeys;
	// Every time the profiles hold, by boss; read once, on the first ask, and kept only once whole.
	private volatile Map<String, List<Kept>> kept;
	@Nullable
	private volatile String chosen;

	/** The times kept on these profiles of one account ({@link #profileKeys}); nothing is read until asked. */
	PersonalBests(@Nullable ConfigManager configManager, List<String> profileKeys)
	{
		this.configManager = configManager;
		this.profileKeys = profileKeys;
	}

	/** Explicit ownership for publication, from RuneLite profiles of one type; names can change or be reused. */
	static List<String> profileKeys(Iterable<RuneScapeProfile> profiles, long accountHash, @Nullable String type)
	{
		if (accountHash == 0 || accountHash == RuneScapeProfile.ACCOUNT_HASH_INVALID)
		{
			return List.of();
		}
		Set<String> keys = new LinkedHashSet<>();
		for (RuneScapeProfile profile : profiles)
		{
			if (profile.getType() != null && profile.getType().name().equals(type)
				&& profile.getAccountHash() == accountHash)
			{
				String key = profile.getKey();
				if (key != null && !key.isEmpty())
				{
					keys.add(withPrefix(key));
				}
			}
		}
		return List.copyOf(keys);
	}

	/**
	 * Formatted fastest time for a panel boss across team sizes, each the time {@link #records} picks (the one the
	 * sync sends, so your card and killclog.com agree), or null when none recorded.
	 */
	@Nullable
	String pbText(String bossName)
	{
		Map<String, Double> seconds = new LinkedHashMap<>();
		records(bossName).forEach((key, record) -> seconds.put(key, record.seconds));
		return labeled(seconds, bossName);
	}

	/**
	 * A boss's time for each team size: RuneLite's store, then the game's own records over it (the adventure log, the
	 * collection log's line and the kills seen), as {@link PbRecord#pick} ranks them. In each lane, the profile
	 * RuneLite chose for the account speaks for every team size it has; the ones it ignores (it logs "multiple
	 * matching profiles") fill only the rest, their fastest. The one place the card and the sync choose a PB.
	 */
	Map<String, PbRecord> records(String bossName)
	{
		Map<String, PbRecord> out = new LinkedHashMap<>();
		List<Kept> times = kept().getOrDefault(encounter(bossName), List.of());
		String base = syncBase(bossName);
		for (Lane lane : Lane.values())
		{
			Map<String, Kept> chosenBest = new HashMap<>();
			Map<String, Kept> othersBest = new HashMap<>();
			for (Kept time : times)
			{
				if (time.lane == lane)
				{
					(time.profile.equals(chosen) ? chosenBest : othersBest).merge(time.variant, time,
						(a, b) -> b.seconds < a.seconds ? b : a);
				}
			}
			othersBest.forEach(chosenBest::putIfAbsent);
			chosenBest.keySet().stream().sorted(VARIANT_ORDER).forEach(variant ->
				out.merge(base + variant, record(chosenBest.get(variant)), PbRecord::pick));
		}
		return out;
	}

	/** A looked-up player's synced times for a boss, by team size, from the names they arrived under. */
	static Map<String, Double> variantSeconds(Map<String, Double> stored, String bossName)
	{
		Map<String, Double> best = new HashMap<>();
		String boss = encounter(bossName);
		stored.forEach((key, seconds) ->
		{
			Matcher variant = VARIANT.matcher(key.toLowerCase(Locale.ROOT));
			if (seconds != null && seconds > 0 && variant.matches() && encounter(variant.group(1)).equals(boss))
			{
				best.merge(variant.group(2) != null ? variant.group(2) : "", seconds, Math::min);
			}
		});
		Map<String, Double> out = new LinkedHashMap<>();
		String base = syncBase(bossName);
		best.keySet().stream().sorted(VARIANT_ORDER).forEach(variant -> out.put(base + variant, best.get(variant)));
		return out;
	}

	/**
	 * The fastest variant's time; a team size's carries it, "(5 players) 22:13.80", which the card reads as
	 * killclog.com does, "PB (5 players): 22:13.80" ({@link ClogHelper#pbLabel}). On a tie the team size wins.
	 */
	@Nullable
	static String labeled(Map<String, Double> variants, String bossName)
	{
		Map.Entry<String, Double> best = null;
		for (Map.Entry<String, Double> variant : variants.entrySet())
		{
			best = best == null || variant.getValue() <= best.getValue() ? variant : best;
		}
		if (best == null)
		{
			return null;
		}
		String team = best.getKey().substring(syncBase(bossName).length()).trim();
		String time = formatSeconds(best.getValue());
		return team.isEmpty() ? time : "(" + Character.toUpperCase(team.charAt(0)) + team.substring(1) + ") " + time;
	}

	/**
	 * The one name every lane's spelling of a boss reaches: the panel's ("Theatre of Blood: Hard Mode"), RuneLite's
	 * store ("theatre of blood hard mode"), a kill count message's, an adventure log section's and a collection log
	 * page's. Lowercase, a mode's colon gone, a leading "the" gone, then pb-names.tsv for true renames.
	 */
	static String encounter(String name)
	{
		String key = name.toLowerCase(Locale.ROOT).trim().replace(": ", " ");
		key = ALIASES.getOrDefault(key, key);
		key = key.startsWith("the ") ? key.substring("the ".length()) : key;
		return ALIASES.getOrDefault(key, key);
	}

	/** The name the sync and the server have always filed a boss's times under: lowercase, a mode's colon gone. */
	static String syncBase(String bossName)
	{
		return bossName.toLowerCase(Locale.ROOT)
			.replace(": challenge mode", " challenge mode")
			.replace(": hard mode", " hard mode")
			.replace(": expert mode", " expert mode")
			.replace(": entry mode", " entry mode");
	}

	/** Same rendering vanilla uses for !pb, trailing precision only when real. */
	/* package */ static String formatSeconds(double seconds)
	{
		int hours = (int) (Math.floor(seconds) / 3600);
		int minutes = (int) (Math.floor(seconds / 60) % 60);
		double secs = seconds % 60;

		String prefix = hours > 0
			? String.format(Locale.US, "%d:%02d:", hours, minutes)
			: String.format(Locale.US, "%d:", minutes);
		return prefix + (Math.floor(secs) == secs
			? String.format(Locale.US, "%02d", (int) secs)
			: String.format(Locale.US, "%05.2f", secs));
	}

	/**
	 * Every lane's times on every profile, listed once per lane and profile, on the first ask. The list is kept only
	 * once whole, so a reader on another thread sees it whole or reads it again; never a half-built one.
	 */
	private Map<String, List<Kept>> kept()
	{
		Map<String, List<Kept>> list = kept;
		if (list != null)
		{
			return list;
		}
		list = new HashMap<>();
		if (configManager == null || profileKeys.isEmpty())
		{
			kept = list;
			return list;
		}
		chosen = withPrefix(configManager.getRSProfileKey());
		for (Lane lane : Lane.values())
		{
			for (String profile : profileKeys)
			{
				for (String key : configManager.getRSProfileConfigurationKeys(lane.group, profile, lane.prefix))
				{
					Double seconds = configManager.getConfiguration(lane.group, profile, key,
						(java.lang.reflect.Type) double.class);
					Matcher variant = VARIANT.matcher(key.substring(lane.prefix.length()));
					if (seconds != null && seconds > 0 && variant.matches())
					{
						list.computeIfAbsent(encounter(variant.group(1)), boss -> new ArrayList<>()).add(new Kept(lane,
							profile, key.substring(lane.prefix.length()), variant.group(2) != null ? variant.group(2) : "",
							seconds));
					}
				}
			}
		}
		kept = list;
		return list;
	}

	/** A kept time as the sync sends it; a kill's time with the labels Kill Clog kept beside it. */
	private PbRecord record(Kept time)
	{
		return time.lane != Lane.LIVE ? new PbRecord(time.seconds, time.lane.source)
			: PbRecord.live(time.seconds, configManager.getConfiguration(time.lane.group, time.profile,
				KillLog.TAG_PREFIX + time.key));
	}

	// The plain key first, then solo, then each team size by its players.
	private static int players(String variant)
	{
		if (variant.isEmpty())
		{
			return -2;
		}
		Matcher count = DIGITS.matcher(variant);
		return count.find() ? Integer.parseInt(count.group()) : -1;
	}

	@Nullable
	private static String withPrefix(@Nullable String key)
	{
		return key == null || key.startsWith("rsprofile.") ? key : "rsprofile." + key;
	}
}

package com.killclog;

import java.awt.image.BufferedImage;
import java.util.function.BooleanSupplier;
import javax.annotation.Nullable;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.Text;

/**
 * A player's clan for the Player Summary: its name, and the icon their title in it wears in clan chat. Your own comes
 * from the game, anyone else's from their Kill Clog sync, else RuneProfile's summary. Your sync carries yours (2.6.3).
 */
@RequiredArgsConstructor
class PlayerClans
{
	private final Client client;
	private final ChatIconManager icons;
	private final RuneProfileService runeProfile;
	// Your own, as the game showed it on the last tick. The card is built on Swing's thread, where the
	// client's clan state must not be read, so it reads this instead.
	// Whether this main-game world has settled since login or a hop: until then the game hasn't said you're in no clan.
	private final BooleanSupplier settled;
	// Share Clan (2.7.3, a player's ask): off, your sync says you're in no clan, so no Kill Clog surface names it.
	private final BooleanSupplier shared;
	private volatile Yours yours = Yours.NONE;

	/** Reads your name, clan and title from the game; client thread only, each tick. */
	void refreshClientSnapshot()
	{
		Player you = client.getLocalPlayer();
		String name = you != null ? you.getName() : null;
		ClanSettings settings = client.getClanSettings();
		ClanChannel channel = client.getClanChannel();
		// Membership lives in the clan's settings, so it stands without the clan's chat channel joined; the channel
		// names the clan only while the settings haven't loaded.
		ClanMember member = settings != null && name != null ? settings.findMember(name) : null;
		ClanChannelMember inChannel = member == null && channel != null && name != null ? channel.findMember(name) : null;
		String clan = member != null ? settings.getName() : channel != null ? channel.getName() : null;
		ClanRank rank = member != null ? member.getRank() : inChannel != null ? inChannel.getRank() : null;
		yours = new Yours(name, clan, rank != null && settings != null ? settings.titleForRank(rank) : null,
			settled.getAsBoolean() && (member != null || settings == null && channel == null));
	}

	void clearClientSnapshot()
	{
		yours = Yours.NONE;
	}

	/**
	 * Your clan for a sync of {@code player}, its clan null when you're in none; null while the game hasn't said
	 * since the world last settled, or when the snapshot is another account's.
	 */
	@Nullable
	Yours forSync(String player)
	{
		Yours you = yours;
		if (!you.is(player))
		{
			return null;
		}
		return !shared.getAsBoolean() ? new Yours(you.name, null, null, true) : you.known ? you : null;
	}

	@Nullable
	String name(String player, @Nullable ClogResult clog)
	{
		Yours you = yours;
		// Share Clan off, your own card shows none too, so it never looks like it's being shared.
		return you.is(player) ? (shared.getAsBoolean() ? you.clan : null)
			: synced(clog) ? clog.getSyncedClan() : runeProfile.clan(player);
	}

	/** The title's icon, or null when there is none or it hasn't loaded (the card then names the clan instead). */
	@Nullable
	BufferedImage icon(String player, @Nullable ClogResult clog)
	{
		Yours you = yours;
		ClanTitle title = you.is(player) ? (shared.getAsBoolean() ? you.title : null)
			: synced(clog) ? clog.getSyncedClanTitle() : runeProfile.clanTitle(player);
		try
		{
			return title != null ? icons.getRankImage(title) : null;
		}
		catch (RuntimeException e)
		{
			// RuneLite loads the clan icons once logged in; an unknown title has no icon.
			return null;
		}
	}

	private static boolean synced(@Nullable ClogResult clog)
	{
		return clog != null && clog.isSyncedClanKnown();
	}

	@RequiredArgsConstructor
	static final class Yours
	{
		static final Yours NONE = new Yours(null, null, null, false);

		final String name;
		final String clan;
		final ClanTitle title;
		// The game has said: in this clan, or in none.
		final boolean known;

		boolean is(String player)
		{
			return name != null && player != null && Text.toJagexName(name).equalsIgnoreCase(Text.toJagexName(player));
		}
	}
}

package com.killclog;

import java.util.List;
import java.util.Map;

/** One player's locally cached collection log, as persisted by
 *  {@link LocalClogCache} (one JSON file per player). */
class PlayerClogData
{
	String playerName;
	String lastUpdated;
	String lastChanged;
	// Which account hash wrote this file: claims in the identity ledger
	// order NAMES, but the bytes belong to whoever wrote them. Parking
	// targets this over any claim-derived guess. Null on legacy files and
	// pure lookup caches.
	String ownerHash;
	AccountType providerAccountType;
	int uniqueObtained = -1;
	int uniqueTotal = -1;
	Map<String, List<Integer>> categories;
	Map<String, List<ClogResult.ClogItem>> obtained;
	List<PendingClogUnlock> pendingUnlocks;
	/**
	 * Whether this client completed the full Collection Log Search walk. False (and a missing or null field in an
	 * older file) keeps provider-only and live-unlock-only stores in setup.
	 */
	boolean firstPartySetupComplete;
	// Hardcore Worlds: the character's total XP as last seen there, and when a reset started this log over and at
	// what XP (null and 0 for the first run). XP only ever grows, so a fall is a reset.
	long overallXp;
	String runStartedAt;
	long runStartXp;
}

package com.killclog;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Iterator;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;
import javax.imageio.stream.MemoryCacheImageInputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;

/**
 * Kill Clog syncers' characters for the Player Summary. When a player publishes their character,
 * killclog.com draws it in the game's own style, with their follower beside them, and serves it at
 * {@code /api/player/{rsn}/portrait/large}. Only lookups that came back from the player's own Kill Clog
 * sync (or the local player's own log) ask for one, so nobody else costs a request.
 *
 * <p>Every lookup re-checks the portrait (an unchanged one answers 304 with no body), and a portrait
 * shows only once the server has confirmed it for that lookup: a player who withdraws or deletes
 * their character is gone from their next lookup on. Each lookup is a new generation for its player,
 * and only an answer to the latest generation confirms; one request per player is out at a time, and
 * an answer to an older one sends a fresh check for the lookup that landed meanwhile.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(access = AccessLevel.PACKAGE, onConstructor_ = @Inject)
class PlayerPortraits
{
	static final int MAX_BYTES = 64 * 1024;
	static final int MAX_SIDE = 256;
	// A miss is often a character still being drawn, or one about to be published (a lookup right
	// after a player's first sync), so it is asked about again within a minute.
	static final long NOT_FOUND_TTL_MS = 60 * 1000;
	// Lookup counts kept past this are pruned to names with a portrait held or a check out.
	static final int MAX_GENERATIONS = 2 * HttpUtil.CACHE_CAP;
	private static final byte[] PNG_SIGNATURE = {(byte) 0x89, 'P', 'N', 'G', '\r', '\n', 0x1a, '\n'};

	private final OkHttpClient httpClient;
	final HttpUtil.Lane<Portrait> lane = new HttpUtil.Lane<>(new CircuitBreaker("killclog.com portraits"),
		HttpUtil.Lane.RESULT_TTL_MS, NOT_FOUND_TTL_MS);
	// Names whose held portrait the server confirmed since their latest lookup.
	private final Set<String> confirmed = ConcurrentHashMap.newKeySet();
	// Each player's latest lookup, and the lookup the request now out for them was sent for.
	private final Map<String, Integer> generations = new ConcurrentHashMap<>();
	private final Map<String, Integer> asked = new ConcurrentHashMap<>();

	/** A portrait and the ETag it was served with, for the next lookup's re-check. */
	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	static final class Portrait
	{
		final BufferedImage image;
		@Nullable
		final String etag;

	}

	/** A lookup landed: withhold this player's portrait until the server confirms it again. */
	synchronized void lookedUp(@Nullable ClogResult clog)
	{
		String name = syncedName(clog);
		if (name != null)
		{
			String key = key(name);
			generations.merge(key, 1, Integer::sum);
			if (generations.size() > MAX_GENERATIONS)
			{
				// A name with nothing held and nothing asked needs no count: its next lookup starts over.
				generations.keySet().removeIf(other -> !other.equals(key) && !asked.containsKey(other)
					&& !lane.values.containsKey(other));
			}
			confirmed.remove(key);
			ask(name);
		}
	}

	/** The local player just published their character: their own summary asks for it now, not after a miss rests. */
	synchronized void published(@Nullable String name)
	{
		if (name != null && !name.trim().isEmpty())
		{
			// A new generation: a check sent before the publish can neither confirm the old character nor rest a miss.
			String key = key(name.trim());
			generations.merge(key, 1, Integer::sum);
			confirmed.remove(key);
			lane.notFound.remove(key);
			ask(name.trim());
		}
	}

	/** The portrait to draw for this lookup's player: one the server confirmed since the lookup, or null. */
	@Nullable
	BufferedImage forSummary(@Nullable ClogResult clog)
	{
		String name = syncedName(clog);
		if (name == null)
		{
			return null;
		}
		String key = key(name);
		Portrait held = lane.values.get(key);
		if (held != null && confirmed.contains(key))
		{
			return held.image;
		}
		ask(name);
		return null;
	}

	/** The player's name when their log came from their own Kill Clog sync or the local player's own log. */
	@Nullable
	private static String syncedName(@Nullable ClogResult clog)
	{
		if (clog == null || !(clog.isFromKillclog() || clog.isFromLocal()))
		{
			return null;
		}
		String name = clog.getPlayerName();
		return name == null || name.trim().isEmpty() ? null : name.trim();
	}

	/** Sends a check for the player's latest lookup, unless one is already out or the name is resting. */
	private synchronized void ask(String name)
	{
		String key = key(name);
		if (asked.containsKey(key) || lane.resting(key))
		{
			return;
		}
		int generation = generations.getOrDefault(key, 0);
		asked.put(key, generation);
		Portrait held = lane.values.get(key);
		// The Player Summary draws characters 200 pixels tall; the server serves today's size until those are drawn.
		String url = KillClogEndpoint.apiBaseUrl() + "/player/" + HttpUtil.pathSegment(name) + "/portrait/large";
		CompletableFuture<HttpUtil.BytesResult> request;
		try
		{
			request = HttpUtil.httpGetBytes(httpClient, url, MAX_BYTES, held != null ? held.etag : null);
		}
		catch (RuntimeException e)
		{
			asked.remove(key);
			throw e;
		}
		request.thenAccept(response -> onResponse(name, generation, response.code, response.bytes, response.etag));
	}

	/**
	 * The answer to a check sent for lookup {@code generation}. 404 (no published character, or one
	 * still being drawn) and 451 (opted out) drop the portrait whatever lookup asked; only an answer for
	 * the latest lookup confirms one; a failure keeps it held but unconfirmed. An answer for an older
	 * lookup sends a fresh check for the latest.
	 */
	synchronized void onResponse(String name, int generation, int code, @Nullable byte[] bytes, @Nullable String etag)
	{
		String key = key(name);
		asked.remove(key);
		boolean latest = generation == generations.getOrDefault(key, 0);
		if (code == 404 || code == 451)
		{
			confirmed.remove(key);
			lane.values.remove(key);
			lane.fetched.remove(key);
			// A miss rests only when it answers the latest lookup or publish; an older one asks again at once.
			if (latest || code == 451)
			{
				lane.missing(key);
			}
			else
			{
				ask(name);
			}
			return;
		}
		Portrait held = lane.values.get(key);
		if (code == 304 && held != null)
		{
			lane.breaker.success();
			lane.ok(key, held);
		}
		else
		{
			BufferedImage image = code == 200 ? decode(bytes) : null;
			if (image == null)
			{
				lane.fail(key);
				return;
			}
			lane.breaker.success();
			lane.ok(key, new Portrait(image, etag));
		}
		if (latest)
		{
			confirmed.add(key);
			confirmed.retainAll(lane.values.keySet());
		}
		else
		{
			ask(name);
		}
	}

	/**
	 * A PNG of at most {@link #MAX_SIDE} pixels a side, or null. The size is read from the header
	 * before any pixels are, so a hostile file can't make the decoder allocate a huge image.
	 */
	@Nullable
	static BufferedImage decode(@Nullable byte[] bytes)
	{
		if (bytes == null || bytes.length < PNG_SIGNATURE.length || bytes.length > MAX_BYTES)
		{
			return null;
		}
		for (int i = 0; i < PNG_SIGNATURE.length; i++)
		{
			if (bytes[i] != PNG_SIGNATURE[i])
			{
				return null;
			}
		}
		Iterator<ImageReader> readers = ImageIO.getImageReadersByFormatName("png");
		if (!readers.hasNext())
		{
			return null;
		}
		ImageReader reader = readers.next();
		// Read in memory: ImageIO's default stream can spill to a temporary file on disk.
		try (ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(bytes)))
		{
			reader.setInput(input, true, true);
			int width = reader.getWidth(0);
			int height = reader.getHeight(0);
			if (width <= 0 || height <= 0 || width > MAX_SIDE || height > MAX_SIDE)
			{
				return null;
			}
			return reader.read(0);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Unreadable portrait: {}", e.getMessage());
			return null;
		}
		finally
		{
			reader.dispose();
		}
	}

	/** Space, hyphen and underscore are one separator to Jagex, so every spelling is one player. */
	static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ROOT).replaceAll("[\\s_-]+", " ");
	}
}

package com.killclog;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;

/** Only known codes and a bounded support reference may reach logs or tooltips. */
final class ProfileAppearanceFailure
{
	final String reason;
	final String reference;
	final String message;

	// Each known code's plain message, from appearance-failures.tsv; its parity test pins them.
	private static final Map<String, String> MESSAGES = new HashMap<>();

	static
	{
		for (String[] row : CatalogTsv.rows(ProfileAppearanceFailure.class, "appearance-failures.tsv", 2))
		{
			MESSAGES.put(row[0], row[1]);
		}
	}

	private ProfileAppearanceFailure(String reason, String reference, String message)
	{
		this.reason = reason;
		this.reference = reference;
		this.message = message + (reference.isEmpty() ? "" : " Reference: " + reference + ".");
	}

	static ProfileAppearanceFailure fromResponse(int status, @Nullable JsonObject body)
	{
		String code = field(body, "error");
		String reference = field(body, "request_id");
		if (!reference.matches("[a-f0-9]{16}"))
		{
			reference = "";
		}
		String message = "update_required".equals(code) ? FirstPartyFeedback.UPDATE_REQUIRED : MESSAGES.get(code);
		if (message == null)
		{
			code = status < 0 ? "network_failure" : "request_failed";
			message = status < 0 ? "Could not reach Kill Clog. Try again."
				: status == 429 ? "Too many requests. Please wait before retrying."
				: status >= 500 ? "Character service is unavailable. Try again later."
				: "Character request failed. Click to retry.";
		}
		return new ProfileAppearanceFailure(code, reference, message);
	}

	private static String field(@Nullable JsonObject body, String key)
	{
		JsonElement value = body != null ? body.get(key) : null;
		return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString()
			? value.getAsString() : "";
	}
}

package com.killclog;

import com.google.gson.annotations.SerializedName;
import java.util.Arrays;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import net.runelite.api.ColorTextureOverride;
import net.runelite.api.Item;
import net.runelite.api.PlayerComposition;

/** Fixed, data-only PlayerComposition recipe accepted by killclog.com. */
final class ProfileAppearanceManifest
{
	static final String SCHEMA = "killclog.appearance.v3";
	static final int EQUIPMENT_SLOTS = 12;
	static final int BODY_COLORS = 5;

	private final String schema = SCHEMA;

	@SerializedName("game_build")
	private final String gameBuild;

	@SerializedName("client_version")
	private final String clientVersion;

	private final int gender;
	private final int[] equipment;
	private final int[] colors;
	private final Override[] overrides;

	@SerializedName("transformed_npc_id")
	private final int transformedNpcId;

	@SerializedName("follower_npc_id")
	private final int followerNpcId;

	@SerializedName("idle_pose_animation")
	private final int idlePoseAnimation;

	private ProfileAppearanceManifest(String gameBuild, String clientVersion, int gender,
		int[] equipment, int[] colors, Override[] overrides, int transformedNpcId,
		int followerNpcId, int idlePoseAnimation)
	{
		this.gameBuild = gameBuild;
		this.clientVersion = clientVersion;
		this.gender = gender;
		this.equipment = Arrays.copyOf(equipment, equipment.length);
		this.colors = Arrays.copyOf(colors, colors.length);
		this.overrides = Arrays.copyOf(overrides, overrides.length);
		this.transformedNpcId = transformedNpcId;
		this.followerNpcId = followerNpcId;
		this.idlePoseAnimation = idlePoseAnimation;
	}

	@Nullable
	static ProfileAppearanceManifest capture(PlayerComposition composition, int gameBuild,
		String clientVersion, int followerNpcId, int idlePoseAnimation)
	{
		if (composition == null || composition.getTransformedNpcId() != -1
			|| followerNpcId < -1 || idlePoseAnimation < 0 || idlePoseAnimation > 65_535)
		{
			return null;
		}
		int[] equipment = composition.getEquipmentIds();
		int[] colors = composition.getColors();
		ColorTextureOverride[] sourceOverrides = composition.getColorTextureOverrides();
		if (equipment == null || equipment.length != EQUIPMENT_SLOTS
			|| colors == null || colors.length != BODY_COLORS
			|| (sourceOverrides != null && sourceOverrides.length != EQUIPMENT_SLOTS))
		{
			return null;
		}
		int gender = composition.getGender();
		if (gender != 0 && gender != 1)
		{
			return null;
		}

		Override[] overrides = new Override[EQUIPMENT_SLOTS];
		for (int i = 0; sourceOverrides != null && i < sourceOverrides.length; i++)
		{
			ColorTextureOverride value = sourceOverrides[i];
			if (value != null)
			{
				overrides[i] = new Override(
					toInts(value.getColorToReplaceWith()),
					toInts(value.getTextureToReplaceWith()));
			}
		}
		return new ProfileAppearanceManifest(Integer.toString(gameBuild), clientVersion,
			gender, equipment, colors, overrides, -1, followerNpcId, idlePoseAnimation);
	}

	ProfileAppearanceManifest withFollower(int npcId)
	{
		return new ProfileAppearanceManifest(gameBuild, clientVersion, gender, equipment,
			colors, overrides, transformedNpcId, npcId, idlePoseAnimation);
	}

	/** Reject an original snapshot that predates the current equipped items. */
	boolean matchesEquipment(Item[] worn)
	{
		if (worn == null) return false;
		// Arms, hair and jaw are body parts, not worn items. Native jaw values
		// can also encode game icons. Ring and ammo have no player model.
		for (int slot = 0; slot < EQUIPMENT_SLOTS; slot++)
		{
			if (slot == 6 || slot == 8 || slot == 11) continue;
			Item item = slot < worn.length ? worn[slot] : null;
			int itemId = item == null ? -1 : item.getId();
			if (itemId >= 0)
			{
				if (equipment[slot] != itemId + PlayerComposition.ITEM_OFFSET) return false;
			}
			else if (equipment[slot] >= PlayerComposition.ITEM_OFFSET) return false;
		}
		return true;
	}

	private static int[] toInts(short[] values)
	{
		if (values == null)
		{
			return new int[0];
		}
		int[] result = new int[values.length];
		for (int i = 0; i < values.length; i++)
		{
			result[i] = values[i];
		}
		return result;
	}

	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Override
	{
		private final int[] colors;
		private final int[] textures;

	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.function.BiFunction;
import java.util.function.BooleanSupplier;
import java.util.function.Function;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.CompletableFuture;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;

/** Publishes the current player's bounded appearance recipe, never image data. */
@Slf4j
@Singleton
final class ProfileAppearanceService
{
	static final long PUBLISH_RETRY_DELAY_MS = 2250L;
	private static final PublishResult PROFILE_REQUIRED = new PublishResult(Outcome.PROFILE_REQUIRED,
		"Sync your Collection Log, then publish your character again.");

	enum Outcome
	{
		PUBLISHED,
		DELETED,
		NO_CHARACTER,
		PROFILE_REQUIRED,
		DISABLED,
		RENDERING,
		BUSY,
		CANCELLED,
		UNKNOWN,
		APPEARANCE_PENDING,
		FAILED
	}

	static final class PublishResult
	{
		final Outcome outcome;
		final String message;

		private PublishResult(Outcome outcome)
		{
			this(outcome, null);
		}

		PublishResult(Outcome outcome, @Nullable String message)
		{
			this.outcome = outcome;
			this.message = message;
		}
	}

	private final Client client;
	private final ClientThread clientThread;
	private final AtomicBoolean inFlight = new AtomicBoolean();
	private volatile RetryHold retryHold;
	private volatile OriginalAppearance originalAppearance;

	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class OriginalAppearance
	{
		final Player player;
		final long account;
		final ProfileAppearanceManifest manifest;

	}

	/** Called before cosmetic plugins mutate the game's fresh appearance. */
	void captureOriginalAppearance(Player player)
	{
		if (player == null || player != client.getLocalPlayer()) return;
		long account = client.getAccountHash();
		ProfileAppearanceManifest manifest = ProfileAppearanceManifest.capture(
			player.getPlayerComposition(), client.getRevision(), SyncService.CLIENT_VERSION,
			-1, player.getIdlePoseAnimation());
		originalAppearance = account == 0 || manifest == null ? null
			: new OriginalAppearance(player, account, manifest);
	}

	void clearOriginalAppearance()
	{
		originalAppearance = null;
	}

	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class RetryHold
	{
		final long account;
		final long until;
		final PublishResult result;

	}
	private final okhttp3.OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	ProfileAppearanceService(Client client, ClientThread clientThread, okhttp3.OkHttpClient httpClient, Gson gson)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.httpClient = httpClient;
		this.gson = gson;
	}

	/**
	 * Whether a character request still stands, asked at each step; and its final send, made only while it does. The
	 * request's owner can make that send one step with its withdrawal, so nothing goes out once it has been withdrawn.
	 */
	@FunctionalInterface
	interface Authorization extends BooleanSupplier
	{
		default boolean sendIf(Runnable send)
		{
			if (!getAsBoolean())
			{
				return false;
			}
			send.run();
			return true;
		}
	}

	/**
	 * Publishes the logged-in player's character, for the login it was asked in: {@code authorized} says whether that
	 * login is still current and the request still wanted, and each step asks it again before it acts.
	 */
	CompletableFuture<PublishResult> publishCurrent(Session session, Authorization authorized)
	{
		return run(new PublishAttempt(session.getName(), session.getAccountHash(), authorized), this::captureAndPublish);
	}

	/**
	 * Removes the player's character from killclog.com, so their profile goes back to having none; nothing else of
	 * theirs changes.
	 */
	CompletableFuture<PublishResult> deleteCurrent(Session session, Authorization authorized)
	{
		return run(new PublishAttempt(session.getName(), session.getAccountHash(), authorized), attempt -> !attempt.active()
			? completed(Outcome.CANCELLED)
			: attempt.post("appearance/delete", "{}", (response, json) ->
			{
				if (response.code == 200 && json != null && json.has("deleted") && json.get("deleted").getAsBoolean())
				{
					return completed(Outcome.DELETED);
				}
				// No synced profile here, so no character on killclog.com: nothing to remove.
				return isProfileRequired(response.code, json) ? completed(Outcome.NO_CHARACTER)
					: failedResponse(attempt, "delete", response, json);
			}));
	}

	/** One character request at a time: it starts on the client thread and frees the slot when its chain settles. */
	private CompletableFuture<PublishResult> run(PublishAttempt attempt,
		Function<PublishAttempt, CompletableFuture<PublishResult>> request)
	{
		if (!inFlight.compareAndSet(false, true)) return completed(Outcome.BUSY);
		CompletableFuture<PublishResult> result = new CompletableFuture<>();
		try
		{
			clientThread.invokeLater(() ->
			{
				try
				{
					request.apply(attempt).whenComplete((value, error) ->
					{
						// Retain the slot across cancellation until the whole chain settles.
						inFlight.set(false);
						result.complete(error == null ? value : failed());
					});
				}
				catch (RuntimeException e)
				{
					inFlight.set(false);
					result.complete(failed());
				}
			});
		}
		catch (RuntimeException e)
		{
			inFlight.set(false);
			result.complete(failed());
		}
		return result;
	}

	private CompletableFuture<PublishResult> captureAndPublish(PublishAttempt attempt)
	{
		if (!attempt.active()) return completed(Outcome.CANCELLED);
		RetryHold hold = retryHold;
		if (hold != null && hold.account == attempt.accountHash && System.currentTimeMillis() < hold.until)
		{
			return CompletableFuture.completedFuture(hold.result);
		}
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return CompletableFuture.completedFuture(new PublishResult(Outcome.FAILED,
				"Your character is not ready. Wait until it is visible, then retry."));
		}
		PlayerComposition composition = local.getPlayerComposition();
		if (composition != null && composition.getTransformedNpcId() != -1)
		{
			return CompletableFuture.completedFuture(new PublishResult(Outcome.FAILED,
				"Return to your normal player form and retry."));
		}
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null || worn.getItems() == null)
		{
			return CompletableFuture.completedFuture(new PublishResult(Outcome.FAILED,
				"Your equipment is not ready. Wait a moment, then retry."));
		}
		OriginalAppearance original = originalAppearance;
		if (original == null || original.player != local || original.account != attempt.accountHash
			|| !original.manifest.matchesEquipment(worn.getItems()))
		{
			return CompletableFuture.completedFuture(new PublishResult(Outcome.APPEARANCE_PENDING,
				"Equip or unequip an item, then publish again so Kill Clog can read your real appearance."));
		}
		ProfileAppearanceManifest manifest = original.manifest.withFollower(visibleFollowerNpcId(client.getFollower()));
		return attempt.post("appearance/publish/main", gson.toJson(manifest), (response, json) ->
		{
			if (isRenderedPublishResponse(response.code, json))
			{
				return completed(Outcome.PUBLISHED);
			}
			if (isAcceptedPendingPublishResponse(response.code, json))
			{
				return holdRetry(attempt, new PublishResult(Outcome.RENDERING,
					"Your character was accepted and is still rendering. Check your profile shortly."), 15);
			}
			return isProfileRequired(response.code, json) ? CompletableFuture.completedFuture(PROFILE_REQUIRED)
				: failedResponse(attempt, "publish", response, json);
		});
	}

	/**
	 * Each HTTP dispatch asks again, on the client thread, whether its login is still current and the request still
	 * wanted. A request proves its account by the account hash its name is bound to, as a sync does.
	 */
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private final class PublishAttempt
	{
		private final String rsn;
		private final long accountHash;
		private final Authorization authorized;

		private boolean active()
		{
			return authorized.getAsBoolean();
		}

		private CompletableFuture<PublishResult> post(String suffix, String body,
			BiFunction<HttpUtil.HttpResult, JsonObject, CompletableFuture<PublishResult>> handle)
		{
			CompletableFuture<HttpUtil.HttpResult> result = new CompletableFuture<>();
			try
			{
				clientThread.invokeLater(() ->
				{
					try
					{
						boolean sent = authorized.sendIf(() ->
							HttpUtil.httpPostJson(httpClient, endpoint(rsn, suffix), body, Long.toString(accountHash))
								.whenComplete((response, error) ->
								{
									if (error != null) result.completeExceptionally(error);
									else result.complete(response);
								}));
						if (!sent)
						{
							result.complete(new HttpUtil.HttpResult(-2, null));
						}
					}
					catch (RuntimeException e)
					{
						result.completeExceptionally(e);
					}
				});
			}
			catch (RuntimeException e)
			{
				result.completeExceptionally(e);
			}
			return result.thenCompose(response ->
			{
				JsonObject json = parse(response.body);
				return response.code == -2 ? completed(Outcome.CANCELLED)
					: isDryRun(response, json) ? CompletableFuture.completedFuture(new PublishResult(Outcome.DISABLED,
						"Character publishing is temporarily unavailable. Try again later."))
					: handle.apply(response, json);
			});
		}
	}

	static int visibleFollowerNpcId(@Nullable NPC follower)
	{
		if (follower == null)
		{
			return -1;
		}
		NPCComposition transformed = follower.getTransformedComposition();
		NPCComposition visible = transformed != null ? transformed : follower.getComposition();
		String[] actions = visible != null ? visible.getActions() : null;
		if (visible == null || !visible.isFollower() || actions == null
			|| !Arrays.asList(actions).contains("Pick-up"))
		{
			return -1;
		}
		return transformed != null ? transformed.getId() : follower.getId();
	}

	private CompletableFuture<PublishResult> failedResponse(PublishAttempt attempt, String operation,
		HttpUtil.HttpResult response, @Nullable JsonObject json)
	{
		ProfileAppearanceFailure failure = ProfileAppearanceFailure.fromResponse(response.code, json);
		log.warn("Character {} failed: status={} reason={} reference={}",
			operation, response.code, failure.reason, failure.reference);
		if (response.code < 0 && "publish".equals(operation))
		{
			return holdRetry(attempt, new PublishResult(Outcome.UNKNOWN,
				"The connection was interrupted. Your character may have updated. Check your profile before retrying."), 10);
		}
		int delay = response.retryAfterSeconds;
		if (delay == 0 && (response.code == 429 || response.code == 503)) delay = 60;
		PublishResult result = new PublishResult(Outcome.FAILED, failure.message
			+ (delay > 0 ? " Retry after " + displayTime(java.time.Instant.now().plusSeconds(delay).toString()) + "." : ""));
		return holdRetry(attempt, result, delay);
	}

	private CompletableFuture<PublishResult> holdRetry(PublishAttempt attempt, PublishResult result, int seconds)
	{
		retryHold = new RetryHold(attempt.accountHash, System.currentTimeMillis() + seconds * 1000L, result);
		return CompletableFuture.completedFuture(result);
	}

	@Nullable
	private static String displayTime(@Nullable String value)
	{
		try
		{
			return java.time.format.DateTimeFormatter.ofPattern("MMM d, HH:mm z", java.util.Locale.ENGLISH)
				.withZone(java.time.ZoneId.systemDefault()).format(java.time.Instant.parse(value));
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private JsonObject parse(@Nullable String body)
	{
		if (body == null || body.isBlank())
		{
			return null;
		}
		try
		{
			return gson.fromJson(body, JsonObject.class);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static boolean isDryRun(HttpUtil.HttpResult response, @Nullable JsonObject json)
	{
		return response.code >= 200 && response.code < 300
			&& json != null && json.has("dry_run") && json.get("dry_run").getAsBoolean();
	}

	private static boolean hasError(@Nullable JsonObject json, String error)
	{
		return error.equals(stringValue(json, "error"));
	}

	static boolean isProfileRequired(int responseCode, @Nullable JsonObject json)
	{
		return responseCode == 409
			&& (hasError(json, "no_bound_account")
				|| hasError(json, "binding_not_verified"));
	}

	static boolean isRenderedPublishResponse(int responseCode, @Nullable JsonObject json)
	{
		try
		{
			return responseCode == 200
				&& json != null && json.has("published")
				&& json.get("published").getAsBoolean()
				&& "ready".equals(stringValue(json, "render_status"));
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	static boolean isAcceptedPendingPublishResponse(int responseCode,
		@Nullable JsonObject json)
	{
		try
		{
			return responseCode == 202
				&& json != null && json.has("accepted")
				&& json.get("accepted").getAsBoolean()
				&& "pending_renderer".equals(stringValue(json, "render_status"));
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	@Nullable
	private static String stringValue(@Nullable JsonObject json, String key)
	{
		try
		{
			return json != null && json.has(key) && !json.get(key).isJsonNull()
				? json.get(key).getAsString() : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static String endpoint(String rsn, String suffix)
	{
		return KillClogEndpoint.apiBaseUrl() + "/player/"
			+ HttpUtil.pathSegment(rsn)
			+ "/" + suffix;
	}

	private static CompletableFuture<PublishResult> completed(Outcome outcome)
	{
		return CompletableFuture.completedFuture(new PublishResult(outcome));
	}

	private static PublishResult failed()
	{
		return new PublishResult(Outcome.FAILED, "Could not update your character. Please retry.");
	}
}

package com.killclog;

import java.util.List;
import java.util.Map;
import javax.swing.JLabel;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.ui.ColorScheme;

/**
 * Color-setting logic for the completionist highlighter.
 * Constructor takes stable references (maps populated before construction);
 * methods take per-lookup state and late-assigned labels.
 */
final class ProgressHighlighter
{
	private final Map<HiscoreSkill, JLabel> bossLabels;

	private final Map<HiscoreSkill, JLabel> activityLabels;
	private final Map<HiscoreSkill, JLabel> clueTierLabels;
	private final KillClogConfig config;

	ProgressHighlighter(
		Map<HiscoreSkill, JLabel> bossLabels,
		Map<HiscoreSkill, JLabel> activityLabels,
		Map<HiscoreSkill, JLabel> clueTierLabels,
		KillClogConfig config)
	{
		this.bossLabels = bossLabels;
		this.activityLabels = activityLabels;
		this.clueTierLabels = clueTierLabels;
		this.config = config;
	}

	/** Color boss, activity and clue tier cells by clog completion progress. */
	void colorCellsByCompletion(HiscoreResult hiscoreResult, ClogResult clogResult)
	{
		if (clogResult == null)
		{
			return;
		}

		for (Map.Entry<HiscoreSkill, JLabel> entry : bossLabels.entrySet())
		{
			HiscoreSkill skill = entry.getKey();
			String hiscoreName = PanelData.hiscoreName(skill.getName());
			colorBossCell(entry.getValue(), hiscoreName, hiscoreResult, clogResult);
		}
		colorClueTiers(hiscoreResult, clogResult);

		// Clue All aggregates across all six tier categories.
		JLabel clueAllLabel = activityLabels.get(HiscoreSkill.CLUE_SCROLL_ALL);
		if (clueAllLabel != null)
		{
			int totalItems = 0;
			int totalObtained = 0;
			for (String cat : PanelData.CLUE_CATEGORIES.values())
			{
				List<Integer> items = clogResult.getCategoryItems().get(cat);
				if (items != null)
				{
					totalItems += items.size();
					totalObtained += ClogHelper.countObtained(items, ClogHelper.getObtainedIds(cat, clogResult));
				}
			}
			if (totalItems > 0)
			{
				clueAllLabel.setForeground(ClogHelper.clogColor(totalObtained, totalItems, config));
			}
		}
	}

	/** Recolor "--" cells to emptyClogColor when highlighter is active. */
	void colorEmptyCells()
	{
		for (JLabel label : bossLabels.values())
		{
			if (ColorScheme.LIGHT_GRAY_COLOR.equals(label.getForeground()))
			{
				label.setForeground(config.emptyClogColor());
			}
		}
		for (JLabel label : activityLabels.values())
		{
			if (ColorScheme.LIGHT_GRAY_COLOR.equals(label.getForeground()))
			{
				label.setForeground(config.emptyClogColor());
			}
		}
		for (JLabel label : clueTierLabels.values())
		{
			if (ColorScheme.LIGHT_GRAY_COLOR.equals(label.getForeground()))
			{
				label.setForeground(config.emptyClogColor());
			}
		}
	}

	// Private helpers.

	private void colorBossCell(JLabel label, String hiscoreName,
		HiscoreResult hiscoreResult, ClogResult clogResult)
	{

		int kc = hiscoreResult.getKc(hiscoreName);
		if (kc <= 0) return;

		colorByCompletion(label, ClogService.bossToCategory(hiscoreName), clogResult);
	}

	private void colorClueTiers(HiscoreResult hiscoreResult, ClogResult clogResult)
	{
		for (Map.Entry<HiscoreSkill, String> entry : PanelData.CLUE_CATEGORIES.entrySet())
		{
			JLabel label = clueTierLabels.get(entry.getKey());
			if (label != null)
			{
				int score = hiscoreResult.getActivityScore(entry.getKey().getName());
				if (score > 0)
				{
					colorByCompletion(label, entry.getValue(), clogResult);
				}
			}
		}
	}

	private void colorByCompletion(JLabel label, String category, ClogResult clogResult)
	{
		List<Integer> allItems = clogResult.getCategoryItems().get(category);
		if (allItems == null || allItems.isEmpty())
		{
			// KC exists but no clog data was found for this category.
			label.setForeground(config.emptyClogColor());
			return;
		}

		label.setForeground(ClogHelper.clogColor(
			ClogHelper.countObtained(allItems, ClogHelper.getObtainedIds(category, clogResult)),
			allItems.size(), config));
	}
}

package com.killclog;

import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import javax.swing.SwingUtilities;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * The plugin's publication flow: the debounced killclog.com sync push with its one slot and the push waiting for it,
 * and the character publish that may run one sync of the log first and try again once. Event subscriptions stay in
 * the plugin; it forwards the moments that matter (captures, login, logout, opt-in, opt-out, shutdown) and hands the
 * panel's feedback in through {@link Feedback}.
 *
 * <p>One owner: every bit of the flow's state belongs to a serial executor, and every other thread (the client's, the
 * panel's, a timer's, a network reply's) only posts to it, so a check and the change it allows are never pulled apart.
 * Work that leaves the owner (the client thread's gather, the network) carries tokens back: the login it is for, the
 * era it was asked in (an opt-out, logout or shutdown moves it on at once), and its attempt's number. The two places a
 * request goes out, the sync gate's commit and the character's send, check their tokens under their own lock, so
 * nothing goes once its withdrawal has returned.
 */
@Slf4j
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class PublicationCoordinator
{
	/** The panel's side of the flow. Every call arrives on the EDT. */
	interface Feedback
	{
		void showSyncProgress(boolean manual, String text, boolean autoClear);

		void showSyncResult(boolean manual, boolean ok, String message);

		void showCharacterPublishStatus(CharacterStatus status, boolean autoClear, String failureMessage);

		/** The sync's own line and memory taken down, nothing else on the row. */
		void resetSyncFeedback();
	}

	// Quiet time: a log walk lands page after page, and one push carries them all once the captures stop for this
	// long. A walk that never pauses still sends a minute after its first capture.
	static final int SYNC_DEBOUNCE_SECONDS = 10;
	static final long SYNC_MAX_WAIT_MS = 60_000L;
	private static final String SYNC_FAILED = "Collection log sync failed. See the client log.";
	static final int NONE = -1;

	private final KillClogConfig config;
	private final ConfigManager configManager;
	private final ClientThread clientThread;
	private final ScheduledExecutorService executor;
	private final SessionTracker sessions;
	private final SyncService syncService;
	private final ProfileAppearanceService profileAppearanceService;
	private final KillClogChatNotifier chatNotifier;
	private final Feedback feedback;
	private final Supplier<AccountType> localAccountType;
	// The world's game mode, each mode's own store and a League's RuneLite PB profile type;
	// no mode means nothing is sent.
	private final Supplier<String> mode;
	// On the client thread: the world's Hardcore Worlds reading (total XP, 0 before it settles, -1 off it), taken with
	// the game each push gathers for, so a push never carries another login's (Sol 10/27).
	private final LongSupplier hardcoreXp;
	private final Function<String, LocalClogCache> modeCache;
	private final Function<String, String> leagueProfileType;

	// The owner, and everything only its tasks touch.
	private final SerialExecutor owner = new SerialExecutor();
	private final KillclogSyncGate<Push> syncGate = new KillclogSyncGate<>(Push::merge);
	private ScheduledFuture<?> pendingTimer;
	// The push that timer sends; a timer whose push is no longer this one was superseded.
	private Push pendingPush;
	// Whether the push waiting is an automatic one, which a capture may push back, and when its first capture came.
	private boolean pendingAutomatic;
	private long quietSince;
	// The login the server turned away (opted out, the name another account's, an update needed): its automatic
	// pushes stop, so the log stops leaving the client, until the next login or a click's attempt.
	private long stoppedSession = -1;
	/* package */ java.util.function.LongSupplier clock = System::currentTimeMillis;
	// The attempt whose line ("syncing...", "retrying...") the row shows, 0 for none: a line comes down only for its own.
	private volatile int lineAttempt;

	// The character request, one at a time. The generation only grows: a withdrawal moves it on, so work from before
	// can never act, wait or free the slot again. A request keeps its slot through its log's sync and retry. Read on
	// the Swing thread to fence status lines, so volatile; changed only by the owner.
	private volatile int characterGeneration;
	private int characterHolder = NONE;
	private int characterWaiting = NONE;
	private boolean characterPrerequisiteAttempted;
	private Session characterSession = Session.none(0);
	private int characterRequestEra;
	// The character's withdrawal fence: turning publication off, or a logout, moves the era at once, and a request's
	// final send checks it in the same step, so nothing goes once the withdrawal has returned.
	private final Object characterFence = new Object();
	private int characterEra;

	boolean characterPublishingEnabled()
	{
		return config.killclogSync() && config.characterModel();
	}

	/**
	 * One push of the log: the login it is for, taken where it began (a press, the opt-in, a capture); the era it was
	 * asked in; its game (null follows the world); whether a player asked for it; the character request it is the sync
	 * for, by generation (NONE for none); when it was asked; the games whose one advised retry it has spent; and the
	 * attempt whose line speaks for it while it waits (0 for none).
	 */
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Push
	{
		private static final java.util.concurrent.atomic.AtomicLong ASKED = new java.util.concurrent.atomic.AtomicLong();

		final Session session;
		final int era;
		final String mode;
		final boolean manual;
		final int forCharacter;
		final long asked;
		final Set<String> retried;
		final int line;
		// Whether this is the server's retry of its own ask: fixed, so the lead between two never shifts with merging.
		final boolean retryOfAsk;
		// Automatic sync's era it was asked in, and whether it carries a server-advised wait (kept through merging).
		final int automaticEra;
		final boolean holdsWait;

		/** A push asked for now, with the eras it was asked in. */
		static Push ask(Session session, int era, int automaticEra, String mode, boolean manual, int forCharacter)
		{
			return new Push(session, era, mode, manual, forCharacter, ASKED.incrementAndGet(), Collections.emptySet(), 0,
				false, automaticEra, false);
		}

		/** The server's one retry, for the game its attempt resolved, its line kept by that attempt, and its wait. */
		Push retriedIn(String game, int attempt)
		{
			Set<String> spent = new HashSet<>(retried);
			spent.add(game);
			return new Push(session, era, game, manual, forCharacter, asked, Collections.unmodifiableSet(spent), attempt,
				true, automaticEra, true);
		}

		Push withoutCharacter()
		{
			return new Push(session, era, mode, manual, NONE, asked, retried, line, retryOfAsk, automaticEra, holdsWait);
		}

		/** Whether its one advised retry is spent for its game: it never retries again. */
		boolean retry()
		{
			return retried.contains(mode);
		}

		/** A click's or a character's: it goes past Automatic sync being off, and nothing automatic stands in for it. */
		boolean deliberate()
		{
			return manual || forCharacter != NONE;
		}

		/** The later of two to lead: a click over an automatic push, then the later asked, a retry after its own push. */
		private static boolean leads(Push one, Push other)
		{
			if (one.manual != other.manual)
			{
				return one.manual;
			}
			if (one.asked != other.asked)
			{
				return one.asked > other.asked;
			}
			return one.retryOfAsk && !other.retryOfAsk;
		}

		/**
		 * Two pushes go as one, the same in whatever order and grouping they meet: pushes of two logins, or of two eras
		 * of one, never mix (the newer stands whole; both only grow); within one, the lead's game and age, a click if
		 * either was, the newer character request (generations only grow), the retries spent by either, and any
		 * server-advised wait either carries.
		 */
		static Push merge(Push one, Push other)
		{
			if (one.session.getNumber() != other.session.getNumber())
			{
				return one.session.getNumber() > other.session.getNumber() ? one : other;
			}
			if (one.era != other.era)
			{
				return one.era > other.era ? one : other;
			}
			Push lead = leads(other, one) ? other : one;
			Set<String> spent = new HashSet<>(one.retried);
			spent.addAll(other.retried);
			return new Push(lead.session, lead.era, lead.mode, one.manual || other.manual,
				Math.max(one.forCharacter, other.forCharacter), lead.asked, Collections.unmodifiableSet(spent),
				Math.max(one.line, other.line), lead.retryOfAsk, Math.max(one.automaticEra, other.automaticEra),
				one.holdsWait || other.holdsWait);
		}
	}

	// ── entry points: any thread; each takes its tokens where it begins, then posts to the owner ──

	/** A capture, login or settled identity, on the client thread: one quiet push for this game after the debounce. */
	void scheduleAutomaticSync()
	{
		int automatic = syncGate.automaticEra();
		int era = syncGate.era();
		Push push = Push.ask(sessions.current(), era, automatic, mode.get(), false, NONE);
		owner.execute(() -> schedule(SYNC_DEBOUNCE_SECONDS, push));
	}

	/**
	 * Manual web pushes (the panel sync button, an explicit opt-in) narrate in chat;
	 * automatic ones (capture debounce and login catch-up) default to silent
	 * panel feedback. Chat still follows its separate setting.
	 */
	void pushNow(Session origin, int era, boolean manual)
	{
		pushNow(origin, era, manual, NONE);
	}

	/** The sync's era now: a press or an opt-in takes it with its login, before anything else. */
	int syncEra()
	{
		return syncGate.era();
	}

	private void pushNow(Session origin, int era, boolean manual, int forCharacter)
	{
		int automatic = syncGate.automaticEra();
		// The game it pushes is read on the client thread; a logout before the hop drops it.
		clientThread.invoke(() ->
		{
			String game = mode.get();
			owner.execute(() ->
			{
				if (sessions.isCurrent(origin))
				{
					schedule(0, Push.ask(origin, era, automatic, game, manual, forCharacter));
				}
				else
				{
					failWaiting(forCharacter);
				}
			});
		});
	}

	/**
	 * The panel's sync arrow: push now, skipping any pending debounce. The
	 * single-flight gate remembers a click during an in-flight request, so
	 * icon-only feedback never makes that deliberate action disappear.
	 */
	void manualSync()
	{
		int era = syncGate.era();
		Session pressed = sessions.current();
		if (config.killclogSync())
		{
			pushNow(pressed, era, true);
		}
	}

	/** Opt-out, logout, shutdown: the era moves on at once, so nothing begun before claims, commits or speaks. */
	void cancelSync()
	{
		int era = syncGate.cancel();
		owner.execute(() -> withdrawSync(era));
		// A request already in the air keeps the slot until it completes (no overlap on re-enable); its completion
		// finds its era passed and stays silent.
	}

	/**
	 * Automatic sync turned off: an automatic push not yet sent never goes, waiting on its timer or its retry, and one
	 * in the air is silenced, its line taken down; a click or a character's own sync goes on.
	 */
	void cancelAutomaticSync()
	{
		int silenced = syncGate.withdrawAutomatic();
		int cutoff = syncGate.automaticEra();
		owner.execute(() -> withdrawAutomatic(silenced, cutoff));
	}

	/** The owner's half of an opt-out: only what was asked before it goes; a push asked in the new era stays. */
	private void withdrawSync(int era)
	{
		if (pendingPush != null && pendingPush.era < era)
		{
			dropPending();
		}
	}

	/** Whether turning Automatic sync off (to {@code cutoff}) withdraws this push: automatic, asked before it. */
	private static boolean withdrawnBy(Push push, int cutoff)
	{
		return !push.deliberate() && push.automaticEra < cutoff;
	}

	/** The owner's half of Automatic sync off: only an automatic push asked before it; one asked since stays. */
	private void withdrawAutomatic(int silenced, int cutoff)
	{
		takeLineDown(silenced);
		if (pendingPush != null && withdrawnBy(pendingPush, cutoff))
		{
			takeLineDown(pendingPush.line);
			dropPending();
		}
	}

	void publishCharacter()
	{
		int era = characterEra();
		Session pressed = sessions.current();
		owner.execute(() -> startCharacterRequest(pressed, era, NONE, CharacterStatus.RENDERING,
			profileAppearanceService::publishCurrent, this::handleCharacterPublishResult));
	}

	/**
	 * Shift-click on the character: removes it from killclog.com, so the profile goes back to having none. It shares
	 * the publish's one-at-a-time slot and its status line.
	 */
	void deleteCharacter()
	{
		int era = characterEra();
		Session pressed = sessions.current();
		owner.execute(() -> startCharacterRequest(pressed, era, NONE, CharacterStatus.DELETING,
			profileAppearanceService::deleteCurrent, this::characterDone));
	}

	/** Publication turned off, or a logout: no character request goes out from the moment this returns. */
	void cancelCharacterPublish()
	{
		int era;
		synchronized (characterFence)
		{
			era = ++characterEra;
		}
		owner.execute(() -> withdrawCharacter(era));
	}

	/** The owner's half of a character withdrawal: a request pressed in the new era is newer than it, and stays. */
	private void withdrawCharacter(int era)
	{
		// Held or already finished, a request pressed in this era or later is newer than the withdrawal.
		if (characterRequestEra >= era)
		{
			return;
		}
		int generation = ++characterGeneration;
		characterHolder = NONE;
		characterWaiting = NONE;
		characterPrerequisiteAttempted = false;
		showCharacterPublishStatus(generation, CharacterStatus.CLEAR, false);
	}

	private int characterEra()
	{
		synchronized (characterFence)
		{
			return characterEra;
		}
	}

	// ── sync push: the owner's ─────────────────────────────────────────

	/**
	 * Whether a push goes now: sync is on, its era and login last; a click always; a character's own sync while that
	 * request still waits on it; an automatic one with Automatic sync on and its login not turned away.
	 */
	private boolean sends(Push push)
	{
		if (!config.killclogSync() || push.era != syncGate.era() || !sessions.isCurrent(push.session))
		{
			return false;
		}
		if (push.manual)
		{
			return true;
		}
		if (push.forCharacter != NONE)
		{
			return waitingFor(push.forCharacter);
		}
		return config.automaticSync() && push.automaticEra == syncGate.automaticEra()
			&& push.session.getNumber() != stoppedSession;
	}

	/** The settings still want it sent: sync on, and an automatic push with Automatic sync on. Any thread. */
	private boolean stillWanted(Push push)
	{
		return config.killclogSync() && (push.deliberate() || config.automaticSync());
	}

	/** A push whose character request was withdrawn is just a push again, so it goes, or not, on its own terms. */
	private Push live(Push push)
	{
		return push.forCharacter == NONE || waitingFor(push.forCharacter) ? push : push.withoutCharacter();
	}

	/**
	 * A push after its delay. A push that can't go fails the character request it was for, so none waits forever. An
	 * automatic push while another automatic one waits starts its quiet time again, up to the minute's cap; one behind
	 * a click, a character's sync or a retry rides it. A click or a character's sync takes over what waits, merged.
	 */
	private void schedule(int delaySeconds, Push asked)
	{
		Push push = live(asked);
		if (!sends(push))
		{
			abandon(push, 0);
			return;
		}
		long now = clock.getAsLong();
		long delayMs = delaySeconds * 1000L;
		if (pendingPush != null && !sends(live(pendingPush)))
		{
			// Waiting work a withdrawal has made obsolete never stands in for a live push; its cleanup may still be
			// on its way.
			takeLineDown(pendingPush.line);
			dropPending();
		}
		if (pendingPush != null)
		{
			if (!push.deliberate())
			{
				long left = quietSince + SYNC_MAX_WAIT_MS - now;
				if (pendingAutomatic && !push.retry() && left > 0)
				{
					startTimer(Math.min(delayMs, left), push);
				}
				return;
			}
			if (pendingPush.holdsWait && pendingTimer != null)
			{
				// The server asked for this wait: a click or a character's sync asked meanwhile rides what is left of
				// it, by the timer's own clock.
				delayMs = Math.max(delayMs, pendingTimer.getDelay(TimeUnit.MILLISECONDS));
			}
			push = Push.merge(pendingPush, push);
		}
		quietSince = now;
		startTimer(delayMs, push);
	}

	private void startTimer(long delayMs, Push push)
	{
		if (pendingTimer != null)
		{
			pendingTimer.cancel(false);
		}
		pendingPush = push;
		pendingAutomatic = !push.deliberate() && !push.retry();
		try
		{
			pendingTimer = executor.schedule(() -> owner.execute(() -> fire(push)), delayMs, TimeUnit.MILLISECONDS);
		}
		catch (RuntimeException e)
		{
			pendingPush = null;
			pendingTimer = null;
			abandon(push, 0);
		}
	}

	/** The push waiting on its timer, if any, never fires. */
	private void dropPending()
	{
		if (pendingTimer != null)
		{
			pendingTimer.cancel(false);
		}
		pendingTimer = null;
		pendingPush = null;
	}

	/** A timer fired: its push goes, unless another has taken its place since. */
	private void fire(Push push)
	{
		if (push != pendingPush)
		{
			return;
		}
		pendingPush = null;
		pendingTimer = null;
		send(push);
	}

	private void launchQueued()
	{
		Push queued = syncGate.takeQueued();
		if (queued != null)
		{
			schedule(0, queued);
		}
	}

	private void send(Push asked)
	{
		Push push = live(asked);
		if (!sends(push))
		{
			abandon(push, 0);
			return;
		}
		int attempt = syncGate.begin(push, push.era,
			push.deliberate() ? KillclogSyncGate.DELIBERATE : push.automaticEra);
		if (attempt == KillclogSyncGate.BUSY)
		{
			return;
		}
		if (attempt == KillclogSyncGate.STALE)
		{
			abandon(push, 0);
			return;
		}
		if (push.manual)
		{
			// A click's attempt begins: its login's automatic pushes go again.
			stoppedSession = -1;
		}
		clientThread.invoke(() ->
		{
			// Any throw before the request takes ownership must release the slot, or sync is silently dead until
			// restart: the client thread swallows the exception and the player sees nothing.
			try
			{
				gather(push, attempt);
			}
			catch (RuntimeException e)
			{
				log.warn("killclog sync push failed before dispatch", e);
				owner.execute(() -> failBeforeSend(push, attempt));
			}
		});
	}

	/** On the client thread: the game, its store, the account type and the PBs the attempt carries. */
	private void gather(Push push, int attempt)
	{
		if (standsDown(push, attempt))
		{
			return;
		}
		// A League sync reads only that League's store and profile, so it finishes after a hop off its worlds; a
		// main sync needs a settled main world, so it follows this one. A retry is for the game its attempt resolved:
		// a main one off the main game is let go, since the main account type answers only on a settled main world.
		String world = mode.get();
		long hardcore = hardcoreXp.getAsLong();
		String gameMode = push.retry() ? (GameMode.MAIN.equals(push.mode) && !GameMode.MAIN.equals(world) ? null
			: push.mode) : push.mode == null || GameMode.MAIN.equals(push.mode) ? world : push.mode;
		LocalClogCache cache = gameMode == null ? null : modeCache.apply(gameMode);
		if (!push.session.loggedIn() || gameMode == null || cache == null)
		{
			// Fired before a new world settled: its login catch-up waited behind this timer.
			boolean again = push.mode != null && gameMode == null && !push.manual && !push.retry();
			owner.execute(() -> stopped(push, attempt, again));
			return;
		}
		boolean main = GameMode.MAIN.equals(gameMode);
		// A League is one account status for everyone: its sync never carries a main type.
		AccountType accountType = main ? localAccountType.get() : null;
		if (push.manual)
		{
			chatNotifier.send(ChatNotice.SYNC_RESULT, "Syncing collection log...");
		}
		List<String> profileKeys = PersonalBests.profileKeys(configManager.getRSProfiles(), push.session.getAccountHash(),
			main ? RuneScapeProfileType.STANDARD.name() : leagueProfileType.apply(gameMode));
		Map<String, Double> pbs = new LinkedHashMap<>();
		Map<String, PbRecord> detailedPbs = gatherPersonalBests(profileKeys, pbs);
		// Off the client thread before dispatch: the sync pre-flight can block up to ten seconds waiting for the
		// rename disk verdict, and game ticks must never pay that wait.
		long pushHardcore = main ? hardcore : -1;
		executor.execute(() -> dispatch(push, attempt, accountType, pbs, detailedPbs, cache, gameMode, pushHardcore));
	}

	/**
	 * Queued behind a logout, an opt-out or Automatic sync going off, an attempt never gathers or sends for the next
	 * account: it stops instead.
	 */
	private boolean standsDown(Push push, int attempt)
	{
		if (!syncGate.live(attempt) || !sessions.isCurrent(push.session) || !stillWanted(push))
		{
			owner.execute(() -> stopped(push, attempt, false));
			return true;
		}
		return false;
	}

	/** The attempt never went: its slot frees, it ends what it began, and the push waiting goes. */
	private void stopped(Push push, int attempt, boolean scheduleCatchUp)
	{
		syncGate.release(attempt);
		abandon(push, attempt);
		launchQueued();
		if (scheduleCatchUp)
		{
			// The catch-up follows the world, so a world still unknown when it fires gets no more.
			schedule(SYNC_DEBOUNCE_SECONDS, Push.ask(push.session, push.era, push.automaticEra, null, false, NONE));
		}
	}

	/** Off the owner (the pre-flight can block): the request, its reply posted back to the owner. */
	private void dispatch(Push push, int attempt, AccountType accountType, Map<String, Double> pbs,
		Map<String, PbRecord> detailedPbs, LocalClogCache cache, String gameMode, long hardcore)
	{
		if (standsDown(push, attempt))
		{
			return;
		}
		try
		{
			syncService.syncCollectionLog(push.session, accountType, pbs, detailedPbs, syncGate, attempt, cache, gameMode,
				hardcore, push.deliberate(), () -> owner.execute(() -> sending(push, attempt)))
				.whenComplete((result, error) -> owner.execute(() -> completed(push, attempt, gameMode, result, error)));
		}
		catch (RuntimeException e)
		{
			log.warn("killclog sync push failed at dispatch", e);
			owner.execute(() -> failBeforeSend(push, attempt));
		}
	}

	/** The push really goes: only then does the row say so (one killclog.com already holds stays quiet). */
	private void sending(Push push, int attempt)
	{
		if (push.forCharacter == NONE && syncGate.live(attempt))
		{
			lineAttempt = attempt;
			say(push, () -> feedback.showSyncProgress(push.manual, "syncing...", false));
		}
	}

	private void completed(Push push, int attempt, String gameMode, SyncService.SyncResult result, Throwable error)
	{
		boolean live = syncGate.release(attempt);
		boolean character = push.forCharacter != NONE;
		if (live && result != null && config.killclogSync())
		{
			// Server-advised contention retry: another client of this account held the lock. A character request
			// rides that one allowed retry.
			if (result.retryAdvised && !push.retry())
			{
				retry(push, attempt, gameMode, result.retryAfterSeconds);
				launchQueued();
				return;
			}
			if (result.stopsSession)
			{
				stoppedSession = push.session.getNumber();
			}
			if (character)
			{
				// Only the request this sync was for goes on or fails; a withdrawn one has nothing to say.
				if (takeWaiting(push.forCharacter))
				{
					if (result.ok && !result.dryRun && characterPublishingEnabled())
					{
						scheduleCharacterPublishAfterSync(push.forCharacter);
					}
					else
					{
						failCharacterPublish(push.forCharacter);
					}
				}
			}
			else if (result != SyncService.UNCHANGED)
			{
				sayResult(push, result.ok, result.message);
			}
			if (push.manual || !result.ok)
			{
				chatFor(push.session, result.message);
			}
		}
		else if (live)
		{
			if (character)
			{
				failWaiting(push.forCharacter);
			}
			else if (error != null)
			{
				sayResult(push, false, SYNC_FAILED);
			}
		}
		else
		{
			// Silenced or from a passed era: what it began ends quietly.
			abandon(push, attempt);
		}
		launchQueued();
	}

	/**
	 * The server's one advised retry, after its own delay: a capture's shorter debounce must not stand in for it.
	 * Nobody is watching an automatic sync, so it waits out a slow restart; a player waiting on a click or a
	 * character publish gets the advised delay as it is.
	 */
	private void retry(Push push, int attempt, String gameMode, int retryAfterSeconds)
	{
		Push retry = live(push.retriedIn(gameMode, attempt));
		if (!sends(retry))
		{
			abandon(push, attempt);
			return;
		}
		int delay = Math.max(retryAfterSeconds, 2);
		// A click or a character's sync asked meanwhile rides this retry; an automatic push waiting gives way to it.
		Push next = pendingPush != null && pendingPush.deliberate() ? Push.merge(retry, pendingPush) : retry;
		dropPending();
		schedule(retry.deliberate() ? delay : delay * 2, next);
		if (retry.forCharacter != NONE)
		{
			showCharacterPublishStatus(retry.forCharacter, CharacterStatus.RENDERING, false);
		}
		else if (pendingPush == next)
		{
			lineAttempt = attempt;
			say(push, () -> feedback.showSyncProgress(push.manual, "retrying...", false));
		}
	}

	/** Failures always chat; chat sends need the client thread, which invoke runs at once when already on it. */
	private void failBeforeSend(Push push, int attempt)
	{
		boolean live = syncGate.release(attempt);
		if (push.forCharacter != NONE)
		{
			failWaiting(push.forCharacter);
		}
		else if (live)
		{
			sayResult(push, false, SYNC_FAILED);
		}
		if (live)
		{
			chatFor(push.session, SYNC_FAILED);
		}
		launchQueued();
	}

	/**
	 * A push that will not go after all, perhaps after saying "syncing..." or "retrying...": the character request it
	 * was for fails, or its line comes down, if the row still shows it ({@code attempt}'s, or the one it waits under).
	 */
	private void abandon(Push push, int attempt)
	{
		if (push.forCharacter != NONE)
		{
			failWaiting(push.forCharacter);
			return;
		}
		takeLineDown(attempt);
		takeLineDown(push.line);
	}

	/** The push's last word on the row, which then answers to no attempt. */
	private void sayResult(Push push, boolean ok, String message)
	{
		lineAttempt = 0;
		say(push, () -> feedback.showSyncResult(push.manual, ok, message));
	}

	/** The row's sync line comes down, only if it is this attempt's (never a newer sync's, never the next login's). */
	private void takeLineDown(int attempt)
	{
		if (attempt == 0 || lineAttempt != attempt)
		{
			return;
		}
		lineAttempt = 0;
		SwingUtilities.invokeLater(() ->
		{
			if (lineAttempt == 0)
			{
				feedback.resetSyncFeedback();
			}
		});
	}

	/** A line for the row, said only while its era and login last and sync is on, and the row still answers to it. */
	private void say(Push push, Runnable line)
	{
		int shown = lineAttempt;
		SwingUtilities.invokeLater(() ->
		{
			if (lineAttempt == shown && push.era == syncGate.era() && config.killclogSync()
				&& sessions.isCurrent(push.session))
			{
				line.run();
			}
		});
	}

	/** A sync's chat line, said only while its login lasts: the next login never hears the last one's. */
	private void chatFor(Session session, String message)
	{
		clientThread.invoke(() ->
		{
			if (sessions.isCurrent(session))
			{
				chatNotifier.send(ChatNotice.SYNC_RESULT, message);
			}
		});
	}

	// ── character publish: the owner's ─────────────────────────────────

	/** A character request: publish or delete, for the logged-in player of the main game. */
	@FunctionalInterface
	private interface CharacterRequest
	{
		CompletableFuture<ProfileAppearanceService.PublishResult> start(Session session,
			ProfileAppearanceService.Authorization authorized);
	}

	@FunctionalInterface
	private interface CharacterOutcome
	{
		void handle(ProfileAppearanceService.PublishResult result, Throwable error, int generation);
	}

	/**
	 * One character request at a time, for the login it was pressed in ({@code origin}) and the withdrawal era of the
	 * press: its status line at once, then on the client thread the request, unless that login has ended or left the
	 * main game (it fails, or a withdrawn one stands down). A request that {@code continues} an earlier one (its
	 * generation) takes its place only while that one is still current and holds the slot, keeping its login and era.
	 */
	private void startCharacterRequest(Session origin, int era, int continues, CharacterStatus progress,
		CharacterRequest request, CharacterOutcome outcome)
	{
		if (!characterPublishingEnabled())
		{
			return;
		}
		// A holder from a withdrawn era (its cleanup still on the way) never blocks a newer press.
		if (continues == NONE ? characterHolder != NONE && characterRequestEra >= era || era != characterEra()
			|| !sessions.isCurrent(origin)
			: continues != characterGeneration || characterHolder != continues)
		{
			return;
		}
		if (continues == NONE)
		{
			characterSession = origin;
			characterRequestEra = era;
			characterPrerequisiteAttempted = false;
		}
		int generation = ++characterGeneration;
		characterHolder = generation;
		Session session = characterSession;
		int requestEra = characterRequestEra;
		showCharacterPublishStatus(generation, progress, false);
		clientThread.invokeLater(() ->
		{
			if (generation != characterGeneration)
			{
				return;
			}
			if (!characterPublishingEnabled() || !session.loggedIn() || !sessions.isCurrent(session)
				|| !GameMode.MAIN.equals(mode.get()))
			{
				owner.execute(() -> failCharacterPublish(generation));
				return;
			}
			request.start(session, new ProfileAppearanceService.Authorization()
			{
				@Override
				public boolean getAsBoolean()
				{
					return generation == characterGeneration && characterPublishingEnabled() && sessions.isCurrent(session);
				}

				@Override
				public boolean sendIf(Runnable send)
				{
					// One step with a withdrawal (cancelCharacterPublish moves the era under this lock).
					synchronized (characterFence)
					{
						if (requestEra != characterEra || !sessions.isCurrent(session))
						{
							return false;
						}
						send.run();
						return true;
					}
				}
			}).whenComplete((result, error) -> owner.execute(() -> outcome.handle(result, error, generation)));
		});
	}

	private void handleCharacterPublishResult(ProfileAppearanceService.PublishResult result,
		Throwable error, int generation)
	{
		if (generation != characterGeneration || !characterPublishingEnabled())
		{
			return;
		}
		if (error == null && result != null && result.outcome == ProfileAppearanceService.Outcome.PROFILE_REQUIRED
			&& characterHolder == generation && !characterPrerequisiteAttempted)
		{
			// It waits on one sync of its log first, for its own login and era.
			characterPrerequisiteAttempted = true;
			characterWaiting = generation;
			showCharacterPublishStatus(generation, CharacterStatus.RENDERING, false);
			pushNow(characterSession, syncGate.era(), false, generation);
		}
		else
		{
			characterDone(result, error, generation);
		}
	}

	/** A publish or delete is over: failed without an answer, else the row shows how it ended. */
	private void characterDone(ProfileAppearanceService.PublishResult result, Throwable error, int generation)
	{
		if (error != null || result == null)
		{
			failCharacterPublish(generation);
		}
		else if (finishCharacter(generation))
		{
			showCharacterPublishStatus(generation, CharacterStatus.terminal(result.outcome), true, result.message);
		}
	}

	/** The attempt is over and failed: the slot frees and the row says so, only while the attempt is still current. */
	private void failCharacterPublish(int generation)
	{
		if (finishCharacter(generation))
		{
			showCharacterPublishStatus(generation, CharacterStatus.FAILED, true);
		}
	}

	/** The request still current, holding the slot, ends and frees it; false for anything withdrawn or stale. */
	private boolean finishCharacter(int generation)
	{
		if (generation != characterGeneration || characterHolder != generation)
		{
			return false;
		}
		characterHolder = NONE;
		characterWaiting = NONE;
		return true;
	}

	/** Whether this request is still current and waits on its sync. */
	private boolean waitingFor(int generation)
	{
		return generation != NONE && characterWaiting == generation && generation == characterGeneration;
	}

	/** Its sync ended: the request stops waiting; false when it was no longer the one waiting. */
	private boolean takeWaiting(int generation)
	{
		if (!waitingFor(generation))
		{
			return false;
		}
		characterWaiting = NONE;
		return true;
	}

	/** The sync a request waited on can't go or broke: the request fails, if it still waited on it. */
	private void failWaiting(int generation)
	{
		if (takeWaiting(generation))
		{
			failCharacterPublish(generation);
		}
	}

	/** The publish again once its log's sync landed: the same request, keeping its slot, login and era. */
	private void scheduleCharacterPublishAfterSync(int generation)
	{
		try
		{
			executor.schedule(() -> owner.execute(() -> startCharacterRequest(null, NONE, generation,
					CharacterStatus.RENDERING, profileAppearanceService::publishCurrent, this::handleCharacterPublishResult)),
				ProfileAppearanceService.PUBLISH_RETRY_DELAY_MS, TimeUnit.MILLISECONDS);
		}
		catch (RuntimeException e)
		{
			failCharacterPublish(generation);
		}
	}

	private void showCharacterPublishStatus(int generation, CharacterStatus status, boolean autoClear)
	{
		showCharacterPublishStatus(generation, status, autoClear, null);
	}

	private void showCharacterPublishStatus(int generation, CharacterStatus status, boolean autoClear,
		String failureMessage)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (generation == characterGeneration && (status == CharacterStatus.CLEAR || characterPublishingEnabled()))
			{
				feedback.showCharacterPublishStatus(status, autoClear, failureMessage);
			}
		});
	}

	// ── personal-best cargo ────────────────────────────────────────────

	/**
	 * RuneLite's own chat-commands store records the local player's personal
	 * bests; no public provider serves them, which makes this map the sync's
	 * defining cargo. One account splinters into many rs-profile fragments
	 * over time, so the gather reads every fragment owned by the captured
	 * account hash ({@link PersonalBests#records}). STANDARD-world fragments
	 * only: Leagues and speedrun profiles share the display name but store
	 * buffed-world times, and the min-merge would launder those into the
	 * player's real record. Client thread (config reads).
	 */
	private Map<String, PbRecord> gatherPersonalBests(List<String> profileKeys, Map<String, Double> pbs)
	{
		PersonalBests store = new PersonalBests(configManager, profileKeys);
		Map<String, PbRecord> out = new LinkedHashMap<>();
		for (HiscoreSkill boss : PanelData.BOSSES)
		{
			// Each team size's time as the card shows it: RuneLite's store, the game's own records over it.
			Map<String, PbRecord> records = store.records(boss.getName());
			records.forEach((key, record) -> out.merge(key, record, PbRecord::pick));
			// The boss's best at any team size, from those same records.
			records.values().stream().mapToDouble(record -> record.seconds).min()
				.ifPresent(seconds -> pbs.put(boss.getName(), seconds));
		}
		log.debug("killclog sync pb gather: {} owned profiles, {} bosses from RuneLite's store, {} detailed pbs"
			+ " (the store, the adventure log, the collection log, kills seen)", profileKeys.size(), pbs.size(), out.size());
		return out;
	}
}

