	{
		this.caResult = ca;
		this.caRewardSprite = rewardSprite;
	}

	public void setMegarares(int tbowCount, int scytheCount,
		int shadowCount, int obligatorCount, ItemManager itemManager)
	{
		weaponCounts[0] = tbowCount;
		weaponCounts[1] = scytheCount;
		weaponCounts[2] = shadowCount;
		weaponCounts[3] = obligatorCount;

		weaponSprites = TooltipItemSprites.load(TooltipData.itemList(PanelData.MEGARARE_ITEM_IDS), null, itemManager,
			id -> 1, this);
	}

	public void setSuperiors(int imbuedHeartCount, int eternalGemCount,
		ItemManager itemManager)
	{
		superiorCounts[0] = imbuedHeartCount;
		superiorCounts[1] = eternalGemCount;

		superiorSprites = TooltipItemSprites.load(TooltipData.itemList(PanelData.SUPERIOR_ITEMS), null, itemManager,
			id -> 1, this);
	}

	public void setSlayer(HiscoreResult hiscoreResult, ClogResult clogResult)
	{
		slayerXp = hiscoreResult != null
			? hiscoreResult.getSkillXp(PanelData.SLAYER_CATEGORY) : -1;
		slayerRank = hiscoreResult != null
			? hiscoreResult.getSkillRank(PanelData.SLAYER_CATEGORY) : -1;
		slayerObtained = -1;
		slayerTotal = 0;
		int[] slayer = ClogHelper.clogCounts(PanelData.SLAYER_CATEGORY, clogResult);
		if (slayer != null)
		{
			slayerObtained = slayer[0];
			slayerTotal = slayer[1];
		}
	}

	public void setRaids(HiscoreResult hiscoreResult, ClogResult clogResult)
	{
		tfaOut = hiscoreResult.hasBossRow(PanelData.TFA_HISCORE);
		for (int i = 0; i < RAID_LABELS.length; i++)
		{
			raidKc[i] = Math.max(0, hiscoreResult.getKc(hasHardMode(i) ? PanelData.RAIDS[i].getName() : PanelData.TFA_HISCORE));
			hardKc[i] = hasHardMode(i) ? Math.max(0, hiscoreResult.getKc(PanelData.RAID_HARD_MODES[i].getName())) : 0;
			int[] counts = clogResult != null ? ClogHelper.clogCounts(RAID_CATEGORIES[i], clogResult) : null;
			if (counts != null)
			{
				raidObtained[i] = counts[0];
				raidTotal[i] = counts[1];
			}
		}
	}

	/** Called with the raid when the player presses its row. */
	void setOnOpenRaid(@Nullable BiConsumer<MouseEvent, HiscoreSkill> onOpenRaid)
	{
		this.onOpenRaid = onOpenRaid;
	}

	@Override
	CardBody.Scroll scroll()
	{
		return scroll;
	}

	@Override
	protected CardBody body()
	{
		// The combat level leads the card; PvM and PvP each follow under their own subheader. A sprite's name shows
		// in the band over Raids, the first section with sprites, and everything from there scrolls.
		CardBody card = new CardBody()
			.add(CardBody.gap(LEVEL_GAP_ABOVE))
			.add(leadRow(combatIcon, combatText(combatLevel)))
			.add(CardBody.gap(LEVEL_GAP_BELOW))
			.add(CardBody.section(PVM_HEADER));
		// The CA tier leads the PvM rows, built like the combat level row above it, once one is held.
		if (hasTierRow())
		{
			card.add(CardBody.gap(LEVEL_GAP_ABOVE))
				.add(leadRow(caRewardSprite, tierDisplayName(caResult)))
				.add(CardBody.gap(LEVEL_GAP_BELOW));
		}
		card.add(CardBody.line("Total Kills: ", scoreText(totalKills)))
			.add(CardBody.line("EHB: ", ehbText(ehb)))
			.add(CardBody.line("Bosses Killed: ", bossesWithKc + "/" + totalBosses,
				completionColor(bossesWithKc, totalBosses)));
		if (bossesCompleted >= 0)
		{
			card.add(CardBody.line("Logs Completed: ", bossesCompleted + "/" + bossesWithClog,
				completionColor(bossesCompleted, bossesWithClog)));
		}
		// Most Killed closes the PvM rows.
		if (mostKilled != null)
		{
			card.add(CardBody.gap(SECTION_GAP))
				.add(CardBody.text("Most Killed:", labelColor, false))
				.add(CardBody.text(mostKilled + " (" + grouped(mostKilledKc) + ")", NativeTooltip.valueColor, true));
		}
		// Raids lead the sections under the band, their megarares under the rows.
		CardBody body = new CardBody().titled("Raids");
		for (int i = 0; i < raidRowCount(); i++)
		{
			body.add(raidRow(i));
		}
		body.add(CardBody.gap(WEAPON_PAD))
			.add(CardBody.sprites(1, weaponSprites, PanelData.MEGARARE_ITEM_IDS, PanelData.MEGARARE_ITEM_NAMES,
				weaponCounts, WEAPON_PAD));
		// Slayer: XP and Rank from the hiscores, then clog progress when a synced log is known.
		body.titled("Slayer")
			.add(CardBody.line("XP: ", slayerXpText(slayerXp)))
			.add(CardBody.line("Rank: ", scoreText(slayerRank)));
		if (slayerObtained >= 0)
		{
			body.add(CardBody.line("Obtained: ", progressCountText(slayerObtained, slayerTotal),
				completionColor(slayerObtained, slayerTotal)));
		}
		body.add(CardBody.gap(WEAPON_PAD))
			.add(CardBody.sprites(0, superiorSprites, PanelData.SUPERIOR_ITEMS, PanelData.SUPERIOR_ITEM_NAMES,
				superiorCounts, WEAPON_PAD))
			.titled(PVP_HEADER)
			.add(pvpRows.part());
		return card.add(CardBody.hoverBand()).add(CardBody.scroll(scroll, body.asPart()));
	}

	/** Progress rides alongside a real kc in either mode; a raid never run stays dash-only. */
	private boolean raidLog(int row)
	{
		return raidKc[row] + hardKc[row] > 0 && raidObtained[row] >= 0;
	}

	/** The rows drawn: CoX, ToB and ToA, then The Fractured Archive once the hiscores carry its row. */
	private int raidRowCount()
	{
		return tfaOut ? RAID_LABELS.length : PanelData.RAID_HARD_MODES.length;
	}

	/** CoX, ToB and ToA pair a hard mode; The Fractured Archive, the row after them, has none. */
	private static boolean hasHardMode(int row)
	{
		return row < PanelData.RAID_HARD_MODES.length;
	}

	/** The raid a row opens, null for one the panel has no popup for yet. */
	@Nullable
	private static HiscoreSkill raid(int row)
	{
		return hasHardMode(row) ? PanelData.RAIDS[row] : PanelData.listed(PanelData.TFA);
	}

	/**
	 * The raid rows' columns (Dylan, 2026-10-13): each label starts its own column and each value ends its own, so
	 * the labels line up on their left and the kills and logs on their right. Offsets from the row's start: the
	 * kills' right edge, the hard mode's label, its kills' right edge and the log's right edge.
	 */
	private int[] raidColumns(FontMetrics fm)
	{
		int label = 0;
		int kills = 0;
		int hardLabel = 0;
		int hard = 0;
		int log = 0;
		for (int row = 0; row < raidRowCount(); row++)
		{
			label = Math.max(label, fm.stringWidth(RAID_LABELS[row]));
			kills = Math.max(kills, fm.stringWidth(scoreText(raidKc[row])));
			if (hasHardMode(row))
			{
				hardLabel = Math.max(hardLabel, fm.stringWidth(PanelData.RAID_HARD_LABELS[row] + ": "));
				hard = Math.max(hard, fm.stringWidth(scoreText(hardKc[row])));
			}
			if (raidLog(row))
			{
				log = Math.max(log, fm.stringWidth(raidLogText(row)));
			}
		}
		int hardLabelX = label + kills + PAIR_GAP;
		int hardEnd = hardLabelX + hardLabel + hard;
		return new int[]{label + kills, hardLabelX, hardEnd, log > 0 ? hardEnd + PAIR_GAP + log : hardEnd};
	}

	private String raidLogText(int row)
	{
		return "(" + progressCountText(raidObtained[row], raidTotal[row]) + ")";
	}

	/** A raid's normal and hard-mode kills, then its log, in the rows' columns; the row opens the raid's own popup. */
	private CardBody.Part raidRow(int row)
	{
		return CardBody.clickRow(raidRows, row, c -> raidColumns(c.fm)[3], (c, y, hovered) ->
		{
			int textY = y + c.fm.getAscent();
			int[] at = raidColumns(c.fm);
			int x = c.inset();
			// No pointer cursor in this UI: the hovered row answers in white instead, and a row that opens
			// nothing yet doesn't answer.
			c.g.setColor(hovered && raid(row) != null ? NativeTooltip.valueColor : labelColor);
			c.g.drawString(RAID_LABELS[row], x, textY);
			if (hasHardMode(row))
			{
				c.g.drawString(PanelData.RAID_HARD_LABELS[row] + ": ", x + at[1], textY);
			}
			c.g.setColor(NativeTooltip.valueColor);
			drawRightAligned(c.g, c.fm, scoreText(raidKc[row]), x + at[0], textY);
			if (hasHardMode(row))
			{
				drawRightAligned(c.g, c.fm, scoreText(hardKc[row]), x + at[2], textY);
			}
			if (raidLog(row))
			{
				c.g.setColor(completionColor(raidObtained[row], raidTotal[row]));
				drawRightAligned(c.g, c.fm, raidLogText(row), x + at[3], textY);
			}
		});
	}

	/** The exact amount, never rounded: max slayer xp is 200,000,000 and the summary has the width for it. */
	/* package */ static String slayerXpText(long xp)
	{
		return scoreText(xp);
	}

	/**
	 * A lead row like the panel's combat cell: an icon centered in the icon column, then its text in
	 * bold white. The combat level and the CA tier share the column, so their text lines up.
	 */
	private CardBody.Part leadRow(@Nullable Image icon, String text)
	{
		return CardBody.row(LEVEL_ROW_HEIGHT, c -> iconColumnWidth() + c.bfm.stringWidth(text), (c, y) ->
		{
			Graphics2D g2 = c.g;
			if (icon != null)
			{
				int column = iconColumnWidth() - LEVEL_ICON_GAP;
				g2.drawImage(icon, c.inset() + (column - icon.getWidth(null)) / 2,
					y + (LEVEL_ROW_HEIGHT - icon.getHeight(null)) / 2, null);
			}
			g2.setFont(FontManager.getRunescapeBoldFont());
			FontMetrics bfm = g2.getFontMetrics();
			g2.setColor(NativeTooltip.valueColor);
			g2.drawString(text, c.inset() + iconColumnWidth(),
				y + (LEVEL_ROW_HEIGHT + bfm.getAscent() - bfm.getDescent()) / 2);
			g2.setFont(FontManager.getRunescapeSmallFont());
		});
	}

	/** The tier row waits for a tier: a player still short of Easy has nothing to lead with. */
	private boolean hasTierRow()
	{
		return caResult != null && caResult.getTier() != null;
	}

	/** The icon column the lead rows share: as wide as the wider icon, then the gap. */
	private int iconColumnWidth()
	{
		int width = Math.max(combatIcon != null ? combatIcon.getWidth(null) : 0,
			hasTierRow() && caRewardSprite != null ? caRewardSprite.getWidth() : 0);
		return width > 0 ? width + LEVEL_ICON_GAP : 0;
	}

	/** Vanilla's hiscore formatter: up to three decimals, trailing zeros dropped. */
	static String combatText(double combatLevel)
	{
		return combatLevel > 0 ? QuantityFormatter.formatNumber(combatLevel) : "--";
	}
}

package com.killclog;

import java.awt.image.BufferedImage;
import java.util.Arrays;
import lombok.Setter;

/**
 * The five PvP activities as rows inside the Combat Summary: icon, label,
 * score, and collection progress where the activity has a log.
 */
final class PvpSummaryRows
{
	private static final int ICON_SIZE = 13;
	private static final int ICON_GAP = 4;
	private static final int COL_GAP = 6;

	// Short names for PanelData.PVP_ACTIVITIES, in its order.
	private static final String[] LABELS = {
		"LMS", "Soul Wars", "PvP Arena", "BH Hunter", "BH Rogue",
	};

	private final int[] scores = new int[LABELS.length];
	private final int[] obtained = new int[LABELS.length];
	private final int[] total = new int[LABELS.length];

	@Setter
	private BufferedImage[] icons;

	/** A null result renders all five rows with "--" scores: the empty state. */
	void setData(HiscoreResult hiscoreResult, ClogResult clogResult)
	{
		Arrays.fill(scores, 0);
		Arrays.fill(obtained, -1);
		if (hiscoreResult == null)
		{
			return;
		}

		for (int i = 0; i < LABELS.length; i++)
		{
			scores[i] = hiscoreResult.getActivityScore(PanelData.PVP_ACTIVITIES[i].getName());
		}

		if (clogResult != null)
		{
			setProgress(0, ClogHelper.clogCounts("last_man_standing", clogResult));
			setProgress(1, ClogHelper.clogCounts("soul_wars", clogResult));
		}
	}

	private void setProgress(int row, int[] counts)
	{
		if (counts != null)
		{
			obtained[row] = counts[0];
			total[row] = counts[1];
		}
	}

	/** The rows as one table part: progress only rides alongside a real score; a "--" row stays dash-only. */
	CardBody.Part part()
	{
		int[] shown = new int[LABELS.length];
		for (int i = 0; i < LABELS.length; i++)
		{
			shown[i] = scores[i] > 0 ? obtained[i] : -1;
		}
		return CardBody.table(icons, LABELS, scores, shown, total, null, ICON_SIZE, ICON_GAP, COL_GAP);
	}
}

package com.killclog;

import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;

/** Rank selection is independent of the account identity and its current stats. */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
enum RankLeaderboard
{
	NORMAL("Normal", "hiscore_oldschool", "normal.png"),
	IRONMAN("Ironman", "hiscore_oldschool_ironman", "ironman.png"),
	HARDCORE("Hardcore Ironman", "hiscore_oldschool_hardcore_ironman", "hardcore_ironman.png"),
	ULTIMATE("Ultimate Ironman", "hiscore_oldschool_ultimate", "ultimate_ironman.png"),
	SKILLER("Skiller", "hiscore_oldschool_skiller", "level_3_skiller.png"),
	PURE("Pure", "hiscore_oldschool_skiller_defence", "pure.png");

	final String label;
	final String endpoint;
	final String icon;

	static RankLeaderboard nativeOf(HiscoreResult result)
	{
		if (result.getHiscoreTable() == HiscoreTable.SKILLER) return SKILLER;
		if (result.getHiscoreTable() == HiscoreTable.ONE_DEFENCE) return PURE;
		return of(result.getAccountType());
	}

	/** A solo Ironman type's own board; every other type, a group one among them, ranks on the normal board. */
	static RankLeaderboard of(@Nullable AccountType type)
	{
		if (type == null) return NORMAL;
		switch (type)
		{
			case IRONMAN: return IRONMAN;
			case HARDCORE_IRONMAN: return HARDCORE;
			case ULTIMATE_IRONMAN: return ULTIMATE;
			default: return NORMAL;
		}
	}
}

package com.killclog;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.function.BiFunction;
import java.util.function.BiPredicate;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;

/** EDT-owned leaderboard views for the looked-up player. Cached service results stay untouched. */
final class RankSelector extends JPanel
{
	/** The row a board without this player shows: nothing. */
	private static final HiscoreResult NOTHING = new HiscoreResult(null, null, null, null, null, null, null, null, null,
		0, 0, 0, -1);

	private final BiFunction<String, RankLeaderboard, CompletableFuture<HiscoreResult>> fetch;
	private final BiPredicate<String, RankLeaderboard> absent;
	private final Runnable changed;
	private final Set<RankLeaderboard> open = EnumSet.noneOf(RankLeaderboard.class);
	private final Map<RankLeaderboard, JButton> buttons = new EnumMap<>(RankLeaderboard.class);
	private final Map<HiscoreResult, HiscoreResult> views = new IdentityHashMap<>();
	private final Map<HiscoreResult, String> notices = new IdentityHashMap<>();
	private HiscoreResult blue;
	private String blueName;
	private RankLeaderboard selected;
	private boolean enabled;
	private int version;
	private int probes;

	RankSelector(BiFunction<String, RankLeaderboard, CompletableFuture<HiscoreResult>> fetch,
		BiPredicate<String, RankLeaderboard> absent, Runnable changed)
	{
		super(new FlowLayout(FlowLayout.CENTER, 4, 3));
		this.fetch = fetch;
		this.absent = absent;
		this.changed = changed;
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (RankLeaderboard table : RankLeaderboard.values())
		{
			BufferedImage image = AccountBadgeResolver.hiscoreIcon(table.icon);
			JButton button = new JButton(icon(image, 0.45f));
			button.setRolloverIcon(icon(image, 0.8f));
			button.setSelectedIcon(icon(image, 1f));
			button.setDisabledIcon(icon(image, 0.2f));
			button.setContentAreaFilled(false);
			button.setFocusPainted(false);
			button.setPreferredSize(new Dimension(26, 26));
			button.getAccessibleContext().setAccessibleName(table.label + " Hiscores");
			button.addActionListener(event -> select(table));
			buttons.put(table, button);
			add(button);
		}
		updateButtons();
		setVisible(false);
	}

	static ImageIcon icon(BufferedImage image, float alpha)
	{
		BufferedImage dimmed = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = dimmed.createGraphics();
		g.setComposite(AlphaComposite.SrcOver.derive(alpha));
		g.drawImage(image, 0, 0, null);
		g.dispose();
		return new ImageIcon(dimmed);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		// Continue the scrollbar track below the scroll pane without moving the buttons.
		g.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g.fillRect(getWidth() - MinimalScrollBarUI.WIDTH, 0, MinimalScrollBarUI.WIDTH, getHeight());
	}

	void update(boolean enabled, String blueName, HiscoreResult blue)
	{
		if (this.enabled == enabled && this.blue == blue && Objects.equals(this.blueName, blueName))
		{
			return;
		}
		this.enabled = enabled;
		this.blue = blue;
		this.blueName = blueName;
		if (!enabled) selected = null;
		setVisible(enabled);
		probe();
		reload();
	}

	void reset()
	{
		version++;
		probes++;
		selected = null;
		blue = null;
		open.clear();
		views.clear();
		notices.clear();
		updateButtons();
	}

	/** A board gets its button once the player has a row on it, or Jagex didn't answer and a click can retry. */
	private void probe()
	{
		int probe = ++probes;
		open.clear();
		if (!enabled || blue == null) return;
		String name = blueName;
		open.add(RankLeaderboard.nativeOf(blue));
		for (RankLeaderboard table : RankLeaderboard.values())
		{
			fetch.apply(name, table).whenComplete((row, error) -> SwingUtilities.invokeLater(() ->
			{
				if (probe == probes && (row != null || !absent.test(name, table)) && open.add(table)) updateButtons();
			}));
		}
	}

	void select(RankLeaderboard table)
	{
		if (!enabled || blue == null) return;
		selected = table;
		reload();
	}

	RankLeaderboard active()
	{
		return selected != null ? selected : blue != null ? RankLeaderboard.nativeOf(blue) : null;
	}

	HiscoreResult view(HiscoreResult result)
	{
		if (!enabled || result == null) return result;
		HiscoreResult view = views.get(result);
		return view != null ? view : result.withRanks(null);
	}

	/** Why a displayed board shows nothing, or null when it shows a row. */
	String blankNotice(HiscoreResult view)
	{
		for (Map.Entry<HiscoreResult, HiscoreResult> entry : views.entrySet())
		{
			if (entry.getValue() == view && view.getTotalLevel() == 0) return notices.get(entry.getKey());
		}
		return null;
	}

	/** Why a frozen or empty board shows no log, for the status line and the cards alike. */
	String logNotice(HiscoreResult view)
	{
		String blank = blankNotice(view);
		return blank != null ? blank : active().label.replace(" Ironman", "") + " collection log not recorded";
	}

	private void reload()
	{
		int requestVersion = ++version;
		views.clear();
		notices.clear();
		if (enabled && blue != null)
		{
			load(blueName, blue, requestVersion);
		}
		updateButtons();
		changed.run();
	}

	private void load(String name, HiscoreResult base, int requestVersion)
	{
		RankLeaderboard table = active();
		if (table == RankLeaderboard.nativeOf(base))
		{
			views.put(base, base);
			return;
		}
		CompletableFuture<HiscoreResult> fetching = fetch.apply(name, table);
		if (fetching.isDone() && !fetching.isCompletedExceptionally())
		{
			settle(name, base, table, fetching.join());
			return;
		}
		views.put(base, base.withRow(NOTHING));
		notices.put(base, "Loading...");
		fetching.whenComplete((row, error) -> SwingUtilities.invokeLater(() ->
		{
			if (version != requestVersion) return;
			settle(name, base, table, error == null ? row : null);
			updateButtons();
			changed.run();
		}));
	}

	/** A board without this player's row shows nothing, never another board's stats. */
	private void settle(String name, HiscoreResult base, RankLeaderboard table, HiscoreResult row)
	{
		HiscoreResult view = base.withRow(row != null ? row : NOTHING);
		views.put(base, view);
		notices.put(base, row == null ? absent.test(name, table) ? "Not on this leaderboard" : "Unavailable; click to retry"
			: view.isFrozen() ? "Stats frozen on this leaderboard" : "");
	}

	private void updateButtons()
	{
		for (Map.Entry<RankLeaderboard, JButton> entry : buttons.entrySet())
		{
			boolean active = entry.getKey() == active();
			JButton button = entry.getValue();
			button.setVisible(active || open.contains(entry.getKey()));
			button.setEnabled(enabled && blue != null);
			button.setSelected(active);
			button.setBorder(BorderFactory.createMatteBorder(0, 0, 2, 0,
				active ? ColorScheme.BRAND_ORANGE : new Color(0, 0, 0, 0)));
			String hint = entry.getKey().label + " Hiscores";
			if (active)
			{
				hint += notice(blueName, blue);
			}
			button.setToolTipText(hint);
		}
	}

	private String notice(String name, HiscoreResult result)
	{
		String notice = notices.get(result);
		return notice == null || notice.isEmpty() ? "" : " - " + name + ": " + notice;
	}
}

package com.killclog;

import java.util.Locale;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.util.Text;

/** RSN shape validation for names entered in the panel search box. */
final class RsnInputPolicy
{
	static final int MAX_LENGTH = 12;

	private static final Pattern ALLOWED = Pattern.compile("[A-Za-z0-9_ -]+");
	private static final Pattern HAS_ALPHANUMERIC = Pattern.compile(".*[A-Za-z0-9].*");

	private RsnInputPolicy()
	{
	}

	/** One player whatever the spelling Jagex accepts: an underscore, hyphen or non-breaking space for a space. */
	/** The local player's name as the client has it now, or null while it doesn't know it yet. */
	@Nullable
	static String localName(Client client)
	{
		Player local = client.getLocalPlayer();
		return local != null ? local.getName() : null;
	}

	static boolean sameName(@Nullable String a, @Nullable String b)
	{
		return a != null && b != null && key(a).equals(key(b));
	}

	/**
	 * The one key for a player, by the same rule: every cache, index and file keyed by name uses it, so each spelling
	 * Jagex accepts finds the same entry ("Foo_Bar" and "foo-bar" are "foo bar").
	 */
	static String key(String name)
	{
		return Text.toJagexName(name).toLowerCase(Locale.ROOT);
	}

	static boolean isValid(String raw)
	{
		if (raw == null)
		{
			return false;
		}
		String value = raw.replace('\u00a0', ' ').trim();
		if (value.isEmpty() || value.length() > MAX_LENGTH
			|| !ALLOWED.matcher(value).matches()
			|| !HAS_ALPHANUMERIC.matcher(value).matches())
		{
			return false;
		}

		return true;
	}
}

package com.killclog;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import javax.annotation.Nullable;
import net.runelite.api.clan.ClanTitle;

final class RuneProfileAccountSummaryParser
{
	private RuneProfileAccountSummaryParser()
	{
	}

	@Nullable
	static AccountType parseAccountType(JsonObject root)
	{
		if (!root.has("accountType") || root.get("accountType").isJsonNull()
			|| !root.get("accountType").isJsonObject())
		{
			return null;
		}
		JsonObject accountType = root.getAsJsonObject("accountType");
		AccountType parsed = parseValue(accountType, "key");
		if (parsed == null)
		{
			parsed = parseValue(accountType, "name");
		}
		if (parsed != null)
		{
			return parsed;
		}
		return accountType.has("id") && !accountType.get("id").isJsonNull()
			? AccountType.fromProviderId(accountType.get("id").getAsInt()) : null;
	}

	/** The clan's name, as RuneProfile's summary carries it; null without one. */
	@Nullable
	static String parseClan(JsonObject root)
	{
		JsonElement name = clanField(root, "name");
		return name != null && !name.getAsString().trim().isEmpty() ? name.getAsString().trim() : null;
	}

	/** The player's title in the clan: RuneProfile's icon is the title's id, which picks its clan-chat icon. */
	@Nullable
	static ClanTitle parseClanTitle(JsonObject root)
	{
		JsonElement icon = clanField(root, "icon");
		JsonElement title = clanField(root, "title");
		return icon != null ? new ClanTitle(icon.getAsInt(), title != null ? title.getAsString() : null) : null;
	}

	@Nullable
	private static JsonElement clanField(JsonObject root, String field)
	{
		JsonElement clan = root.get("clan");
		JsonElement value = clan != null && clan.isJsonObject() ? clan.getAsJsonObject().get(field) : null;
		return value != null && value.isJsonPrimitive() ? value : null;
	}

	@Nullable
	private static AccountType parseValue(JsonObject accountType, String field)
	{
		return accountType.has(field) && !accountType.get(field).isJsonNull()
			? AccountType.fromProviderValue(accountType.get(field).getAsString()) : null;
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import net.runelite.api.clan.ClanTitle;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;

/**
 * Fetches player data from RuneProfile. Two lanes:
 * <ol>
 *   <li><strong>Account summary</strong> ({@link #lookup}) -- public CA source for other
 *       players, plus account-type metadata. One GET per player against {@code /accounts/{rsn}}.
 *       The local player is asked for too, only so Sources can list RuneProfile.</li>
 *   <li><strong>Collection log provider</strong> ({@link #lookupClog}) -- one GET against
 *       {@code /collection-log}, parsed into a {@link ClogResult}. LookupSession and
 *       ComparisonController combine this with TempleOSRS and keep the freshest result.</li>
 * </ol>
 *
 * <p>Both lanes share the same freshness model: success TTL, not-synced (404) TTL, transient
 * failure cooldown, and in-flight dedup. Caches are independent per lane so a CA 404 does not
 * suppress a clog request (or vice versa).
 *
 * <p>A 404 on either lane means the player has not synced to RuneProfile; held longer than a
 * transient failure since it rarely flips quickly. A previous success is still returned while
 * cached, so a provider-side 404 cannot blank known-good data mid-session.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RuneProfileService
{
	private static final String BASE_URL = "https://api.runeprofile.com/v1/accounts/";
	private static final String CLOG_SUFFIX = "/collection-log";

	// Shared across the CA and clog lanes. A single success clears it.
	private final CircuitBreaker breaker = new CircuitBreaker("RuneProfile");

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final LocalCaCache localCaCache;

	// Plugin-owned live catalog, set at startup. Read from HTTP threads; the
	// catalog publishes complete immutable snapshots through a volatile field.
	@Nullable private volatile CaCatalog caCatalog;

	// Summary lane (CA tiers plus account metadata) and clog lane: independent, same TTLs.
	private final HttpUtil.Lane<RuneProfileSummary> summaries = new HttpUtil.Lane<>(breaker);
	private final HttpUtil.Lane<ClogResult> clogs = new HttpUtil.Lane<>(breaker);

	public void setCaCatalog(@Nullable CaCatalog caCatalog)
	{
		this.caCatalog = caCatalog;
	}

	/** Clear transient failure cooldowns immediately (called on login); TTLs auto-expire otherwise. */
	public void clearFailures()
	{
		summaries.failed.clear();
		clogs.failed.clear();
		breaker.reset();
	}

	/** Cached CA result for SWR reveal without an API call, or null if none is held. */
	public CombatAchievementResult getCached(String playerName)
	{
		if (playerName == null)
		{
			return null;
		}
		RuneProfileSummary cached = summaries.values.get(RsnInputPolicy.key(playerName));
		return cached != null ? rebased(cached.combatAchievements) : null;
	}

	/**
	 * Cached results heal against the current catalog on read: a verdict
	 * computed before a capture (or across a threshold change) must not serve
	 * its old tier for the cache TTL.
	 */
	@Nullable
	private CombatAchievementResult rebased(@Nullable CombatAchievementResult result)
	{
		CaCatalog catalog = caCatalog;
		if (result == null || catalog == null)
		{
			return result;
		}
		return result.rebasedOn(catalog.totals());
	}

	/** RuneProfile's account type from its last answer for this name, or null without one. */
	@Nullable
	public AccountType getCachedAccountType(String playerName)
	{
		// The active player's summary is fetched for Sources only; their own
		// client stays the authority on account type.
		if (playerName == null || localCaCache != null && localCaCache.isActivePlayer(playerName))
		{
			return null;
		}
		RuneProfileSummary held = held(playerName);
		return held != null ? held.accountType : null;
	}

	/** A player's clan as RuneProfile last saw it; null without one. */
	@Nullable
	String clan(String playerName)
	{
		RuneProfileSummary held = held(playerName);
		return held != null ? held.clan : null;
	}

	/** The player's title in that clan, its id the game's clan-chat icon; null without one. */
	@Nullable
	ClanTitle clanTitle(String playerName)
	{
		RuneProfileSummary held = held(playerName);
		return held != null ? held.clanTitle : null;
	}

	/** True once RuneProfile has answered with a profile for this name. */
	boolean hasProfile(@Nullable String playerName)
	{
		return playerName != null && held(playerName) != null;
	}

	/**
	 * The profile RuneProfile last answered with for this name, whatever its age: a card shows what its own lookup
	 * brought, and the next lookup asks again once it's stale (a card hovered five minutes on lost its clan, 2.6.2).
	 * Matched as Jagex names, because the panel asks with a provider's canonical spelling while the cache is keyed by
	 * what was typed.
	 */
	@Nullable
	private RuneProfileSummary held(String playerName)
	{
		String wanted = RsnInputPolicy.key(playerName);
		for (Map.Entry<String, RuneProfileSummary> entry : summaries.values.entrySet())
		{
			if (Text.toJagexName(entry.getKey()).equals(wanted))
			{
				return entry.getValue();
			}
		}
		return null;
	}

	/**
	 * Look up CA tier data for a player. Resolves to null when the player has no CA data
	 * (not synced, or RuneProfile is unavailable with no cached result) so the caller can
	 * simply omit the CA surface.
	 */
	public CompletableFuture<CombatAchievementResult> lookup(String playerName)
	{
		// Active player: CA is read straight from the game and held locally.
		// It is authoritative even when empty, so RuneProfile never supplies it.
		// The summary is still requested so Sources can say whether this player
		// has a RuneProfile; nothing from it replaces local data.
		if (localCaCache != null && localCaCache.isActivePlayer(playerName))
		{
			lookupSummary(playerName).exceptionally(ex -> null);
			CombatAchievementResult local = localCaCache.hasDataFor(playerName)
				? localCaCache.getCached(playerName) : null;
			return CompletableFuture.completedFuture(local);
		}

		return lookupSummary(playerName).thenApply(summary ->
			summary != null ? rebased(summary.combatAchievements) : null);
	}

	private CompletableFuture<RuneProfileSummary> lookupSummary(String playerName)
	{
		String key = RsnInputPolicy.key(playerName);
		return summaries.lookup(key, () -> startSummaryLookup(playerName, key));
	}

	private CompletableFuture<RuneProfileSummary> startSummaryLookup(String playerName, String key)
	{
		return HttpUtil.httpGet(httpClient, BASE_URL + HttpUtil.pathSegment(playerName)).thenApply(resp ->
		{
			if (resp.code == 404)
			{
				// No profile now: what it held goes, so no card shows a clan or account from one that's gone.
				forgetSpellings(key);
				return summaries.missing(key);
			}
			RuneProfileSummary result = resp.code == 200 && resp.body != null ? parseAccountSummary(resp.body) : null;
			if (result == null)
			{
				return summaries.fail(key);
			}
			breaker.reset();
			// The new answer is the only one held for the name, so no older spelling's answer can stand for it. Under
			// the lane's lock, as ok() stores: two spellings answering at once can't both clear and then both stay.
			synchronized (summaries)
			{
				forgetSpellings(key);
				return summaries.ok(key, result);
			}
		});
	}

	/** Drop every spelling of a name, as held() matches them all (a_q_p_weed held, a q p weed asked). */
	private void forgetSpellings(String key)
	{
		String name = Text.toJagexName(key);
		synchronized (summaries)
		{
			summaries.values.keySet().removeIf(held -> Text.toJagexName(held).equals(name));
		}
	}

	/**
	 * Parse RuneProfile CA rows from either {@code /combat-achievements} ({@code data}) or
	 * the account summary response ({@code combatAchievements}).
	 */
	CombatAchievementResult parseCombatAchievements(String json)
	{
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			if (root == null)
			{
				return null;
			}
			JsonArray data = null;
			if (root.has("data") && root.get("data").isJsonArray())
			{
				data = root.getAsJsonArray("data");
			}
			else if (root.has("combatAchievements") && root.get("combatAchievements").isJsonArray())
			{
				data = root.getAsJsonArray("combatAchievements");
			}

			if (data == null)
			{
				return null;
			}
			return parseCombatAchievementRows(data);
		}
		catch (Exception e)
		{
			log.debug("Failed to parse combat achievements: {}", e.getMessage());
			return null;
		}
	}

	private CombatAchievementResult parseCombatAchievementRows(JsonArray data)
	{
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> total = new EnumMap<>(CombatAchievementTier.class);

		for (JsonElement element : data)
		{
			if (!element.isJsonObject())
			{
				continue;
			}
			JsonObject row = element.getAsJsonObject();
			if (!row.has("name"))
			{
				continue;
			}
			CombatAchievementTier tier = CombatAchievementTier.fromName(row.get("name").getAsString());
			if (tier == null)
			{
				continue;
			}
			completed.put(tier, intField(row, "completed"));
			total.put(tier, intField(row, "total"));
		}

		if (completed.isEmpty())
		{
			return null;
		}
		CaCatalog catalog = caCatalog;
		return CombatAchievementResult.of(completed, total,
			catalog != null ? catalog.totals() : null);
	}

	@Nullable
	RuneProfileSummary parseAccountSummary(String json)
	{
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			if (root == null)
			{
				return null;
			}

			AccountType accountType = RuneProfileAccountSummaryParser.parseAccountType(root);
			CombatAchievementResult ca = parseCombatAchievements(json);
			String clan = RuneProfileAccountSummaryParser.parseClan(root);
			if (accountType == null && ca == null && clan == null)
			{
				return null;
			}
			return new RuneProfileSummary(accountType, ca, clan,
				clan != null ? RuneProfileAccountSummaryParser.parseClanTitle(root) : null);
		}
		catch (Exception e)
		{
			log.debug("Failed to parse RuneProfile account summary: {}", e.getMessage());
			return null;
		}
	}

	private static int intField(JsonObject obj, String field)
	{
		return obj.has(field) && !obj.get(field).isJsonNull() ? obj.get(field).getAsInt() : 0;
	}

	// Collection log provider lane.

	/**
	 * Look up collection log data from RuneProfile. LookupSession and ComparisonController
	 * combine this with TempleOSRS and keep the freshest result.
	 *
	 * <p>Caching mirrors the CA lookup: success TTL, 404 TTL, failure cooldown,
	 * in-flight dedup. Caches are independent of the CA caches so a CA 404 does
	 * not suppress a clog lookup (though in practice both will 404 together for
	 * players not on RuneProfile).
	 */
	public CompletableFuture<ClogResult> lookupClog(String playerName)
	{
		String key = RsnInputPolicy.key(playerName);
		return clogs.lookup(key, () -> startClogLookup(playerName, key));
	}

	private CompletableFuture<ClogResult> startClogLookup(String playerName, String key)
	{
		lookupSummary(playerName).exceptionally(ex -> null);

		return HttpUtil.httpGet(httpClient, BASE_URL + HttpUtil.pathSegment(playerName) + CLOG_SUFFIX).thenApply(resp ->
		{
			if (resp.code == 404)
			{
				return clogs.missing(key);
			}
			if (resp.code != 200 || resp.body == null)
			{
				return clogs.fail(key);
			}
			RuneProfileSummary summary = summaries.fresh(key);
			AccountType accountType = summary != null ? summary.accountType : null;
			ClogParseOutcome parsed = parseCollectionLogOutcome(playerName, resp.body, accountType);
			if (parsed.state == ClogParseState.NOT_SYNCED)
			{
				// RuneProfile can return a complete all-zero catalog instead of 404
				// when no player snapshot exists. This is a healthy negative result,
				// and it must replace any stale success rather than revive it.
				clogs.values.remove(key);
				clogs.fetched.remove(key);
				clogs.failed.remove(key);
				clogs.missing(key);
				breaker.reset();
				return null;
			}
			if (parsed.result == null)
			{
				return clogs.fail(key);
			}
			breaker.reset();
			return clogs.ok(key, parsed.result);
		});
	}

	/**
	 * Parse the RuneProfile collection-log response into a {@link ClogResult}.
	 * The collection-log endpoint response shape (confirmed from RuneProfile OpenAPI spec):
	 * <pre>{@code
	 * { obtained, total, tabs: [{ name, pages: [{ name, items: [{ id, name, quantity }] }] }] }
	 * }</pre>
	 * Items with {@code quantity > 0} are obtained. The page name is normalized through
	 * the category canon shared with TempleOSRS and the boss grid.
	 */
	ClogParseOutcome parseCollectionLogOutcome(String playerName, String json,
		@Nullable AccountType providerAccountType)
	{
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			if (root == null || !root.has("tabs")
				|| !root.has("obtained") || root.get("obtained").isJsonNull()
				|| !root.has("total") || root.get("total").isJsonNull())
			{
				return ClogParseOutcome.invalid();
			}

			int rootObtained = intField(root, "obtained");
			int rootTotal = intField(root, "total");

			if (!root.get("tabs").isJsonArray())
			{
				return ClogParseOutcome.invalid();
			}
			JsonArray tabs = root.getAsJsonArray("tabs");
			Map<String, List<ClogResult.ClogItem>> obtainedItems = new HashMap<>();
			Map<String, List<Integer>> categoryItems = new HashMap<>();
			Map<Integer, String> itemNames = new HashMap<>();
			int parsedItemCount = 0;

			for (JsonElement tabEl : tabs)
			{
				if (!tabEl.isJsonObject())
				{
					continue;
				}
				JsonObject tab = tabEl.getAsJsonObject();
				if (!tab.has("pages") || !tab.get("pages").isJsonArray())
				{
					continue;
				}

				JsonArray pages = tab.getAsJsonArray("pages");
				for (JsonElement pageEl : pages)
				{
					if (!pageEl.isJsonObject())
					{
						continue;
					}
					JsonObject page = pageEl.getAsJsonObject();
					if (!page.has("name") || page.get("name").isJsonNull())
					{
						continue;
					}
					String pageName = page.get("name").getAsString();
					if (!page.has("items") || !page.get("items").isJsonArray())
					{
						continue;
					}

					String categoryKey = normalizePageKey(pageName);
					JsonArray items = page.getAsJsonArray("items");

					List<ClogResult.ClogItem> obtained = new ArrayList<>();
					List<Integer> allIds = new ArrayList<>();

					for (JsonElement itemEl : items)
					{
						if (!itemEl.isJsonObject())
						{
							continue;
						}
						JsonObject item = itemEl.getAsJsonObject();
						if (!item.has("id") || item.get("id").isJsonNull()
							|| !item.has("quantity") || item.get("quantity").isJsonNull())
						{
							continue;
						}
						parsedItemCount++;
						int id = intField(item, "id");
						int qty = intField(item, "quantity");
						String name = item.has("name") && !item.get("name").isJsonNull()
							? item.get("name").getAsString() : null;

						allIds.add(id);
						if (name != null)
						{
							itemNames.put(id, name);
						}
						if (qty > 0)
						{
							obtained.add(new ClogResult.ClogItem(id, qty, null));
						}
					}

					categoryItems.put(categoryKey, allIds);
					if (!obtained.isEmpty())
					{
						obtainedItems.put(categoryKey, obtained);
					}
				}
			}

			if (categoryItems.isEmpty() || parsedItemCount == 0)
			{
				return ClogParseOutcome.invalid();
			}

			if (obtainedItems.isEmpty())
			{
				return rootObtained == 0
					? ClogParseOutcome.notSynced()
					: ClogParseOutcome.invalid();
			}

			ClogResult result = new ClogResult(
				playerName,
				obtainedItems,
				categoryItems,
				itemNames,
				null,   // no lastChanged from RuneProfile clog endpoint
				providerAccountType
			).withSources(false, true, false);
			result.setUniqueObtained(rootObtained);
			result.setUniqueTotal(rootTotal);
			return ClogParseOutcome.data(result);
		}
		catch (Exception e)
		{
			log.debug("Failed to parse RuneProfile collection log: {}", e.getMessage());
			return ClogParseOutcome.invalid();
		}
	}

	private enum ClogParseState
	{
		DATA,
		NOT_SYNCED,
		INVALID
	}

	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	static final class ClogParseOutcome
	{
		private final ClogParseState state;
		@Nullable final ClogResult result;

		private static ClogParseOutcome data(ClogResult result)
		{
			return new ClogParseOutcome(ClogParseState.DATA, result);
		}

		private static ClogParseOutcome notSynced()
		{
			return new ClogParseOutcome(ClogParseState.NOT_SYNCED, null);
		}

		private static ClogParseOutcome invalid()
		{
			return new ClogParseOutcome(ClogParseState.INVALID, null);
		}
	}

	/**
	 * Normalize a RuneProfile collection-log page name through the same category
	 * canon used by TempleOSRS and the boss grid.
	 */
	static String normalizePageKey(String pageName)
	{
		return ClogService.bossToCategory(pageName);
	}

	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	static final class RuneProfileSummary
	{
		final AccountType accountType;
		final CombatAchievementResult combatAchievements;
		final String clan;
		final ClanTitle clanTitle;

	}
}

package com.killclog;

import java.awt.Color;
import java.util.concurrent.ThreadLocalRandom;

/** Search status message pools: lookup, comparison, not-found, and self flavor text. */
final class SearchMessages
{
	private SearchMessages()
	{
	}

	static final String INVALID_NAME = "That name didn't seem to take.";

	static final String[] SEARCH = pool("search");

	static final String[] NOT_FOUND = pool("not_found");

	static final String[] SELF = pool("self");

	static final String[] SELF_RARE = pool("self_rare");

	static final String[] SELF_ULTRA = pool("self_ultra");

	static final Color SELF_COLOR = new Color(0x4c, 0xaf, 0x6e);

	static final String[] COMPARE_SEARCH = pool("compare_search");

	static final String[] COMPARE_NOT_FOUND = pool("compare_not_found");

	static final String[] COMPARE_MIRROR = pool("compare_mirror");

	static final String[] COMPARE_SELF_MIRROR = pool("compare_self_mirror");

	static final String[] COMPARE_SELF_BLUE = pool("compare_self_blue");

	static final String[] COMPARE_SELF_RED = pool("compare_self_red");

	/** One line from a pool, at random. */
	static String pick(String[] pool)
	{
		return pool[ThreadLocalRandom.current().nextInt(pool.length)];
	}

	/** Bundled pool rows of this kind; the parity test pins contents. */
	private static String[] pool(String kind)
	{
		java.util.List<String> texts =
			CatalogTsv.values(SearchMessages.class, "search-messages.tsv", kind);
		if (texts.isEmpty())
		{
			// A broken catalog degrades to a plain line, never an empty pool:
			// every consumer draws by random index.
			return new String[]{"Searching for %s..."};
		}
		return texts.toArray(new String[0]);
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.BooleanSupplier;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.IconTextField;

final class SearchRowController
{
	private static final int SEARCH_ICON_HIT_X = 32;
	private static final int COMPARE_ICON_WIDTH = 22;

	private final JPanel searchRow;
	private final IconTextField searchBar;
	private final JLabel compareLabel;
	private final JTextField searchTextField;
	private final BooleanSupplier comparisonMode;
	private final BooleanSupplier compareLookupInFlight;
	private final Runnable normalLookup;
	private final Runnable compareLookup;
	private final Runnable comparisonExit;
	private final Runnable clearSearchStatus;
	private final Runnable lookupSelf;
	private final Runnable panelRevalidate;
	private final ImageIcon compareIconDim;
	private final ImageIcon compareIconBright;
	private final ImageIcon searchIconDim;
	private final ImageIcon searchIconBright;
	private final KeyListener compareEntryKeyListener;

	@Getter(AccessLevel.PACKAGE)
	private boolean compareEntryMode;
	private boolean compareIconHover;
	private boolean searchRowHover;
	private boolean compareAvailable;
	private boolean comparisonEnabled = true;

	SearchRowController(
		JPanel searchRow,
		IconTextField searchBar,
		JLabel compareLabel,
		JTextField searchTextField,
		Color textDim,
		BooleanSupplier comparisonMode,
		BooleanSupplier compareLookupInFlight,
		Runnable normalLookup,
		Runnable compareLookup,
		Runnable comparisonExit,
		Runnable clearSearchStatus,
		Runnable lookupSelf,
		Runnable panelRevalidate)
	{
		this.searchRow = searchRow;
		this.searchBar = searchBar;
		this.compareLabel = compareLabel;
		this.searchTextField = searchTextField;
		this.comparisonMode = comparisonMode;
		this.compareLookupInFlight = compareLookupInFlight;
		this.normalLookup = normalLookup;
		this.compareLookup = compareLookup;
		this.comparisonExit = comparisonExit;
		this.clearSearchStatus = clearSearchStatus;
		this.lookupSelf = lookupSelf;
		this.panelRevalidate = panelRevalidate;
		compareIconDim = new ImageIcon(ClogHelper.makeCompareIcon(
			ComparisonController.COMPARE_BLUE, ComparisonController.COMPARE_RED, 0.55f));
		compareIconBright = new ImageIcon(ClogHelper.makeCompareIcon(
			ComparisonController.COMPARE_BLUE, ComparisonController.COMPARE_RED, 1.0f));
		searchIconDim = new ImageIcon(ClogHelper.makeSearchIcon(textDim, 0.70f));
		searchIconBright = new ImageIcon(ClogHelper.makeSearchIcon(textDim, 1.0f));
		compareEntryKeyListener = new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
				{
					exitEntry();
				}
			}
		};
	}

	void install()
	{
		searchBar.addActionListener(e ->
		{
			if (compareEntryMode)
			{
				compareLookup.run();
			}
			else
			{
				normalLookup.run();
			}
		});

		compareLabel.setIcon(compareIconDim);
		compareLabel.setHorizontalAlignment(JLabel.CENTER);
		compareLabel.setVerticalAlignment(JLabel.CENTER);
		compareLabel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		compareLabel.setOpaque(true);
		// Mirror the search glass's left inset: glyph sits 8 px from the right edge.
		compareLabel.setBorder(new EmptyBorder(0, 0, 0, 7));
		compareLabel.setVisible(false);
		compareLabel.setPreferredSize(new Dimension(COMPARE_ICON_WIDTH, 30));

		MouseAdapter searchRowHoverSync = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				setSearchRowHover(true);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				SwingUtilities.invokeLater(() ->
				{
					if (!isMouseInsideSearchRow())
					{
						setSearchRowHover(false);
					}
				});
			}
		};
		installMouseListenerDeep(searchRow, searchRowHoverSync);

		installMouseListenerDeep(searchBar, new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (!SwingUtilities.isLeftMouseButton(e) || e.getClickCount() != 2)
				{
					return;
				}
				Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), searchBar);
				if (p.x <= SEARCH_ICON_HIT_X)
				{
					lookupSelf.run();
				}
			}
		});

		compareLabel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				toggleEntry();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				compareIconHover = true;
				setSearchRowHover(true);
				refreshIcon();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				compareIconHover = false;
				refreshIcon();
				SwingUtilities.invokeLater(() ->
				{
					if (!isMouseInsideSearchRow())
					{
						setSearchRowHover(false);
					}
				});
			}
		});
	}

	int compareIconWidth()
	{
		return compareLabel.isVisible() ? COMPARE_ICON_WIDTH : 0;
	}

	void setCompareVisible(boolean visible)
	{
		compareAvailable = visible;
		applyCompareVisibility();
	}

	void setComparisonEnabled(boolean enabled)
	{
		comparisonEnabled = enabled;
		if (!enabled)
		{
			compareIconHover = false;
			exitIfActive();
		}
		applyCompareVisibility();
	}

	private void applyCompareVisibility()
	{
		compareLabel.setVisible(comparisonEnabled && compareAvailable);
		refreshIcon();
		searchRow.revalidate();
	}

	void toggleEntry()
	{
		if (!comparisonEnabled)
		{
			return;
		}
		if (compareEntryMode || comparisonMode.getAsBoolean() || compareLookupInFlight.getAsBoolean())
		{
			exitEntry();
		}
		else
		{
			enterEntry();
		}
	}

	void exitIfActive()
	{
		if (compareEntryMode || comparisonMode.getAsBoolean() || compareLookupInFlight.getAsBoolean())
		{
			exitEntry();
		}
	}

	void onComparisonExit()
	{
		searchBar.setText("");
		searchBar.setIcon(IconTextField.Icon.SEARCH);
		resetTextField();
		compareEntryMode = false;
		refreshIcon();
	}

	void onComparisonEnter()
	{
		searchBar.setIcon(IconTextField.Icon.SEARCH);
		searchBar.setText("");
		refreshIcon();
	}

	void refreshIcon()
	{
		boolean active = compareIconHover || compareEntryMode || comparisonMode.getAsBoolean();
		boolean comparing = compareEntryMode || comparisonMode.getAsBoolean();
		compareLabel.setIcon(comparing
			? (compareIconHover ? searchIconBright : searchIconDim)
			: (active ? compareIconBright : compareIconDim));
		compareLabel.setBackground(searchRowHover
			? ColorScheme.DARK_GRAY_HOVER_COLOR
			: ColorScheme.DARKER_GRAY_COLOR);
		if (!compareLookupInFlight.getAsBoolean())
		{
			if (comparing)
			{
				searchBar.setIcon(compareIconBright);
			}
			else
			{
				searchBar.setIcon(IconTextField.Icon.SEARCH);
			}
		}
	}

	private void enterEntry()
	{
		if (!comparisonEnabled)
		{
			return;
		}
		compareEntryMode = true;
		refreshIcon();

		if (searchTextField != null)
		{
			searchTextField.setText("");
			searchTextField.setForeground(ComparisonController.COMPARE_RED);
			searchTextField.setCaretColor(ComparisonController.COMPARE_RED);
			searchTextField.addKeyListener(compareEntryKeyListener);
			searchTextField.requestFocusInWindow();
		}

		clearSearchStatus.run();
		panelRevalidate.run();
	}

	private void exitEntry()
	{
		compareEntryMode = false;
		if (comparisonMode.getAsBoolean() || compareLookupInFlight.getAsBoolean())
		{
			comparisonExit.run();
			return;
		}
		resetTextField();
		searchBar.setText("");
		refreshIcon();
		clearSearchStatus.run();
		panelRevalidate.run();
	}

	private void resetTextField()
	{
		if (searchTextField != null)
		{
			searchTextField.removeKeyListener(compareEntryKeyListener);
			searchTextField.setForeground(Color.WHITE);
			searchTextField.setCaretColor(Color.WHITE);
		}
	}

	private void installMouseListenerDeep(Component component, MouseAdapter adapter)
	{
		component.addMouseListener(adapter);
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				installMouseListenerDeep(child, adapter);
			}
		}
	}

	private boolean isMouseInsideSearchRow()
	{
		return searchRow.getMousePosition(true) != null;
	}

	private void setSearchRowHover(boolean hover)
	{
		searchRowHover = hover;
		Color background = hover ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR;
		for (Component part : searchRow.getComponents())
		{
			part.setBackground(background);
		}
	}
}

package com.killclog;

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.concurrent.Executor;
import lombok.extern.slf4j.Slf4j;

/**
 * Runs what it is given one at a time, in the order given, on whichever thread finds it idle: the single owner of
 * state that many threads post to, so no two of its tasks ever interleave and none needs a lock of its own. A task
 * posted while one runs (by that task or another thread) waits its turn and runs before the owner goes idle. Its
 * tasks must be short and never wait on another thread. A task that fails is logged and the next one runs; an Error
 * still leaves the owner idle, so the next task posted runs the queue again rather than waiting forever.
 */
@Slf4j
final class SerialExecutor implements Executor
{
	private final Queue<Runnable> tasks = new ArrayDeque<>();
	private boolean running;

	@Override
	public void execute(Runnable task)
	{
		synchronized (tasks)
		{
			tasks.add(task);
			if (running)
			{
				return;
			}
			running = true;
		}
		boolean idle = false;
		try
		{
			while (true)
			{
				Runnable next;
				synchronized (tasks)
				{
					next = tasks.poll();
					if (next == null)
					{
						running = false;
						idle = true;
						return;
					}
				}
				try
				{
					next.run();
				}
				catch (RuntimeException e)
				{
					log.warn("publication task failed", e);
				}
			}
		}
		finally
		{
			if (!idle)
			{
				synchronized (tasks)
				{
					running = false;
				}
			}
		}
	}
}

package com.killclog;

import javax.annotation.Nullable;
import lombok.Value;

/**
 * Who is logged in, for one login: the account (its hash, which a name change keeps) and the name it plays under.
 * The plugin keeps no other copy of it ({@link SessionTracker}): work that outlives the session it began in asks
 * whether that session is still current before it does anything. {@code number} only grows, so each login and each
 * logout is a session of its own, and nothing from one can pass for another.
 */
@Value
class Session
{
	long number;
	// Null while nobody is logged in.
	@Nullable
	String name;
	long accountHash;

	static Session none(long number)
	{
		return new Session(number, null, -1);
	}

	boolean loggedIn()
	{
		return name != null;
	}
}

package com.killclog;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import net.runelite.api.Client;
import net.runelite.api.GameState;

/**
 * The one place the plugin decides who is logged in. The client thread hands it the game's state on each game state
 * change and each tick: a login whose name and account have both arrived becomes a session, a different account or
 * name is a new one, and the login screen ends it. A hop or a dropped connection keeps it, as the game does. Each
 * change goes once to every listener, in the order they were added, so the stores, the panel and the publication
 * flow move together; work that outlives its session asks {@link #isCurrent} before it acts.
 */
final class SessionTracker
{
	/** Told of each change on the client thread, before anything else can see the new session. */
	interface Listener
	{
		void sessionChanged(Session previous, Session now);
	}

	private final List<Listener> listeners = new CopyOnWriteArrayList<>();
	private volatile Session current = Session.none(0);

	void addListener(Listener listener)
	{
		listeners.add(listener);
	}

	Session current()
	{
		return current;
	}

	/** Whether nothing has changed who is logged in since {@code session} began. */
	boolean isCurrent(Session session)
	{
		return session.getNumber() == current.getNumber();
	}

	/** On the client thread, after each game state change and on every tick. */
	void update(Client client)
	{
		GameState state = client.getGameState();
		Session now = current;
		if (state == GameState.LOGIN_SCREEN)
		{
			end();
			return;
		}
		if (state != GameState.LOGGED_IN)
		{
			return;
		}
		String name = RsnInputPolicy.localName(client);
		long accountHash = client.getAccountHash();
		if (name == null || accountHash == -1)
		{
			return;
		}
		if (!now.loggedIn() || now.getAccountHash() != accountHash || !RsnInputPolicy.sameName(now.getName(), name))
		{
			change(now, new Session(now.getNumber() + 1, name, accountHash));
		}
	}

	/** The plugin stopping ends the login as the login screen would. */
	void end()
	{
		Session now = current;
		if (now.loggedIn())
		{
			change(now, Session.none(now.getNumber() + 1));
		}
	}

	private void change(Session previous, Session next)
	{
		current = next;
		for (Listener listener : listeners)
		{
			listener.sessionChanged(previous, next);
		}
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.swing.Icon;
import javax.swing.JToolTip;

/**
 * Comparison tooltip: the two players' complete single tooltips side by side
 * on one parchment card, blue (primary) on the left, red (compared) on the
 * right, each under its player's name. Comparison mode renders through the
 * exact tooltip code players see solo, so every tooltip feature carries into
 * comparison automatically and the two modes can never drift apart.
 */
public class SideBySideTooltip extends NativeTooltip
{
	private static final int CARD_GAP = 8;
	private static final int NAME_GAP = 4;

	private final String blueName;
	private final String redName;
	private final JToolTip blueTip;
	private final JToolTip redTip;
	private Icon blueBadge;
	private Icon redBadge;

	public SideBySideTooltip(String blueName, JToolTip blueTip, String redName, JToolTip redTip)
	{
		this.blueName = blueName;
		this.blueTip = blueTip;
		this.redName = redName;
		this.redTip = redTip;
		setLayout(null);
		add(blueTip);
		add(redTip);
	}

	/** The two live child tooltips, for hover wiring and tests. */
	public JToolTip[] sides()
	{
		return new JToolTip[]{blueTip, redTip};
	}

	void setAccountBadges(Icon blueBadge, Icon redBadge)
	{
		this.blueBadge = blueBadge;
		this.redBadge = redBadge;
	}

	private int nameStripHeight()
	{
		return Math.max(getFontMetrics(TitleTooltip.TITLE_FONT_SMALL).getHeight(),
			Math.max(blueBadge != null ? blueBadge.getIconHeight() : 0,
				redBadge != null ? redBadge.getIconHeight() : 0)) + NAME_GAP;
	}

	// Child getPreferredSize is not a pure query (ImgTooltip caches grid
	// geometry from it), so sizing, layout, and paint must all ask with the
	// same inputs; do not add state-dependent sizing here.
	@Override
	public Dimension getPreferredSize()
	{
		Dimension blue = blueTip.getPreferredSize();
		Dimension red = redTip.getPreferredSize();
		int inset = getInset();
		return new Dimension(inset * 2 + blue.width + CARD_GAP + red.width,
			inset * 2 + nameStripHeight() + Math.max(blue.height, red.height));
	}

	@Override
	public void doLayout()
	{
		int inset = getInset();
		int top = inset + nameStripHeight();
		Dimension blue = blueTip.getPreferredSize();
		Dimension red = redTip.getPreferredSize();
		blueTip.setBounds(inset, top, blue.width, blue.height);
		redTip.setBounds(inset + blue.width + CARD_GAP, top, red.width, red.height);
	}

	@Override
	protected void paintComponent(java.awt.Graphics g)
	{
		// Popups validate before painting; direct paints (tests, previews) may
		// not, and unlaid-out children would render as nothing.
		if (blueTip.getWidth() == 0)
		{
			doLayout();
		}
		super.paintComponent(g);
	}

	@Override
	protected void paintContent(Graphics2D g2, int w, int h)
	{
		g2.setFont(TitleTooltip.TITLE_FONT_SMALL);
		FontMetrics fm = g2.getFontMetrics();
		int inset = getInset();
		int top = inset + (nameStripHeight() - NAME_GAP - fm.getHeight()) / 2 + fm.getAscent();
		Dimension blue = blueTip.getPreferredSize();
		Dimension red = redTip.getPreferredSize();
		paintName(g2, fm, blueName, blueBadge, TitleTooltip.COMPARE_BLUE, inset, blue.width, top);
		paintName(g2, fm, redName, redBadge, TitleTooltip.COMPARE_RED,
			inset + blue.width + CARD_GAP, red.width, top);
	}

	private void paintName(Graphics2D g2, FontMetrics fm, String name, Icon badge,
		Color color, int cardX, int cardWidth, int baseline)
	{
		if (name == null || name.isEmpty())
		{
			return;
		}
		// A name wider than its card trims to fit rather than bleeding into
		// the neighbor card's lane or the iron border.
		int badgeWidth = badge != null ? badge.getIconWidth() + 3 : 0;
		int textWidth = Math.max(0, cardWidth - badgeWidth);
		String shown = name;
		if (fm.stringWidth(shown) > textWidth)
		{
			while (!shown.isEmpty() && fm.stringWidth(shown + "..") > textWidth)
			{
				shown = shown.substring(0, shown.length() - 1);
			}
			shown = fm.stringWidth(shown + "..") <= textWidth ? shown + ".." : "";
		}
		int x = cardX + Math.max(0, (cardWidth - badgeWidth - fm.stringWidth(shown)) / 2);
		if (badge != null)
		{
			badge.paintIcon(this, g2, x,
				getInset() + (nameStripHeight() - NAME_GAP - badge.getIconHeight()) / 2);
		}
		g2.setColor(color);
		g2.drawString(shown, x + badgeWidth, baseline);
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import javax.annotation.Nullable;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToolTip;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ImageUtil;

/**
 * A movable 3x8 grid of real skill cells with compact native stat tooltips.
 * Reusable skill collection-log sections grow below those stats when mapped.
 */
final class SkillCellGrid
{
	static final int SKILL_ICON_SIZE = 22;
	private static final int SKILL_ICON_CANVAS_SIZE = 25;

	private final JPanel component = new JPanel();
	private final JPanel grid = new JPanel(
		new GridLayout(SkillGridOrder.ROWS, SkillGridOrder.COLUMNS));
	private final Map<Skill, JLabel> labels = new LinkedHashMap<>();
	private final ComparisonController comparison;
	private final TooltipController tooltipController;
	private final KillClogConfig config;
	@Nullable
	private final ItemManager itemManager;
	@Nullable
	private HiscoreResult primary;
	@Nullable
	private HiscoreResult compared;
	@Nullable
	private ClogResult primaryClog;
	@Nullable
	private ClogResult comparedClog;
	@Nullable
	private ClogResult catalog;
	@Nullable
	private ClogIndex clogIndex;
	private boolean virtualLevels;

	SkillCellGrid(SkillIconManager skillIconManager,
		TooltipController tooltipController, ComparisonController comparison,
		KillClogConfig config, @Nullable ItemManager itemManager)
	{
		this.comparison = comparison;
		this.tooltipController = tooltipController;
		this.config = config;
		this.itemManager = itemManager;

		component.setLayout(new BoxLayout(component, BoxLayout.Y_AXIS));
		component.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		component.setAlignmentX(0f);

		grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		grid.setAlignmentX(0f);
		for (Skill skill : SkillGridOrder.skills())
		{
			grid.add(buildCell(skill, skillIconManager));
		}
		component.add(grid);
		component.add(buildDivider());
	}

	private JPanel buildCell(Skill skill, SkillIconManager skillIconManager)
	{
		JLabel label = new JLabel()
		{
			@Override
			public JToolTip createToolTip()
			{
				return buildTooltip(this, skill);
			}
		};
		Cells.styleLabel(label, " ");
		try
		{
			BufferedImage image = skillIconManager.getSkillImage(skill, true);
			if (image != null)
			{
				label.setIcon(new ImageIcon(ImageUtil.resizeImage(
					ImageUtil.resizeCanvas(image, SKILL_ICON_CANVAS_SIZE,
						SKILL_ICON_CANVAS_SIZE), SKILL_ICON_SIZE, SKILL_ICON_SIZE)));
			}
		}
		catch (Exception ignored)
		{
			// A missing icon must not suppress the skill's level.
		}

		labels.put(skill, label);
		return Cells.cell(label, tooltipController, comparison);
	}

	private static JPanel buildDivider()
	{
		JPanel divider = new JPanel();
		divider.setBackground(ColorScheme.DARK_GRAY_COLOR);
		divider.setPreferredSize(new Dimension(0, 7));
		divider.setMaximumSize(new Dimension(Integer.MAX_VALUE, 7));
		divider.setAlignmentX(0f);
		return divider;
	}

	void render(HiscoreResult primary, @Nullable HiscoreResult compared,
		boolean virtualLevels)
	{
		render(primary, compared, virtualLevels, null, null, null);
	}

	void render(HiscoreResult primary, @Nullable HiscoreResult compared,
		boolean virtualLevels, @Nullable ClogResult primaryClog,
		@Nullable ClogResult comparedClog, @Nullable ClogResult catalog)
	{
		this.primary = primary;
		this.compared = compared;
		this.virtualLevels = virtualLevels;
		this.primaryClog = primaryClog;
		this.comparedClog = comparedClog;
		this.catalog = catalog;
		for (Map.Entry<Skill, JLabel> entry : labels.entrySet())
		{
			Skill skill = entry.getKey();
			JLabel label = entry.getValue();
			int primaryLevel = level(primary, skill, virtualLevels);
			if (compared != null)
			{
				int comparedLevel = level(compared, skill, virtualLevels);
				renderComparison(label, skill, primaryLevel, comparedLevel);
			}
			else
			{
				renderSolo(label, skill, primaryLevel);
			}
		}
	}

	void clear()
	{
		clear(null);
	}

	void clear(@Nullable ClogResult catalog)
	{
		primary = null;
		compared = null;
		primaryClog = null;
		comparedClog = null;
		this.catalog = catalog;
		for (JLabel label : labels.values())
		{
			comparison.clearCompareCell(label);
			label.setText(ClogHelper.pad("--"));
			label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			label.setHorizontalAlignment(JLabel.LEADING);
		}
	}

	void setClogIndex(@Nullable ClogIndex clogIndex)
	{
		this.clogIndex = clogIndex;
	}

	private JToolTip buildTooltip(JLabel owner, Skill skill)
	{
		// In comparison mode each side is the ordinary solo tooltip, with the
		// other player's clog unioned into its sections so both cards show the
		// same slot census.
		JToolTip tooltip = compared != null
			? comparison.wrapSideBySide(owner,
				soloTooltip(skill, primary, primaryClog, comparedClog),
				soloTooltip(skill, compared, comparedClog, primaryClog))
			: soloTooltip(skill, primary, primaryClog, comparedClog);
		tooltip.setComponent(owner);
		tooltipController.keepTooltipOnHover(tooltip, (JPanel) owner.getParent());
		return tooltip;
	}

	private SkillTooltip soloTooltip(Skill skill, @Nullable HiscoreResult result,
		@Nullable ClogResult clog, @Nullable ClogResult otherClog)
	{
		SkillTooltip solo = new SkillTooltip();
		// With Skill Clogs off the modal is the stats rows alone.
		solo.setData(skill, result, virtualLevels, config.enableSkillClogs()
			? SkillClogSection.forSkill(skill, clog, otherClog, catalog, clogIndex)
			: Collections.emptyList(), itemManager);
		if (skill == Skill.RUNECRAFT)
		{
			solo.setRiftsClosed(riftsClosed(result));
		}
		solo.setLinks(config.cardLinks());
		return solo;
	}

	private static int riftsClosed(@Nullable HiscoreResult result)
	{
		return result != null
			? result.getActivityScore(PanelData.RIFTS_CLOSED_ACTIVITY) : -1;
	}

	private void renderSolo(JLabel label, Skill skill, int level)
	{
		comparison.clearCompareCell(label);
		label.setText(ClogHelper.pad(levelText(level)));
		label.setForeground(level > 0
			? cellColor(skill, level, primaryClog)
			: ColorScheme.LIGHT_GRAY_COLOR);
		label.setHorizontalAlignment(JLabel.LEADING);
	}

	private void renderComparison(JLabel label, Skill skill, int primaryLevel, int comparedLevel)
	{
		// Same machinery as the boss cells: shared blue-over-red state plus
		// hover swapping to each player's configured skill colors.
		comparison.setCompareCell(label, primaryLevel, comparedLevel,
			hoverColor(skill, primaryLevel, primaryClog),
			hoverColor(skill, comparedLevel, comparedClog));
	}

	/**
	 * The hovered value color for one player's side, from the same skill color
	 * configs solo cells use. Null (no swap) when that player has no clog,
	 * matching the boss cells' synced-only hover rule.
	 */
	@Nullable
	private Color hoverColor(Skill skill, int level, @Nullable ClogResult clog)
	{
		return level <= 0 || clog == null ? null : cellColor(skill, level, clog);
	}

	/** One player's cell color under the skill color configs; solo and hover share it. */
	private Color cellColor(Skill skill, int level, @Nullable ClogResult clog)
	{
		int obtained = -1;
		int total = -1;
		if (SkillLevelColor.usesClogProgress(config))
		{
			SkillClogSection.Progress progress = SkillClogSection.combinedProgress(
				SkillClogSection.forSkill(skill, clog, null, catalog, clogIndex));
			obtained = progress.obtained();
			total = progress.total();
		}
		return SkillLevelColor.forCell(level, clog != null, obtained, total, config);
	}

	private static int level(HiscoreResult result, Skill skill, boolean virtualLevels)
	{
		String key = skill.getName().toLowerCase(Locale.ROOT);
		return ClogHelper.displayLevel(result.getSkillLevel(key),
			result.getSkillXp(key), virtualLevels);
	}

	private static String levelText(int level)
	{
		return level > 0 ? String.valueOf(level) : "--";
	}

	JPanel component()
	{
		return component;
	}

	JPanel grid()
	{
		return grid;
	}

	Map<Skill, JLabel> labels()
	{
		return Collections.unmodifiableMap(labels);
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Skill;

/**
 * A presentation-only view of collection-log slots associated with a skill.
 * The view never writes synthetic categories into {@link ClogResult}, so these
 * repeated slots cannot affect the plugin's canonical collection-log totals.
 */
final class SkillClogSection
{
	private static final Map<Skill, List<Spec>> SPECS = buildSpecs();

	@Nullable
	private final String heading;
	@Nullable
	private final String category;
	private final List<Integer> itemIds;
	private final Map<Integer, String> itemNames;
	private final PlayerItems primary;

	private SkillClogSection(@Nullable String heading, @Nullable String category,
		List<Integer> itemIds,
		Map<Integer, String> itemNames, PlayerItems primary)
	{
		this.heading = heading;
		this.category = category;
		this.itemIds = Collections.unmodifiableList(itemIds);
		this.itemNames = Collections.unmodifiableMap(itemNames);
		this.primary = primary;
	}

	static List<SkillClogSection> forSkill(Skill skill,
		@Nullable ClogResult primary, @Nullable ClogResult compared,
		@Nullable ClogResult catalog)
	{
		return forSkill(skill, primary, compared, catalog, null);
	}

	static List<SkillClogSection> forSkill(Skill skill,
		@Nullable ClogResult primary, @Nullable ClogResult compared,
		@Nullable ClogResult catalog, @Nullable ClogIndex clogIndex)
	{
		List<Spec> specs = SPECS.get(skill);
		if (specs == null)
		{
			return Collections.emptyList();
		}

		List<SkillClogSection> sections = new ArrayList<>();
		for (Spec spec : specs)
		{
			SkillClogSection section = fromSpec(spec, primary, compared, catalog,
				clogIndex);
			if (section != null)
			{
				sections.add(section);
			}
		}
		return Collections.unmodifiableList(sections);
	}

	@Nullable
	private static SkillClogSection fromSpec(Spec spec,
		@Nullable ClogResult primary, @Nullable ClogResult compared,
		@Nullable ClogResult catalog,
		@Nullable ClogIndex clogIndex)
	{
		LinkedHashSet<Integer> distinctIds = new LinkedHashSet<>();
		if (spec.category != null)
		{
			addCategoryItems(distinctIds, catalog, spec.category, clogIndex);
			addCategoryItems(distinctIds, primary, spec.category, clogIndex);
			addCategoryItems(distinctIds, compared, spec.category, clogIndex);
		}
		else
		{
			for (int itemId : spec.itemIds)
			{
				distinctIds.add(canonicalItemId(itemId, clogIndex));
			}
		}
		if (distinctIds.isEmpty())
		{
			return null;
		}

		List<Integer> itemIds = new ArrayList<>(distinctIds);
		Map<Integer, String> itemNames = new LinkedHashMap<>();
		addItemNames(itemNames, itemIds, catalog, clogIndex);
		addItemNames(itemNames, itemIds, compared, clogIndex);
		addItemNames(itemNames, itemIds, primary, clogIndex);
		return new SkillClogSection(spec.heading, spec.category, itemIds, itemNames,
			PlayerItems.from(primary, spec, distinctIds, clogIndex));
	}

	private static void addCategoryItems(Set<Integer> destination,
		@Nullable ClogResult result, String category, @Nullable ClogIndex clogIndex)
	{
		if (result == null)
		{
			return;
		}
		List<Integer> items = result.getCategoryItems().get(category);
		if (items != null)
		{
			for (int itemId : items)
			{
				destination.add(canonicalItemId(itemId, clogIndex));
			}
		}
	}

	private static void addItemNames(Map<Integer, String> destination,
		List<Integer> itemIds, @Nullable ClogResult result, @Nullable ClogIndex clogIndex)
	{
		if (result == null)
		{
			return;
		}
		for (int itemId : itemIds)
		{
			String name = ClogIndex.itemNameOrAlias(clogIndex, result, itemId);
			if (name != null)
			{
				destination.put(itemId, name);
			}
		}
	}

	private static int canonicalItemId(int itemId, @Nullable ClogIndex clogIndex)
	{
		return clogIndex != null
			? clogIndex.canonicalItemId(itemId) : ClogIndex.fallbackCanonicalItemId(itemId);
	}

	static Progress combinedProgress(List<SkillClogSection> sections)
	{
		Set<Integer> allItems = new HashSet<>();
		Set<Integer> obtained = new HashSet<>();
		boolean synced = false;
		for (SkillClogSection section : sections)
		{
			allItems.addAll(section.itemIds);
			PlayerItems playerItems = section.primary;
			synced |= playerItems.synced;
			obtained.addAll(playerItems.obtainedIds);
		}
		return new Progress(synced ? obtained.size() : -1, allItems.size());
	}

	@Nullable
	String heading()
	{
		return heading;
	}

	boolean hasHeading()
	{
		return heading != null && !heading.isEmpty();
	}

	boolean isCategory(String expectedCategory)
	{
		return expectedCategory.equals(category);
	}

	List<Integer> itemIds()
	{
		return itemIds;
	}

	Map<Integer, String> itemNames()
	{
		return itemNames;
	}

	PlayerItems primary()
	{
		return primary;
	}

	private static Map<Skill, List<Spec>> buildSpecs()
	{
		// The curated taxonomy ships as a bundled catalog; the parity test pins
		// its exact contents. Rows are presentation order per skill: pets stay
		// first, activity sections follow alphabetically, and full activities
		// read their live category catalogs instead of copying slots.
		Map<Skill, List<Spec>> specs = new LinkedHashMap<>();
		for (String[] row : CatalogTsv.rows(SkillClogSection.class, "skill-clog-sections.tsv", 4))
		{
			String heading = row[2].isEmpty() ? null : row[2];
			Spec spec;
			if ("category".equals(row[1]))
			{
				spec = new Spec(heading, row[3], Collections.emptyList());
			}
			else
			{
				List<Integer> itemIds = new ArrayList<>();
				for (String itemId : row[3].split(","))
				{
					itemIds.add(Integer.parseInt(itemId.trim()));
				}
				spec = new Spec(heading, null, itemIds);
			}
			Skill skill;
			try
			{
				skill = Skill.valueOf(row[0]);
			}
			catch (IllegalArgumentException e)
			{
				// Skip: skill not present in this client build.
				continue;
			}
			specs.computeIfAbsent(skill, s -> new ArrayList<>()).add(spec);
		}
		for (Map.Entry<Skill, List<Spec>> entry : specs.entrySet())
		{
			entry.setValue(Collections.unmodifiableList(entry.getValue()));
		}
		return Collections.unmodifiableMap(specs);
	}

	static final class PlayerItems
	{
		private final boolean synced;
		private final Set<Integer> obtainedIds;
		private final Map<Integer, Integer> obtainedCounts;

		private PlayerItems(boolean synced, Set<Integer> obtainedIds,
			Map<Integer, Integer> obtainedCounts)
		{
			this.synced = synced;
			this.obtainedIds = Collections.unmodifiableSet(obtainedIds);
			this.obtainedCounts = Collections.unmodifiableMap(obtainedCounts);
		}

		private static PlayerItems from(@Nullable ClogResult result,
			Spec spec, Set<Integer> catalogIds, @Nullable ClogIndex clogIndex)
		{
			Set<Integer> obtainedIds = new HashSet<>();
			Map<Integer, Integer> obtainedCounts = new LinkedHashMap<>();
			if (result != null)
			{
				if (spec.category != null)
				{
					addObtained(result.getObtainedItems().get(spec.category),
						catalogIds, obtainedIds, obtainedCounts, clogIndex);
				}
				else
				{
					for (List<ClogResult.ClogItem> categoryItems
						: result.getObtainedItems().values())
					{
						addObtained(categoryItems, catalogIds,
							obtainedIds, obtainedCounts, clogIndex);
					}
				}
			}
			return new PlayerItems(result != null, obtainedIds, obtainedCounts);
		}

		private static void addObtained(@Nullable List<ClogResult.ClogItem> items,
			Set<Integer> catalogIds, Set<Integer> obtainedIds,
			Map<Integer, Integer> obtainedCounts, @Nullable ClogIndex clogIndex)
		{
			if (items == null)
			{
				return;
			}
			for (ClogResult.ClogItem item : items)
			{
				int itemId = canonicalItemId(item.getId(), clogIndex);
				if (catalogIds.contains(itemId))
				{
					obtainedIds.add(itemId);
					obtainedCounts.merge(itemId, item.getCount(), Integer::max);
				}
			}
		}

		boolean synced()
		{
			return synced;
		}

		Set<Integer> obtainedIds()
		{
			return obtainedIds;
		}

		Map<Integer, Integer> obtainedCounts()
		{
			return obtainedCounts;
		}

		int obtainedCount()
		{
			return synced ? obtainedIds.size() : -1;
		}
	}

	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Progress
	{
		private final int obtained;
		private final int total;

		int obtained()
		{
			return obtained;
		}

		int total()
		{
			return total;
		}
	}

	private static final class Spec
	{
		@Nullable
		private final String heading;
		@Nullable
		private final String category;
		private final List<Integer> itemIds;

		private Spec(@Nullable String heading, @Nullable String category,
			List<Integer> itemIds)
		{
			this.heading = heading;
			this.category = category;
			this.itemIds = Collections.unmodifiableList(new ArrayList<>(itemIds));
		}
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

/** Paints adaptive item sections inside solo and comparison skill tooltips. */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class SkillClogSectionRenderer
{
	private static final int SPRITE_SIZE = 32;
	private static final int PADDING = 4;
	static final int CELL_SIZE = SPRITE_SIZE + PADDING;
	private static final int SOLO_MIN_COLS = 5;
	private static final int HEADER_GAP = 2;
	private static final String OBTAINED_LABEL = "Obtained: ";
	private static final Font SECTION_FONT = FontManager.getRunescapeBoldFont();
	private static final Font DETAIL_FONT = FontManager.getRunescapeSmallFont();

	private final SkillTooltip repaintTarget;
	private List<Entry> entries = Collections.emptyList();

	void setSections(List<SkillClogSection> sections, @Nullable ItemManager itemManager)
	{
		if (sections == null || sections.isEmpty())
		{
			entries = Collections.emptyList();
			return;
		}

		List<Entry> next = new ArrayList<>();
		for (SkillClogSection section : sections)
		{
			TooltipItemSprites sprites = itemManager != null
				? TooltipItemSprites.load(section.itemIds(), section.itemNames(), itemManager,
					itemId -> 1, repaintTarget)
				: null;
			next.add(new Entry(section, sprites));
		}
		entries = Collections.unmodifiableList(next);
	}

	Dimension soloSize(int availableWidth)
	{
		if (entries.isEmpty())
		{
			return new Dimension(0, 0);
		}

		FontMetrics headingMetrics = repaintTarget.getFontMetrics(SECTION_FONT);
		FontMetrics detailMetrics = repaintTarget.getFontMetrics(DETAIL_FONT);
		int width = availableWidth;
		for (Entry entry : entries)
		{
			if (entry.section.hasHeading())
			{
				width = Math.max(width,
					headingMetrics.stringWidth(entry.section.heading()));
			}
			width = Math.max(width, soloProgressWidth(detailMetrics, entry.section));
			if (showsRiftsClosed(entry.section))
			{
				width = Math.max(width, detailMetrics.stringWidth(
					SkillTooltip.RIFTS_CLOSED_LABEL + repaintTarget.riftsClosedText()));
			}
		}
		for (Entry entry : entries)
		{
			int cols = soloColumns(width, entry.section.itemIds().size());
			width = Math.max(width, gridWidth(cols));
		}

		return new Dimension(width, sectionHeight(width, headingMetrics, detailMetrics));
	}

	private int sectionHeight(int width, FontMetrics headingMetrics, FontMetrics detailMetrics)
	{
		int height = 0;
		for (Entry entry : entries)
		{
			int cols = soloColumns(width, entry.section.itemIds().size());
			if (entry.section.hasHeading())
			{
				height += headingMetrics.getHeight() + HEADER_GAP + CardBody.SECTION_RULE + CardBody.SECTION_AFTER;
			}
			height += detailMetrics.getHeight() + HEADER_GAP;
			if (showsRiftsClosed(entry.section))
			{
				height += detailMetrics.getHeight() + HEADER_GAP;
			}
			height += gridHeight(entry.section.itemIds().size(), cols);
		}
		height += CardBody.SECTION_SPACE * Math.max(0, entries.size() - 1);
		return height;
	}

	int paintSolo(Graphics2D g2, int width, int startY,
		List<TooltipItemHover.HitBox> hitBoxes)
	{
		int y = startY;
		int inset = TitleTooltip.getInset();
		int availableWidth = width - inset * 2;
		FontMetrics headingMetrics = g2.getFontMetrics(SECTION_FONT);
		FontMetrics detailMetrics = g2.getFontMetrics(DETAIL_FONT);
		for (int i = 0; i < entries.size(); i++)
		{
			Entry entry = entries.get(i);
			SkillClogSection section = entry.section;
			int cols = soloColumns(availableWidth, section.itemIds().size());
			if (section.hasHeading())
			{
				g2.setFont(SECTION_FONT);
				g2.setColor(NativeTooltip.labelColor);
				g2.drawString(section.heading(), inset, y + headingMetrics.getAscent());
				// A heading carries its rule like a card's section title.
				CardBody.divider(g2, y + headingMetrics.getHeight() + HEADER_GAP, inset, width);
				y += headingMetrics.getHeight() + HEADER_GAP + CardBody.SECTION_RULE + CardBody.SECTION_AFTER;
			}
			g2.setFont(DETAIL_FONT);
			TitleTooltip.drawLabelValue(g2, detailMetrics, inset, y + detailMetrics.getAscent(), OBTAINED_LABEL,
				progressText(section.primary(), section.itemIds().size()),
				progressColor(section.primary(), section.itemIds().size()));
			y += detailMetrics.getHeight() + HEADER_GAP;
			if (showsRiftsClosed(section))
			{
				TitleTooltip.drawLabelValue(g2, detailMetrics, inset, y + detailMetrics.getAscent(),
					SkillTooltip.RIFTS_CLOSED_LABEL, repaintTarget.riftsClosedText(),
					repaintTarget.riftsClosed >= 0 ? NativeTooltip.valueColor : TitleTooltip.MUTED_GRAY);
				y += detailMetrics.getHeight() + HEADER_GAP;
			}
			y = paintGrid(g2, entry, section.primary(), i, inset, y, cols, hitBoxes);
			if (i + 1 < entries.size()) y += CardBody.SECTION_SPACE;
		}
		return y;
	}

	private int paintGrid(Graphics2D g2, Entry entry,
		SkillClogSection.PlayerItems playerItems, int sectionIndex,
		int startX, int y, int cols, List<TooltipItemHover.HitBox> hitBoxes)
	{
		List<Integer> itemIds = entry.section.itemIds();
		g2.setFont(DETAIL_FONT);
		hitBoxes.addAll(TooltipItemSprites.paintGrid(g2, entry.sprites, entry.section.itemNames(), sectionIndex,
			itemIds, playerItems.obtainedIds(), playerItems.obtainedCounts(), startX, y, cols, SPRITE_SIZE,
			CELL_SIZE));
		return y + gridHeight(itemIds.size(), cols);
	}

	static String progressText(SkillClogSection.PlayerItems items, int total)
	{
		return items.synced()
			? TitleTooltip.progressCountText(items.obtainedCount(), total)
			: TitleTooltip.progressPlaceholderText(total);
	}

	private static Color progressColor(SkillClogSection.PlayerItems items, int total)
	{
		return items.synced()
			? TitleTooltip.completionColor(items.obtainedCount(), total)
			: TitleTooltip.MUTED_GRAY;
	}

	private static int soloProgressWidth(FontMetrics fm, SkillClogSection section)
	{
		return fm.stringWidth(OBTAINED_LABEL
			+ progressText(section.primary(), section.itemIds().size()));
	}

	private boolean showsRiftsClosed(SkillClogSection section)
	{
		return repaintTarget.showsRiftsClosed() && section.isCategory(PanelData.GOTR_CATEGORY);
	}

	private int soloColumns(int availableWidth, int itemCount)
	{
		int fit = Math.max(SOLO_MIN_COLS, (availableWidth + PADDING) / CELL_SIZE);
		return Math.min(fit, Math.max(itemCount, 1));
	}

	private static int gridWidth(int cols)
	{
		return cols * CELL_SIZE - PADDING;
	}

	private static int gridHeight(int itemCount, int cols)
	{
		int rows = (Math.max(itemCount, 1) + cols - 1) / cols;
		return rows * CELL_SIZE - PADDING;
	}

	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Entry
	{
		private final SkillClogSection section;
		@Nullable
		private final TooltipItemSprites sprites;

	}
}

