package com.killclog;

import java.awt.Color;

final class SkillLevelColor
{
	private SkillLevelColor()
	{
	}

	static Color forCell(int level, boolean synced, int obtained, int total,
		KillClogConfig config)
	{
		if (!synced)
		{
			return Cells.KC_COLOR;
		}
		if (config.skillColorMode() == SkillColorMode.SKILL_COLOR)
		{
			return config.skillLevelColor();
		}
		if (usesClogProgress(config))
		{
			return obtained >= 0 && total > 0
				? ClogHelper.clogColor(obtained, total, config)
				: config.skillLevelColor();
		}
		if (level >= 99)
		{
			return config.completedClogColor();
		}
		return config.skillLevelColor();
	}

	/** Clog Progression needs Skill Clogs on; with them off it reads as the 99+ default. */
	static boolean usesClogProgress(KillClogConfig config)
	{
		return config.enableSkillClogs()
			&& config.skillColorMode() == SkillColorMode.CLOG_PROGRESSION;
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.FontMetrics;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

/** Compact Kill Clog-native stat tooltip for one skill cell. */
public class SkillTooltip extends TitleTooltip
{
	static final String LEVEL_LABEL = "Level: ";
	static final String XP_LABEL = "XP: ";
	static final String RANK_LABEL = "Rank: ";
	static final String XP_TO_LEVEL_LABEL = "XP to Level: ";
	static final String RIFTS_CLOSED_LABEL = "Rifts Closed: ";
	private static final Color UNRANKED_COLOR = new Color(128, 128, 128);

	private Stats stats = Stats.empty();
	private List<SkillClogSection> sections = Collections.emptyList();
	private boolean showRiftsClosed;
	int riftsClosed = -1;
	private final SkillClogSectionRenderer sectionRenderer = new SkillClogSectionRenderer(this);
	// A skill's log scrolls at full size past the height of a long Collection Log tab, a sprite row a notch.
	private final CardBody.Scroll scroll = new CardBody.Scroll(this,
		CardBody.WINDOW, SkillClogSectionRenderer.CELL_SIZE);

	public void setData(Skill skill, @Nullable HiscoreResult result, boolean virtualLevels,
		List<SkillClogSection> sections, @Nullable ItemManager itemManager)
	{
		itemHover.clear();
		setTitle(skill.getName());
		clearTitleSuffix();
		clearSubtitle();
		stats = Stats.from(skill, result, virtualLevels);
		this.sections = sections != null ? sections : Collections.emptyList();
		showRiftsClosed = false;
		riftsClosed = -1;
		sectionRenderer.setSections(this.sections, itemManager);
		if (!this.sections.isEmpty())
		{
			SkillClogSection.Progress progress = SkillClogSection.combinedProgress(
				this.sections);
			String progressText = progress.obtained() >= 0
				? progressCountText(progress.obtained(), progress.total())
				: progressPlaceholderText(progress.total());
			setTitleSuffix(" (" + progressText + ")",
				progress.obtained() >= 0
					? completionColor(progress.obtained(), progress.total()) : MUTED_GRAY);
		}
	}

	public void setRiftsClosed(int riftsClosed)
	{
		showRiftsClosed = true;
		this.riftsClosed = riftsClosed;
	}

	@Override
	protected CardBody body()
	{
		CardBody body = new CardBody()
			.add(CardBody.line(LEVEL_LABEL, stats.levelText(), stats.levelColor()))
			.add(CardBody.line(XP_LABEL, stats.xpText(), stats.xpColor()))
			.add(CardBody.line(RANK_LABEL, stats.rankText(), stats.rankColor()))
			.add(CardBody.line(XP_TO_LEVEL_LABEL, stats.xpToLevelText(), stats.xpToLevelColor()));
		if (sections.isEmpty())
		{
			return body;
		}
		// The skill's clog sections fill the card's width under the band their hovered item is named in.
		return body.add(CardBody.hoverBand())
			.add(CardBody.scroll(scroll, CardBody.part(c -> sectionRenderer.soloSize(Math.max(statsWidth(c.fm), c.available)).width,
				c -> sectionRenderer.soloSize(Math.max(statsWidth(c.fm), c.available)).height,
				(c, y) -> sectionRenderer.paintSolo(c.g, c.w, y, c.hits))));
	}

	private int statsWidth(FontMetrics fm)
	{
		int width = Math.max(rowWidth(fm, LEVEL_LABEL, stats.levelText()), rowWidth(fm, XP_LABEL, stats.xpText()));
		width = Math.max(width, rowWidth(fm, RANK_LABEL, stats.rankText()));
		return Math.max(width, rowWidth(fm, XP_TO_LEVEL_LABEL, stats.xpToLevelText()));
	}

	@Override
	CardBody.Scroll scroll()
	{
		return scroll;
	}

	boolean showsRiftsClosed()
	{
		return showRiftsClosed;
	}

	String riftsClosedText()
	{
		return riftsClosed >= 0 ? grouped(riftsClosed) : "--";
	}

	private static int rowWidth(FontMetrics fm, String label, String value)
	{
		return fm.stringWidth(label) + fm.stringWidth(value);
	}

	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Stats
	{
		private final int level;
		private final long xp;
		private final int rank;
		private final long xpToLevel;
		private final boolean maxed;
		private final boolean rankAvailable;

		static Stats empty()
		{
			return new Stats(-1, -1, -1, -1, false, false);
		}

		static Stats from(Skill skill, @Nullable HiscoreResult result, boolean virtualLevels)
		{
			if (result == null)
			{
				return empty();
			}

			String key = skill.getName().toLowerCase(Locale.ROOT);
			long xp = result.getSkillXp(key);
			int level = ClogHelper.displayLevel(result.getSkillLevel(key), xp, virtualLevels);
			int rank = result.getSkillRank(key);
			int maxLevel = virtualLevels ? Experience.MAX_VIRT_LEVEL : Experience.MAX_REAL_LEVEL;
			boolean maxed = level >= maxLevel && xp >= 0;
			long xpToLevel = level > 0 && xp >= 0 && !maxed
				? Math.max(0L, (long) Experience.getXpForLevel(level + 1) - xp)
				: -1;
			return new Stats(level, xp, rank, xpToLevel, maxed, result.isRankDataAvailable());
		}

		String levelText()
		{
			return level > 0 ? String.valueOf(level) : "--";
		}

		String xpText()
		{
			return xp >= 0 ? grouped(xp) : "--";
		}

		String rankText()
		{
			return rank > 0 ? grouped(rank) : rankAvailable ? "Unranked" : "--";
		}

		String xpToLevelText()
		{
			if (maxed)
			{
				return "Maxed";
			}
			return xpToLevel >= 0 ? grouped(xpToLevel) : "--";
		}

		private Color levelColor()
		{
			return level > 0 ? NativeTooltip.valueColor : UNRANKED_COLOR;
		}

		private Color xpColor()
		{
			return xp >= 0 ? NativeTooltip.valueColor : UNRANKED_COLOR;
		}

		private Color rankColor()
		{
			return rank > 0 ? NativeTooltip.valueColor : UNRANKED_COLOR;
		}

		private Color xpToLevelColor()
		{
			if (maxed)
			{
				return CLOG_GREEN;
			}
			return xpToLevel >= 0 ? NativeTooltip.valueColor : UNRANKED_COLOR;
		}
	}
}

package com.killclog;

import java.awt.Color;
import javax.annotation.Nullable;
import net.runelite.api.Experience;
import net.runelite.client.util.LinkBrowser;

/**
 * Experience &amp; Efficiency on the total level cell: total XP, overall rank and the XP left to max, then Efficient
 * Hours (Dylan, 2026-10-15): Played and Clogged, TempleOSRS's EHP and EHC, when Temple tracks the player, and Bossed,
 * the Combat Summary's EHB, for anyone. Each skill's own numbers live in its cell, in the grid or the activity tray.
 */
public class SkillsTooltip extends TitleTooltip
{
	static final String TITLE = "Experience & Efficiency";
	private static final long MAX_SKILL_XP = Experience.getXpForLevel(Experience.MAX_REAL_LEVEL);
	private static final Color UNRANKED_COLOR = new Color(128, 128, 128);

	private HiscoreResult result;
	private double ehp = -1;
	private double ehc = -1;
	private double ehb = -1;
	// The player's TempleOSRS page, which the Efficient Hours lines open (null when the name isn't known).
	@Nullable
	private String temple;
	private final CardBody.ClickRows hourRows = new CardBody.ClickRows(this, (e, row) ->
	{
		if (temple != null && linkOpens(e))
		{
			LinkBrowser.browse(temple);
			hideTooltipTree(this);
			e.consume();
		}
	});
	private boolean templeRows;

	/** {@code templeRows}: show Temple's rows, "--" where this player has none, so a comparison pair lines up. */
	public void setData(HiscoreResult result, ClogResult clog, boolean templeRows)
	{
		this.result = result;
		ehp = clog != null ? clog.getTempleEhp() : -1;
		ehc = clog != null ? clog.getTempleEhc() : -1;
		ehb = LookupQueries.ehb(result, clog);
		temple = clog != null && clog.getPlayerName() != null ? TooltipItemLink.templeUrl(clog.getPlayerName()) : null;
		this.templeRows = templeRows;
		setTitle(TITLE);
	}

	static boolean onTemple(ClogResult clog)
	{
		return clog != null && (clog.getTempleEhp() >= 0 || clog.getTempleEhc() >= 0);
	}

	@Override
	protected CardBody body()
	{
		long toMax = xpToMax(result);
		CardBody card = new CardBody()
			.add(CardBody.line("XP: ", displayedXpText(),
				result != null && result.getTotalXp() >= 0 ? NativeTooltip.valueColor : UNRANKED_COLOR))
			.add(CardBody.line("Rank: ", scoreText(displayedRank()), displayedRank() > 0 ? NativeTooltip.valueColor : UNRANKED_COLOR))
			.add(CardBody.line("To max: ", toMax == 0 ? "Maxed" : toMax > 0 ? grouped(toMax) : "--",
				toMax == 0 ? CLOG_GREEN : NativeTooltip.valueColor));
		card.titled("Efficient Hours");
		if (templeRows)
		{
			card.add(hours(0, "Played: ", ehp)).add(hours(1, "Clogged: ", ehc));
		}
		return card.add(hours(2, "Bossed: ", ehb));
	}

	private CardBody.Part hours(int row, String label, double value)
	{
		String text = ehbText(value);
		return CardBody.clickRow(hourRows, row, c -> c.fm.stringWidth(label + text), (c, y, hovered) ->
			drawLabelValue(c.g, c.fm, c.inset(), y + c.fm.getAscent(), label, text,
				hovered && temple != null ? NativeTooltip.valueColor : labelColor, NativeTooltip.valueColor));
	}

	/** XP left until every skill is 99: 0 once maxed, -1 when a skill isn't on the hiscores. */
	static long xpToMax(HiscoreResult result)
	{
		if (result == null)
		{
			return -1;
		}
		long left = 0;
		for (String skill : HiscoreService.skillNames())
		{
			long xp = result.getSkillXp(skill);
			if (xp < 0)
			{
				return -1;
			}
			left += Math.max(0, MAX_SKILL_XP - xp);
		}
		return left;
	}

	String displayedXpText()
	{
		long xp = result != null ? result.getTotalXp() : -1;
		return xp >= 0 ? grouped(xp) : "--";
	}

	int displayedRank()
	{
		return result != null ? result.getOverallRank() : -1;
	}
}

package com.killclog;

import java.awt.Color;
import javax.swing.Timer;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;

/**
 * One occupant of the panel status row: who wrote it, how it shares the row,
 * and the expiry that belongs to it. Two messages with the same text are still
 * two messages, so a stale expiry can never clear a newer one.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class StatusMessage
{
	enum Owner
	{
		LOOKUP, BOARD, SYNC, CHARACTER
	}

	enum Kind
	{
		/** A control's hover line; yields to anything and clears when the pointer leaves. */
		HOVER,
		/** An actionable hint; yields to anything and keeps the controls visible while it expires. */
		NOTICE,
		/** Work in flight; holds the row until its owner replaces it. */
		PROGRESS,
		/** An outcome; holds the row until it expires or its owner replaces it. */
		RESULT
	}

	final Owner owner;
	final Kind kind;
	final String text;
	final Color color;
	private Timer expiry;

	/** Hover lines and notices leave the row free for the next writer. */
	boolean yields()
	{
		return kind == Kind.HOVER || kind == Kind.NOTICE;
	}

	/** Runs the action once on the EDT after the delay unless {@link #cancelExpiry} comes first. */
	void expireAfter(int delayMs, Runnable action)
	{
		cancelExpiry();
		expiry = new Timer(delayMs, e -> action.run());
		expiry.setRepeats(false);
		expiry.start();
	}

	void cancelExpiry()
	{
		if (expiry != null)
		{
			expiry.stop();
			expiry = null;
		}
	}
}

package com.killclog;

import com.google.gson.Gson;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The stores' file names and their one way to read, write and list a file. Own logs are account-keyed; 2.4's
 * name-keyed files, which 2.5 to 2.6.5 moved on first start, are left where they are and never read.
 */
@Slf4j
final class StoreFiles
{
	static final String LOOKUPS = "lookups";

	private StoreFiles()
	{
	}

	/** An account's own-log file: its hash as 16 hex digits, longer than any character name. */
	static String ownFileName(String hashKey)
	{
		return String.format("%016x", Long.parseLong(hashKey)) + ".json";
	}

	static void write(Gson gson, Filepath folder, Filepath dest, Object data) throws IOException
	{
		Filepath tmp = folder.createTempFile(".write-", ".tmp");
		try
		{
			// On the disk before it takes the file's place: a power cut then leaves the old log or the new one, never
			// an empty file where a log was.
			ByteBuffer json = ByteBuffer.wrap(gson.toJson(data).getBytes(StandardCharsets.UTF_8));
			try (FileChannel channel = tmp.openFileChannel(StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING))
			{
				while (json.hasRemaining())
				{
					channel.write(json);
				}
				channel.force(true);
			}
			LocalClogCache.atomicMove(tmp, dest);
		}
		finally
		{
			tmp.deleteIfExists();
		}
	}

	static <T> T read(Gson gson, Filepath file, Class<T> type)
	{
		try (BufferedReader reader = file.openBufferedReader())
		{
			return gson.fromJson(reader, type);
		}
		catch (Exception e)
		{
			log.warn("Unreadable Kill Clog file '{}': {}", file.getFileName(), e.getMessage());
			return null;
		}
	}

	/** The files directly in a folder; the store lists its own folder the same way. */
	static List<Filepath> list(Filepath dir) throws IOException
	{
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk.filter(Filepath::isFile).collect(Collectors.toList());
		}
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Font;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import javax.annotation.Nullable;
import net.runelite.client.game.ItemManager;

/**
 * Player summary tooltip on the summary-bar name label.
 * The player's name is the title, in white beside their account badge. Under it stand the
 * prestige cape or a Kill Clog syncer's character, centered, then the account and prestige
 * lines, then the obtained pets at full size. Like the other summaries, only the title and the hover band
 * under it stay put: the rest scrolls as one once it outgrows the window. Hovering a pet names it in that band
 * and left-click opens its wiki page - same contract as the boss grids.
 */
public class SummaryTooltip extends TitleTooltip
{
	private static final int PET_COLS = 5;
	private static final int FIGURE_GAP = 4;
	private static final String PRESTIGE_LABEL = "Prestige: ";
	private static final String FORMER_TITLE = "Player Summary";

	private int overallRank;
	// The prestige cape, or a Kill Clog syncer's character (PlayerPortraits) standing in its place.
	private BufferedImage figure;
	private String accountLabel;
	@Nullable
	private String clan;
	@Nullable
	private BufferedImage clanIcon;
	private String prestige;
	// With a character standing in, the prestige cape sits small in the header's corner and names its prestige.
	@Nullable
	private BufferedImage cape;

	// Pet data only includes obtained pets: the gallery shows what you have,
	// not the empty slots.
	private int totalPetCount;
	private List<Integer> petList;
	private Map<Integer, String> petNames;
	private Map<Integer, Integer> petCounts = Collections.emptyMap();
	@Nullable
	private TooltipItemSprites petSprites;
	// Everything under the band scrolls in the standard window, a sprite row a notch, as a skill's log does.
	private final CardBody.Scroll scroll = new CardBody.Scroll(this, CardBody.WINDOW, CardBody.GRID_CELL);

	public void setData(String rsn, int overallRank, BufferedImage figure,
						BufferedImage badgeIcon, String accountLabel, String prestige)
	{
		itemHover.clear();
		// The panel's own stand-in when a lookup has no name, so the card always keeps its title.
		setTitle(rsn != null ? rsn : "Player");
		setTitleIcon(badgeIcon);
		this.overallRank = overallRank;
		this.figure = withoutHeadroom(figure);
		this.accountLabel = accountLabel;
		this.prestige = prestige;
		rankLine();
	}

	/**
	 * The player's clan, after the rank under the name: the icon their title wears in clan chat, the clan's name in the
	 * band while it's hovered (Dylan, 2026-10-09). Without the icon, the name itself follows the rank.
	 */
	void setClan(@Nullable String clan, @Nullable BufferedImage icon)
	{
		this.clan = clan;
		clanIcon = clan != null ? icon : null;
		setSubtitleIcon(clanIcon);
		rankLine();
	}

	// "#1,200" and the clan's icon under the name, above the title's divider; "#1,200 \u00B7 Clannabis" when the icon
	// can't be drawn. The account type's words show in the band while the name or its badge is hovered.
	private void rankLine()
	{
		String rank = overallRank > 0 ? "#" + grouped(overallRank) : null;
		String line = clanIcon != null ? (rank != null ? rank : "")
			: rank != null && clan != null ? rank + " \u00B7 " + clan : rank != null ? rank : clan;
		if (line != null)
		{
			setSubtitle("", line, NativeTooltip.valueColor);
		}
		else
		{
			clearSubtitle();
		}
	}

	/** A published character's prestige cape, drawn small in the header; null when the cape is the figure. */
	void setCape(@Nullable BufferedImage cape)
	{
		this.cape = cape;
	}

	/** The player's name reads white, like the name it is, not an orange card label. */
	@Override
	protected Color titleColor()
	{
		return NativeTooltip.valueColor;
	}

	/** The player's name at the size the grid cards title in. */
	@Override
	protected Font getTitleFont()
	{
		return TITLE_FONT_SMALL;
	}

	/** The pets held, in the log's order, each with its count for the corner like any item sprite. */
	public void setPets(List<Integer> allPetIds, Map<Integer, Integer> obtainedPetCounts,
		ItemManager itemManager, IntFunction<String> nameLookup)
	{
		this.totalPetCount = allPetIds != null ? allPetIds.size() : 0;
		petCounts = obtainedPetCounts != null ? obtainedPetCounts : Collections.emptyMap();

		petList = new ArrayList<>();
		if (allPetIds != null)
		{
			for (int id : allPetIds)
			{
				if (petCounts.containsKey(id))
				{
					petList.add(id);
				}
			}
		}

		// A pet without a name still hovers and links, under the name its id gives it.
		petNames = new HashMap<>();
		for (int id : petList)
		{
			petNames.put(id, nameLookup != null ? nameLookup.apply(id) : null);
		}
		petSprites = !petList.isEmpty() && itemManager != null
			? TooltipItemSprites.load(petList, petNames, itemManager, id -> 1, this) : null;
	}

	@Override
	CardBody.Scroll scroll()
	{
		return scroll;
	}

	private boolean hasPets()
	{
		return petList != null && !petList.isEmpty();
	}

	/** Without a figure or prestige, nothing stands between the title and the pets. */
	private boolean hasBodyAbovePets()
	{
		return figure != null || prestige != null;
	}

	@Override
	protected CardBody body()
	{
		// The cape or character stands centered under the name; with a character, the cape names its prestige from
		// the header's corner instead of a line under the figure.
		boolean capeInHeader = cape != null && prestige != null;
		CardBody card = new CardBody().add(CardBody.minWidth(c -> getFontMetrics(getTitleFont()).stringWidth(FORMER_TITLE)));
		if (accountLabel != null)
		{
			card.add(CardBody.row(0, c -> 0, (c, y) -> c.hits.add(new TooltipItemHover.HitBox(TooltipItemHover.HEADER_SECTION, 0, accountLabel, titleArea(), true))));
		}
		if (clanIcon != null)
		{
			card.add(CardBody.row(0, c -> 0, (c, y) ->
			{
				if (getSubtitleIconBounds() != null)
				{
					c.hits.add(new TooltipItemHover.HitBox(TooltipItemHover.HEADER_SECTION, 0, clan, getSubtitleIconBounds(), true,
						TooltipItemLink.runeProfileClanUrl(clan)));
				}
			}));
		}
		if (capeInHeader)
		{
			card.add(headerCorner(true, cape, prestige));
		}
		if (figure != null)
		{
			card.add(CardBody.row(figure.getHeight() + FIGURE_GAP, c -> figure.getWidth(),
				(c, y) -> c.g.drawImage(figure, (c.w - figure.getWidth()) / 2, y, null)));
		}
		// Prestige centered under the figure, when the figure is the cape.
		if (prestige != null && !capeInHeader)
		{
			card.add(centered(PRESTIGE_LABEL, prestige));
		}
		if (totalPetCount > 0)
		{
			// A pet's name shows in the band over the pets, straight under the title's divider when nothing stands
			// between, and the pets scroll under it.
			int count = hasPets() ? petList.size() : 0;
			CardBody pets = new CardBody().add(CardBody.line("Pets: ", String.valueOf(count),
				completionColor(count, totalPetCount)));
			if (hasPets())
			{
				pets.add(CardBody.grid(PET_COLS, petSprites, petNames, petList, new HashSet<>(petList), petCounts));
			}
			card.add(hasBodyAbovePets() ? CardBody.hoverBand() : CardBody.headerHoverBand())
				.add(CardBody.scroll(scroll, pets.asPart()));
		}
		else if (capeInHeader)
		{
			card.add(CardBody.hoverBand());
		}
		return card;
	}

	private static CardBody.Part centered(String label, String value)
	{
		return CardBody.row(LINE_HEIGHT, c -> c.fm.stringWidth(label + value), (c, y) -> drawLabelValue(c.g, c.fm,
			(c.w - c.fm.stringWidth(label + value)) / 2, y + c.fm.getAscent(), label, value));
	}

	/**
	 * The figure cut to its first row of pixels: a character's portrait leaves room above the head
	 * for tall hats, which would read as a gap under the name.
	 */
	@Nullable
	static BufferedImage withoutHeadroom(@Nullable BufferedImage image)
	{
		if (image == null)
		{
			return null;
		}
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					return y == 0 ? image : image.getSubimage(0, y, image.getWidth(), image.getHeight() - y);
				}
			}
		}
		return image;
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ThreadLocalRandom;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;

/**
 * Pushes the active player's locally captured collection log to the
 * killclog.com first-party ingest endpoint
 * ({@code POST https://killclog.com/api/player/<rsn>/sync}).
 *
 * <p>Gated behind a default-off config toggle
 * ({@link KillClogConfig#killclogSync()}); nothing is pushed until the
 * player opts in.
 *
 * <p>Scope: only the logged-in account can push, and only its own local
 * store - the log this client has accumulated across its own captures and
 * live unlocks. Publishing your own account's truth is what the opt-in
 * means; other players' data has no path here.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(access = AccessLevel.PACKAGE, onConstructor_ = @Inject)
class SyncService
{
	// Attributed on the server per client build.
	static final String CLIENT_VERSION = "2.7.4";

	private final OkHttpClient httpClient;
	private final Gson gson;
	// The game's Collection Log as this client reads it, shared when killclog.com holds another.
	@Setter
	@Nullable
	private ClogIndex clogIndex;
	// Your clan as the game shows it, for each sync (2.6.3).
	@Setter
	@Nullable
	private volatile PlayerClans clans;
	// The structure killclog.com holds, as its last sync reply named it; null until one has.
	private volatile String serverStructureHash;
	// Every loading screen schedules a push: one identical to the last that killclog.com took, within a day, stays home.
	static final long RESEND_UNCHANGED_MS = 24 * 60 * 60 * 1000L;
	private volatile String acceptedPush;
	private volatile long acceptedAt;
	private volatile SyncResult acceptedResult;
	/** What a push killclog.com already holds answers: nothing went, so nothing is said. */
	static final SyncResult UNCHANGED = new SyncResult(true, false, "");

	/** Outcome of a sync attempt, surfaced for chat feedback. */
	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	static final class SyncResult
	{
		final boolean ok;
		final boolean dryRun;
		final String message;
		/** Server says another sync holds this player's lock: retry, don't fail. */
		final boolean retryAdvised;
		final int retryAfterSeconds;
		/** The server turned this account away for the session (opted out, the name another's, an update needed). */
		final boolean stopsSession;

		SyncResult(boolean ok, boolean dryRun, String message)
		{
			this(ok, dryRun, message, false, 0, false);
		}

		SyncResult(boolean ok, boolean dryRun, String message, boolean retryAdvised, int retryAfterSeconds)
		{
			this(ok, dryRun, message, retryAdvised, retryAfterSeconds, false);
		}

		/** A refusal that holds for the session: automatic pushes stop until the next login or a click. */
		static SyncResult stopping(String message)
		{
			return new SyncResult(false, false, message, false, 0, true);
		}

	}

	/**
	 * Build the ingest body from this client's in-game observations and POST
	 * it. Completes with a failed-shape result rather than throwing.
	 *
	 * @param accountType the locally detected account type (client varbits),
	 *                    never the provider-derived one
	 */
	/**
	 * {@code session} is the login the push was gathered in and {@code cache} the mode's own store; {@code always}
	 * sends even what killclog.com already holds (a click, or a character publish that needs the profile).
	 * {@code sending} runs just before a push goes.
	 */
	CompletableFuture<SyncResult> syncCollectionLog(Session session,
		@Nullable AccountType accountType, Map<String, Double> personalBests,
		Map<String, PbRecord> detailedPersonalBests,
		KillclogSyncGate<?> syncGate, int attempt, LocalClogCache cache, String mode, long hardcoreXp, boolean always,
		Runnable sending)
	{
		String rsn = session.getName();
		long accountHash = session.getAccountHash();
		if (rsn == null || rsn.isBlank())
		{
			return CompletableFuture.completedFuture(
				new SyncResult(false, false, "No player to sync."));
		}

		// Only this session's account, its own log serving, can be the payload: a logout since the gather fences
		// the whole pre-flight inside the cache monitor.
		if (!cache.servesAccount(session))
		{
			return CompletableFuture.completedFuture(new SyncResult(false, false,
				"Still checking this account. Try again in a moment."));
		}

		// The player's own accumulated local store is the payload: months of
		// their in-client captures and live unlocks, published as their own
		// truth - requiring a full re-walk to seed the sync would be needless
		// friction. Only the logged-in account can
		// ever push, and only its own file - filtered to items this client
		// observed first-hand, so provider-cached data (pre-login lookups,
		// cross-character searches) can never launder into first-party proof.
		ClogResult clog = cache.toFirstPartySyncResult(rsn);
		if (clog == null || clog.getObtainedItems().isEmpty())
		{
			// Never read on this PC, or read and empty: say which, and what to do.
			return CompletableFuture.completedFuture(new SyncResult(false, false, clog == null
				? "Open your Collection Log to set up Kill Clog automatically."
				: "Your Collection Log is empty: Kill Clog syncs from your first item."));
		}

		String body = requestBody(accountHash, accountType, clog, personalBests, detailedPersonalBests, mode, hardcoreXp);
		final int observedCount = ClogResult.coverageCount(clog);
		String url = KillClogEndpoint.apiBaseUrl() + "/player/" + HttpUtil.pathSegment(rsn) + "/sync/" + mode;
		String push = url + body;
		if (!always && acceptedResult != null && push.equals(acceptedPush)
			&& System.currentTimeMillis() - acceptedAt < RESEND_UNCHANGED_MS)
		{
			return CompletableFuture.completedFuture(UNCHANGED);
		}
		sending.run();

		log.debug("Syncing collection log for '{}' to {} ({} items)",
			rsn, url, observedCount);
		final int pbCount = personalBests != null ? personalBests.size() : 0;
		String sent = withOverallXp(body, hardcoreXp);
		CompletableFuture<HttpUtil.HttpResult> request = cache.commitIfSessionCurrent(
			session, () -> syncGate.commitIfCurrent(attempt,
				() -> HttpUtil.httpPostJson(httpClient, url, sent, null)));
		if (request == null)
		{
			return CompletableFuture.completedFuture(
				new SyncResult(false, false, "Sync session ended before send."));
		}
		return request.thenApply(r ->
		{
			SyncResult result = outcome(r, rsn, observedCount, pbCount);
			if (result.ok && !result.dryRun)
			{
				acceptedResult = result;
				acceptedAt = System.currentTimeMillis();
				acceptedPush = push;
			}
			return result;
		});
	}

	/**
	 * A Hardcore Worlds push also carries your total XP, the run's highest for killclog.com; it never makes a push new.
	 * {@code hardcoreXp} is the push's own reading, taken as it gathered: the total XP, 0 before the world settles, -1
	 * off Hardcore Worlds.
	 */
	String withOverallXp(String body, long hardcoreXp)
	{
		if (hardcoreXp <= 0)
		{
			return body;
		}
		JsonObject root = gson.fromJson(body, JsonObject.class);
		root.addProperty("overall_xp", hardcoreXp);
		return wire(gson, root);
	}

	/** The text a push sends: the body, and the game's structure on a main-game sync that should carry it. */
	String requestBody(long accountHash, @Nullable AccountType accountType, ClogResult clog,
		Map<String, Double> personalBests, Map<String, PbRecord> detailedPersonalBests, String mode, long hardcoreXp)
	{
		JsonObject root = buildBody(accountHash, accountType, clog, personalBests, detailedPersonalBests, hardcoreXp);
		JsonObject structure = GameMode.MAIN.equals(mode) ? structureToShare() : null;
		if (structure != null)
		{
			root.add("clog_structure", structure);
		}
		return wire(gson, root);
	}

	/**
	 * The body as sent. Gson leaves a null field out by default, and "clan": null is how a sync says you're in no
	 * clan (or Share Clan is off): left out, killclog.com kept the clan it held, since 2.6.3.
	 */
	static String wire(Gson gson, JsonObject root)
	{
		return gson.newBuilder().serializeNulls().create().toJson(root);
	}

	/** The game's structure when killclog.com named a different one in its last reply, else null. */
	@Nullable
	JsonObject structureToShare()
	{
		ClogIndex index = clogIndex;
		String held = serverStructureHash;
		JsonObject structure = index != null && held != null ? ClogStructure.of(index) : null;
		return structure != null && !held.equals(ClogStructure.hash(gson, structure)) ? structure : null;
	}

	/** What one round trip means for the player, in plain words. */
	SyncResult outcome(HttpUtil.HttpResult r, String rsn, int observedCount, int pbCount)
	{
		if (r.code >= 200 && r.code < 300)
		{
			rememberStructureHash(r.body);
			boolean dryRun = responseSaysDryRun(r.body);
			return new SyncResult(true, dryRun,
				"Collection log synced! ("
				+ observedCount + (observedCount == 1 ? " item" : " items")
				+ (pbCount > 0 ? ", " + pbCount + (pbCount == 1 ? " pb" : " pbs") : "")
				+ (dryRun ? ", not saved" : "") + ").");
		}
		// 409 sync_in_flight is contention, not failure: another client of
		// this account holds the per-player lock for a moment. Advise a
		// short retry instead of booking a failure. The retry says so itself
		// ("retrying..."), so these words only show once it is spent.
		if (r.code == 409 && r.body != null && r.body.contains("sync_in_flight"))
		{
			return new SyncResult(false, false,
				"Another sync for this account is in flight. Try again in a moment.",
				true, parseRetryAfterSeconds(r.body));
		}
		// The server's identity arbitration answers (2026-08-16 wire
		// contract): each gets plain words instead of a bare HTTP code.
		if (r.code == 409 && r.body != null && r.body.contains("name_active_with_another_account"))
		{
			return SyncResult.stopping(
				"This name's previous owner played recently - Kill Clog will "
				+ "accept your log after their continuity window passes.");
		}
		if (r.code == 409 && r.body != null && r.body.contains("account_hash_mismatch"))
		{
			return SyncResult.stopping("This name is registered to a different account on Kill Clog.");
		}
		// The server no longer takes this version's syncs (a League cutover): only an update helps.
		if (r.code == 426)
		{
			return SyncResult.stopping(FirstPartyFeedback.UPDATE_REQUIRED);
		}
		if (r.code == 451)
		{
			return SyncResult.stopping("This account has opted out of Kill Clog sync.");
		}
		log.debug("killclog sync failed for '{}': HTTP {}", rsn, r.code);
		// A restarting server answers 502 to 504 for a few seconds: worth one
		// quiet retry before anyone is told. The delay is spread out so the
		// clients it turned away do not all come back together.
		boolean restarting = r.code >= 502 && r.code <= 504;
		return new SyncResult(false, false,
			"Collection log sync failed. Try again later.",
			restarting, restarting ? 15 + ThreadLocalRandom.current().nextInt(16) : 0);
	}

	private int parseRetryAfterSeconds(String body)
	{
		try
		{
			JsonObject obj = gson.fromJson(body, JsonObject.class);
			if (obj != null && obj.has("retry_after_seconds"))
			{
				int seconds = obj.get("retry_after_seconds").getAsInt();
				// Bounded: the server advises, the client decides.
				return Math.max(1, Math.min(seconds, 30));
			}
		}
		catch (RuntimeException e)
		{
			// fall through to the default
		}
		return 2;
	}

	private void rememberStructureHash(String body)
	{
		try
		{
			JsonObject obj = body != null ? gson.fromJson(body, JsonObject.class) : null;
			if (obj != null && obj.has("clog_structure_hash") && obj.get("clog_structure_hash").isJsonPrimitive())
			{
				serverStructureHash = obj.get("clog_structure_hash").getAsString();
			}
		}
		catch (RuntimeException e)
		{
			// a reply without it changes nothing
		}
	}

	private boolean responseSaysDryRun(String body)
	{
		if (body == null || body.isEmpty())
		{
			return false;
		}
		try
		{
			JsonObject obj = gson.fromJson(body, JsonObject.class);
			return obj != null && obj.has("dry_run") && obj.get("dry_run").getAsBoolean();
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	/**
	 * Request body per the ingest contract:
	 * {@code { account_hash, account_type?, clog: [{item_id, quantity, categories[], obtained_at?}], client_version }}.
	 * Items in multiple categories merge to one entry; sorted by item id so
	 * identical stores produce identical payloads.
	 */
	private JsonObject buildBody(long accountHash, @Nullable AccountType accountType,
		ClogResult clog, Map<String, Double> personalBests,
		Map<String, PbRecord> detailedPersonalBests, long hardcoreXp)
	{
		JsonObject root = new JsonObject();
		root.addProperty("account_hash", Long.toString(accountHash));
		if (accountType != null)
		{
			root.addProperty("account_type", accountType.name().toLowerCase(Locale.ROOT));
		}
		// The game's own unique counters (varp-sourced) ride along so the
		// site can show the true "obtained out of how many" fraction instead
		// of approximating the denominator from catalogs.
		if (clog.getUniqueObtained() > 0)
		{
			root.addProperty("unique_obtained", clog.getUniqueObtained());
		}
		if (clog.getUniqueTotal() > 0)
		{
			root.addProperty("unique_total", clog.getUniqueTotal());
		}
		// PBs are the sync's defining cargo: RuneLite records them locally per
		// profile and no public provider serves them. Raw seconds; the site
		// owns formatting.
		if (personalBests != null && !personalBests.isEmpty())
		{
			JsonObject pbs = new JsonObject();
			for (Map.Entry<String, Double> entry : new TreeMap<>(personalBests).entrySet())
			{
				pbs.addProperty(entry.getKey(), entry.getValue());
			}
			root.add("pbs", pbs);
		}

		// Ladder cargo: the same bests keyed by vanilla's variant key with
		// team sizes SPLIT ("chambers of xeric solo" vs "... 5 players").
		// The collapsed map above stays for display compatibility; ladders
		// need the split because solo and team runs rank separately. Each
		// entry carries where this client observed it: "store" from
		// RuneLite's own pb store, "advlog" from the Counters scroll harvest,
		// "clog" from the collection log's line, "live" from a kill seen.
		if (detailedPersonalBests != null && !detailedPersonalBests.isEmpty())
		{
			JsonObject detailed = new JsonObject();
			for (Map.Entry<String, PbRecord> entry : new TreeMap<>(detailedPersonalBests).entrySet())
			{
				JsonObject record = new JsonObject();
				PbRecord pb = entry.getValue();
				record.addProperty("seconds", pb.seconds);
				record.addProperty("source", pb.source.wire());
				if (pb.team != null) record.addProperty("team", pb.team);
				if (pb.scale != null) record.addProperty("scale", pb.scale);
				if (pb.timer != null) record.addProperty("timer", pb.timer);
				if (pb.kc != null) record.addProperty("kc", pb.kc);
				detailed.add(entry.getKey(), record);
			}
			root.add("pbs_detailed", detailed);
		}

		Map<Integer, ItemEntry> byId = new TreeMap<>();
		for (Map.Entry<String, List<ClogResult.ClogItem>> categoryEntry
			: clog.getObtainedItems().entrySet())
		{
			String category = categoryEntry.getKey();
			for (ClogResult.ClogItem item : categoryEntry.getValue())
			{
				ItemEntry entry = byId.computeIfAbsent(item.getId(),
					id -> new ItemEntry(id, item.getCount()));
				entry.quantity = Math.max(entry.quantity, item.getCount());
				String date = ClogDates.iso(item.getDate());
				if (date != null && (entry.obtainedAt == null || date.compareTo(entry.obtainedAt) < 0))
				{
					entry.obtainedAt = date;
				}
				if (!entry.categories.contains(category))
				{
					entry.categories.add(category);
				}
			}
		}

		JsonArray items = new JsonArray();
		for (ItemEntry entry : byId.values())
		{
			JsonObject obj = new JsonObject();
			obj.addProperty("item_id", entry.id);
			obj.addProperty("quantity", Math.max(entry.quantity, 1));
			if (entry.obtainedAt != null) obj.addProperty("obtained_at", entry.obtainedAt);
			JsonArray cats = new JsonArray();
			for (String category : new TreeSet<>(entry.categories))
			{
				cats.add(category);
			}
			obj.add("categories", cats);
			items.add(obj);
		}
		root.add("clog", items);
		root.addProperty("client_version", CLIENT_VERSION);
		// A Hardcore Worlds character says so, with the reset its log started from: killclog.com starts its run over.
		if (hardcoreXp >= 0)
		{
			root.addProperty("world", "hardcore");
			root.addProperty("run_started_at", clog.getRunStartedAt());
			if (clog.getRunStartXp() > 0)
			{
				root.addProperty("run_start_xp", clog.getRunStartXp());
			}
		}
		// Your clan and title, or null for none; left out until the game has said, so killclog.com keeps what it holds.
		PlayerClans.Yours you = clans != null ? clans.forSync(clog.getPlayerName()) : null;
		if (you != null)
		{
			JsonObject clan = null;
			if (you.clan != null)
			{
				clan = new JsonObject();
				clan.addProperty("name", you.clan);
				if (you.title != null)
				{
					clan.addProperty("title_id", you.title.getId());
					clan.addProperty("title", you.title.getName());
				}
			}
			root.add("clan", clan != null ? clan : JsonNull.INSTANCE);
		}
		return root;
	}


	private static final class ItemEntry
	{
		final int id;
		int quantity;
		String obtainedAt;
		final List<String> categories = new ArrayList<>();

		ItemEntry(int id, int quantity)
		{
			this.id = id;
			this.quantity = Math.max(quantity, 1);
		}
	}
}

package com.killclog;

import net.runelite.client.config.ConfigManager;

/**
 * Sync and its two followers, Automatic sync and Publish Character Model. RuneLite can't gray a setting out,
 * so the dependency is kept at the data: the followers read off while Sync is off, and turn on with it.
 */
final class SyncSettings
{
	private final KillClogConfig config;
	private final ConfigManager configManager;

	SyncSettings(KillClogConfig config, ConfigManager configManager)
	{
		this.config = config;
		this.configManager = configManager;
	}

	/** At startup and whenever a follower changes: one ticked while Sync is off doesn't stay ticked. */
	void enforce()
	{
		if (!config.killclogSync())
		{
			if (config.automaticSync())
			{
				configManager.setConfiguration("killclog", "automaticSync", false);
			}
			if (config.characterModel())
			{
				configManager.unsetConfiguration("killclog", "characterModel");
			}
		}
	}

	/** Turning Sync on turns its followers on with it. */
	void syncTurnedOn()
	{
		configManager.unsetConfiguration("killclog", "automaticSync");
		configManager.setConfiguration("killclog", "characterModel", true);
	}
}

package com.killclog;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import javax.annotation.Nullable;

/**
 * What Kill Clog reads from TempleOSRS: one player's stats answer (player_stats.php's data) for their account type,
 * name and EHP, and the collection log answer's EHC. A figure Temple didn't send reads -1.
 */
final class TempleStats
{
	/** A mode other than regular, or a group ironman by its group; null when Temple says regular or nothing. */
	@Nullable
	final AccountType accountType;
	@Nullable
	final String canonicalName;
	/** Temple's EHP for the account's own mode. */
	final double ehp;

	TempleStats(JsonObject data)
	{
		JsonElement infoElement = data.get("info");
		JsonObject info = infoElement != null && infoElement.isJsonObject()
			? infoElement.getAsJsonObject() : new JsonObject();
		AccountType mode = AccountType.fromTempleGameMode(text(info, "Game mode"));
		accountType = mode != null && mode != AccountType.REGULAR ? mode
			: number(info, "GIM") > 0 ? AccountType.GROUP_IRONMAN : null;
		canonicalName = text(info, "player_name_with_capitalization");
		ehp = number(data, "Overall_ehp");
	}

	/** The collection log answer's EHC for the account's flavour: an ironman's own rates, or the main game's. */
	static double ehc(JsonObject clogData, @Nullable AccountType type)
	{
		return number(clogData, type != null && type != AccountType.REGULAR ? "ehc_im" : "ehc");
	}

	@Nullable
	private static String text(JsonObject object, String key)
	{
		JsonElement value = object.get(key);
		return value != null && value.isJsonPrimitive() ? value.getAsString() : null;
	}

	private static double number(JsonObject object, String key)
	{
		try
		{
			return Math.max(-1, Double.parseDouble(text(object, key)));
		}
		catch (NumberFormatException | NullPointerException e)
		{
			return -1;
		}
	}
}

