/**
 * Manages tooltip display mechanics: pinned popups, cell hover effects,
 * and component-scoped ToolTipManager registration.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
class TooltipController
{
	static final Border CELL_BORDER = new EmptyBorder(1, 1, 1, 1);
	// A grey-text cell's outline lifts the cell's own background toward white: RuneLite's grey 30 becomes 90.
	private static final double OUTLINE_TINT = 60 / 225.0;
	// Tint lifts a hovered cell's own background this far toward white: RuneLite's grey 30 becomes 41, a green 39 becomes 50.
	private static final double HOVER_TINT = 0.05;

	private final KillClogConfig config;

	// Stable popup state. Click mode opens this directly; hover mode promotes its
	// transient preview into the same popup when the source is pressed.
	private Popup activePinnedPopup;
	private JToolTip activePinnedTip;
	private JComponent activePinnedComponent;
	private JPanel activePinnedCell;
	private boolean pinnedFromHover;
	private JComponent suppressedTooltipComponent;
	private String suppressedTooltipText;
	private AWTEventListener pinDismissListener;
	private JComponent pinDismissedComponent;
	private Window focusWindow;
	private WindowAdapter windowFocusListener;

	// Cell hover state. Only the panel's own cells take the outline; a card pinned under another
	// surface, like the info row the Collection Log card opens from, leaves that surface as it is.
	private JPanel hoveredCell;
	// The hovered cell's own background, which it gets back when the pointer leaves.
	private Color hoveredRest;
	private final Set<JPanel> hoverCells = Collections.newSetFromMap(new WeakHashMap<>());
	private Timer hoverExitTimer;
	// While the panel autoscrolls, cells pass under a still pointer: no hover tint and no hover card until it ends.
	private boolean hoverSuspended;

	// ToolTipManager is shared by every RuneLite plugin. Track only Kill Clog's
	// components so click mode never changes another plugin's tooltip behavior.
	private final Set<JComponent> tooltipComponents =
		Collections.newSetFromMap(new WeakHashMap<>());

	// A shift-press opens a card and copies it as a picture, ready to paste (Dylan, 2026-10-20): where it goes, and
	// who says whether it went.
	@Setter(AccessLevel.PACKAGE)
	private Predicate<BufferedImage> clipboard = TooltipController::toClipboard;
	@Setter(AccessLevel.PACKAGE)
	private Consumer<Boolean> cardCopied = copied ->
	{
	};
	// A look every 200 ms; unchanged for two in a row (400 ms) means drawn, and 2.5 s copies whatever shows.
	private static final int COPY_LOOK_MS = 200;
	private static final int COPY_QUIET_LOOKS = 2;
	private static final int COPY_WAIT_MS = 2500;
	private Timer copyTimer;

	/**
	 * Wire hover effect onto a cell panel.
	 * Shows outline or tint on hover, handles click-to-reveal.
	 * 150ms debounced exit keeps the effect while tooltip is open.
	 */
	void addCellHoverEffect(JPanel cell, JLabel label)
	{
		addCellHoverEffect(cell, label, label);
	}

	/**
	 * Row-shaped variant: the hover outline follows {@code colorSource}'s
	 * foreground while the cell and every listed surface accept hover and
	 * click. The pinned tooltip comes from the pressed surface when it carries
	 * one, else from the first surface (which also keeps the popup anchor
	 * stable for presses on the bare cell).
	 */
	void addCellHoverEffect(JPanel cell, JLabel colorSource, JLabel... surfaces)
	{
		MouseAdapter hoverAdapter = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				JLabel source = e.getSource() instanceof JLabel
					&& ((JLabel) e.getSource()).getToolTipText() != null
					? (JLabel) e.getSource() : surfaces[0];
				if (source.getToolTipText() != null)
				{
					pinTooltipFromPress(source, cell, e);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (hoverExitTimer != null) hoverExitTimer.stop();
				hoverCell(cell, colorSource);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (hoverExitTimer != null) hoverExitTimer.stop();
				hoverExitTimer = new Timer(150, evt ->
				{
					if (hoveredCell == cell
						&& !(pinnedFromHover && activePinnedCell == cell))
					{
						resetCellHover();
						hoveredCell = null;
					}
				});
				hoverExitTimer.setRepeats(false);
				hoverExitTimer.start();
			}
		};
		hoverCells.add(cell);
		cell.addMouseListener(hoverAdapter);
		for (JLabel surface : surfaces)
		{
			surface.addMouseListener(hoverAdapter);
			trackTooltipComponent(surface);
		}
	}

	void trackTooltipComponent(JComponent component)
	{
		if (tooltipComponents.add(component))
		{
			component.addPropertyChangeListener("ToolTipText", event ->
				SwingUtilities.invokeLater(() -> applyTooltipMode(component)));
		}
		applyTooltipMode(component);
	}

	/**
	 * Update a tracked tooltip and immediately reapply this controller's
	 * registration rule. Swing otherwise re-registers null-to-value changes
	 * even while another tooltip is pinned.
	 */
	void setTooltipText(JComponent component, String tooltipText)
	{
		component.setToolTipText(tooltipText);
		applyTooltipMode(component);
	}

	void onTooltipModeChanged()
	{
		hideTransientTooltipState();
		refreshTooltipRegistrations();
	}

	void resetCellHover()
	{
		if (hoveredCell != null)
		{
			hoveredCell.setBorder(CELL_BORDER);
			hoveredCell.setBackground(hoveredRest);
		}
	}

	/**
	 * Wire mouse + hierarchy listeners on a tooltip to clear the parent cell's hover
	 * when the tooltip hides. Listeners attach to the tooltip and its children
	 * (a side-by-side comparison tooltip hosts two live child tooltips), and the
	 * exit handler checks position so crossing between the composite and a child
	 * never reads as leaving the tooltip.
	 */
	void keepTooltipOnHover(JToolTip tip, JPanel parentCell)
	{
		attachToTipTree(tip, new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (hoverExitTimer != null) hoverExitTimer.stop();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Guard against the WHOLE tooltip: a child card's exit while
				// crossing into its sibling must not read as leaving.
				if (((JToolTip) NativeTooltip.tooltipRoot(tip)).getMousePosition(true) != null)
				{
					return;
				}
				clearCellHover(parentCell);
			}
		});
		tip.addHierarchyListener(e ->
		{
			if ((e.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0 && !tip.isShowing())
			{
				clearCellHover(parentCell);
			}
		});
	}

	private static void attachToTipTree(JToolTip tip, MouseListener listener)
	{
		tip.addMouseListener(listener);
		for (Component child : tip.getComponents())
		{
			child.addMouseListener(listener);
		}
	}

	/**
	 * A press on anything in the panel that opens a card: the left button opens it (with shift, copies it too), the
	 * right one offers both, and the middle one scrolls the panel ({@link PanelAutoscroll}).
	 */
	void pinTooltipFromPress(JComponent source, JPanel cell, MouseEvent event)
	{
		if (SwingUtilities.isMiddleMouseButton(event))
		{
			return;
		}
		if (SwingUtilities.isRightMouseButton(event))
		{
			cardMenu(source, cell, event).show(event.getComponent(), event.getX(), event.getY());
			return;
		}
		openFromPress(source, cell, event, event.isShiftDown());
	}

	/** The right button's menu: what a click and a shift-click do, named. */
	JPopupMenu cardMenu(JComponent source, JPanel cell, MouseEvent press)
	{
		JPopupMenu menu = new JPopupMenu();
		JMenuItem open = new JMenuItem("Open");
		open.addActionListener(a -> openFromPress(source, cell, press, false));
		JMenuItem copy = new JMenuItem("Copy (Shift+Click)");
		copy.addActionListener(a -> openFromPress(source, cell, press, true));
		menu.add(open);
		menu.add(copy);
		return menu;
	}

	private void openFromPress(JComponent source, JPanel cell, MouseEvent event, boolean copy)
	{
		if (config.tooltipMode() == TooltipMode.HOVER)
		{
			dismissHoverPreview(event);
		}
		showPinnedTooltip(source, cell);
		if (copy)
		{
			copyPinned(source);
		}
	}

	/** Opens a card where the owner's card was, with a back line that reopens the owner's own card. */
	void openInPlace(JLabel owner, MouseEvent press, JToolTip card, String backLabel)
	{
		pinTooltipFromPress(owner, (JPanel) owner.getParent(), press, TitleTooltip.withBack(card, backLabel, back ->
			pinTooltipFromPress(owner, (JPanel) owner.getParent(), back, owner.createToolTip())));
	}

	/**
	 * A press inside one modal that opens another in its place, the way a rare
	 * row opens its collection from the Clue Summary. The hover preview is a
	 * window of its own and has to be taken down like any other press does, and
	 * the cell keeps the outline that modal's closing just cleared.
	 */
	void pinTooltipFromPress(JComponent source, JPanel cell, MouseEvent event, JToolTip tip)
	{
		if (config.tooltipMode() == TooltipMode.HOVER)
		{
			dismissHoverPreview(event);
		}
		pinTooltip(source, cell, tip);
		if (hoverCells.contains(cell))
		{
			hoverCell(cell, source);
		}
		if (event.isShiftDown())
		{
			copyPinned(source);
		}
	}

	/**
	 * Copies the card the source just opened, once it has finished drawing: a card's item pictures load as it first
	 * draws, so the copy waits until none is still on its way and the card has looked the same for
	 * {@link #COPY_QUIET_LOOKS} looks in a row, at most {@link #COPY_WAIT_MS}. A card closed first is not copied.
	 */
	private void copyPinned(JComponent source)
	{
		JToolTip tip = activePinnedTip;
		if (activePinnedComponent != source || tip == null)
		{
			return;
		}
		stopCopy();
		long until = System.currentTimeMillis() + COPY_WAIT_MS;
		BufferedImage[] last = new BufferedImage[1];
		int[] same = new int[1];
		copyTimer = new Timer(COPY_LOOK_MS, e ->
		{
			if (activePinnedTip != tip)
			{
				stopCopy();
				return;
			}
			BufferedImage now = cardImage(tip);
			same[0] = !TooltipItemSprites.loading(tip) && last[0] != null && samePicture(last[0], now) ? same[0] + 1 : 0;
			if (same[0] >= COPY_QUIET_LOOKS || System.currentTimeMillis() >= until)
			{
				stopCopy();
				cardCopied.accept(clipboard.test(now));
			}
			last[0] = now;
		});
		copyTimer.setInitialDelay(0);
		copyTimer.start();
	}

	private void stopCopy()
	{
		if (copyTimer != null)
		{
			copyTimer.stop();
			copyTimer = null;
		}
	}

	private static boolean samePicture(BufferedImage a, BufferedImage b)
	{
		int w = a.getWidth();
		int h = a.getHeight();
		return w == b.getWidth() && h == b.getHeight()
			&& Arrays.equals(a.getRGB(0, 0, w, h, null, 0, w), b.getRGB(0, 0, w, h, null, 0, w));
	}

	/**
	 * The card exactly as it opened, the way the lab draws one: before the pointer is on it. A card that scrolls, or a
	 * comparison's cards that do, is drawn whole at its full height, then laid back down at its own size, so the one
	 * on screen keeps its rows where they show.
	 */
	static BufferedImage cardImage(JToolTip tip)
	{
		List<CardBody.Scroll> scrolls = new ArrayList<>();
		for (Component card : tip instanceof SideBySideTooltip ? tip.getComponents() : new Component[]{tip})
		{
			CardBody.Scroll scroll = card instanceof TitleTooltip ? ((TitleTooltip) card).scroll() : null;
			if (scroll != null)
			{
				scrolls.add(scroll);
			}
		}
		if (scrolls.isEmpty())
		{
			return drawn(tip);
		}
		Dimension shown = tip.getSize();
		try
		{
			return unrolled(scrolls, 0, () ->
			{
				tip.setSize(tip.getPreferredSize());
				tip.doLayout();
				return drawn(tip);
			});
		}
		finally
		{
			tip.setSize(shown);
			tip.doLayout();
			if (shown.width > 0 && shown.height > 0)
			{
				drawn(tip);
			}
		}
	}

	private static BufferedImage unrolled(List<CardBody.Scroll> scrolls, int from, Supplier<BufferedImage> draw)
	{
		return from == scrolls.size() ? draw.get() : scrolls.get(from).unrolled(() -> unrolled(scrolls, from + 1, draw));
	}

	private static BufferedImage drawn(JToolTip tip)
	{
		if (tip.getWidth() <= 0 || tip.getHeight() <= 0)
		{
			tip.setSize(tip.getPreferredSize());
			tip.doLayout();
		}
		BufferedImage image = new BufferedImage(Math.max(1, tip.getWidth()), Math.max(1, tip.getHeight()),
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		tip.paint(g);
		g.dispose();
		return image;
	}

	private static boolean toClipboard(BufferedImage image)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new Transferable()
			{
				@Override
				public DataFlavor[] getTransferDataFlavors()
				{
					return new DataFlavor[]{DataFlavor.imageFlavor};
				}

				@Override
				public boolean isDataFlavorSupported(DataFlavor flavor)
				{
					return DataFlavor.imageFlavor.equals(flavor);
				}

				@Override
				public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
				{
					if (!isDataFlavorSupported(flavor))
					{
						throw new UnsupportedFlavorException(flavor);
					}
					return image;
				}
			}, null);
			return true;
		}
		catch (IllegalStateException | HeadlessException e)
		{
			// Another program holds the clipboard, or there is no desktop to hold one.
			return false;
		}
	}

	private void hoverCell(JPanel cell, JComponent colorSource)
	{
		if (hoveredCell == cell || hoverSuspended) return;

		if (hoveredCell != null) resetCellHover();

		hoveredCell = cell;
		hoveredRest = cell.getBackground();
		switch (config.hoverStyle())
		{
			case OUTLINE:
				Color fg = colorSource.getForeground();
				Color outline = (fg.equals(Cells.KC_COLOR) || fg.equals(ColorScheme.LIGHT_GRAY_COLOR))
					? ColorUtil.colorLerp(hoveredRest, Color.WHITE, OUTLINE_TINT) : fg;
				cell.setBorder(new MatteBorder(1, 1, 1, 1, outline));
				break;
			case TINT:
				cell.setBackground(ColorUtil.colorLerp(hoveredRest, Color.WHITE, HOVER_TINT));
				break;
			case NONE:
				break;
		}
	}

	void dismissHoverPreview(MouseEvent event)
	{
		ToolTipManager.sharedInstance().mousePressed(event);
	}

	/** Pin the tooltip for any component with tooltip text (labels included). */
	void showPinnedTooltip(JComponent source, JPanel cell)
	{
		// The global listener dismissed this component on the same click; treat it as toggle-off.
		if (source == pinDismissedComponent)
		{
			pinDismissedComponent = null;
			return;
		}
		pinTooltip(source, cell, source.createToolTip());
	}

	/**
	 * Pin a specific modal on a cell: how one modal opens another in its place.
	 * It skips the toggle-off check above, because the press that asked for this
	 * is the same press that just dismissed the modal it came from.
	 */
	void pinTooltip(JComponent source, JPanel cell, JToolTip tip)
	{
		// A row pressed in a preview that outlived its panel has nowhere to open.
		if (!source.isShowing())
		{
			return;
		}
		pinDismissedComponent = null;

		hidePinnedTooltip();

		String tooltipText = source.getToolTipText();
		tip.setTipText(tooltipText);
		guardPinnedTooltip(tip);

		Dimension tipSize = tip.getPreferredSize();

		Point sourceLoc = source.getLocationOnScreen();
		Point cellLoc = cell.getLocationOnScreen();
		Rectangle screen = cell.getGraphicsConfiguration().getBounds();

		int x = sourceLoc.x;
		int y = cellLoc.y + cell.getHeight();

		if (x + tipSize.width > screen.x + screen.width)
		{
			x = screen.x + screen.width - tipSize.width;
		}
		if (y + tipSize.height > screen.y + screen.height)
		{
			y = cellLoc.y - tipSize.height;
		}
		// Wide side-by-side tooltips must stay reachable: clamp the top and
		// left edges too, like the hover path does.
		x = Math.max(x, screen.x);
		y = Math.max(y, screen.y);

		activePinnedPopup = PopupFactory.getSharedInstance().getPopup(cell, tip, x, y);
		activePinnedTip = tip;
		activePinnedComponent = source;
		activePinnedCell = cell;
		pinnedFromHover = config.tooltipMode() == TooltipMode.HOVER;
		suppressPinnedSourceTooltip(source, tooltipText);
		activePinnedPopup.show();
		refreshTooltipRegistrations();

		pinDismissListener = event ->
		{
			if (event.getID() == MouseEvent.MOUSE_PRESSED)
			{
				if (onCardRail((MouseEvent) event))
				{
					return;
				}
				JComponent dismissedComponent = activePinnedComponent;
				pinDismissedComponent = dismissedComponent;
				hidePinnedTooltip();
				SwingUtilities.invokeLater(() ->
				{
					if (pinDismissedComponent == dismissedComponent)
					{
						pinDismissedComponent = null;
					}
				});
			}
			else if (event.getID() == KeyEvent.KEY_PRESSED
				&& ((KeyEvent) event).getKeyCode() == KeyEvent.VK_ESCAPE)
			{
				pinDismissedComponent = null;
				hidePinnedTooltip();
			}
		};
		Toolkit.getDefaultToolkit().addAWTEventListener(
			pinDismissListener, AWTEvent.MOUSE_EVENT_MASK | AWTEvent.KEY_EVENT_MASK);
	}

	/** A press on a card's own scroll rail scrolls it, and the card stays. */
	static boolean onCardRail(MouseEvent press)
	{
		Component source = press.getComponent();
		Component card = source instanceof TitleTooltip ? source
			: SwingUtilities.getAncestorOfClass(TitleTooltip.class, source);
		return card != null && CardBody.onRail(card, SwingUtilities.convertPoint(source, press.getPoint(), card));
	}

	void hidePinnedTooltip()
	{
		JPanel pinnedCell = activePinnedCell;
		boolean clearPinnedHover = pinnedFromHover;
		boolean hadPopup = activePinnedPopup != null;

		if (pinDismissListener != null)
		{
			Toolkit.getDefaultToolkit().removeAWTEventListener(pinDismissListener);
			pinDismissListener = null;
		}
		if (activePinnedPopup != null)
		{
			activePinnedPopup.hide();
			activePinnedPopup = null;
		}
		activePinnedTip = null;
		activePinnedComponent = null;
		activePinnedCell = null;
		pinnedFromHover = false;
		restorePinnedSourceTooltip();

		if (hadPopup)
		{
			refreshTooltipRegistrations();
		}
		if (clearPinnedHover && pinnedCell != null)
		{
			clearCellHover(pinnedCell);
		}
	}

	/** Dismiss only when a refresh is replacing the pinned tooltip's own source. */
	void hidePinnedTooltipIfOwnedBy(JComponent source)
	{
		if (activePinnedComponent == source)
		{
			hidePinnedTooltip();
		}
	}

	void guardPinnedTooltip(JToolTip tip)
	{
		attachToTipTree(tip, new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				dismissHoverPreview(event);
			}
		});
	}

	void suppressPinnedSourceTooltip(JComponent component, String tooltipText)
	{
		suppressedTooltipComponent = component;
		suppressedTooltipText = tooltipText;
		setTooltipText(component, null);
	}

	void restorePinnedSourceTooltip()
	{
		JComponent component = suppressedTooltipComponent;
		String tooltipText = suppressedTooltipText;
		suppressedTooltipComponent = null;
		suppressedTooltipText = null;
		if (component != null && component.getToolTipText() == null)
		{
			setTooltipText(component, tooltipText);
		}
	}

	void activate(Component owner)
	{
		onTooltipModeChanged();
		installWindowFocusListener(owner);
	}

	void deactivate()
	{
		hideTransientTooltipState();
		uninstallWindowFocusListener();
	}

	void clearHoveredCell()
	{
		if (hoverExitTimer != null)
		{
			hoverExitTimer.stop();
			hoverExitTimer = null;
		}
		resetCellHover();
		hoveredCell = null;
	}

	private void clearCellHover(JPanel cell)
	{
		if (hoveredCell == cell)
		{
			if (pinnedFromHover && activePinnedCell == cell)
			{
				return;
			}
			Point mouse = cell.getMousePosition();
			if (mouse != null)
			{
				return;
			}
			resetCellHover();
			hoveredCell = null;
		}
	}

	private void applyTooltipMode(JComponent component)
	{
		ToolTipManager manager = ToolTipManager.sharedInstance();
		boolean registered = false;
		for (MouseListener listener : component.getMouseListeners())
		{
			if (listener == manager)
			{
				registered = true;
				break;
			}
		}

		boolean shouldRegister = config.tooltipMode() == TooltipMode.HOVER
			&& !hasPinnedTooltip()
			&& !hoverSuspended
			&& component.getToolTipText() != null;
		if (shouldRegister && !registered)
		{
			manager.registerComponent(component);
		}
		else if (!shouldRegister && registered)
		{
			manager.unregisterComponent(component);
		}
		if (!shouldRegister)
		{
			// Hovering adds the manager itself as a motion listener, and neither its unregister nor a press removes
			// it; that listener alone restarts the hover timer, so a cell clicked earlier opened a second card over
			// a pinned one whenever the mouse crossed it.
			component.removeMouseMotionListener(manager);
		}
	}

	/** Autoscroll began: the hover card the press found goes, and hovering waits until {@link #resumeHover}. */
	void suspendHover(MouseEvent press)
	{
		dismissHoverPreview(press);
		hoverSuspended = true;
		clearHoveredCell();
		refreshTooltipRegistrations();
	}

	void resumeHover()
	{
		hoverSuspended = false;
		refreshTooltipRegistrations();
	}

	boolean hasPinnedTooltip()
	{
		return activePinnedPopup != null;
	}

	private void refreshTooltipRegistrations()
	{
		for (JComponent component : new ArrayList<>(tooltipComponents))
		{
			applyTooltipMode(component);
		}
	}

	private void installWindowFocusListener(Component owner)
	{
		if (owner == null)
		{
			return;
		}
		Window window = SwingUtilities.getWindowAncestor(owner);
		if (window == null)
		{
			return;
		}
		if (focusWindow == window && windowFocusListener != null)
		{
			return;
		}
		uninstallWindowFocusListener();
		focusWindow = window;
		windowFocusListener = new WindowAdapter()
		{
			@Override
			public void windowLostFocus(WindowEvent e)
			{
				hideTransientTooltipState();
			}
		};
		window.addWindowFocusListener(windowFocusListener);
	}

	private void uninstallWindowFocusListener()
	{
		if (focusWindow != null && windowFocusListener != null)
		{
			focusWindow.removeWindowFocusListener(windowFocusListener);
		}
		focusWindow = null;
		windowFocusListener = null;
	}

	private void hideTransientTooltipState()
	{
		hidePinnedTooltip();
		clearHoveredCell();
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Builder;

/** Immutable data holder for sprite tooltip content. */
@Builder(toBuilder = true)
final class TooltipData
{
	final String name;
	@Builder.Default
	final int rank = -1;
	/** -1 means unsynced; the default keeps an omission from faking a synced state. */
	@Builder.Default
	final int obtainedCount = -1;
	final int totalItems;
	@Builder.Default
	final boolean rankTracked = true;
	final String statLabel;
	@Builder.Default
	final int statValue = -1;
	final List<Integer> allItemIds;
	final Set<Integer> obtainedIds;
	final Map<Integer, Integer> obtainedCounts;
	@Builder.Default
	final Map<Integer, String> itemNames = Collections.emptyMap();
	/** Boss kill count for the KC/PB header line, -1 when unknown. */
	@Builder.Default
	final int kc = -1;
	/** That line's label where it is not "KC: ", as a clue card's "Master clues completed: ". */
	final String kcLabel;
	/** The local player's recorded personal best for the KC/PB header line, null when none. */
	final String pb;
	/** A raid's hard mode on the raid's card, a second KC/PB line and a second rank: its name, KC, PB and rank. */
	final String hardLabel;
	@Builder.Default
	final int hardKc = -1;
	final String hardPb;
	@Builder.Default
	final int hardRank = -1;

	static List<Integer> itemList(int[] itemIds)
	{
		List<Integer> items = new ArrayList<>(itemIds.length);
		for (int itemId : itemIds)
		{
			items.add(itemId);
		}
		return items;
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.UnaryOperator;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import net.runelite.client.game.ItemManager;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * Builds {@link TooltipData} objects from a {@link ClogResult} without touching any UI.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class TooltipDataBuilder
{
	private final ItemManager itemManager;
	@Nullable
	private ClogIndex clogIndex;

	void setClogIndex(@Nullable ClogIndex clogIndex)
	{
		this.clogIndex = clogIndex;
	}

	/**
	 * Build TooltipData for a clog category.
	 * Returns null if no item data exists for the category.
	 */
	TooltipData buildTooltipData(String displayName, String category, int rank, ClogResult clogResult)
	{
		return buildTooltipData(displayName, category, rank, -1, null, clogResult);
	}

	/**
	 * Boss-cell variant: carries the hiscore kc and the local player's
	 * recorded pb for the KC/PB header line.
	 */
	TooltipData buildTooltipData(String displayName, String category, int rank, int kc, String pb, ClogResult clogResult)
	{
		if (clogResult == null) return null;

		List<ClogResult.ClogItem> obtained = clogResult.getObtainedItems().get(category);
		List<Integer> allItems = canonicalItemIds(clogResult.getCategoryItems().get(category));

		if ((obtained == null || obtained.isEmpty()) && (allItems == null || allItems.isEmpty()))
		{
			return null;
		}

		Map<Integer, Integer> obtainedCounts = obtainedCounts(obtained);
		Set<Integer> obtainedIds = new HashSet<>(obtainedCounts.keySet());

		// No catalog for the category means the denominator is UNKNOWN (-1,
		// rendered as "X/?"), never obtainedIds.size() -- that would claim
		// every category complete for sources that only report obtained items.
		int totalItems = allItems != null ? allItems.size() : -1;
		int obtainedCount = allItems != null
			? ClogHelper.countObtained(allItems, obtainedIds) : obtainedIds.size();

		List<Integer> itemList = allItems != null ? allItems : new ArrayList<>(obtainedIds);
		return itemData(displayName, obtainedCount, totalItems, itemList, obtainedIds, obtainedCounts, clogResult)
			.rank(rank)
			.kc(kc)
			.pb(pb)
			.build();
	}

	/** What every item card carries: its name, its items with what the player holds of them, and their names. */
	private TooltipData.TooltipDataBuilder itemData(String name, int obtainedCount, int totalItems, List<Integer> items,
		Set<Integer> obtainedIds, Map<Integer, Integer> obtainedCounts, ClogResult clogResult)
	{
		return TooltipData.builder()
			.name(name)
			.obtainedCount(obtainedCount)
			.totalItems(totalItems)
			.allItemIds(items)
			.obtainedIds(obtainedIds)
			.obtainedCounts(obtainedCounts)
			.itemNames(itemNamesFor(items, clogResult));
	}

	/** A raid's card with its hard mode's KC and PB, the PB looked up by the hard mode's name; others as they are. */
	@Nullable
	static TooltipData withHardMode(@Nullable TooltipData data, HiscoreSkill raid, @Nullable HiscoreResult result,
		UnaryOperator<String> pb)
	{
		HiscoreSkill hard = PanelData.hardMode(raid);
		if (data == null || hard == null)
		{
			return data;
		}
		return data.toBuilder()
			.hardLabel(PanelData.hardLabel(raid))
			.hardKc(result != null ? result.getKc(hard.getName()) : -1)
			.hardRank(result != null ? result.getRank(hard.getName()) : -1)
			.hardPb(pb.apply(hard.getName()))
			.build();
	}

	/**
	 * A boss card on either side: the synced log's, else the catalog preview carrying the caller's
	 * stat line. Null when neither holds the boss.
	 */
	@Nullable
	TooltipData buildBossCard(String displayName, String category, int rank, int kc, @Nullable String pb,
		@Nullable ClogResult clog, @Nullable String statLabel, int statValue, @Nullable ClogResult catalog)
	{
		TooltipData data = buildTooltipData(displayName, category, rank, kc, pb, clog);
		if (data == null)
		{
			return buildUnsyncedTooltipData(displayName, category, rank, statLabel, statValue, catalog);
		}
		preloadItemImages(data);
		return data;
	}

	/**
	 * A clue tier card on either side: the synced log's, else the catalog preview with the tier's
	 * completions. A null catalog leaves out the preview.
	 */
	@Nullable
	TooltipData buildClueTierCard(HiscoreSkill tier, @Nullable HiscoreResult result, @Nullable ClogResult clog,
		@Nullable ClogResult catalog)
	{
		String category = PanelData.CLUE_CATEGORIES.get(tier);
		if (category == null)
		{
			return null;
		}
		String name = Cells.capitalizeTier(tier);
		int rank = result != null ? result.getActivityRank(tier.getName()) : -1;
		TooltipData data = buildTooltipData(name, category, rank, clog);
		if (data != null)
		{
			return data;
		}
		int score = result != null ? result.getActivityScore(tier.getName()) : -1;
		return buildUnsyncedTooltipData(name, category, rank, Cells.cluesCompletedLabel(tier), score, catalog);
	}

	TooltipData buildUnsyncedTooltipData(String displayName, String category, int rank,
		String statLabel, int statValue, ClogResult catalog)
	{
		if (catalog == null) return null;
		List<Integer> allItems = canonicalItemIds(catalog.getCategoryItems().get(category));
		if (allItems == null || allItems.isEmpty())
		{
			return null;
		}
		return buildUnsyncedTooltipData(displayName, allItems, rank, statLabel, statValue, true, catalog);
	}

	/**
	 * Build TooltipData for a clue rare category (3rd Age / Gilded).
	 * Returns null if the category has no items.
	 */
	TooltipData buildClueRareData(String name, String clogCategory, ClogResult clogResult)
	{
		if (clogResult == null) return null;
		List<Integer> allItems = canonicalItemIds(
			clogResult.getCategoryItems().get(clogCategory));
		if (allItems == null || allItems.isEmpty())
		{
			allItems = canonicalItemIds(staticClueRareItems(clogCategory));
		}
		if (allItems.isEmpty())
		{
			return null;
		}

		List<ClogResult.ClogItem> obtained = clogResult.getObtainedItems().get(clogCategory);
		if (obtained == null || obtained.isEmpty())
		{
			// A log without the page's own items still holds them wherever else it lists them.
			return buildPageData(name, allItems, clogResult);
		}
		Map<Integer, Integer> obtainedCounts = obtainedCounts(obtained);
		Set<Integer> obtainedIds = new HashSet<>(obtainedCounts.keySet());

		int obtainedCount = ClogHelper.countObtained(allItems, obtainedIds);
		return itemData(name, obtainedCount, allItems.size(), allItems, obtainedIds, obtainedCounts, clogResult)
			.rankTracked(false)
			.build();
	}

	/** Each obtained item's highest count, keyed by canonical id. */
	private Map<Integer, Integer> obtainedCounts(@Nullable List<ClogResult.ClogItem> obtained)
	{
		Map<Integer, Integer> counts = new LinkedHashMap<>();
		if (obtained != null)
		{
			for (ClogResult.ClogItem item : obtained)
			{
				counts.merge(canonicalItemId(item.getId()), item.getCount(), Integer::max);
			}
		}
		return counts;
	}

	private static List<Integer> staticClueRareItems(String clogCategory)
	{
		if (PanelData.CLOG_THIRD_AGE.equals(clogCategory))
		{
			return TooltipData.itemList(PanelData.THIRD_AGE_ITEMS);
		}
		if (PanelData.CLOG_GILDED.equals(clogCategory))
		{
			return TooltipData.itemList(PanelData.GILDED_ITEMS);
		}
		return new ArrayList<>();
	}

	/**
	 * A Clue Summary rare row's data, for either player: from their log when there is one (rows 0 and 1 are its 3rd
	 * age and gilded pages, rows 2 to 4 the tiers' rare items, held from anywhere in it), else the catalog's dimmed
	 * preview of the row.
	 */
	@Nullable
	TooltipData rareRow(int row, @Nullable ClogResult clog, @Nullable ClogResult catalog)
	{
		String name = PanelData.RARE_NAMES[row];
		TooltipData data = clog == null ? null : row < 2
			? buildClueRareData(name, PanelData.RARE_KEYS[row], clog)
			: buildCustomRareData(name, PanelData.RARE_ITEMS[row], clog);
		if (data == null)
		{
			data = buildUnsyncedTooltipData(name, PanelData.RARE_KEYS[row], -1, null, -1, catalog);
		}
		return data != null ? data : buildUnsyncedItemData(name, PanelData.RARE_ITEMS[row], catalog);
	}

	/** A custom rare collection (Hard, Elite and Master Rare), held from anywhere in the log. */
	TooltipData buildCustomRareData(String name, int[] itemIds, ClogResult clogResult)
	{
		return buildPageData(name, TooltipData.itemList(itemIds), clogResult);
	}

	/**
	 * A set of items, such as a Collection Log page from the game, with what the player holds of each
	 * anywhere in the log: an item counts once however many pages list it, the way the game counts it.
	 */
	TooltipData buildPageData(String name, List<Integer> itemIds, ClogResult clogResult)
	{
		if (clogResult == null) return null;
		Map<Integer, Integer> held = new HashMap<>();
		for (List<ClogResult.ClogItem> catObtained : clogResult.getObtainedItems().values())
		{
			for (ClogResult.ClogItem item : catObtained)
			{
				held.merge(canonicalItemId(item.getId()), item.getCount(), Integer::max);
			}
		}

		List<Integer> allItemsList = canonicalItemIds(itemIds);
		Set<Integer> obtainedIds = new HashSet<>();
		Map<Integer, Integer> obtainedCounts = new LinkedHashMap<>();
		for (int itemId : allItemsList)
		{
			Integer count = held.get(itemId);
			if (count != null)
			{
				obtainedIds.add(itemId);
				obtainedCounts.put(itemId, count);
			}
		}

		return itemData(name, obtainedIds.size(), allItemsList.size(), allItemsList, obtainedIds, obtainedCounts,
			clogResult).rankTracked(false).build();
	}

	TooltipData buildUnsyncedItemData(String name, int[] itemIds, ClogResult catalog)
	{
		return buildUnsyncedItemData(name, TooltipData.itemList(itemIds), catalog);
	}

	TooltipData buildUnsyncedItemData(String name, List<Integer> itemIds, ClogResult catalog)
	{
		if (catalog == null || itemIds == null || itemIds.isEmpty())
		{
			return null;
		}
		return buildUnsyncedTooltipData(name, itemIds, -1, null, -1, false, catalog);
	}

	private TooltipData buildUnsyncedTooltipData(String displayName, List<Integer> itemIds,
		int rank, String statLabel, int statValue, boolean rankTracked, ClogResult catalog)
	{
		List<Integer> canonicalItems = canonicalItemIds(itemIds);
		return TooltipData.builder()
			.name(displayName)
			.rank(rank)
			.totalItems(canonicalItems.size())
			.allItemIds(canonicalItems)
			.obtainedIds(new HashSet<>())
			.obtainedCounts(new LinkedHashMap<>())
			.itemNames(itemNamesFor(canonicalItems, catalog))
			.rankTracked(rankTracked)
			.statLabel(statLabel)
			.statValue(statValue)
			.build();
	}

	private Map<Integer, String> itemNamesFor(List<Integer> itemIds, ClogResult clogResult)
	{
		Map<Integer, String> names = new LinkedHashMap<>();
		for (int itemId : itemIds)
		{
			String name = ClogIndex.itemNameOrAlias(clogIndex, clogResult, itemId);
			if (name != null)
			{
				names.put(itemId, name);
			}
		}
		return names;
	}

	private List<Integer> canonicalItemIds(@Nullable List<Integer> itemIds)
	{
		if (itemIds == null)
		{
			return null;
		}
		Set<Integer> distinct = new java.util.LinkedHashSet<>();
		for (int itemId : itemIds)
		{
			distinct.add(canonicalItemId(itemId));
		}
		return new ArrayList<>(distinct);
	}

	private int canonicalItemId(int itemId)
	{
		return clogIndex != null
			? clogIndex.canonicalItemId(itemId) : ClogIndex.fallbackCanonicalItemId(itemId);
	}

	/** Trigger async loads for all tooltip items. */
	void preloadItemImages(TooltipData data)
	{
		for (int itemId : data.allItemIds)
		{
			int count = data.obtainedIds.contains(itemId)
				? data.obtainedCounts.getOrDefault(itemId, 1) : 1;
			itemManager.getImage(itemId, count, false);
		}
	}
}

package com.killclog;

import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.annotation.Nullable;
import javax.swing.JComponent;
import lombok.AccessLevel;
import lombok.Setter;
import net.runelite.client.util.LinkBrowser;

final class TooltipItemHover
{
	private final JComponent component;
	private List<HitBox> hitBoxes = Collections.emptyList();
	private int hoveredItemId = -1;
	private int hoveredSection = -1;
	private boolean hoveredObtained;
	private String hoveredItemName;
	// Where the mouse last was over the card, so a scroll can hover what now sits under it.
	private int lastX = -1;
	private int lastY = -1;
	private boolean rehover;
	@Setter(AccessLevel.PACKAGE)
	private CardLinks links = CardLinks.ON;

	TooltipItemHover(JComponent component)
	{
		this.component = component;
		install();
	}

	void setHitBoxes(List<HitBox> hitBoxes)
	{
		this.hitBoxes = hitBoxes != null ? hitBoxes : Collections.emptyList();
		if (rehover)
		{
			rehover = false;
			updateHoveredItem(lastX, lastY);
		}
	}

	/** After a scroll the item now under the still mouse becomes the hovered one, once the card repaints. */
	void rehoverAfterPaint()
	{
		rehover = true;
	}

	void clear()
	{
		if (hoveredItemId != -1 || hoveredItemName != null || hoveredSection != -1)
		{
			hoveredItemId = -1;
			hoveredItemName = null;
			hoveredSection = -1;
			hoveredObtained = false;
			component.repaint();
		}
	}

	String hoveredItemName()
	{
		return hoveredItemName;
	}

	/** Whether the hovered thing is held: an item the player has, a tier reached, a source that supplied the log. */
	boolean hoveredItemObtained()
	{
		return hoveredObtained;
	}

	private void install()
	{
		component.addMouseMotionListener(new MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				updateHoveredItem(e.getX(), e.getY());
			}
		});
		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				// A press on the card's scroll rail scrolls it; it never opens an item too.
				if (CardBody.onRail(component, e.getPoint()))
				{
					return;
				}
				updateHoveredItem(e.getX(), e.getY());
				HitBox pressed = findHitBox(e.getX(), e.getY());
				if (e.getButton() == MouseEvent.BUTTON1 && pressed != null && pressed.url != null && links.opens(e))
				{
					LinkBrowser.browse(pressed.url);
					closeTooltip();
					e.consume();
				}
				else if (links.opens(e) && e.getButton() == MouseEvent.BUTTON1 && hoveredItemId > 0)
				{
					TooltipItemLink.openWiki(hoveredItemId);
					closeTooltip();
					e.consume();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				lastX = -1;
				lastY = -1;
				clear();
			}
		});
	}

	private void updateHoveredItem(int mx, int my)
	{
		lastX = mx;
		lastY = my;
		HitBox hitBox = findHitBox(mx, my);
		int nextId = hitBox != null ? hitBox.itemId : -1;
		int nextSection = hitBox != null ? hitBox.section : -1;
		boolean nextObtained = hitBox != null && hitBox.obtained;
		if (nextId == hoveredItemId && nextSection == hoveredSection
			&& nextObtained == hoveredObtained
			&& Objects.equals(hitBox != null ? hitBox.itemName : null, hoveredItemName))
		{
			return;
		}
		hoveredItemId = nextId;
		hoveredItemName = hitBox != null ? hitBox.itemName : null;
		hoveredSection = nextSection;
		hoveredObtained = nextObtained;
		component.repaint();
	}

	private void closeTooltip()
	{
		clear();
		NativeTooltip.hideTooltipTree(component);
	}

	private HitBox findHitBox(int mx, int my)
	{
		for (HitBox hitBox : hitBoxes)
		{
			if (hitBox.bounds.contains(mx, my))
			{
				return hitBox;
			}
		}
		return null;
	}

	/** The hover section of a name in a card's header (its title, badge, clan or corner image), apart from its body's. */
	static final int HEADER_SECTION = 9;

	static final class HitBox
	{
		private final int section;
		private final int itemId;
		private final String itemName;
		private final Rectangle bounds;
		private final boolean obtained;
		@Nullable
		private final String url;

		HitBox(int section, int itemId, String itemName, Rectangle bounds, boolean obtained)
		{
			this(section, itemId, itemName, bounds, obtained, null);
		}

		/** A named box that opens {@code url} when pressed. */
		HitBox(int section, int itemId, String itemName, Rectangle bounds, boolean obtained, @Nullable String url)
		{
			this.section = section;
			this.itemId = itemId;
			this.itemName = TooltipItemLink.displayName(itemId, itemName);
			this.bounds = bounds;
			this.obtained = obtained;
			this.url = url;
		}

		/** The part of this box a window shows, or null when it shows none of it. */
		@Nullable
		HitBox within(Rectangle window)
		{
			Rectangle shown = bounds.intersection(window);
			return shown.isEmpty() ? null : new HitBox(section, itemId, itemName, shown, obtained);
		}
	}
}

package com.killclog;

import java.util.HashMap;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import net.runelite.client.util.LinkBrowser;

/** Wiki-link and display helpers for tooltip affordances. */
final class TooltipItemLink
{
	private static final String WIKI_ITEM_LOOKUP =
		"https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=";
	private static final String WIKI_PAGE =
		"https://oldschool.runescape.wiki/w/";
	private static final String FALLBACK_NAME_PREFIX = "Item ";

	// The chompy bird hats, from item 2978 up: the kills each takes and its rank (chompy-hats.tsv).
	private static final Map<Integer, String> CHOMPY_HATS = new HashMap<>();

	static
	{
		for (String[] row : CatalogTsv.rows(TooltipItemLink.class, "chompy-hats.tsv", 2))
		{
			CHOMPY_HATS.put(Integer.parseInt(row[0]), row[1]);
		}
	}

	static String displayName(int itemId, String name)
	{
		return CHOMPY_HATS.getOrDefault(itemId, name);
	}

	private TooltipItemLink()
	{
	}

	// A player's or a clan's page elsewhere (Dylan, 2026-10-17): the addresses killclog.com's badges open.
	static String templeUrl(String rsn)
	{
		return "https://templeosrs.com/player/overview.php?player=" + URLEncoder.encode(rsn, StandardCharsets.UTF_8);
	}

	static String runeProfileUrl(String rsn)
	{
		return "https://runeprofile.com/" + HttpUtil.pathSegment(rsn);
	}

	static String runeProfileClanUrl(String clan)
	{
		return "https://runeprofile.com/clan/" + HttpUtil.pathSegment(clan);
	}

	static String killclogUrl(String rsn)
	{
		return "https://killclog.com/p/" + HttpUtil.pathSegment(rsn.trim().replaceAll("\\s+", "-"));
	}

	static String wikiUrl(int itemId)
	{
		return WIKI_ITEM_LOOKUP + itemId;
	}

	static void openWiki(int itemId)
	{
		if (itemId > 0)
		{
			LinkBrowser.browse(wikiUrl(itemId));
		}
	}

	static String wikiPageUrl(String pageName)
	{
		return WIKI_PAGE + encodePageName(pageName);
	}

	static void openWikiPage(String pageName)
	{
		if (pageName != null && !pageName.trim().isEmpty())
		{
			LinkBrowser.browse(wikiPageUrl(pageName));
		}
	}

	static String itemName(Map<Integer, String> itemNames, int itemId)
	{
		String hatName = displayName(itemId, null);
		if (hatName != null) return hatName;
		if (itemNames == null)
		{
			return fallbackName(itemId);
		}
		String name = itemNames.get(itemId);
		if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name))
		{
			return fallbackName(itemId);
		}
		return name;
	}

	/** A page name, and after a '#' the section on it, as the wiki's URLs write them. */
	private static String encodePageName(String pageName)
	{
		if (pageName == null)
		{
			return "";
		}
		int section = pageName.indexOf('#');
		if (section >= 0)
		{
			return encodePageName(pageName.substring(0, section)) + "#" + encodePageName(pageName.substring(section + 1));
		}
		String normalized = pageName.trim().replace(' ', '_');
		String[] parts = normalized.split("/", -1);
		for (int i = 0; i < parts.length; i++)
		{
			parts[i] = URLEncoder.encode(parts[i], StandardCharsets.UTF_8)
				.replace("+", "_");
		}
		return String.join("/", parts);
	}

	private static String fallbackName(int itemId)
	{
		return FALLBACK_NAME_PREFIX + itemId;
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import javax.swing.SwingUtilities;

@Slf4j
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class TooltipItemNameResolver
{
	private static final int BATCH_SIZE = 48;

	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final Runnable onComplete;
	private final Set<ClogResult> inFlight = Collections.synchronizedSet(
		Collections.newSetFromMap(new IdentityHashMap<>()));

	void resolve(ClogResult result)
	{
		Set<Integer> allIds = new HashSet<>();
		for (List<ClogResult.ClogItem> items : result.getObtainedItems().values())
		{
			for (ClogResult.ClogItem item : items)
			{
				allIds.add(item.getId());
			}
		}
		for (List<Integer> ids : result.getCategoryItems().values())
		{
			allIds.addAll(ids);
		}

		List<Integer> missing = new ArrayList<>();
		for (int id : allIds)
		{
			if (!result.isItemResolved(id))
			{
				missing.add(id);
			}
		}
		if (missing.isEmpty() || !inFlight.add(result))
		{
			return;
		}

		log.debug("Resolving {} untradeable item names via game cache", missing.size());
		resolveBatch(result, missing, 0);
	}

	private void resolveBatch(ClogResult result, List<Integer> missing, int start)
	{
		clientThread.invokeLater(() ->
		{
			int end = Math.min(start + BATCH_SIZE, missing.size());
			for (int i = start; i < end; i++)
			{
				try
				{
					int id = missing.get(i);
					String name = itemManager.getItemComposition(id).getName();
					if (name != null && !name.isEmpty() && !name.equals("null") && !name.equals("Null"))
					{
						result.markItemResolved(id, name);
					}
				}
				catch (Exception e)
				{
					// Item not in cache - skip.
				}
			}
			if (end < missing.size())
			{
				resolveBatch(result, missing, end);
				return;
			}
			inFlight.remove(result);
			SwingUtilities.invokeLater(onComplete);
		});
	}
}

package com.killclog;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

final class TooltipItemSprites
{
	private final BufferedImage[] sprites;
	private final String[] itemNames;

	private TooltipItemSprites(int count)
	{
		sprites = new BufferedImage[count];
		itemNames = new String[count];
	}

	static TooltipItemSprites load(List<Integer> itemIds, Map<Integer, String> itemNames,
		ItemManager itemManager, IntUnaryOperator countForItem, JComponent repaintTarget)
	{
		TooltipItemSprites loaded = new TooltipItemSprites(itemIds.size());
		for (int i = 0; i < itemIds.size(); i++)
		{
			int itemId = itemIds.get(i);
			loaded.itemNames[i] = TooltipItemLink.itemName(itemNames, itemId);
			BufferedImage img = itemManager.getImage(itemId, Math.max(1, countForItem.applyAsInt(itemId)), false);
			final int idx = i;
			whenLoaded(img, repaintTarget, () ->
			{
				loaded.sprites[idx] = img;
				repaintTarget.repaint();
			});
			loaded.sprites[i] = img;
		}
		return loaded;
	}

	// How many of a card's pictures are still on their way, kept on the card itself.
	private static final String LOADING = "killclog.card.loading";

	/**
	 * Runs on the Swing thread once a picture the card asked for has drawn; until then the card counts it as loading,
	 * so a copy of the card waits for it. A picture already there needs nothing.
	 */
	static void whenLoaded(BufferedImage image, JComponent card, Runnable loaded)
	{
		if (!(image instanceof AsyncBufferedImage))
		{
			return;
		}
		count(card, 1);
		((AsyncBufferedImage) image).onLoaded(() -> SwingUtilities.invokeLater(() ->
		{
			count(card, -1);
			loaded.run();
		}));
	}

	/** Whether a card, or either card of a comparison, still waits on a picture. Swing thread. */
	static boolean loading(JComponent card)
	{
		Object pending = card.getClientProperty(LOADING);
		if (pending instanceof Integer && (Integer) pending > 0)
		{
			return true;
		}
		for (java.awt.Component child : card.getComponents())
		{
			if (child instanceof JComponent && loading((JComponent) child))
			{
				return true;
			}
		}
		return false;
	}

	private static void count(JComponent card, int change)
	{
		Object pending = card.getClientProperty(LOADING);
		card.putClientProperty(LOADING, (pending instanceof Integer ? (Integer) pending : 0) + change);
	}

	BufferedImage spriteAt(int index)
	{
		if (index < 0 || index >= sprites.length)
		{
			return null;
		}
		return sprites[index];
	}

	String nameAt(int index)
	{
		if (index < 0 || index >= itemNames.length)
		{
			return null;
		}
		return itemNames[index];
	}

	/**
	 * One grid of item sprites in the current font: unobtained ones dimmed,
	 * each centered in its cell, the quantity in the corner when wanted.
	 * Returns a hit box per item, named from {@code names} when given, else as the sprites were loaded.
	 * Without sprites the cells still hover.
	 */
	static List<TooltipItemHover.HitBox> paintGrid(Graphics2D g2, TooltipItemSprites sprites,
		Map<Integer, String> names, int section, List<Integer> ids, Set<Integer> obtainedIds,
		Map<Integer, Integer> counts, int startX, int startY, int cols, int size, int cellSize)
	{
		List<TooltipItemHover.HitBox> hitBoxes = new ArrayList<>(ids.size());
		int ascent = g2.getFontMetrics().getAscent();
		for (int i = 0; i < ids.size(); i++)
		{
			int x = startX + (i % cols) * cellSize;
			int y = startY + (i / cols) * cellSize;
			int itemId = ids.get(i);
			boolean obtained = obtainedIds.contains(itemId);
			int count = obtained ? counts.getOrDefault(itemId, 1) : 1;
			hitBoxes.add(new TooltipItemHover.HitBox(section, itemId,
				names != null || sprites == null ? TooltipItemLink.itemName(names, itemId) : sprites.nameAt(i),
				new Rectangle(x, y, size, size), obtained));
			BufferedImage sprite = sprites != null ? sprites.spriteAt(i) : null;
			if (sprite != null)
			{
				g2.setComposite(obtained
					? AlphaComposite.SrcOver
					: AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.3f));
				g2.drawImage(sprite, x + (size - sprite.getWidth()) / 2, y + (size - sprite.getHeight()) / 2, null);
				g2.setComposite(AlphaComposite.SrcOver);
			}
			if (obtained && count > 1)
			{
				String quantity = String.valueOf(count);
				g2.setColor(Color.BLACK);
				g2.drawString(quantity, x + 1, y + ascent + 1);
				g2.setColor(atCap(itemId, count) ? TitleTooltip.CLOG_GREEN : TitleTooltip.CLOG_YELLOW);
				g2.drawString(quantity, x, y + ascent);
			}
		}
		return hitBoxes;
	}

	/** A count the game stops at, 250 for most log items and 65,535 for the rest, reads green: there's no more to log. */
	static boolean atCap(int itemId, int count)
	{
		return count >= 65535 || count == 250 && Arrays.stream(PanelData.COUNTS_PAST_250_ITEMS).noneMatch(id -> id == itemId);
	}
}

