package com.killclog;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;

/**
 * Shared empty collection-log catalog for players without synced clog data.
 * Prefers the parsed in-game clog index so unsynced popups use the same item
 * ids and item names as local/synced tooltip data, with provider categories as
 * a startup fallback.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class UnsyncedClogCatalog
{
	private static final String CATALOG_NAME = "Collection Log";

	private final ClogService clogService;
	private Consumer<ClogResult> resolver = UnsyncedClogCatalog::noop;
	@Nullable private ClogIndex clogIndex;
	@Nullable private ClogResult indexCatalog;
	@Nullable private ClogResult fallbackCatalog;
	@Nullable private Object builtFrom;

	void setClogIndex(@Nullable ClogIndex clogIndex)
	{
		this.clogIndex = clogIndex;
		this.indexCatalog = null;
		this.builtFrom = null;
	}

	void setResolver(@Nullable Consumer<ClogResult> resolver)
	{
		this.resolver = resolver != null ? resolver : UnsyncedClogCatalog::noop;
	}

	@Nullable
	ClogResult result()
	{
		ClogResult catalog = indexCatalog();
		if (catalog == null)
		{
			catalog = fallbackCatalog();
		}
		if (catalog != null)
		{
			resolver.accept(catalog);
		}
		return catalog;
	}

	@Nullable
	private ClogResult indexCatalog()
	{
		ClogIndex index = clogIndex;
		if (index == null || index.generation() == null)
		{
			return null;
		}

		// The generation token names one parse. When it moves, copyCatalog()
		// captures categories and item names atomically from a single parse
		// (possibly newer than the token just read; the cache keys on the
		// generation the copy actually came from, so it stays coherent).
		if (indexCatalog == null || builtFrom != index.generation())
		{
			ClogIndex.CatalogCopy copy = index.copyCatalog();
			if (copy == null)
			{
				return null;
			}
			indexCatalog = new ClogResult(
				CATALOG_NAME,
				emptyObtained(copy.categoryItems),
				copy.categoryItems,
				copy.itemNames,
				null,
				null);
			builtFrom = copy.generation;
		}
		return indexCatalog;
	}

	@Nullable
	private ClogResult fallbackCatalog()
	{
		if (fallbackCatalog == null)
		{
			fallbackCatalog = clogService.getCatalogResult(CATALOG_NAME);
		}
		return fallbackCatalog;
	}

	private static Map<String, List<ClogResult.ClogItem>> emptyObtained(
		Map<String, List<Integer>> categories)
	{
		Map<String, List<ClogResult.ClogItem>> obtained = new HashMap<>();
		for (String category : categories.keySet())
		{
			obtained.put(category, Collections.emptyList());
		}
		return obtained;
	}

	private static void noop(ClogResult result)
	{
	}
}

package com.killclog;

import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import net.runelite.api.WorldType;

/**
 * Which game the logged-in world plays (the main game, the announced League, or none known), the store
 * its captures belong in, and whether the world has settled: counters, CA tiers and the account type
 * sent to the server wait for it, so a hop or login never carries another game's values into this one.
 * When the world's game or the running League changes, the panel and chat are told which to read.
 */
final class WorldSession
{
	static final int SETTLED_TICKS = 10;

	/** Hands the panel and chat the game to read: a League and its store, or null for the main game. */
	interface Shown
	{
		void show(@Nullable String league, @Nullable LocalClogCache leagueLog, @Nullable String activeLeague);
	}

	private final Supplier<String> mode;
	private final Supplier<String> activeLeague;
	private final Supplier<LocalClogCache> main;
	private final Function<String, LocalClogCache> leagueStores;
	private final Consumer<LocalClogCache> opened;
	// Ticks on this world with an unchanged account type.
	private int settledTicks;
	// The active League's own store, opened on first use; one League at a time.
	private LocalClogCache leagueCache;
	private String leagueCacheId;
	// The world's game and running League last handed over.
	private String shown = "";

	/**
	 * @param mode         main, the announced League, or null: logged in on a world whose game is known
	 * @param leagueStores opens a League's own store; {@code opened} wires each one as it opens
	 */
	WorldSession(Supplier<String> mode, Supplier<String> activeLeague, Supplier<LocalClogCache> main,
		Function<String, LocalClogCache> leagueStores, Consumer<LocalClogCache> opened)
	{
		this.mode = mode;
		this.activeLeague = activeLeague;
		this.main = main;
		this.leagueStores = leagueStores;
		this.opened = opened;
	}

	@Nullable
	String mode()
	{
		return mode.get();
	}

	boolean settled()
	{
		return settledTicks >= SETTLED_TICKS;
	}

	boolean mainSettled()
	{
		return settled() && GameMode.MAIN.equals(mode());
	}

	/** On a Hardcore Worlds world, the character's total XP once the world has settled (0 before); else -1. */
	long hardcoreXp(@Nullable Set<WorldType> flags, LongSupplier overallXp)
	{
		if (!GameMode.hardcore(flags))
		{
			return -1;
		}
		return mainSettled() ? overallXp.getAsLong() : 0;
	}

	void unsettle()
	{
		settledTicks = 0;
	}

	/** Counts this world's settled ticks; true on the tick a main-game world settles. */
	boolean tick()
	{
		if (mode() == null)
		{
			settledTicks = 0;
			return false;
		}
		return ++settledTicks == SETTLED_TICKS && GameMode.MAIN.equals(mode());
	}

	/** The store this world's captures belong in, or null when the world's game is unknown. */
	@Nullable
	LocalClogCache captureCache()
	{
		String current = mode();
		return current == null ? null : cacheFor(current);
	}

	LocalClogCache cacheFor(String game)
	{
		if (GameMode.MAIN.equals(game))
		{
			return main.get();
		}
		if (!game.equals(leagueCacheId))
		{
			if (leagueCache != null)
			{
				leagueCache.close();
			}
			LocalClogCache created = leagueStores.apply(game);
			opened.accept(created);
			leagueCache = created;
			leagueCacheId = game;
		}
		return leagueCache;
	}

	/** A League world reads its League in the panel and chat; every other world, or none, the main game. */
	void follow(Shown shown)
	{
		String current = mode();
		String league = current == null || GameMode.MAIN.equals(current) ? null : current;
		String active = activeLeague.get();
		// Keyed on the mode itself, so a logout (no mode) ends a flip made on a main world.
		if (!(current + "/" + active).equals(this.shown))
		{
			this.shown = current + "/" + active;
			shown.show(league, league == null ? null : captureCache(), active);
		}
	}

	/** Nothing matches it, so the next follow hands the world's game over again. */
	void showAgain()
	{
		shown = "";
	}

	/** The open League's store serves the same login as the main one. */
	void serve(Session session)
	{
		if (leagueCache != null)
		{
			leagueCache.serve(session);
		}
	}

	void close()
	{
		if (leagueCache != null)
		{
			leagueCache.close();
			leagueCache = null;
			leagueCacheId = null;
		}
	}
}

package com.killclog;

import java.awt.image.BufferedImage;
import java.util.Collections;
import javax.swing.ImageIcon;
import net.runelite.client.util.ImageUtil;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class AccountDisplayTest
{
	@Test
	public void aFrozenBoardWearsTheModeTheAccountLeft()
	{
		AccountDisplay iron = AccountDisplay.of(AccountType.IRONMAN, HiscoreTable.STANDARD);
		assertEquals("Dead Hardcore", iron.frozenOn(RankLeaderboard.HARDCORE).label());

		AccountDisplay main = AccountDisplay.of(AccountType.REGULAR, HiscoreTable.STANDARD);
		AccountDisplay pure = AccountDisplay.of(AccountType.REGULAR, HiscoreTable.ONE_DEFENCE);
		for (RankLeaderboard board : new RankLeaderboard[]{
			RankLeaderboard.IRONMAN, RankLeaderboard.HARDCORE, RankLeaderboard.ULTIMATE})
		{
			assertEquals("De-ironed", main.frozenOn(board).label());
			// The mode left outranks a pure's or skiller's own table.
			assertEquals("De-ironed", pure.frozenOn(board).label());
		}
	}

	@Test
	public void onlyARecordedFrozenRowWearsTheModeLeft()
	{
		HiscoreResult today = row(AccountType.IRONMAN, 1_500, 20_000_000L, true);
		HiscoreResult atTheDeath = row(AccountType.HARDCORE_IRONMAN, 1_200, 9_000_000L, null);
		AccountDisplay iron = AccountDisplay.of(AccountType.IRONMAN, HiscoreTable.STANDARD);
		assertEquals("Dead Hardcore", iron.shownOn(today.withRow(atTheDeath), RankLeaderboard.HARDCORE).label());

		// Loading, unanswered, or not on the board: the placeholder row trails too, but records nothing.
		HiscoreResult nothing = TestViews.hiscore(null, null, null, null, null, null, 0, 0, 0, -1);
		assertSame(iron, iron.shownOn(today.withRow(nothing), RankLeaderboard.HARDCORE));
		// The account's own row, or a row level with it, isn't frozen.
		assertSame(iron, iron.shownOn(today, RankLeaderboard.HARDCORE));
		assertSame(iron, iron.shownOn(today.withRow(today), RankLeaderboard.HARDCORE));
		assertSame(iron, iron.shownOn(null, RankLeaderboard.HARDCORE));
	}

	@Test
	public void aFormerModeNeedsTheLookupsOwnIronmanAnswerToAgree()
	{
		AccountDisplay iron = AccountDisplay.of(AccountType.IRONMAN, HiscoreTable.STANDARD);
		AccountDisplay main = AccountDisplay.of(AccountType.REGULAR, HiscoreTable.STANDARD);
		HiscoreResult hardcoreRow = row(AccountType.HARDCORE_IRONMAN, 1_200, 9_000_000L, null);

		// Ironman now: a dead Hardcore, never a de-ironed account.
		HiscoreResult ironNow = row(AccountType.IRONMAN, 1_500, 20_000_000L, true).withRow(hardcoreRow);
		assertEquals("Dead Hardcore", iron.shownOn(ironNow, RankLeaderboard.HARDCORE).label());
		assertSame(main, main.shownOn(ironNow, RankLeaderboard.HARDCORE));
		// An Ultimate who stepped down is an Ironman now, and keeps the Ironman helm.
		assertSame(iron, iron.shownOn(ironNow, RankLeaderboard.ULTIMATE));
		// Ironman row trailing: de-ironed, never a dead Hardcore.
		HiscoreResult leftIron = row(AccountType.REGULAR, 1_500, 20_000_000L, false).withRow(hardcoreRow);
		assertEquals("De-ironed", main.shownOn(leftIron, RankLeaderboard.HARDCORE).label());
		assertSame(iron, iron.shownOn(leftIron, RankLeaderboard.HARDCORE));
		// A lookup whose regular or Ironman board didn't answer proves neither.
		HiscoreResult unproven = row(AccountType.REGULAR, 1_500, 20_000_000L, null).withRow(hardcoreRow);
		assertSame(iron, iron.shownOn(unproven, RankLeaderboard.HARDCORE));
		assertSame(main, main.shownOn(unproven, RankLeaderboard.HARDCORE));
		// The answer travels with the lookup into its projections.
		assertEquals(Boolean.TRUE, row(AccountType.IRONMAN, 1, 1L, true).withRanks(null).getIronmanNow());
	}

	@Test
	public void everyOtherFrozenBoardKeepsTheAccountsOwnBadge()
	{
		for (AccountType type : AccountType.values())
		{
			AccountDisplay display = AccountDisplay.of(type, HiscoreTable.STANDARD);
			assertSame(display, display.frozenOn(null));
			for (RankLeaderboard board : RankLeaderboard.values())
			{
				boolean deadHardcore = type == AccountType.IRONMAN && board == RankLeaderboard.HARDCORE;
				boolean deIroned = type == AccountType.REGULAR && (board == RankLeaderboard.IRONMAN
					|| board == RankLeaderboard.HARDCORE || board == RankLeaderboard.ULTIMATE);
				if (!deadHardcore && !deIroned)
				{
					// An Ultimate who stepped down to Ironman is one of these.
					assertSame(type + " on " + board, display, display.frozenOn(board));
				}
			}
		}
		assertNull(AccountDisplay.of(AccountType.IRONMAN, HiscoreTable.STANDARD).former());
	}

	@Test
	public void aFormerBadgeIsTheHelmWithItsMarkDrawnOver()
	{
		AccountDisplay[] shown = {
			AccountDisplay.of(AccountType.IRONMAN, HiscoreTable.STANDARD).frozenOn(RankLeaderboard.HARDCORE),
			AccountDisplay.of(AccountType.REGULAR, HiscoreTable.STANDARD).frozenOn(RankLeaderboard.IRONMAN)};
		// The red Hardcore helm under the skull; the grey Ironman helm under the circle and slash.
		AccountType[] helms = {AccountType.HARDCORE_IRONMAN, AccountType.IRONMAN};
		String[] marks = {"dead-hardcore-overlay.png", "de-ironed-overlay.png"};
		for (int i = 0; i < shown.length; i++)
		{
			AccountDisplay display = shown[i];
			AccountDisplay.Former former = display.former();
			BufferedImage helm = AccountBadgeResolver.badge(AccountDisplay.of(helms[i], HiscoreTable.STANDARD));
			BufferedImage mark = ImageUtil.loadImageResource(AccountBadgeResolver.class, marks[i]);
			BufferedImage badge = AccountBadgeResolver.badge(display);
			assertNotNull(badge);
			assertEquals(helm.getWidth(), badge.getWidth());
			assertEquals(helm.getHeight(), badge.getHeight());
			int marked = 0;
			for (int y = 0; y < helm.getHeight(); y++)
			{
				for (int x = 0; x < helm.getWidth(); x++)
				{
					int alpha = mark.getRGB(x, y) >>> 24;
					if (alpha == 255)
					{
						assertEquals(former + " at " + x + "," + y, mark.getRGB(x, y), badge.getRGB(x, y));
						marked++;
					}
					else if (alpha == 0)
					{
						assertEquals(former + " at " + x + "," + y, helm.getRGB(x, y), badge.getRGB(x, y));
					}
				}
			}
			assertTrue(marked > 0);
			// The name row draws it at the same 15px as every other account badge.
			ImageIcon icon = AccountBadgeResolver.labelIcon(display);
			assertEquals(15, icon.getIconHeight());
		}
	}

	@Test
	public void aDeIronedAccountThatDiedAsAHardcoreWearsTheDeadHardcoreBadgeOnTheHardcoreBoard()
	{
		// My Specialty, 10/13: Hardcore 243M XP (stopped at the death), Ironman 471M (played on), regular 527M (now).
		AccountDisplay main = AccountDisplay.of(AccountType.REGULAR, HiscoreTable.STANDARD);
		HiscoreResult today = row(AccountType.REGULAR, 2_278, 526_533_458L, false);
		today.setDiedAsHardcore(true);
		HiscoreResult hardcoreRow = row(AccountType.HARDCORE_IRONMAN, 2_155, 243_370_767L, null);
		HiscoreResult ironmanRow = row(AccountType.IRONMAN, 2_278, 470_950_791L, null);
		assertEquals("Dead Hardcore", main.shownOn(today.withRow(hardcoreRow), RankLeaderboard.HARDCORE).label());
		assertEquals("De-ironed", main.shownOn(today.withRow(ironmanRow), RankLeaderboard.IRONMAN).label());

		// A Hardcore who de-ironed alive left both boards level: de-ironed on both.
		today.setDiedAsHardcore(false);
		assertEquals("De-ironed", main.shownOn(today.withRow(hardcoreRow), RankLeaderboard.HARDCORE).label());
		// The answer travels with the lookup into its projections.
		today.setDiedAsHardcore(true);
		assertEquals(Boolean.TRUE, today.withRanks(null).getDiedAsHardcore());
	}

	private static HiscoreResult row(AccountType type, int totalLevel, long totalXp, Boolean ironmanNow)
	{
		HiscoreResult row = TestViews.hiscore(type, Collections.emptyMap(), Collections.emptyMap(),
			Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(), totalLevel, totalXp, 100, 1);
		row.setIronmanNow(ironmanNow);
		return row;
	}
}

package com.killclog;

import org.junit.Test;
