		index.publishForTest(Collections.emptyMap(), Collections.emptyMap(),
			Collections.emptyMap(), Collections.singletonMap(90_001, 90_000));
		assertEquals(90_000, index.canonicalItemId(90_001));
		assertEquals(10420, index.canonicalItemId(10420));
		assertEquals(10422, index.canonicalItemId(10422));
	}

	@Test
	public void openContainersAndFemaleOutfitAreOneSevenSlotTitheFarmLogEverywhere()
	{
		Map<String, List<Integer>> categories = Collections.singletonMap(
			"tithe_farm", TITHE_CATALOG);
		Map<String, List<ClogResult.ClogItem>> obtained = Collections.singletonMap(
			"tithe_farm", FEMALE_TITHE_OBTAINED);
		ClogResult result = new ClogResult("Based Batt", obtained, categories,
			Collections.emptyMap(), null, null);

		Map<String, List<String>> tabs = new LinkedHashMap<>();
		tabs.put("Minigames", Collections.singletonList("tithe_farm"));
		ClogIndex index = new ClogIndex();
		index.publishForTest(categories, Collections.emptyMap(), tabs, Collections.emptyMap());

		SkillClogSection tithe = SkillClogSection.forSkill(
			Skill.FARMING, result, null, result, index).stream()
			.filter(section -> "Tithe Farm".equals(section.heading()))
			.findFirst()
			.orElseThrow(AssertionError::new);
		assertEquals(7, tithe.itemIds().size());
		assertEquals(7, tithe.primary().obtainedCount());
		assertTrue(tithe.primary().obtainedIds().containsAll(
			Arrays.asList(13646, 13642, 13640, 13644)));

		TooltipDataBuilder builder = new TooltipDataBuilder(null);
		builder.setClogIndex(index);
		TooltipData tooltip = builder.buildTooltipData(
			"Tithe Farm", "tithe_farm", -1, result);
		assertEquals(7, tooltip.totalItems);
		assertEquals(7, tooltip.obtainedCount);

		assertEquals(7, ClogHelper.sumClogTotals(result, index::canonicalItemId)[0]);
		assertEquals(7, ClogHelper.sumClogTotals(result, index::canonicalItemId)[1]);
	}

	@Test
	public void tabProgressCountsEachSlotOnceAgainstTheGamesOwnCatalog()
	{
		Map<String, List<Integer>> categories = new LinkedHashMap<>();
		categories.put("tithe_farm", TITHE_CATALOG);
		// 4151 sits on two pages of one tab; 11286 is on a page the provider files elsewhere.
		categories.put("abyssal_sire", Arrays.asList(4151, 13262));
		categories.put("slayer", Arrays.asList(4151, 11286));
		Map<String, List<String>> tabs = new LinkedHashMap<>();
		tabs.put("Bosses", Arrays.asList("abyssal_sire", "slayer"));
		tabs.put("Minigames", Collections.singletonList("tithe_farm"));
		tabs.put("Other", Collections.emptyList());
		ClogIndex index = new ClogIndex();
		index.publishForTest(categories, Collections.emptyMap(), tabs, Collections.emptyMap());

		Map<String, List<ClogResult.ClogItem>> obtained = new LinkedHashMap<>();
		obtained.put("tithe_farm", FEMALE_TITHE_OBTAINED);
		obtained.put("abyssal_sire", Collections.singletonList(item(4151)));
		obtained.put("some_provider_key", Collections.singletonList(item(11286)));
		ClogResult result = new ClogResult("Probe", obtained, Collections.emptyMap(),
			Collections.emptyMap(), null, null);

		Map<String, int[]> progress = index.tabProgress(result, new int[]{9, 10});
		assertEquals(Arrays.asList("Bosses", "Minigames", "Other"), new ArrayList<>(progress.keySet()));
		assertArrayEquals(new int[]{2, 3}, progress.get("Bosses"));
		assertArrayEquals(new int[]{7, 7}, progress.get("Minigames"));
		assertArrayEquals(new int[]{0, 0}, progress.get("Other"));

		assertTrue(new ClogIndex().tabProgress(result, new int[]{9, 10}).isEmpty());

		// Nine distinct items are itemized here. They still speak for a count of
		// ten, but not for an account that has logged 1,189, and not for a log
		// that arrived without a denominator: those keep every tab to browse, its count unknown.
		assertArrayEquals(new int[]{2, 3}, index.tabProgress(result, new int[]{10, 1561}).get("Bosses"));
		for (int[] totals : new int[][]{{11, 1561}, {1189, 1561}, {0, 0}})
		{
			Map<String, int[]> partial = index.tabProgress(result, totals);
			assertArrayEquals(new int[]{-1, 3}, partial.get("Bosses"));
			assertArrayEquals(new int[]{-1, 7}, partial.get("Minigames"));
		}
	}

	@Test
