			{20449, 8844}, {24478, 13226}, {24482, 13639}, {24555, 20661},
			{25541, 25539}, {25584, 25582}, {26382, 26376}, {26858, 26850},
			{27235, 27226}, {28142, 28140}, {28585, 28583}, {29998, 29996}
		};
		for (int[] pair : pairs)
		{
			assertEquals(pair[1], index.canonicalItemId(pair[0]));
