package com.killclog;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/** Where a right-click offers a Kill Clog lookup: a Jagex interface change breaks this silently, in game only. */
public class ClogLookupMenuTest
{
	private static final KillClogConfig ALL_ON = new KillClogConfig()
	{
	};

	@Test
	public void eachListOffersTheLookupBesideItsOwnOption()
	{
		int chat = InterfaceID.CHATBOX << 16 | 5;
		int pm = InterfaceID.PM_CHAT << 16 | 3;
		int friends = InterfaceID.FRIENDS << 16 | 11;
		int ignore = InterfaceID.IGNORE << 16 | 11;
		int channel = InterfaceID.CHATCHANNEL_CURRENT << 16 | 8;
		int gim = InterfaceID.GIM_SIDEPANEL << 16 | 4;
		Object[][] table = {
			{chat, "Add ignore", true}, {chat, "Message", true}, {chat, "Report", false},
			{pm, "Add ignore", true}, {pm, "Message", true},
			{friends, "Delete", true}, {friends, "Message", false},
			{ignore, "Delete", true},
			{channel, "Add ignore", true}, {channel, "Remove friend", true}, {channel, "Kick", false},
			{InterfaceID.ClansSidepanel.PLAYERLIST, "Add ignore", true},
			{InterfaceID.ClansSidepanel.PLAYERLIST, "Remove friend", true},
			{InterfaceID.ClansSidepanel.PLAYERLIST, "Message", false},
			{InterfaceID.ClansGuestSidepanel.PLAYERLIST, "Add ignore", true},
			{gim, "Add friend", true}, {gim, "Remove friend", true}, {gim, "Remove ignore", true},
			{InterfaceID.BANKMAIN << 16 | 12, "Delete", false},
		};
		for (Object[] row : table)
		{
			List<String> looked = new ArrayList<>();
			boolean added = offer(ALL_ON, (int) row[0], (String) row[1], "<col=ffffff>Foo_Bar</col>", looked);
			assertEquals(row[0] + " " + row[1], row[2], added);
			if (added)
			{
				assertEquals("tags and the underscore go: the name as Jagex spells it", List.of("Foo Bar"), looked);
			}
		}
	}

	@Test
	public void eachListsSettingTurnsItsLookupOff()
	{
		KillClogConfig noChat = new KillClogConfig()
		{
			@Override
			public boolean menuOnChat()
			{
				return false;
			}
		};
		KillClogConfig noLookups = new KillClogConfig()
		{
			@Override
			public boolean playerMenuLookup()
			{
				return false;
			}
		};
		int chat = InterfaceID.CHATBOX << 16 | 5;
		assertFalse(offer(noChat, chat, "Message", "Foo", new ArrayList<>()));
		assertTrue(offer(noChat, InterfaceID.PM_CHAT << 16 | 3, "Message", "Foo", new ArrayList<>()));
		assertFalse(offer(noLookups, chat, "Message", "Foo", new ArrayList<>()));
	}

	@Test
	public void aFullPlayerMenuWarnsOnceASession()
	{
		ClogLookupMenu menu = new ClogLookupMenu();
		Client client = mock(Client.class);
		KillClogChatNotifier notifier = mock(KillClogChatNotifier.class);
		when(client.getPlayerOptions()).thenReturn(new String[]{"", "", "", "", "Trade", "Follow", "Report", "Walk"});
		menu.warnIfPlayerMenuSlotUnavailable(client, ALL_ON, notifier);
		menu.warnIfPlayerMenuSlotUnavailable(client, ALL_ON, notifier);
		verify(notifier, times(1)).send(eq(ChatNotice.WARNING), contains("Right-click menu is full"));

		ClogLookupMenu placed = new ClogLookupMenu();
		KillClogChatNotifier quiet = mock(KillClogChatNotifier.class);
		when(client.getPlayerOptions()).thenReturn(new String[]{"", "", "", "", "Trade", "Kill Clog", "Report", "Walk"});
		placed.warnIfPlayerMenuSlotUnavailable(client, ALL_ON, quiet);
		verifyNoInteractions(quiet);
	}

	/** Whether a right-click on this component and option gained a lookup entry; a click on it records the name. */
	private static boolean offer(KillClogConfig config, int componentId, String option, String target, List<String> looked)
	{
		MenuEntry source = mock(MenuEntry.class);
		when(source.getType()).thenReturn(MenuAction.CC_OP);
		when(source.getParam1()).thenReturn(componentId);
		when(source.getOption()).thenReturn(option);
		when(source.getTarget()).thenReturn(target);
		MenuEntry created = mock(MenuEntry.class, RETURNS_SELF);
		Menu gameMenu = mock(Menu.class);
		when(gameMenu.createMenuEntry(-2)).thenReturn(created);
		Client client = mock(Client.class);
		when(client.getMenu()).thenReturn(gameMenu);

		new ClogLookupMenu().addLookupEntry(new MenuEntryAdded(source), client, config, looked::add);
		boolean added = mockingDetails(gameMenu).getInvocations().stream()
			.anyMatch(call -> call.getMethod().getName().equals("createMenuEntry"));
		if (added)
		{
			org.mockito.ArgumentCaptor<java.util.function.Consumer<MenuEntry>> click =
				org.mockito.ArgumentCaptor.forClass(java.util.function.Consumer.class);
			verify(created).onClick(click.capture());
			click.getValue().accept(created);
		}
		return added;
	}
}

package com.killclog;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Every log a lookup shows is laid on the game's own pages: TempleOSRS files the Ring of 3rd Age under its Mimic and
 * keeps the Rare pages' leftovers on the tier pages, while the game lists the ring on Elite and Master and the
 * leftovers on the Rare pages (59 and 49 items, the wiki and the game's cache, 2026-10-12).
 */
public class ClogOnGamePagesTest
{
	private static final int RING_OF_3RD_AGE = 23185;
	private static final int LAVA_DRAGON_MASK = 12371;
	private static final int LIGHT_TUXEDO_JACKET = 25075;

	private static ClogResult templeLog()
	{
		Map<String, List<ClogResult.ClogItem>> obtained = new HashMap<>();
		obtained.put("mimic", Collections.singletonList(new ClogResult.ClogItem(RING_OF_3RD_AGE, 1, "2026-09-01")));
		obtained.put("elite_treasure_trails", Collections.singletonList(new ClogResult.ClogItem(LAVA_DRAGON_MASK, 2, null)));
		Map<String, List<Integer>> pages = new HashMap<>();
		pages.put("mimic", Collections.singletonList(RING_OF_3RD_AGE));
		pages.put("elite_treasure_trails", Arrays.asList(LAVA_DRAGON_MASK, LIGHT_TUXEDO_JACKET));
		ClogResult log = new ClogResult("Marni", obtained, pages, null, null, AccountType.REGULAR);
		log.setUniqueObtained(1703);
		return log.withSources(true, false, false);
	}

	private static Map<String, List<Integer>> gamePages()
	{
		Map<String, List<Integer>> pages = new HashMap<>();
		pages.put("elite_treasure_trails", Arrays.asList(RING_OF_3RD_AGE, LIGHT_TUXEDO_JACKET));
		pages.put("elite_treasure_trails_rare", Collections.singletonList(LAVA_DRAGON_MASK));
		return pages;
	}

	@Test
	public void eachGamePageHoldsWhatTheLogHasWhereverTheSourceFiledIt()
	{
		ClogResult laid = templeLog().onPages(gamePages(), id -> id);

		assertEquals(Arrays.asList(RING_OF_3RD_AGE, LIGHT_TUXEDO_JACKET), laid.getCategoryItems().get("elite_treasure_trails"));
		assertArrayEquals(new int[]{1, 2}, ClogHelper.clogCounts("elite_treasure_trails", laid));
		assertArrayEquals(new int[]{1, 1}, ClogHelper.clogCounts("elite_treasure_trails_rare", laid));
		assertEquals(2, laid.getObtainedItems().get("elite_treasure_trails_rare").get(0).getCount());
	}

	@Test
	public void pagesTheGameDoesNotHaveKeepWhatTheSourceSent()
	{
		ClogResult laid = templeLog().onPages(gamePages(), id -> id);

		// Kill Clog's Mimic row reads the ring from here, as before.
		assertArrayEquals(new int[]{1, 1}, ClogHelper.clogCounts("mimic", laid));
	}

	@Test
	public void theLaidLogKeepsItsProvenanceAndCounters()
	{
		ClogResult laid = templeLog().onPages(gamePages(), id -> id);

		assertTrue(laid.isFromTemple());
		assertEquals(1703, laid.getUniqueObtained());
		assertEquals("Marni", laid.getPlayerName());
	}

	@Test
	public void aPageTheSourceNeverKnewStaysUnknownRatherThanEmpty()
	{
		Map<String, List<Integer>> pages = gamePages();
		pages.put("all_pets", Collections.singletonList(13071));

		ClogResult laid = templeLog().onPages(pages, id -> id);

		assertNull("no key and none of its items: not synced, not 0 of 1", laid.getCategoryItems().get("all_pets"));
	}

	@Test
	public void anItemFiledUnderAVariantIdCountsAsTheGamesId()
	{
		Map<String, List<ClogResult.ClogItem>> obtained = new HashMap<>();
		obtained.put("elite_treasure_trails", Collections.singletonList(new ClogResult.ClogItem(99999, 1, null)));
		ClogResult log = new ClogResult("Marni", obtained, new HashMap<>(), null, null, null);

		ClogResult laid = log.onPages(gamePages(), id -> id == 99999 ? RING_OF_3RD_AGE : id);

		assertArrayEquals(new int[]{1, 2}, ClogHelper.clogCounts("elite_treasure_trails", laid));
	}

	@Test
	public void beforeTheClientHasReadTheLogTheLogIsShownAsSent()
	{
		ClogResult log = templeLog();
		assertSame(log, log.onPages(Collections.emptyMap(), id -> id));
		assertSame(log, new ClogIndex().laid(log));
		assertNull(new ClogIndex().laid(null));
	}

	@Test
	public void theGamesIndexLaysALogOnItsPages()
	{
		ClogIndex index = new ClogIndex();
		index.publishForTest(gamePages(), Collections.emptyMap());

		ClogResult laid = index.laid(templeLog());

		assertArrayEquals(new int[]{1, 2}, ClogHelper.clogCounts("elite_treasure_trails", laid));
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.hiscore.HiscoreSkill;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ClogPagesTest
{
	@Test
	public void aPageOpensABossPopupOnlyWhenThePageIsThatBosss()
	{
		assertEquals(HiscoreSkill.ZULRAH, ClogPages.pageBoss("zulrah", "Zulrah"));
		// A page in its own name: Moons of Peril is the Lunar Chests.
		assertEquals(HiscoreSkill.LUNAR_CHESTS, ClogPages.pageBoss("moons_of_peril", "Moons of Peril"));
		// A page shared by a boss's modes opens the one it is named for.
		assertEquals(HiscoreSkill.CHAMBERS_OF_XERIC, ClogPages.pageBoss("chambers_of_xeric", "Chambers of Xeric"));
		assertEquals(HiscoreSkill.NIGHTMARE, ClogPages.pageBoss("the_nightmare", "The Nightmare"));
		// Pages shared by bosses, and pages no boss holds, have their own popups.
		assertNull(ClogPages.pageBoss("dagannoth_kings", "Dagannoth Kings"));
		assertNull(ClogPages.pageBoss("callisto_and_artio", "Callisto and Artio"));
		assertNull(ClogPages.pageBoss("barbarian_assault", "Barbarian Assault"));
	}

	@Test
	public void everyPanelBossHasAPageInTheGamesLog()
	{
		JsonObject seed = new Gson().fromJson(new InputStreamReader(
			ClogPagesTest.class.getResourceAsStream("clog-structure-seed.json"), StandardCharsets.UTF_8), JsonObject.class);
		Set<String> pages = new HashSet<>();
		for (JsonElement tab : seed.getAsJsonArray("tabs"))
		{
			for (JsonElement page : tab.getAsJsonObject().getAsJsonArray("pages"))
			{
				pages.add(page.getAsJsonObject().get("key").getAsString());
			}
		}
		for (HiscoreSkill boss : PanelData.BOSSES)
		{
			if (boss == HiscoreSkill.MIMIC)
			{
				// Its one slot, the 3rd age ring, sits on the clue pages; the plugin keeps a page of its own for it.
				continue;
			}
			String key = ClogService.bossToCategory(PanelData.hiscoreName(boss.getName()));
			assertTrue(boss.getName() + " has no page " + key, pages.contains(key));
		}
	}
}

package com.killclog;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ClogPbsTest
{
	private Client client;
	private ConfigManager configManager;
	private ClogPbs pbs;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		configManager = mock(ConfigManager.class);
		pbs = new ClogPbs(configManager);
		when(client.getLocalPlayer()).thenReturn(mock(Player.class));
	}

	/** The page header's lines, as the game draws them: the page name first. */
	private void page(String... lines)
	{
		Widget[] children = new Widget[lines.length];
		for (int i = 0; i < lines.length; i++)
		{
			children[i] = mock(Widget.class);
			when(children[i].getText()).thenReturn(lines[i]);
		}
		Widget header = mock(Widget.class);
		when(header.getDynamicChildren()).thenReturn(children);
		when(client.getWidget(InterfaceID.Collection.HEADER_TEXT)).thenReturn(header);
	}

	private int cycle = 1000;

	/** The server sends a line's time, as it does a client cycle before it draws that page. */
	private void sends(int varp, int ticks)
	{
		when(client.getVarpValue(varp)).thenReturn(ticks);
		when(client.getGameCycle()).thenReturn(++cycle);
		pbs.varpChanged(client, varp);
	}

	/** The log draws the page on screen: once as it opens, then once or twice more as it settles. */
	private void draws(int times)
	{
		when(client.getGameCycle()).thenReturn(++cycle);
		for (int i = 0; i < times; i++)
		{
			pbs.pageDrawn(client);
		}
		cycle += 15;
	}

	@Test
	public void aPageWithItsLineKeepsTheGamesTimeInTicks()
	{
		page("Vorkath", "Obtained: <col=ffff00>5/6</col>", "Personal Best: <col=ffffff>1:02.40</col>",
			"Vorkath kills: <col=ffffff>500</col>");
		sends(VarPlayerID.COLLECTION_PERSONAL_BEST_TRANSMIT, 104);
		draws(3);
		verify(configManager, times(1)).setRSProfileConfiguration("killclog", "pagepb.vorkath", 62.4);
	}

	@Test
	public void theGauntletsTwoLinesAndTheColosseumsName()
	{
		page("The Gauntlet", "Obtained: <col=ffff00>3/9</col>", "Personal Best: <col=ffffff>2:00</col>",
			"Personal Best Corrupted: <col=ffffff>6:00</col>");
		sends(VarPlayerID.COLLECTION_PERSONAL_BEST_TRANSMIT, 200);
		sends(VarPlayerID.COLLECTION_PERSONAL_BEST_TRANSMIT_2, 600);
		draws(1);
		verify(configManager).setRSProfileConfiguration("killclog", "pagepb.gauntlet", 120.0);
