	@Test
	public void yourOwnLogNeverWaitsLongForItsDates() throws Exception
	{
		// 10/23: at login the date check took longer than every source's 7 s, the own log timed out with it, and the
		// panel asked for setup over a saved log. Past a short wait the log shows without Temple's dates.
		String player = "Own Log";
		AtomicInteger requests = new AtomicInteger();
		String templeJson = "{\"data\":{\"game_mode\":1,\"last_changed\":\"2026-09-06 12:00:00\",\"items\":{\"zulrah\":"
			+ "[{\"id\":1,\"count\":1,\"date\":\"2026-09-06 12:00:00\"}]}}}";
		ClogService service = activeService(player, null, templeJson, "{\"data\":{}}", requests, new AtomicInteger(),
			600);
		long wait = ClogService.ownLogDatesWaitMs;
		ClogService.ownLogDatesWaitMs = 100;
		try
		{
			long start = System.currentTimeMillis();
			ClogResult own = service.lookup(player).get(2, TimeUnit.SECONDS);
			long took = System.currentTimeMillis() - start;
			assertTrue("shown in " + took + " ms", took < 500);
			assertNotNull(own);
			assertTrue(own.isFromLocal());
			assertFalse("shown before Temple's dates came", own.isFromTemple());
			assertNull(own.getObtainedItems().get("zulrah").get(0).getDate());

			// The date check kept running, and its dates are there for the next look, without asking Temple again.
			Thread.sleep(900);
			ClogResult next = service.lookup(player).get(2, TimeUnit.SECONDS);
			assertTrue(next.isFromTemple());
			assertEquals("2026-09-06 12:00:00", next.getObtainedItems().get("zulrah").get(0).getDate());
			assertEquals(1, requests.get());
		}
		finally
		{
			ClogService.ownLogDatesWaitMs = wait;
		}
	}

	private static void assertSelfSources(ClogResult local, List<String> expected)
	{
		ClogResult combined = ClogProviderFanout.lookup(true,
			() -> CompletableFuture.completedFuture(local),
			() ->
			{
				throw new AssertionError("self must not fetch RuneProfile clog");
			},
			() ->
			{
				throw new AssertionError("self must not require a web sync");
			}).join();
		assertTrue(combined.isFromLocal());
		ClogSummaryTooltip tooltip = new ClogSummaryTooltip();
		tooltip.setClogSources(combined, false, false, false);
		assertEquals(expected, TestViews.sourceNames(tooltip));
	}

	private static ClogService serviceWithWarmCatalog(LocalClogCache cache) throws Exception
	{
		ClogService service = new ClogService(null, new Gson(), cache);
		return service;
	}

	private static ClogService activeService(String player, String localDate,
		String templeJson, AtomicInteger requests) throws Exception
	{
		return activeService(player, localDate, templeJson, "{\"data\":{\"info\":{}}}", requests, new AtomicInteger());
	}

	/** {@code requests} counts collection log requests, {@code statsRequests} stats ones; each URL gets its answer. */
	private static ClogService activeService(String player, String localDate, String templeJson, String statsJson,
		AtomicInteger requests, AtomicInteger statsRequests) throws Exception
	{
		return activeService(player, localDate, templeJson, statsJson, requests, statsRequests, 0);
	}

	/** As above, each answer {@code delayMs} late. */
	private static ClogService activeService(String player, String localDate, String templeJson, String statsJson,
		AtomicInteger requests, AtomicInteger statsRequests, long delayMs) throws Exception
	{
		Map<String, List<ClogResult.ClogItem>> obtained = new HashMap<>();
		obtained.put("zulrah", Collections.singletonList(
			new ClogResult.ClogItem(1, 1, localDate)));
		Map<String, List<Integer>> categories = new HashMap<>();
		categories.put("zulrah", Arrays.asList(1, 2, 3));

		LocalClogCache cache = LocalClogCacheTest.ready();
		StoreLogin.activate(cache, player, 1L);
		cache.cacheFirstPartyResult(new ClogResult(player, obtained, categories,
			Collections.emptyMap(), localDate, null));

		OkHttpClient client = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				boolean stats = chain.request().url().encodedPath().endsWith("player_stats.php");
				(stats ? statsRequests : requests).incrementAndGet();
				if (delayMs > 0)
				{
					try
					{
						Thread.sleep(delayMs);
					}
					catch (InterruptedException e)
					{
						Thread.currentThread().interrupt();
					}
				}
				return new Response.Builder()
					.request(chain.request())
					.protocol(Protocol.HTTP_1_1)
					.code(200)
					.message("OK")
					.body(ResponseBody.create(MediaType.parse("application/json"), stats ? statsJson : templeJson))
					.build();
			})
			.build();
		ClogService service = new ClogService(client, new Gson(), cache);
		return service;
	}

	/** One of a player's TempleOSRS moments, written as the service writes them. */
	static void moment(ClogService service, String key, String name, Object value)
	{
		TestViews.call(service, "note", key, (java.util.function.Consumer<Object>) t -> TestViews.set(t, name, value));
	}
}

package com.killclog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class ClogStructureTest
{
	// What killclog.com serves: the game's structure with The Fractured Archive, as 140 verified clients reported it
	// (2026-10-20) and the server hashed it.
	private static final String SERVER_SEED_HASH = "13c735f9eec3ac18";

	private static JsonObject seed()
	{
		return new Gson().fromJson(new InputStreamReader(
			ClogStructureTest.class.getResourceAsStream("clog-structure-seed.json"), StandardCharsets.UTF_8),
			JsonObject.class);
	}

	/** A ClogIndex holding exactly what a structure lists, as the client's own parse would. */
	private static ClogIndex indexOf(JsonObject structure)
	{
		Map<String, List<Integer>> items = new HashMap<>();
		Map<String, List<String>> tabs = new LinkedHashMap<>();
		Map<String, String> names = new HashMap<>();
		for (JsonElement tab : structure.getAsJsonArray("tabs"))
		{
			List<String> keys = new ArrayList<>();
			for (JsonElement element : tab.getAsJsonObject().getAsJsonArray("pages"))
			{
				JsonObject page = element.getAsJsonObject();
				String key = page.get("key").getAsString();
				keys.add(key);
				names.put(key, page.get("name").getAsString());
				List<Integer> ids = new ArrayList<>();
				page.getAsJsonArray("items").forEach(id -> ids.add(id.getAsInt()));
				items.put(key, ids);
			}
			tabs.put(tab.getAsJsonObject().get("name").getAsString(), keys);
		}
		ClogIndex index = new ClogIndex();
		index.publishForTest(items, new HashMap<>(), tabs, new HashMap<>(), names);
		return index;
	}

	@Test
	public void theClientsStructureHashesAsTheServerHashesTheSameOne()
	{
		JsonObject seed = seed();
		JsonObject built = ClogStructure.of(indexOf(seed));
		assertNotNull(built);
		assertEquals(seed.get("tabs"), built.get("tabs"));
		// Names with apostrophes (Kree'arra, Vet'ion) hash as the server writes them, unescaped.
		assertEquals(SERVER_SEED_HASH, ClogStructure.hash(new Gson(), built));
	}

	@Test
	public void beforeTheClientHasReadTheLogThereIsNothingToShare()
	{
		assertNull(ClogStructure.of(new ClogIndex()));
	}

	@Test
	public void theSyncSharesTheStructureOnlyWhenTheServerHoldsAnother()
	{
		JsonObject seed = seed();
		SyncService sync = new SyncService(null, new Gson());
		sync.setClogIndex(indexOf(seed));
		// Before any reply names the server's structure, nothing goes.
		assertNull(sync.structureToShare());
		sync.outcome(reply("{\"clog_structure_hash\":\"" + SERVER_SEED_HASH + "\"}"), "Me", 1, 0);
		assertNull(sync.structureToShare());
		sync.outcome(reply("{\"clog_structure_hash\":\"0000000000000000\"}"), "Me", 1, 0);
		JsonObject shared = sync.structureToShare();
		assertNotNull(shared);
		assertEquals(seed.get("tabs"), shared.get("tabs"));
		// A reply without the field (an older server) leaves what it knew.
		sync.outcome(reply("{}"), "Me", 1, 0);
		assertNotNull(sync.structureToShare());
	}

	@Test
	public void aLookupIsMeasuredAgainstTheGamesOwnPagesOnceTheClientHasReadThem()
		throws ReflectiveOperationException
	{
		ClogService provider = new ClogService(null, new Gson(), null);
		Field catalog = ClogService.class.getDeclaredField("cachedCategories");
		catalog.setAccessible(true);
		Map<String, List<Integer>> temple = new HashMap<>();
		temple.put("master_treasure_trails", Arrays.asList(101, 102, 103, 104));
		temple.put("chaos_druids", Arrays.asList(301, 302));
		catalog.set(provider, temple);
		KillclogService service = new KillclogService(null, new Gson(), provider);
		String json = "{\"rsn\":\"420 kc\",\"clog\":{\"items_by_category\":{"
			+ "\"master_treasure_trails\":[{\"item_id\":101,\"quantity\":1}]}}}";

		// Before the client has read the log, the provider catalog stands in.
		assertEquals(4, service.parseProofView("420 kc", json, "420 kc")
			.getCategoryItems().get("master_treasure_trails").size());

		JsonObject game = new JsonObject();
		JsonArray tabs = new JsonArray();
		game.add("tabs", tabs);
		JsonObject tab = new JsonObject();
		tab.addProperty("name", "Clues");
		JsonArray pages = new JsonArray();
		pages.add(page("Master Treasure Trails", "master_treasure_trails", 101, 102, 103));
		pages.add(page("Elder Chaos Druids", "elder_chaos_druids", 301, 302));
		tab.add("pages", pages);
		tabs.add(tab);
		service.setClogIndex(indexOf(game));
		ClogResult result = service.parseProofView("420 kc", json, "420 kc");
		assertEquals(Arrays.asList(101, 102, 103), result.getCategoryItems().get("master_treasure_trails"));
		// The game's own pages, not the provider's: Elder Chaos Druids, never chaos_druids.
		assertEquals(2, result.getCategoryItems().get("elder_chaos_druids").size());
		assertNull(result.getCategoryItems().get("chaos_druids"));
	}

	private static JsonObject page(String name, String key, int... ids)
	{
		JsonObject page = new JsonObject();
		page.addProperty("name", name);
		page.addProperty("key", key);
		JsonArray items = new JsonArray();
		for (int id : ids)
		{
			items.add(id);
		}
		page.add("items", items);
		return page;
	}

	private static HttpUtil.HttpResult reply(String body)
	{
		return new HttpUtil.HttpResult(200, body);
	}

	@Test
	public void aPageReadHalfWayFailsTheWholeRead()
	{
		// One tab of two pages: Zulrah reads whole, the second page's struct has no name or items.
		net.runelite.api.Client client = org.mockito.Mockito.mock(net.runelite.api.Client.class);
