		assertEquals(inset + (tip.getHeaderHeight() - 32) / 2, top);
		assertTrue(bottom < inset + tip.getHeaderHeight());
		int titleWidth = tip.getFontMetrics(tip.getTitleFont()).stringWidth("Collection Log");
		assertTrue(inset + titleWidth < left);
	}

