	@Test
	public void pageRowsWearTheirProgressionColorsWhenTheHighlighterIsOn()
	{
		java.awt.Color done = new java.awt.Color(1, 2, 3);
		java.awt.Color oneLeft = new java.awt.Color(4, 5, 6);
		java.awt.Color going = new java.awt.Color(7, 8, 9);
		java.awt.Color none = new java.awt.Color(10, 11, 12);
		KillClogConfig progress = new KillClogConfig()
		{
			@Override
			public java.awt.Color completedClogColor()
			{
				return done;
			}

			@Override
			public java.awt.Color missing1Color()
			{
				return oneLeft;
			}

			@Override
			public java.awt.Color inProgressClogColor()
			{
				return going;
			}

			@Override
			public java.awt.Color emptyClogColor()
			{
				return none;
			}
		};
		String[] names = {"Zulrah", "Vorkath", "Giant Mole", "Obor", "Bryophyta"};
		int[] obtained = {10, 9, 3, 0, -1};
		int[] total = {10, 10, 10, 10, 10};
		ClogTabTooltip colored = new ClogTabTooltip();
		colored.setTab("Bosses", new int[]{22, 50}, 50);
		colored.setPages(names, obtained, total, progress);
		ClogTabTooltip plain = new ClogTabTooltip();
		plain.setTab("Bosses", new int[]{22, 50}, 50);
		plain.setPages(names, obtained, total, null);

		java.util.Set<Integer> shown = colors(colored);
		for (java.awt.Color color : new java.awt.Color[]{done, oneLeft, going, none})
		{
			assertTrue(color.toString(), shown.contains(color.getRGB()));
			assertTrue(color.toString(), !colors(plain).contains(color.getRGB()));
		}
		// The empty page's count follows its name: the log's red only shows with the highlighter off.
		assertTrue(colors(plain).contains(TitleTooltip.CLOG_RED.getRGB()));
		assertTrue(!shown.contains(TitleTooltip.CLOG_RED.getRGB()));
	}

	private static java.util.Set<Integer> colors(ClogTabTooltip card)
	{
		Dimension size = card.getPreferredSize();
		card.setSize(size);
		BufferedImage image = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		card.paint(graphics);
		graphics.dispose();
		java.util.Set<Integer> colors = new java.util.HashSet<>();
		for (int y = 0; y < size.height; y++)
		{
			for (int x = 0; x < size.width; x++)
			{
				colors.add(image.getRGB(x, y));
			}
		}
		return colors;
	}

	private static ClogTabTooltip card(int pages)
	{
		String[] names = new String[pages];
		int[] obtained = new int[pages];
		int[] total = new int[pages];
		Arrays.fill(names, "Thermonuclear Smoke Devil");
		Arrays.fill(total, 9);
		ClogTabTooltip card = new ClogTabTooltip();
		card.setTab("Bosses", new int[]{12, 34}, 34);
		card.setPages(names, obtained, total, null);
		return card;
	}

	private static ClogTabTooltip painted(ClogTabTooltip card)
	{
		Dimension size = card.getPreferredSize();
		card.setSize(size);
		Graphics2D graphics = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB).createGraphics();
		card.paint(graphics);
		graphics.dispose();
		return card;
	}

	/** The first y that answers as the first page in view, found the way a pointer would. */
	private static int firstRowY(ClogTabTooltip card)
	{
		for (int y = 0; y < card.getHeight(); y++)
		{
			if (TestViews.rowAt(card, "pageRows", y) == offset(card))
			{
				return y;
			}
		}
		throw new AssertionError("no pages painted");
	}

	private static void wheel(ClogTabTooltip card, int y, int notches)
	{
		for (MouseWheelListener listener : card.getMouseWheelListeners())
		{
			listener.mouseWheelMoved(new MouseWheelEvent(card, MouseEvent.MOUSE_WHEEL, 0, 0, 5, y, 0, false,
				MouseWheelEvent.WHEEL_UNIT_SCROLL, 3, notches));
		}
	}

	private static void press(ClogTabTooltip card, int y)
	{
		press(card, 5, y);
	}

	private static void press(ClogTabTooltip card, int x, int y)
	{
		for (MouseListener listener : card.getMouseListeners())
		{
			listener.mousePressed(new MouseEvent(card, MouseEvent.MOUSE_PRESSED, 0, 0, x, y, 1, false, MouseEvent.BUTTON1));
		}
	}

	private static void drag(ClogTabTooltip card, int x, int y)
	{
		for (MouseMotionListener listener : card.getMouseMotionListeners())
		{
			listener.mouseDragged(new MouseEvent(card, MouseEvent.MOUSE_DRAGGED, 0, 0, x, y, 0, false, MouseEvent.BUTTON1));
		}
	}

	private static void release(ClogTabTooltip card, int x, int y)
	{
		for (MouseListener listener : card.getMouseListeners())
		{
			listener.mouseReleased(new MouseEvent(card, MouseEvent.MOUSE_RELEASED, 0, 0, x, y, 1, false, MouseEvent.BUTTON1));
		}
	}

	/** The first page in view. */
	private static int offset(ClogTabTooltip card)
	{
		return card.scroll().offset() / NativeTooltip.LINE_HEIGHT;
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Delayed;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

/** Shared disk-writer doubles for the cache tests. Each models one timing
 *  shape of the single writer thread; every class here is deterministic and
 *  never spawns real async work. This file intentionally holds several
 *  package-private top-level classes so call sites read like the real thing. */
final class ClogTestExecutors
{
	private ClogTestExecutors()
	{
	}
}

/** Runs everything inline: disk tasks execute synchronously so tests can
 *  assert real files in a temp dir. */
final class InlineScheduledExecutorService extends ScheduledThreadPoolExecutor
{
	InlineScheduledExecutorService()
	{
		super(1);
	}

	@Override
	public void execute(Runnable command)
	{
		command.run();
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
	{
		command.run();
		return new CompletedScheduledFuture();
	}
}

/** execute() runs inline; scheduled (debounced) tasks NEVER fire on their
 *  own - they stay queued so the drain path can be exercised. */
final class DeferredScheduledExecutorService extends ScheduledThreadPoolExecutor
{
	DeferredScheduledExecutorService()
	{
		super(1);
	}

	@Override
	public void execute(Runnable command)
	{
		command.run();
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
	{
		return new CompletedScheduledFuture();
	}
}

/** The inverse of CapturingScheduledExecutorService: debounced (scheduled)
 *  saves queue until fired by hand while execute() runs inline, modeling
 *  a pending capture save outliving an identity change. */
final class CapturingScheduledDebounceService extends ScheduledThreadPoolExecutor
{
	private final List<Runnable> queued = new ArrayList<>();

	CapturingScheduledDebounceService()
	{
		super(1);
	}

	@Override
	public void execute(Runnable command)
	{
		command.run();
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
	{
		queued.add(command);
		return new CompletedScheduledFuture();
	}

	void runQueued()
	{
		List<Runnable> toRun = new ArrayList<>(queued);
		queued.clear();
		for (Runnable r : toRun)
		{
			r.run();
		}
	}
}

/** Debounced saves run inline; execute() calls queue until runQueued(),
 *  modeling the gap between a decision and its disk task. */
final class CapturingScheduledExecutorService extends ScheduledThreadPoolExecutor
{
	private final List<Runnable> queued = new ArrayList<>();

	CapturingScheduledExecutorService()
	{
		super(1);
	}

	@Override
	public void execute(Runnable command)
	{
		queued.add(command);
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
	{
		command.run();
		return new CompletedScheduledFuture();
	}

	void runQueued()
	{
		List<Runnable> toRun = new ArrayList<>(queued);
		queued.clear();
		for (Runnable r : toRun)
		{
			r.run();
		}
	}
}

final class NoopScheduledExecutorService extends ScheduledThreadPoolExecutor
{
	NoopScheduledExecutorService()
	{
		super(1, r ->
		{
			Thread t = new Thread(r, "kill-clog-test-disk");
			t.setDaemon(true);
			return t;
		});
		shutdown();
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
	{
		return new CompletedScheduledFuture();
	}
}

final class CompletedScheduledFuture implements ScheduledFuture<Object>
{
	@Override
	public long getDelay(TimeUnit unit)
	{
		return 0;
	}

	@Override
	public int compareTo(Delayed other)
	{
		return 0;
	}

	@Override
	public boolean cancel(boolean mayInterruptIfRunning)
	{
		return false;
	}

	@Override
	public boolean isCancelled()
	{
		return false;
	}

	@Override
	public boolean isDone()
	{
		return true;
	}

	@Override
	public Object get()
	{
		return null;
	}

	@Override
	public Object get(long timeout, TimeUnit unit)
	{
		return null;
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.lang.reflect.Method;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClogUnlockHistoryTest
{
	private final String date = ClogDates.local(Instant.now().minusSeconds(120).toString());

	@Test
	public void ambiguousHatResolvesOnceAndSurvivesSerialization()
	{
		PlayerClogData data = new PlayerClogData();
		data.pendingUnlocks = List.of(new PendingClogUnlock(List.of(2991, 2992), date, "owner"));
		data = new Gson().fromJson(new Gson().toJson(data), PlayerClogData.class);
		Map<String, List<ClogResult.ClogItem>> obtained = items(2991);
		obtained.put("second_category", new ArrayList<>(obtained.get("hats")));
		assertTrue(PendingClogUnlock.reconcile(data.pendingUnlocks, obtained, "owner").isEmpty());
		assertEquals(date, obtained.get("hats").get(0).getDate());
		assertEquals(date, obtained.get("second_category").get(0).getDate());
		ClogResult result = new ClogResult("Tester", obtained, Map.of(), Map.of(), null, null);
		assertEquals(1, LookupQueries.getRecentItems(result, 5).size());
		assertEquals(2991, LookupQueries.getRecentItems(result, 5).get(0).getId());
	}

	@Test
	public void multipleCandidatesAndHistoricalImportsNeverInventDates()
	{
		Map<String, List<ClogResult.ClogItem>> obtained = items(2991, 2992);
		PendingClogUnlock.reconcile(List.of(new PendingClogUnlock(List.of(2991, 2992), date, "owner")), obtained, "owner");
		for (ClogResult.ClogItem item : obtained.get("hats")) assertNull(item.getDate());
		PendingClogUnlock.reconcile(null, obtained, "owner");
		assertNull(obtained.get("hats").get(0).getDate());
	}

	@Test
	public void unmatchedEvidenceWaitsAcrossDaysButInvalidDatesCannotReachRecent()
	{
		PendingClogUnlock event = new PendingClogUnlock(List.of(2991, 2992), date, "owner");
		assertEquals(1, PendingClogUnlock.reconcile(List.of(event), items(2978), "owner").size());
		Map<String, List<ClogResult.ClogItem>> obtained = items(2991);
		PendingClogUnlock older = new PendingClogUnlock(List.of(2991, 2992),
			ClogDates.local(Instant.now().minusSeconds(172800).toString()), "owner");
		assertTrue(PendingClogUnlock.reconcile(List.of(older), obtained, "owner").isEmpty());
		assertEquals(older.date, obtained.get("hats").get(0).getDate());
		Map<String, List<ClogResult.ClogItem>> invalid = items(2991);
		PendingClogUnlock.reconcile(List.of(new PendingClogUnlock(List.of(2991, 2992), "bad", "owner")), invalid, "owner");
		assertNull(invalid.get("hats").get(0).getDate());
	}

	@Test
	public void payloadAndProofViewRoundTripAcquisitionDatesOnly() throws Exception
	{
		SyncService service = new SyncService(null, new Gson());
		Method build = SyncService.class.getDeclaredMethod("buildBody", long.class, AccountType.class,
			ClogResult.class, Map.class, Map.class, long.class);
		build.setAccessible(true);
		Map<String, List<ClogResult.ClogItem>> obtained = items(2991, 2992);
		obtained.get("hats").set(0, new ClogResult.ClogItem(2991, 1, date));
		ClogResult clog = new ClogResult("Tester", obtained, Map.of(), Map.of(), null, null);
		JsonObject body = (JsonObject) build.invoke(service, 123L, null, clog, Map.of(), Map.of(), -1L);
		JsonArray payload = body.getAsJsonArray("clog");
		assertEquals(ClogDates.iso(date), payload.get(0).getAsJsonObject().get("obtained_at").getAsString());
		assertFalse(payload.get(1).getAsJsonObject().has("obtained_at"));
		JsonObject categories = new JsonObject();
		categories.add("hats", payload);
		JsonObject wrapper = new JsonObject();
		wrapper.add("items_by_category", categories);
		JsonObject proof = new JsonObject();
		proof.add("clog", wrapper);
		ClogResult parsed = new KillclogService(null, new Gson(), null).parseProofView("Tester", proof.toString(), "tester");
		assertEquals(date, parsed.getObtainedItems().get("hats").get(0).getDate());
		assertNull(parsed.getObtainedItems().get("hats").get(1).getDate());
	}

	@Test
	public void sessionGapKeepsEvidenceUntilTheOwnerReturns()
	{
		List<PendingClogUnlock> pending = List.of(new PendingClogUnlock(List.of(2991, 2992), date, "owner"));
		Map<String, List<ClogResult.ClogItem>> obtained = items(2991);
		List<PendingClogUnlock> waiting = PendingClogUnlock.reconcile(pending, obtained, null);
		assertEquals(pending, waiting);
		assertNull(obtained.get("hats").get(0).getDate());
		PendingClogUnlock.reconcile(waiting, obtained, "owner");
		assertEquals(date, obtained.get("hats").get(0).getDate());
		assertNull(PendingClogUnlock.reconcile(null, obtained, "owner"));
	}

	@Test
	public void malformedAndFutureDatesAreIgnored()
	{
		assertNull(ClogDates.iso("2026-02-30 12:00:00"));
		assertNull(ClogDates.iso("<html>untrusted"));
		assertNull(ClogDates.iso(Instant.now().plusSeconds(3600).toString()));
	}

	private static Map<String, List<ClogResult.ClogItem>> items(int... ids)
	{
		List<ClogResult.ClogItem> items = new ArrayList<>();
		for (int id : ids) items.add(new ClogResult.ClogItem(id, 1, null));
		Map<String, List<ClogResult.ClogItem>> result = new HashMap<>();
		result.put("hats", items);
		return result;
	}
}

