package com.killclog;

import java.util.HashMap;
import org.junit.Test;
import static com.killclog.LookupTestFixture.*;
import static org.junit.Assert.*;

public class ComparisonLifecycleTest
{
	@Test
	public void exitCancelsPendingLookupBeforeHiscoreAndAfterHiscore() throws Exception
	{
		for (boolean hiscoreFirst : new boolean[]{false, true})
		{
			LookupTestFixture fixture = new LookupTestFixture();
			edt(() -> fixture.comparison.doCompareLookup("Red", "Blue", null));
			if (hiscoreFirst)
			{
				fixture.hiscores.get("Red").complete(hiscore(2));
				edt(() -> assertTrue(fixture.comparison.isCompareLookupInFlight()));
			}
			edt(fixture.comparison::exit);
			fixture.hiscores.get("Red").complete(hiscore(2));
			if (hiscoreFirst) fixture.clogs.get("Red").complete(clog("Red"));
			fixture.cas.get("Red").complete(ca(2));
			edt(() -> assertFalse(fixture.comparison.isComparisonMode()));
			assertEquals(0, fixture.events("onComparisonEnter"));
			assertEquals(1, fixture.events("onComparisonExit"));
			assertNull(fixture.comparison.getCompareCaResult());
		}
	}

	@Test
	public void quietResetFencesBothSessionsAndAcceptsFreshLookups() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() ->
		{
			fixture.comparison.doCompareLookup("Red", "Blue", null);
			fixture.primary.start("Green", null, null);
			fixture.comparison.reset();
			fixture.primary.reset();
		});
		HashMap<String, Integer> before = new HashMap<>(fixture.events);
		fixture.hiscores.get("Red").complete(hiscore(2));
		fixture.hiscores.get("Green").complete(hiscore(3));
		fixture.clogs.get("Green").complete(clog("Green"));
		fixture.cas.get("Green").complete(ca(3));
		fixture.cas.get("Red").complete(ca(2));
		edt(() -> assertEquals(before, fixture.events));
		assertNull(fixture.primary.getHiscoreResult());
		assertNull(fixture.comparison.getCompareHiscoreResult());
		edt(() -> fixture.primary.start("Fresh", null, null));
		fixture.hiscores.get("Fresh").complete(hiscore(4));
		// A finished hiscore is shown with its clog, so the clog lane settles first.
		fixture.clogs.get("Fresh").complete(clog("Fresh"));
		edt(() -> assertEquals(4, fixture.primary.getHiscoreResult().getTotalLevel()));
		edt(() -> fixture.comparison.doCompareLookup("Other", "Fresh", null));
		assertTrue(fixture.hiscores.containsKey("Other"));
	}

	@Test
	public void cancelAfterPrimarySettlementStillFencesOptionalCa() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.primary.start("Green", null, null));
		fixture.hiscores.get("Green").complete(hiscore(3));
		edt(() ->
		{
			assertFalse(fixture.primary.isLookupInFlight());
			fixture.primary.cancelInFlight();
		});
		fixture.cas.get("Green").complete(ca(3));
		fixture.clogs.get("Green").complete(clog("Green"));
		edt(() -> assertNull(fixture.primary.getCaResult()));
		assertEquals(0, fixture.events("onCaResult"));
		assertEquals(0, fixture.events("onClogResult"));
	}

	@Test
	public void failedComparisonFencesLateCa() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.comparison.doCompareLookup("Missing", "Blue", null));
		fixture.hiscores.get("Missing").complete(null);
		edt(() -> assertEquals(1, fixture.events("onCompareError")));
		fixture.cas.get("Missing").complete(ca(3));
		edt(() -> assertNull(fixture.comparison.getCompareCaResult()));
		assertFalse(fixture.comparison.isComparisonMode());
	}
}

package com.killclog;

import org.junit.Test;
import static com.killclog.LookupTestFixture.*;
import static org.junit.Assert.*;

public class ComparisonSnapshotTest
{
	@Test
	public void replacementPublishesOnePlayerForEveryCaArrivalOrder() throws Exception
	{
		for (int caStage = 0; caStage < 3; caStage++)
		{
			for (boolean clogPresent : new boolean[]{false, true})
			{
				LookupTestFixture fixture = new LookupTestFixture();
				commitFirstPlayer(fixture);
				edt(() -> fixture.comparison.doCompareLookup("Second", "Blue", null));
				assertPlayer(fixture, "First", 2, "First", 2);
				if (caStage == 0) fixture.cas.get("Second").complete(ca(3));
				fixture.hiscores.get("Second").complete(hiscore(3));
				edt(() -> assertTrue(fixture.comparison.isCompareLookupInFlight()));
				if (caStage == 1) fixture.cas.get("Second").complete(ca(3));
				assertPlayer(fixture, "First", 2, "First", 2);
				assertEquals(1, fixture.events("onComparisonEnter"));
				fixture.clogs.get("Second").complete(clogPresent ? clog("Second") : null);
				assertPlayer(fixture, "Second", 3, clogPresent ? "Second" : null, caStage < 2 ? 3 : null);
				assertFalse(fixture.comparison.isCompareLookupInFlight());
				if (caStage == 2) fixture.cas.get("Second").complete(ca(3));
				assertPlayer(fixture, "Second", 3, clogPresent ? "Second" : null, 3);
				assertEquals(2, fixture.events("onComparisonEnter"));
			}
		}
	}

	@Test
	public void aNewComparisonTakesThePlaceOfOneStillLoading() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		commitFirstPlayer(fixture);
		edt(() -> fixture.comparison.doCompareLookup("Second", "Blue", null));
		edt(() -> fixture.comparison.doCompareLookup("Third", "Blue", null));
		assertTrue(fixture.hiscores.containsKey("Third"));
		// Second's answers arrive late and paint nothing: its log is never even asked for.
		fixture.cas.get("Second").complete(ca(3));
		fixture.hiscores.get("Second").complete(hiscore(3));
		edt(() -> assertFalse(fixture.clogs.containsKey("Second")));
		assertPlayer(fixture, "First", 2, "First", 2);
		fixture.cas.get("Third").complete(ca(4));
		fixture.hiscores.get("Third").complete(hiscore(4));
		edt(() -> fixture.clogs.get("Third").complete(clog("Third")));
		assertPlayer(fixture, "Third", 4, "Third", 4);
	}

	@Test
	public void failedReplacementRetainsTheWholePreviousPlayer() throws Exception
	{
		for (boolean error : new boolean[]{false, true})
		{
			LookupTestFixture fixture = new LookupTestFixture();
			commitFirstPlayer(fixture);
			edt(() -> fixture.comparison.doCompareLookup("Missing", "Blue", null));
			fixture.cas.get("Missing").complete(ca(3));
			if (error) fixture.hiscores.get("Missing").completeExceptionally(new IllegalStateException("fixture"));
			else fixture.hiscores.get("Missing").complete(null);
			assertPlayer(fixture, "First", 2, "First", 2);
			assertFalse(fixture.comparison.isCompareLookupInFlight());
			assertEquals(1, fixture.events("onCompareError"));
			assertEquals(0, fixture.events("onCompareDataReady"));
		}
	}

	@Test
	public void failedClogCommitsAbsentClogInsteadOfKeepingAnotherPlayersItems() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		commitFirstPlayer(fixture);
		edt(() -> fixture.comparison.doCompareLookup("Second", "Blue", null));
		fixture.hiscores.get("Second").complete(hiscore(3));
		edt(() -> fixture.clogs.get("Second").completeExceptionally(new IllegalStateException("fixture")));
		assertPlayer(fixture, "Second", 3, null, null);
	}

	@Test
	public void mirrorCommitsBlueSnapshotAndFencesPreviousLateCa() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.comparison.doCompareLookup("First", "Blue", null));
		fixture.hiscores.get("First").complete(hiscore(2));
		edt(() -> fixture.clogs.get("First").complete(clog("First")));
