	@Test
	public void aMirrorsLineOutlastsTheComparisonOpening() throws Exception
	{
		// Entering a comparison clears the status line; the mirror's line comes after it, so it stays on screen.
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.comparison.doCompareLookup("Blue", "Blue", null));
		int entered = fixture.order.lastIndexOf("onComparisonEnter");
		assertTrue(entered >= 0);
		assertTrue(fixture.order.lastIndexOf("onCompareStatus") > entered);
	}

	@Test
	public void aLateCaKeepsTheLocalPlayersOwnAccountType() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		// The local player, a group ironman the hiscores read as regular, on the red side.
		edt(() -> fixture.comparison.doCompareLookup("Me", "Me", AccountType.GROUP_IRONMAN));
		fixture.hiscores.get("Me").complete(hiscore(2));
		edt(() -> fixture.clogs.get("Me").complete(clog("Me")));
		assertEquals(AccountType.GROUP_IRONMAN, redSelfType(fixture));
		fixture.cas.get("Me").complete(ca(5));
		assertPlayer(fixture, "Me", 2, "Me", 5);
		assertEquals(AccountType.GROUP_IRONMAN, redSelfType(fixture));
	}

	private static AccountType redSelfType(LookupTestFixture fixture) throws Exception
	{
		AccountType[] type = new AccountType[1];
		edt(() ->
		{
			try
			{
				java.lang.reflect.Field compared = ComparisonController.class.getDeclaredField("compared");
				compared.setAccessible(true);
				Object red = compared.get(fixture.comparison);
				java.lang.reflect.Field selfType = red.getClass().getDeclaredField("selfType");
				selfType.setAccessible(true);
				type[0] = (AccountType) selfType.get(red);
			}
			catch (ReflectiveOperationException e)
			{
				throw new AssertionError(e);
			}
		});
		return type[0];
	}

	private static void commitFirstPlayer(LookupTestFixture fixture) throws Exception
	{
		edt(() -> fixture.comparison.doCompareLookup("First", "Blue", null));
		fixture.cas.get("First").complete(ca(2));
		fixture.hiscores.get("First").complete(hiscore(2));
		edt(() -> fixture.clogs.get("First").complete(clog("First")));
		assertPlayer(fixture, "First", 2, "First", 2);
	}

	private static void assertPlayer(LookupTestFixture fixture, String name, int level,
		String clogName, Integer points) throws Exception
	{
		edt(() ->
		{
			ComparisonController comparison = fixture.comparison;
			assertTrue(comparison.isComparisonMode());
			assertEquals(name, comparison.getCompareRsn());
			assertEquals(level, comparison.getCompareHiscoreResult().getTotalLevel());
			assertEquals(clogName, comparison.getCompareClogResult() == null
				? null : comparison.getCompareClogResult().getPlayerName());
			assertEquals(points, comparison.getCompareCaResult() == null
				? null : Integer.valueOf(comparison.getCompareCaResult().getTotalPoints()));
		});
	}
}

package com.killclog;

import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.mockito.InOrder;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ConfigMigrationsTest
{
	@Test
	public void wikiLinksTurnedOffStayOffAsCardLinks()
	{
		ConfigManager off = mock(ConfigManager.class);
		when(off.getConfiguration("killclog", "wikiItemLinks")).thenReturn("false");
		ConfigMigrations.run(off);
		verify(off).setConfiguration("killclog", "cardLinks", CardLinks.OFF);
		verify(off).unsetConfiguration("killclog", "wikiItemLinks");

		// Left on, they're the default: nothing to keep but the old key to clear.
		ConfigManager on = mock(ConfigManager.class);
		when(on.getConfiguration("killclog", "wikiItemLinks")).thenReturn("true");
		ConfigMigrations.run(on);
		verify(on, org.mockito.Mockito.never()).setConfiguration(org.mockito.ArgumentMatchers.eq("killclog"),
			org.mockito.ArgumentMatchers.eq("cardLinks"), org.mockito.ArgumentMatchers.<Object>any());
		verify(on).unsetConfiguration("killclog", "wikiItemLinks");
	}

	@Test
	public void aCardLinkOpensOnAClickAShiftClickOnlyOrNever()
	{
		java.awt.Component card = new java.awt.Canvas();
		java.awt.event.MouseEvent click = new java.awt.event.MouseEvent(card, java.awt.event.MouseEvent.MOUSE_PRESSED,
			0, 0, 1, 1, 1, false, java.awt.event.MouseEvent.BUTTON1);
		java.awt.event.MouseEvent shiftClick = new java.awt.event.MouseEvent(card, java.awt.event.MouseEvent.MOUSE_PRESSED,
			0, java.awt.event.InputEvent.SHIFT_DOWN_MASK, 1, 1, 1, false, java.awt.event.MouseEvent.BUTTON1);
		org.junit.Assert.assertTrue(CardLinks.ON.opens(click));
		org.junit.Assert.assertTrue(CardLinks.ON.opens(shiftClick));
		org.junit.Assert.assertFalse(CardLinks.SHIFT.opens(click));
		org.junit.Assert.assertTrue(CardLinks.SHIFT.opens(shiftClick));
		org.junit.Assert.assertFalse(CardLinks.OFF.opens(click));
		org.junit.Assert.assertFalse(CardLinks.OFF.opens(shiftClick));
	}

	@Test
	public void characterCredentialsKeptBefore270AreCleared()
	{
		ConfigManager config = mock(ConfigManager.class);
		when(config.getConfigurationKeys("killclog-profile-appearance.")).thenReturn(java.util.List.of(
			"killclog-profile-appearance.1.production.deviceSecret",
			"killclog-profile-appearance.1.production.recoveryToken"));

		ConfigMigrations.run(config);

		verify(config).unsetConfiguration("killclog-profile-appearance", "1.production.deviceSecret");
		verify(config).unsetConfiguration("killclog-profile-appearance", "1.production.recoveryToken");
	}

	@Test
	public void skillSummaryOnlyPlayersMoveToTheActivityTray()
	{
		ConfigManager config = mock(ConfigManager.class);
		when(config.getConfiguration("killclog", "skillDisplay")).thenReturn("TOOLTIP");

		ConfigMigrations.run(config);

		verify(config).setConfiguration("killclog", "skillDisplay", SkillDisplay.TRAY);
	}

	@Test
	public void savedSettingsMoveAtStartUpBeforeThePanelIsBuiltAndNeverAtInjection() throws Exception
	{
		// RuneLite injects a plugin that is turned off too: handing it its config changes nothing.
		ConfigManager config = mock(ConfigManager.class);
		when(config.getConfiguration("killclog", "skillDisplay")).thenReturn("TOOLTIP");
		KillClogPlugin plugin = new KillClogPlugin();
		plugin.provideConfig(config);
		verify(config, never()).setConfiguration(anyString(), anyString(), any(Object.class));

		// Started, the move comes first, then the panel, which reads its skill location as it is built.
		@SuppressWarnings("unchecked")
		javax.inject.Provider<KillClogPanel> panels = mock(javax.inject.Provider.class);
		when(panels.get()).thenThrow(new IllegalStateException("built"));
		set(plugin, "configManager", config);
		set(plugin, "panelProvider", panels);
		try
		{
			plugin.startUp();
		}
		catch (IllegalStateException built)
		{
			// The panel was asked for; nothing after it is under test here.
		}
		InOrder order = inOrder(config, panels);
		order.verify(config).setConfiguration("killclog", "skillDisplay", SkillDisplay.TRAY);
		order.verify(panels).get();
	}

	private static void set(Object target, String name, Object value) throws ReflectiveOperationException
	{
		java.lang.reflect.Field field = KillClogPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}

	@Test
	public void everyOtherSkillLocationIsLeftAlone()
	{
		for (String saved : new String[]{"FIXED", "TRAY", null})
		{
			ConfigManager config = mock(ConfigManager.class);
			when(config.getConfiguration("killclog", "skillDisplay")).thenReturn(saved);

			ConfigMigrations.run(config);

			verify(config, never()).setConfiguration(eq("killclog"), eq("skillDisplay"), any(Object.class));
		}
	}

	@Test
	public void legacyCompletionColourStillBecomesAColourModeOnce()
	{
		ConfigManager config = mock(ConfigManager.class);
		when(config.getConfiguration("killclog", "skillCompletionColor")).thenReturn("false");

		ConfigMigrations.run(config);

		verify(config).setConfiguration("killclog", "skillColorMode", SkillColorMode.SKILL_COLOR);
		verify(config).unsetConfiguration("killclog", "skillCompletionColor");

		// A mode the player already chose is never overwritten by the legacy value.
		ConfigManager chosen = mock(ConfigManager.class);
		when(chosen.getConfiguration("killclog", "skillCompletionColor")).thenReturn("true");
		when(chosen.getConfiguration("killclog", "skillColorMode")).thenReturn("CLOG_PROGRESSION");

		ConfigMigrations.run(chosen);

		verify(chosen, never()).setConfiguration(anyString(), eq("skillColorMode"), any(Object.class));
		verify(chosen).unsetConfiguration("killclog", "skillCompletionColor");
	}
}

package com.killclog;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * EHB rates resource integrity and computation. Rate values are read from the
 * bundled TempleOSRS table rather than hardcoded, so a rates refresh cannot
 * silently break the suite.
 */
public class EhbRatesTest
{
	private static HiscoreResult result(AccountType type, Map<String, Integer> kcs)
	{
		return TestViews.hiscore(type, HiscoreTable.STANDARD, kcs, new HashMap<>(),
			new HashMap<>(), new HashMap<>(), new HashMap<>(), 0, 0, 0, -1);
	}

	/** A boss Temple rates 0 for mains but positive for ironmen, or null. */
	private static String mainZeroIronPositiveBoss()
	{
		for (Map.Entry<String, double[]> e : TestViews.<java.util.Map<String, double[]>>field(EhbRates.class, "RATES").entrySet())
		{
			if (e.getValue()[0] == 0 && e.getValue()[1] > 0)
			{
				return e.getKey();
			}
		}
		return null;
	}

	@Test
	public void testEveryHiscoreBossHasRates()
	{
		Map<String, double[]> rates = TestViews.<java.util.Map<String, double[]>>field(EhbRates.class, "RATES");
		for (String boss : HiscoreService.bossNames())
		{
			double[] pair = rates.get(boss);
			assertNotNull("No EHB rates entry for " + boss, pair);
			assertEquals(2, pair.length);
			assertTrue(boss + " main rate negative", pair[0] >= 0);
			assertTrue(boss + " ironman rate negative", pair[1] >= 0);
		}
	}

	@Test
	public void testNoUnknownBossesInRates()
	{
		Set<String> known = new HashSet<>(Arrays.asList(HiscoreService.bossNames()));
		for (String boss : TestViews.<java.util.Map<String, double[]>>field(EhbRates.class, "RATES").keySet())
		{
			assertTrue("Rates entry is not a hiscore boss: " + boss, known.contains(boss));
		}
	}

	@Test
	public void testComputeSumsKcOverRate()
	{
		double vorkRate = TestViews.<java.util.Map<String, double[]>>field(EhbRates.class, "RATES").get("Vorkath")[0];
		double zulrahRate = TestViews.<java.util.Map<String, double[]>>field(EhbRates.class, "RATES").get("Zulrah")[0];
		assertTrue(vorkRate > 0 && zulrahRate > 0);

		Map<String, Integer> kcs = new HashMap<>();
		kcs.put("Vorkath", 340);
		kcs.put("Zulrah", 92);
		double expected = 340 / vorkRate + 92 / zulrahRate;
		assertEquals(expected,
			EhbRates.compute(result(AccountType.REGULAR, kcs), null), 1e-9);
	}

	@Test
	public void testZeroRateBossAwardsNothingOnMainButCountsForIronman()
	{
		String split = mainZeroIronPositiveBoss();
		if (split == null)
		{
			return;
		}
		Map<String, Integer> kcs = new HashMap<>();
		kcs.put(split, 1000);
		assertEquals(0, EhbRates.compute(result(AccountType.REGULAR, kcs), null), 1e-9);
		double imRate = TestViews.<java.util.Map<String, double[]>>field(EhbRates.class, "RATES").get(split)[1];
		assertEquals(1000 / imRate,
			EhbRates.compute(result(AccountType.IRONMAN, kcs), null), 1e-9);
	}

	@Test
	public void testResolvedGroupIronmanOutranksRegularHiscoreTag()
	{
		// GIMs only appear on the regular hiscores: the result arrives tagged
		// REGULAR and the provider-resolved type must still pick the ironman
		// column, or a GIM's Barrows-shaped hours silently vanish.
		String split = mainZeroIronPositiveBoss();
		if (split == null)
		{
			return;
		}
		Map<String, Integer> kcs = new HashMap<>();
		kcs.put(split, 1000);
		HiscoreResult regularTagged = result(AccountType.REGULAR, kcs);
		double imRate = TestViews.<java.util.Map<String, double[]>>field(EhbRates.class, "RATES").get(split)[1];
		assertEquals(1000 / imRate,
			EhbRates.compute(regularTagged, AccountType.GROUP_IRONMAN), 1e-9);
	}

	@Test
	public void testEveryIronmanModeUsesIronmanRates()
	{
		Map<String, Integer> kcs = new HashMap<>();
		kcs.put("Vorkath", 340);
		HiscoreResult regularTagged = result(AccountType.REGULAR, kcs);
		double im = EhbRates.compute(regularTagged, AccountType.IRONMAN);
		for (AccountType type : AccountType.values())
		{
			if (type == AccountType.REGULAR)
			{
				continue;
			}
			assertEquals("Ironman mode " + type + " diverged from ironman rates",
				im, EhbRates.compute(regularTagged, type), 1e-9);
		}
	}

	@Test
	public void testUnrankedKcAwardsNothing()
	{
		Map<String, Integer> kcs = new HashMap<>();
		kcs.put("Vorkath", -1);
		assertEquals(0, EhbRates.compute(result(AccountType.REGULAR, kcs), null), 1e-9);
	}

	@Test
	public void testNullResultIsAbsent()
	{
		assertEquals(-1, EhbRates.compute(null, null), 1e-9);
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class FirstPartyFeedbackTest
{
	private static final class Settings implements KillClogConfig
	{
		boolean silentAutomatic = true;

		@Override
		public boolean silentAutomaticSync()
		{
			return silentAutomatic;
		}
	}

	private final Settings config = new Settings();
	private final List<String> events = new ArrayList<>();
	private final List<StatusMessage.Kind> kinds = new ArrayList<>();
	private final FirstPartyFeedback feedback = feedback("sync failed");

	private FirstPartyFeedback feedback(String failureText)
	{
		return new FirstPartyFeedback(config,
			(kind, text, autoClear) ->
			{
				events.add(text);
				kinds.add(kind);
			}, () -> events.add("flash"), failureText);
	}

	@Test
	public void aRefusedVersionSaysUpdateNeededNotFailed()
	{
		feedback.complete(true, false, FirstPartyFeedback.UPDATE_REQUIRED + " Reference: 0123456789abcdef.");
		assertEquals(java.util.Arrays.asList("update needed"), events);
		assertEquals("update needed - restart RuneLite", feedback.hoverText("publish collection log", "publish failed"));
		feedback.complete(true, false, "Server unavailable");
		assertEquals("publish failed", feedback.hoverText("publish collection log", "publish failed"));
		feedback.complete(true, true, "Synced");
		assertEquals("publish collection log", feedback.hoverText("publish collection log", "publish failed"));
	}

	@Test
	public void automaticSyncIsSilentThroughProgressRetryFailureAndSuccess()
	{
		feedback.progress(false, "syncing...", false);
		feedback.progress(false, "retrying...", false);
		feedback.complete(false, false, "Server unavailable");
		assertEquals("Server unavailable", feedback.lastFailure());
		assertTrue(events.isEmpty());
		feedback.complete(false, true, "Synced");
		assertNull(feedback.lastFailure());
		assertTrue(events.isEmpty());
	}

	@Test
	public void manualSyncShowsProgressAndFailureButOnlyFlashesForSuccess()
	{
		feedback.progress(true, "syncing...", false);
		feedback.complete(true, false, "Account opted out");
		assertEquals(java.util.Arrays.asList("syncing...", "sync failed"), events);
		assertEquals("Account opted out", feedback.lastFailure());
		feedback.complete(true, true, "Synced");
		assertEquals(java.util.Arrays.asList("syncing...", "sync failed", "flash"), events);
		assertNull(feedback.lastFailure());
	}

	@Test
	public void manualActionsDoNotUnmuteAutomaticSync()
	{
		feedback.progress(false, "syncing...", false);
		feedback.complete(false, false, "Unavailable");
		assertTrue(events.isEmpty());
		feedback.progress(true, "syncing...", false);
		feedback.complete(true, false, "Unavailable");
		feedback.complete(true, true, "Synced");
		feedback.progress(false, "retrying...", false);
		assertEquals(java.util.Arrays.asList("syncing...", "sync failed", "flash"), events);
	}

	@Test
	public void automaticFeedbackCanBeEnabledWithoutChangingManualFeedback()
	{
		config.silentAutomatic = false;
		feedback.progress(false, "syncing...", false);
		feedback.complete(false, true, "Synced");
		feedback.progress(true, "syncing...", false);
		feedback.complete(true, true, "Synced");
		assertEquals(java.util.Arrays.asList("syncing...", "flash", "syncing...", "flash"), events);
	}

	@Test
	public void characterUploadAlwaysShowsManualFeedbackAndKeepsItsOwnFailure()
	{
		FirstPartyFeedback character = feedback("Publish failed");
		character.progress(true, "rendering...", false);
		character.complete(true, false, "Character upload failed");
		assertEquals(java.util.Arrays.asList("rendering...", "Publish failed"), events);
		feedback.complete(false, true, "Synced prerequisite");
		assertEquals("Character upload failed", character.lastFailure());
		character.complete(true, true, "Published");
		assertEquals(java.util.Arrays.asList("rendering...", "Publish failed", "flash"), events);
		assertNull(character.lastFailure());
		events.clear();
		config.silentAutomatic = false;
		character.progress(true, "rendering...", false);
		character.complete(true, false, "Unavailable");
		assertEquals(java.util.Arrays.asList("rendering...", "Publish failed"), events);
	}

	@Test
	public void changedPreferencesApplyToThePendingResultAndResetForgetsFailure()
	{
		config.silentAutomatic = false;
		feedback.progress(false, "syncing...", false);
		events.clear();
		config.silentAutomatic = true;
		feedback.complete(false, false, "Unavailable");
		assertTrue(events.isEmpty());
		feedback.reset();
		assertNull(feedback.lastFailure());
	}

	@Test
	public void progressNoticeAndFailureCarryTheirKind()
	{
		feedback.progress(true, "syncing...", false);
		feedback.complete(true, false, "Server unavailable");
		feedback.show(true, StatusMessage.Kind.NOTICE, "Change equipment, then retry", true);
		feedback.show(false, StatusMessage.Kind.RESULT, "Finishing previous request...", true);
		assertEquals(java.util.Arrays.asList("syncing...", "sync failed", "Change equipment, then retry"), events);
		assertEquals(java.util.Arrays.asList(StatusMessage.Kind.PROGRESS, StatusMessage.Kind.RESULT,
			StatusMessage.Kind.NOTICE), kinds);
	}
}

package com.killclog;

import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.WorldType;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class GameModeTest
{
	@Test
	public void onlyWorldsWithoutASeparateCharacterAreTheMainGame()
	{
		assertEquals("main", GameMode.of(EnumSet.noneOf(WorldType.class), null));
		assertEquals("main", GameMode.of(EnumSet.of(WorldType.MEMBERS, WorldType.PVP, WorldType.HIGH_RISK), "demonic-pacts"));
		assertEquals("main", GameMode.of(EnumSet.of(WorldType.SKILL_TOTAL, WorldType.BOUNTY, WorldType.LAST_MAN_STANDING), null));
		for (WorldType separate : new WorldType[]{WorldType.DEADMAN, WorldType.BETA_WORLD, WorldType.QUEST_SPEEDRUNNING,
			WorldType.FRESH_START_WORLD, WorldType.NOSAVE_MODE, WorldType.TOURNAMENT_WORLD})
		{
			assertNull(separate.name(), GameMode.of(EnumSet.of(WorldType.MEMBERS, separate), "demonic-pacts"));
		}
		assertNull(GameMode.of(null, "demonic-pacts"));
	}

	@Test
	public void aHardcoreWorldIsTheMainGameAndSaysSo()
	{
		assertEquals("main", GameMode.of(EnumSet.of(WorldType.MEMBERS, WorldType.HARDCORE_MAIN), "demonic-pacts"));
		assertTrue(GameMode.hardcore(EnumSet.of(WorldType.MEMBERS, WorldType.HARDCORE_MAIN)));
		assertTrue(GameMode.hardcore(EnumSet.of(WorldType.MEMBERS, WorldType.PVP, WorldType.HARDCORE_MAIN)));
		assertFalse("a main world", GameMode.hardcore(EnumSet.of(WorldType.MEMBERS)));
		assertFalse("a world with a separate character", GameMode.hardcore(EnumSet.of(WorldType.HARDCORE_MAIN, WorldType.DEADMAN)));
		assertFalse("a League world", GameMode.hardcore(EnumSet.of(WorldType.HARDCORE_MAIN, WorldType.SEASONAL)));
		assertFalse(GameMode.hardcore(null));
	}

	@Test
	public void onlyASettledHardcoreWorldReadsTheXp()
	{
		WorldSession world = new WorldSession(() -> GameMode.MAIN, () -> null, () -> null, id -> null, store ->
		{
		});
		Set<WorldType> hardcore = EnumSet.of(WorldType.MEMBERS, WorldType.HARDCORE_MAIN);
		assertEquals(0, world.hardcoreXp(hardcore, () -> 5_000));
		for (int tick = 0; tick < WorldSession.SETTLED_TICKS; tick++)
		{
			world.tick();
		}
		assertEquals(5_000, world.hardcoreXp(hardcore, () -> 5_000));
		assertEquals("a main-game world never reads it", -1,
			world.hardcoreXp(EnumSet.of(WorldType.MEMBERS), () -> 5_000));
		assertEquals(-1, world.hardcoreXp(null, () -> 5_000));
	}

	@Test
	public void aSeasonalWorldIsTheLeagueTheServerAnnounced()
	{
		assertEquals("demonic-pacts", GameMode.of(EnumSet.of(WorldType.SEASONAL, WorldType.MEMBERS), "demonic-pacts"));
		assertNull("no League announced, no mode", GameMode.of(EnumSet.of(WorldType.SEASONAL), null));
		assertNull("a seasonal Deadman world is not a League", GameMode.of(EnumSet.of(WorldType.SEASONAL, WorldType.DEADMAN), "demonic-pacts"));
	}
}

