package com.killclog;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.Interceptor;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class HiscoreFailureTest
{
	private static final String REGULAR = "/m=hiscore_oldschool/";
	private static final String IRON = "/m=hiscore_oldschool_ironman/";
	private static final String HARDCORE = "/m=hiscore_oldschool_hardcore_ironman/";

	// The real half-second wait before a board's retry changes nothing these tests check.
	@Before
	public void shortenRetries()
	{
		HiscoreService.retryDelayMs = 1;
	}

	@After
	public void restoreRetries()
	{
		HiscoreService.retryDelayMs = 500;
	}

	static String body(long xp)
	{
		return "{\"skills\":[{\"name\":\"Overall\",\"rank\":-1,\"level\":100,\"xp\":" + xp
			+ "},{\"name\":\"Defence\",\"rank\":2,\"level\":50,\"xp\":1000}],\"activities\":[]}";
	}

	static Response response(Interceptor.Chain chain, int code, String body)
	{
		return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
			.code(code).message("fixture").body(ResponseBody.create(MediaType.parse("text/plain"), body)).build();
	}

	@Test
	public void definiteAbsenceStopsEachTableAfterOneJsonRequest() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		HiscoreService service = service(chain ->
		{
			calls.incrementAndGet();
			assertTrue(chain.request().url().encodedPath().endsWith(".json"));
			return response(chain, 404, "");
		});
		assertNull(service.lookup("Missing", null).get(3, TimeUnit.SECONDS));
		assertEquals(4, calls.get());
	}

	@Test
	public void validZeroAndUnrankedRowsSurviveMissingSpecialtyTables() throws Exception
	{
		for (long xp : new long[]{0, -1})
		{
			AtomicInteger calls = new AtomicInteger();
			HiscoreService service = service(chain ->
			{
				calls.incrementAndGet();
				boolean regular = chain.request().url().encodedPath().startsWith(REGULAR);
				return response(chain, regular ? 200 : 404, regular ? body(xp) : "");
			});
			HiscoreResult result = service.lookup("Test", null).get(3, TimeUnit.SECONDS);
			assertNotNull(result);
			assertEquals(xp, result.getTotalXp());
			assertEquals(-1, result.getOverallRank());
			assertEquals(4, calls.get());
		}
	}

	@Test
	public void aMalformedAnswerIsUnavailableAfterOneRetryNeverMissing() throws Exception
	{
		for (String broken : new String[]{"{broken", "{}", "{\"skills\":[],\"activities\":[]}", "-1,100,12345\n-1,1,0"})
		{
			AtomicInteger calls = new AtomicInteger();
			HiscoreService service = service(chain ->
			{
				calls.incrementAndGet();
				String path = chain.request().url().encodedPath();
				assertTrue(path.endsWith("/index_lite.json"));
				return path.startsWith(REGULAR) ? response(chain, 200, broken) : response(chain, 404, "");
			});
			// The main board's bad body is retried once, then the board is unavailable: down, never "no such player".
			assertDown(service.lookup("Test", null));
			assertEquals(5, calls.get());
			assertFalse(service.notOnBoard("Test", RankLeaderboard.NORMAL));
		}
	}

	@Test
	public void malformedAnswersCountAgainstJagexLikeAnOutage() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		HiscoreService service = service(chain ->
		{
			calls.incrementAndGet();
			return response(chain, 200, "{broken");
		});
		assertDown(service.lookup("Test", null));
		int first = calls.get();
		assertDown(service.lookup("Other", null));
		assertEquals("Jagex is left alone while it answers nonsense", first, calls.get());
	}

	@Test
	public void anUnknownOrPartialRowNeverCostsTheBoard() throws Exception
	{
		String partial = body(5000).replace("\"activities\":[]", "\"activities\":[{\"name\":\"A Boss Added Today\"},"
			+ "{\"name\":\"Zulrah\",\"score\":12},{\"name\":\"Vorkath\",\"rank\":3,\"score\":40}]");
		AtomicInteger calls = new AtomicInteger();
		HiscoreService service = service(chain ->
		{
			calls.incrementAndGet();
			return chain.request().url().encodedPath().startsWith(REGULAR) ? response(chain, 200, partial)
				: response(chain, 404, "");
		});
		HiscoreResult result = service.lookup("Test", null).get(3, TimeUnit.SECONDS);
		assertEquals(5000, result.getTotalXp());
		assertEquals(40, result.getKc("Vorkath"));
		assertFalse(result.hasBossRow("Zulrah"));
		assertEquals("accepted first time, nothing retried", 4, calls.get());
	}

	@Test
	public void retryOnlyFailedTableAndNeverTreatAFailureAsAbsence() throws Exception
	{
		for (int failure : new int[]{429, 502, 503, 200})
		{
			Map<String, AtomicInteger> calls = new ConcurrentHashMap<>();
			HiscoreService service = service(chain ->
			{
				String path = chain.request().url().encodedPath();
				int count = calls.computeIfAbsent(path, ignored -> new AtomicInteger()).incrementAndGet();
				if (!path.startsWith(REGULAR)) return response(chain, 404, "");
				return response(chain, count == 1 ? failure : 200, count == 1 ? "{bad" : body(5000));
			});
			assertEquals(5000, service.lookup("Test", null).get(3, TimeUnit.SECONDS).getTotalXp());
			// An outage, a 429 or a bad body retries the JSON once.
			assertEquals(5, calls.values().stream().mapToInt(AtomicInteger::get).sum());
			assertEquals(2, calls.get(REGULAR + "index_lite.json").get());
		}
	}

	@Test
	public void persistentFailureHasFinitePerTableBudget() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		HiscoreService service = service(chain ->
		{
			calls.incrementAndGet();
			return response(chain, 503, "");
		});
		assertDown(service.lookup("Test", null));
		// Each of the four boards: its JSON and at most one retry; the breaker can trip before the last retries start.
		assertTrue("at most 8 requests, got " + calls.get(), calls.get() >= 5 && calls.get() <= 8);
		assertNull(service.getCached("Test"));
	}

	@Test
	public void anOutageTripsTheBreakerSoTheNextLookupSendsNothing() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		HiscoreService service = service(chain ->
		{
			calls.incrementAndGet();
			return response(chain, 503, "");
		});
		assertDown(service.lookup("Test", null));
		int first = calls.get();
		assertDown(service.lookup("Other", null));
		assertEquals("Jagex is left alone while it's down", first, calls.get());
	}

	@Test
	public void frozenHardcoreCannotOverrideFreshRegularAndIronRows() throws Exception
	{
		HiscoreService service = service(chain ->
		{
			String path = chain.request().url().encodedPath();
			if (path.startsWith(HARDCORE)) return response(chain, 200, body(1000));
			if (path.startsWith(REGULAR) || path.startsWith(IRON)) return response(chain, 200, body(2000));
			return response(chain, 404, "");
		});
		HiscoreResult result = service.lookup("Test", null).get(3, TimeUnit.SECONDS);
		assertEquals(AccountType.IRONMAN, result.getAccountType());
		assertEquals(2000, result.getTotalXp());
	}

	@Test
	public void failedOptionalRefinementRetainsValidBaseRow() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		HiscoreService service = service(chain ->
		{
			calls.incrementAndGet();
			String path = chain.request().url().encodedPath();
			String pure = body(1000).replace("\"level\":50", "\"level\":1")
				.replace("],\"activities\"", ",{\"name\":\"Attack\",\"rank\":2,\"level\":50,\"xp\":500}],\"activities\"");
			return response(chain, path.startsWith(REGULAR) ? 200 : 404, pure);
		});
		HiscoreResult result = service.lookup("Test", null).get(3, TimeUnit.SECONDS);
		assertEquals(1000, result.getTotalXp());
		assertEquals(HiscoreTable.STANDARD, result.getHiscoreTable());
		assertEquals(5, calls.get());
	}

	@Test
	public void eachLookupRecordsWhetherItsOwnAnswersMakeAnIronman() throws Exception
	{
		// Dead Hardcore: regular and Ironman match, the Hardcore row trails.
		HiscoreResult dead = service(boards(2000, 2000, 1000)).lookup("Test", null).get(3, TimeUnit.SECONDS);
		assertEquals(AccountType.IRONMAN, dead.getAccountType());
		assertEquals(Boolean.TRUE, dead.getIronmanNow());
		// De-ironed: the Ironman row trails the regular one.
		HiscoreResult deIroned = service(boards(2000, 1000, 404)).lookup("Test", null).get(3, TimeUnit.SECONDS);
		assertEquals(AccountType.REGULAR, deIroned.getAccountType());
		assertEquals(Boolean.FALSE, deIroned.getIronmanNow());
		// Never an Ironman: nothing to claim either way.
		assertNull(service(boards(2000, 404, 404)).lookup("Test", null).get(3, TimeUnit.SECONDS).getIronmanNow());
		// An Ironman row ahead of the regular one is a mismatched read, and says nothing either.
		assertNull(service(boards(2000, 2500, 404)).lookup("Test", null).get(3, TimeUnit.SECONDS).getIronmanNow());
		// RuneLite's own type answers it for a self lookup.
		assertEquals(Boolean.TRUE, service(boards(2000, 2000, 1000))
			.lookup("Test", AccountType.IRONMAN).get(3, TimeUnit.SECONDS).getIronmanNow());
		assertEquals(Boolean.FALSE, service(boards(2000, 1000, 404))
			.lookup("Test", AccountType.REGULAR).get(3, TimeUnit.SECONDS).getIronmanNow());
	}

	@Test
	public void anUnansweredIdentityBoardClaimsNoFormerMode() throws Exception
	{
		HiscoreResult hardcoreAtDeath = TestViews.hiscore(AccountType.HARDCORE_IRONMAN, java.util.Collections.emptyMap(),
			java.util.Collections.emptyMap(), java.util.Collections.emptyMap(), java.util.Collections.emptyMap(),
			java.util.Collections.emptyMap(), 100, 1000, 0, -1);

		// A dead Hardcore whose Ironman board fails reads as a main, but is never called de-ironed.
		HiscoreResult guessedMain = service(boards(2000, 500, 1000)).lookup("Test", null).get(5, TimeUnit.SECONDS);
		assertEquals(AccountType.REGULAR, guessedMain.getAccountType());
		assertNull(guessedMain.getIronmanNow());
		AccountDisplay main = AccountDisplay.of(guessedMain.getAccountType(), HiscoreTable.STANDARD);
		assertSame(main, main.shownOn(guessedMain.withRow(hardcoreAtDeath), RankLeaderboard.HARDCORE));

		// A de-ironed main whose regular board fails reads as an Ironman, but is never called a dead Hardcore.
		HiscoreResult guessedIron = service(boards(500, 1500, 1000)).lookup("Test", null).get(5, TimeUnit.SECONDS);
		assertEquals(AccountType.IRONMAN, guessedIron.getAccountType());
		assertNull(guessedIron.getIronmanNow());
		AccountDisplay iron = AccountDisplay.of(guessedIron.getAccountType(), HiscoreTable.STANDARD);
		assertSame(iron, iron.shownOn(guessedIron.withRow(hardcoreAtDeath), RankLeaderboard.HARDCORE));
	}

	@Test
	public void aWarmCacheNeverAnswersForALaterLookup() throws Exception
	{
		// First lookup: a dead Hardcore, every board answering.
		int[] answers = {2000, 2000, 1000};
		HiscoreService service = service(chain -> boards(answers[0], answers[1], answers[2]).intercept(chain));
		HiscoreResult first = service.lookup("Test", null).get(3, TimeUnit.SECONDS);
		assertEquals(Boolean.TRUE, first.getIronmanNow());

		// Later the player has trained and the Ironman board fails. The earlier Ironman row is
		// still cached, but this lookup's identity rests only on its own answers.
		answers[0] = 3000;
		answers[1] = 500;
		HiscoreResult later = service.lookup("Test", null).get(5, TimeUnit.SECONDS);
		assertEquals(AccountType.REGULAR, later.getAccountType());
		assertNull(later.getIronmanNow());
		assertEquals(Boolean.TRUE, first.getIronmanNow());
	}

	@Test
	public void jagexBeingDownIsNeverAMissingPlayer() throws Exception
	{
		// Down for the weekly update: every board fails, times out, shows a maintenance page or refuses.
		Interceptor[] outages = {
			chain -> response(chain, 503, ""),
			chain ->
			{
				throw new IOException("timed out");
			},
			chain -> response(chain, 200, "<html>We are updating the game</html>"),
			chain -> response(chain, 403, "Forbidden"),
		};
		for (Interceptor outage : outages)
		{
			for (AccountType known : new AccountType[]{null, AccountType.REGULAR, AccountType.IRONMAN})
			{
				assertDown(service(outage).lookup("Test", known));
			}
			assertDown(service(outage).lookupLeague("Test"));
		}
		assertEquals("Lookup failed", HiscoreService.failureText(new IllegalStateException("anything else")));
	}

	@Test
	public void onlyTheBoardsOwnNotFoundIsAMissingPlayer() throws Exception
	{
		Interceptor absent = chain -> response(chain, 404, "");
		for (AccountType known : new AccountType[]{null, AccountType.REGULAR, AccountType.IRONMAN})
		{
			assertNull(service(absent).lookup("Missing", known).get(3, TimeUnit.SECONDS));
		}
		assertNull(service(absent).lookupLeague("Missing").get(3, TimeUnit.SECONDS));
		// A League row still answers.
		assertEquals(5000, service(chain -> response(chain, 200, body(5000))).lookupLeague("Test")
			.get(3, TimeUnit.SECONDS).getTotalXp());
	}

	@Test
	public void aRowOnABoardThatIsNotTheMainOneNeverReadsAsMissingWhileTheRestAreDown() throws Exception
	{
		// The main and Ironman boards are down, the Ultimate board says no row, the Hardcore board has one.
		assertDown(service(chain ->
		{
			String path = chain.request().url().encodedPath();
			if (path.startsWith(HARDCORE))
			{
				return response(chain, 200, body(1000));
			}
			return response(chain, path.startsWith("/m=hiscore_oldschool_ultimate/") ? 404 : 503, "");
		}).lookup("Existing HC", null));
	}

	@Test
	public void aKnownSoloTypeIsDownWhenTheMainBoardIs() throws Exception
	{
		// The main board fails and the type's own board has no row: the main board decides, so Jagex is down.
		for (AccountType known : new AccountType[]{AccountType.IRONMAN, AccountType.HARDCORE_IRONMAN,
			AccountType.ULTIMATE_IRONMAN})
		{
			assertDown(service(chain -> response(chain,
				chain.request().url().encodedPath().startsWith(REGULAR) ? 503 : 404, "")).lookup("Test", known));
		}
	}

	@Test
	public void anEarlierNotFoundNeverDecidesALaterOutage() throws Exception
	{
		// The player is missing, then minutes later Jagex is down: the earlier answer must not stand in.
		int[] code = {404};
		HiscoreService service = service(chain -> response(chain, code[0], ""));
		assertNull(service.lookup("Recent rename", null).get(3, TimeUnit.SECONDS));
		code[0] = 503;
		assertDown(service.lookup("Recent rename", null));
		assertDown(service.lookup("Recent rename", AccountType.IRONMAN));
		assertDown(service.lookupLeague("Recent rename"));
	}

	@Test
	public void anEarlierLeagueNotFoundNeverDecidesALaterOutage() throws Exception
	{
		int[] code = {404};
		int[] asked = {0};
		HiscoreService service = service(chain ->
		{
			asked[0]++;
			return response(chain, code[0], "");
		});
		assertNull(service.lookupLeague("Recent rename").get(3, TimeUnit.SECONDS));
		code[0] = 503;
		assertDown(service.lookupLeague("Recent rename"));
		// A board that just said "not found" still goes unasked for its ranks.
		code[0] = 404;
		assertNull(service.lookupLeague("Recent rename").get(3, TimeUnit.SECONDS));
		int before = asked[0];
		assertNull(service.lookupTable("Recent rename", HiscoreService.LEAGUE_TABLE).get(3, TimeUnit.SECONDS));
		assertEquals(before, asked[0]);
	}

	private static void assertDown(CompletableFuture<HiscoreResult> lookup) throws Exception
	{
		try
		{
			lookup.get(5, TimeUnit.SECONDS);
			fail("an outage read as a lookup's answer");
		}
		catch (ExecutionException e)
		{
			assertEquals(HiscoreService.DOWN_MESSAGE, HiscoreService.failureText(e));
		}
	}

	/** Regular, Ironman and Hardcore answers by total XP; 404 is no row, 500 is a board that fails. */
	private static Interceptor boards(int regular, int iron, int hardcore)
	{
		return chain ->
		{
			String path = chain.request().url().encodedPath();
			int value = path.startsWith(REGULAR) ? regular : path.startsWith(IRON) ? iron
				: path.startsWith(HARDCORE) ? hardcore : 404;
			return value == 404 || value == 500 ? response(chain, value, "") : response(chain, 200, body(value));
		};
	}

	private static HiscoreService service(Interceptor interceptor)
	{
		return new HiscoreService(new OkHttpClient.Builder().addInterceptor(interceptor).build(), new Gson());
	}
}

package com.killclog;

import com.google.gson.Gson;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.*;

/** A Hardcore Worlds character's row comes from the table killclog.com names, only when the regular one has none. */
public class HiscoreHardcoreWorldsTest
{
	private static final String TABLE = "hiscore_oldschool_hardcore_worlds";

	private static HiscoreService service(List<String> asked, int regular, int hardcore, String named)
	{
		HiscoreService service = new HiscoreService(new OkHttpClient.Builder().addInterceptor(chain ->
		{
			String path = chain.request().url().encodedPath();
			asked.add(path);
			boolean there = path.startsWith("/m=" + TABLE + "/");
			int code = path.startsWith("/m=hiscore_oldschool/") ? regular : there ? hardcore : 404;
			return HiscoreFailureTest.response(chain, code, HiscoreFailureTest.body(there ? 1200 : 5000));
		}).build(), new Gson());
		service.setHardcoreTable(() -> named);
		return service;
	}

	@Test
	public void aCharacterOnlyThereReadsFromIt() throws Exception
	{
		for (AccountType type : new AccountType[]{null, AccountType.REGULAR})
		{
			List<String> asked = new CopyOnWriteArrayList<>();
			HiscoreResult result = service(asked, 404, 200, TABLE).lookup("Hc Tester", type).get(3, TimeUnit.SECONDS);
			assertNotNull(String.valueOf(type), result);
			assertEquals(1200, result.getTotalXp());
			assertEquals(AccountType.REGULAR, result.getAccountType());
		}
	}

	@Test
	public void theRegularRowWinsAndNoTableMeansNoAsk() throws Exception
	{
		List<String> asked = new CopyOnWriteArrayList<>();
		assertEquals(5000, service(asked, 200, 200, TABLE).lookup("Main", AccountType.REGULAR)
			.get(3, TimeUnit.SECONDS).getTotalXp());
		assertTrue(asked.toString(), asked.stream().noneMatch(path -> path.contains(TABLE)));

		asked.clear();
		assertNull(service(asked, 404, 200, null).lookup("Nobody", AccountType.REGULAR).get(3, TimeUnit.SECONDS));
		assertTrue(asked.toString(), asked.stream().noneMatch(path -> path.contains(TABLE)));
	}

	@Test
	public void notFoundStandsOnlyWhenBothSaySo() throws Exception
	{
		assertNull(service(new CopyOnWriteArrayList<>(), 404, 404, TABLE).lookup("Nobody", AccountType.REGULAR)
			.get(3, TimeUnit.SECONDS));
		try
		{
			service(new CopyOnWriteArrayList<>(), 404, 503, TABLE).lookup("Hc Tester", AccountType.REGULAR)
				.get(10, TimeUnit.SECONDS);
			fail("a table that answers nothing never says not found");
		}
		catch (ExecutionException e)
		{
			assertEquals(HiscoreService.DOWN_MESSAGE, HiscoreService.failureText(e));
		}
	}
}

package com.killclog;

import com.google.gson.Gson;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Scanner;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Name-keyed JSON hiscore parsing. The fixture is the real Jagex response
 * captured on Wyrmscraig launch day (2026-07-29), which bakes in the exact
 * conditions that once blanked positional parsing: Mad Angel newly inserted,
 * the Mimic/Maggot King reorder, and the Calvar'ion respelling.
 */
public class HiscoreJsonParsingTest
{
	private HiscoreService service;
	private String fixture;

	@Before
	public void setUp()
	{
		service = new HiscoreService(null, new Gson());
		fixture = readResource("hiscore-fixture-wyrmscraig.json");
	}

	private String readResource(String name)
	{
		InputStream in = getClass().getResourceAsStream(name);
		assertNotNull("missing test resource " + name, in);
		try (Scanner s = new Scanner(in, StandardCharsets.UTF_8.name()).useDelimiter("\\A"))
		{
			return s.next();
		}
	}

	@Test
	public void testDayOneBossParsesWithoutAnyListUpdate()
	{
		// The property the whole change exists for: a boss Jagex added this
		// morning parses correctly with no positional bookkeeping.
		HiscoreResult result = service.parseHiscoreBody(fixture, AccountType.REGULAR);
		assertEquals(0, result.getKc("Mad Angel"));
	}

	@Test
	public void testReorderedNeighborsKeyCorrectly()
	{
		// Mimic and Maggot King swapped feed positions in this update, beside the
		// newly inserted Mad Angel; by name the neighbours cannot cross.
		String[] names = {"Lunar Chests", "Mad Angel", "Maggot King", "Mimic", "Nex"};
		com.google.gson.JsonObject root = new Gson().fromJson(fixture, com.google.gson.JsonObject.class);
		for (com.google.gson.JsonElement e : root.getAsJsonArray("activities"))
		{
			com.google.gson.JsonObject row = e.getAsJsonObject();
			int i = java.util.Arrays.asList(names).indexOf(row.get("name").getAsString());
			if (i >= 0)
			{
				row.addProperty("score", 10 * (i + 1));
				row.addProperty("rank", 1000 + i);
			}
		}
		HiscoreResult result = service.parseHiscoreBody(new Gson().toJson(root), AccountType.REGULAR);
		assertEquals(10, result.getKc("Lunar Chests"));
		assertEquals(20, result.getKc("Mad Angel"));
		assertEquals(30, result.getKc("Maggot King"));
		assertEquals(40, result.getKc("Mimic"));
		assertEquals(50, result.getKc("Nex"));
		assertEquals(1001, result.getRank("Mad Angel"));
		assertEquals(1002, result.getRank("Maggot King"));
		assertEquals(1003, result.getRank("Mimic"));
	}

