			+ "\"activities\":[{\"id\":1000,\"name\":\"The Fractured Archive: Challenge Mode\",\"rank\":9,\"score\":3}]}";
		assertFalse(service.parseHiscoreBody(modeAlone, AccountType.REGULAR).hasBossRow(PanelData.TFA_HISCORE));
	}

