	/**
	 * A JSON hiscores answer: Overall, then every skill (the leading ones at {@code levels}
	 * in hiscore order, attack first; the rest 99), every activity at 100 and every boss at 420.
	 */
	private static String body(int overallRank, int totalLevel, long totalXp, int... levels)
	{
		StringBuilder sb = new StringBuilder("{\"skills\":[").append(skill("Overall", overallRank, totalLevel, totalXp));
		String[] skills = HiscoreService.skillNames();
		for (int i = 0; i < skills.length; i++)
		{
			String name = Character.toUpperCase(skills[i].charAt(0)) + skills[i].substring(1);
			sb.append(',').append(skill(name, 1, i < levels.length ? levels[i] : 99, 13034431L));
		}
		sb.append("],\"activities\":[");
		String separator = "";
		for (String name : TestViews.<String[]>field(HiscoreService.class, "ACTIVITY_NAMES"))
		{
			sb.append(separator).append(activity(name, 7, 100));
			separator = ",";
		}
		for (String name : HiscoreService.bossNames())
		{
			sb.append(',').append(activity(name, 50, 420));
		}
		return sb.append("]}").toString();
	}

	private static String skill(String name, int rank, int level, long xp)
	{
		return "{\"name\":\"" + name + "\",\"rank\":" + rank + ",\"level\":" + level + ",\"xp\":" + xp + "}";
	}

	private static String activity(String name, int rank, int score)
	{
		return "{\"name\":\"" + name + "\",\"rank\":" + rank + ",\"score\":" + score + "}";
	}

	@Test
	public void testMarkDirtyForcesStaleDespiteFreshCache()
	{
		long now = System.currentTimeMillis();
		HiscoreResult result = service.parseHiscoreBody(OVERALL_ONLY, AccountType.REGULAR);
		service.cacheResult("Zezima", result, now);
		assertFalse(service.isStale("Zezima"));

		service.markDirty("Zezima", now);
		assertTrue(service.isStale("Zezima"));
	}

	@Test
	public void testDirtyClearsWhenFetchLandsAfterSettleWindow()
	{
		long now = System.currentTimeMillis();
		HiscoreResult result = service.parseHiscoreBody(OVERALL_ONLY, AccountType.REGULAR);
		service.markDirty("Zezima", now);
		service.cacheResult("Zezima", result, now + 10_000);
		assertFalse(service.isStale("Zezima"));
	}

	@Test
	public void testDirtySurvivesFetchInsideSettleWindow()
	{
		// The row lands server-side seconds after a hop: a fetch inside the
		// settle window may still be pre-hop, so the mark must survive it.
		long now = System.currentTimeMillis();
		HiscoreResult result = service.parseHiscoreBody(OVERALL_ONLY, AccountType.REGULAR);
		service.markDirty("Zezima", now);
		service.cacheResult("Zezima", result, now + 3_000);
		assertTrue(service.isStale("Zezima"));
	}

	@Test
	public void testMarkDirtyIsCaseInsensitive()
	{
		long now = System.currentTimeMillis();
		HiscoreResult result = service.parseHiscoreBody(OVERALL_ONLY, AccountType.REGULAR);
		service.cacheResult("Zezima", result, now);
		service.markDirty("ZEZIMA", now);
		assertTrue(service.isStale("zezima"));
	}

	@Test
	public void testFetchClearsOnlyTheMarkItObserved()
	{
		// A second hop can re-mark while the first fetch is completing; the
		// stale fetch must not clear the newer mark. The cache is seeded
		// fresh so the assertion can only pass through the surviving mark.
		long now = System.currentTimeMillis();
		HiscoreResult result = service.parseHiscoreBody(OVERALL_ONLY, AccountType.REGULAR);
		service.cacheResult("Zezima", result, now);
		service.markDirty("Zezima", now);
		service.markDirty("Zezima", now + 5_000);
		service.clearMarkIfSettled("zezima", now, now + 10_000);
		assertTrue(service.isStale("Zezima"));
	}

	@Test
	public void testMarkDirtyLeavesOtherPlayersAlone()
	{
		long now = System.currentTimeMillis();
		HiscoreResult result = service.parseHiscoreBody(OVERALL_ONLY, AccountType.REGULAR);
		service.cacheResult("Woox", result, now);
		service.markDirty("Zezima", now);
		assertFalse(service.isStale("Woox"));
	}
}

package com.killclog;

import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static org.junit.Assert.*;

public class HttpSingleFlightTest
{
	private final Map<String, CompletableFuture<String>> flights = new ConcurrentHashMap<>();

	@Test
	public void timeoutCannotSuppressSourceCompletionOrServiceCleanup() throws Exception
	{
		CompletableFuture<String> transport = new CompletableFuture<>();
		AtomicInteger cached = new AtomicInteger();
		CompletableFuture<String> source = transport.thenApply(value ->
		{
			cached.incrementAndGet();
			return value;
		});
		CompletableFuture<String> first = HttpUtil.singleFlightLookup(flights, "player", () -> source);
		CompletableFuture<String> second = HttpUtil.singleFlightLookup(flights, "player", () -> source);
		assertNull(first.completeOnTimeout(null, 1, TimeUnit.MILLISECONDS).get(1, TimeUnit.SECONDS));
		assertFalse(source.isDone());
		assertFalse(second.isDone());
		transport.complete("late data");
		assertEquals("late data", second.join());
		assertEquals(1, cached.get());
		assertTrue(flights.isEmpty());
		assertEquals("fresh", HttpUtil.singleFlightLookup(flights, "player",
			() -> CompletableFuture.completedFuture("fresh")).join());
	}

	@Test
	public void immediateCompletionRemovesRegisteredFlightWithoutRecursiveUpdate()
	{
		assertEquals("ready", HttpUtil.singleFlightLookup(flights, "player",
			() -> CompletableFuture.completedFuture("ready")).join());
		assertTrue(flights.isEmpty());

		CompletableFuture<String> failed = new CompletableFuture<>();
		failed.completeExceptionally(new IllegalStateException("test failure"));
		assertTrue(HttpUtil.singleFlightLookup(flights, "player", () -> failed)
			.isCompletedExceptionally());
		assertTrue(flights.isEmpty());
	}

	@Test
	public void pendingRequestsShareOneFlightAndReleaseItOnCompletion()
	{
		AtomicInteger starts = new AtomicInteger();
		CompletableFuture<String> source = new CompletableFuture<>();
		java.util.function.Supplier<CompletableFuture<String>> start = () ->
		{
			starts.incrementAndGet();
			return source;
		};
		CompletableFuture<String> first = HttpUtil.singleFlightLookup(flights, "player", start);
		CompletableFuture<String> second = HttpUtil.singleFlightLookup(flights, "player", start);
		assertEquals(1, starts.get());
		assertSame(source, flights.get("player"));
		assertFalse(first.isDone());
		assertFalse(second.isDone());
		source.complete("ready");
		assertEquals("ready", first.join());
		assertEquals("ready", second.join());
		assertTrue(flights.isEmpty());
	}

	@Test
	public void aLookupStartedAsAFlightAnswersStartsAFreshOne()
	{
		AtomicInteger starts = new AtomicInteger();
		java.util.function.Supplier<CompletableFuture<String>> start = () ->
		{
			starts.incrementAndGet();
			return new CompletableFuture<>();
		};
		// The answer is spent: an outage after it must be fetched, not read from the old flight.
		CompletableFuture<String> next = HttpUtil.singleFlightLookup(flights, "player", start)
			.thenCompose(answer -> HttpUtil.singleFlightLookup(flights, "player", start));
		flights.get("player").complete(null);
		assertEquals(2, starts.get());
		assertFalse(next.isDone());
	}

	@Test
	public void lateExceptionalCompletionCannotRemoveReplacementFlight()
	{
		CompletableFuture<String> source = new CompletableFuture<>();
		CompletableFuture<String> first = HttpUtil.singleFlightLookup(flights, "player", () -> source);
		CompletableFuture<String> replacement = new CompletableFuture<>();
		flights.put("player", replacement);
		source.completeExceptionally(new IllegalStateException("test failure"));
		assertTrue(first.isCompletedExceptionally());
		assertSame(replacement, flights.get("player"));
	}
}

package com.killclog;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class HttpUtilLaneTest
{
	@Test
	public void aLaneHoldsAtMostTheCapAndTheStalestNameGoesFirst()
	{
		HttpUtil.Lane<String> lane = new HttpUtil.Lane<>(new CircuitBreaker("test"));
		for (int i = 0; i <= HttpUtil.CACHE_CAP; i++)
		{
			lane.ok("name" + i, "value" + i);
			lane.fetched.put("name" + i, 1_000L + i);
		}
		lane.ok("fresh", "value");
		assertEquals(HttpUtil.CACHE_CAP, lane.values.size());
		assertFalse("the name fetched longest ago went", lane.values.containsKey("name0"));
		assertFalse(lane.fetched.containsKey("name0"));
		assertTrue(lane.values.containsKey("fresh"));
	}

	@Test
	public void pastTheCapOnlyExpiredStampsGo()
	{
		Map<String, Long> stamps = new HashMap<>();
		long now = System.currentTimeMillis();
		for (int i = 0; i < HttpUtil.CACHE_CAP; i++)
		{
			stamps.put("old" + i, now - 10_000L);
		}
		stamps.put("live", now);
		HttpUtil.prune(stamps, 5_000L);
		assertEquals(1, stamps.size());
		assertTrue(stamps.containsKey("live"));

		Map<String, Long> few = new HashMap<>(Map.of("old", now - 10_000L));
		HttpUtil.prune(few, 5_000L);
		assertTrue("under the cap nothing is touched", few.containsKey("old"));
	}

	@Test
	public void aMissingNameKeepsWhatTheLaneHeld()
	{
		HttpUtil.Lane<String> lane = new HttpUtil.Lane<>(new CircuitBreaker("test"));
		lane.ok("name", "value");
		assertEquals("value", lane.missing("name"));
		assertTrue(lane.hold("name"));
	}
}

package com.killclog;

import java.util.concurrent.TimeUnit;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;
import org.junit.Test;
import static org.junit.Assert.*;

public class HttpUtilReadFailureTest
{
	@Test
	public void aBodyThatFailsToReadStillAnswersTheRequest() throws Exception
	{
		// Any failure while reading, not only an IOException, must complete the call: an
		// unanswered future would hold its single-flight entry for the rest of the session.
		ResponseBody broken = new ResponseBody()
		{
			@Override
			public MediaType contentType()
			{
				return MediaType.parse("application/json");
			}

			@Override
			public long contentLength()
			{
				return -1;
			}

			@Override
			public BufferedSource source()
			{
				throw new IllegalStateException("fixture: unreadable body");
			}
		};
		OkHttpClient client = new OkHttpClient.Builder()
			.addInterceptor(chain -> new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
				.code(200).message("fixture").body(broken).build())
			.build();
		HttpUtil.HttpResult result = HttpUtil.httpGet(client, "https://example.test/answer")
			.get(3, TimeUnit.SECONDS);
		assertEquals(-1, result.code);
		assertNull(result.body);
	}
}

package com.killclog;

import static org.junit.Assert.assertEquals;

import java.util.Arrays;
