	public void theChatCommandsAreTheFourItRegisters()
	{
		assertEquals(Arrays.asList("!kclog", "!missing", "!3a", "!gilded"),
			new java.util.ArrayList<>(new KillClogChatCommand().commands().keySet()));
	}
