		"chatNewClogMessages", "showChatEmojis", "showTooltipKc",
		"showTooltipPb", "showTooltipRank", "completionistHighlighter",
		"infoBarColor", "completedClogColor", "missing1Color",
		"inProgressClogColor", "emptyClogColor", "activitiesExpanded",
		"bossListView", "seenSelfGreeting", "killclogSync", "characterModel");

	@Test
	public void reorganizationPreservesEveryExpectedSetting()
	{
		Set<String> keys = Arrays.stream(KillClogConfig.class.getDeclaredMethods())
			.map(method -> method.getAnnotation(ConfigItem.class))
			.filter(item -> item != null)
			.map(ConfigItem::keyName)
			.collect(Collectors.toSet());

		Set<String> expected = new java.util.HashSet<>(PRE_220_KEYS);
		expected.add("enableComparison");
		expected.add("skillDisplay");
		expected.add("skillLevelColor");
		expected.add("skillColorMode");
		expected.add("enableSkillClogs");
		expected.add("silentAutomaticSync");
		expected.add("automaticSync");
		expected.add("showLeaderboardSelector");
		expected.add("cardLabelColor");
		expected.add("cardValueColor");
		expected.add("cardDividerColor");
		expected.add("cardBackgroundColor");
		expected.add("cardBorderColor");
		expected.add("cardScrollbarColor");
		expected.add("shareClan");
		assertEquals(expected, keys);
	}

	@Test
	public void syncFeedbackDefaultsAreQuietAndLiveUnderKillclog() throws Exception
	{
		KillClogConfig defaults = new KillClogConfig()
		{
		};
		assertTrue(defaults.silentAutomaticSync());
		assertTrue(defaults.automaticSync());
		assertEquals(KillClogConfig.killclogSection,
			KillClogConfig.class.getDeclaredMethod("silentAutomaticSync")
				.getAnnotation(ConfigItem.class).section());
		assertEquals(Arrays.asList("killclogSync", "automaticSync", "characterModel", "silentAutomaticSync", "shareClan"),
			keysInSection(KillClogConfig.killclogSection));
		assertTrue("your clan is shared until you turn it off", defaults.shareClan());
	}

	@Test
	public void characterPublishLabelDescribesTheManualButton() throws Exception
	{
		ConfigItem item = KillClogConfig.class.getDeclaredMethod("characterModel")
			.getAnnotation(ConfigItem.class);
		assertEquals("characterModel", item.keyName());
		assertEquals("Publish Character Model", item.name());
		assertEquals("Needs Sync Collection Log. Adds a button beside the chalice that publishes "
			+ "your current look and follower when you click it. Main game only.", item.description());
		KillClogConfig defaults = new KillClogConfig()
		{
		};
		assertFalse(defaults.characterModel());
		assertFalse(defaults.killclogSync());
	}

	@Test
	public void comparisonSettingIsDefaultOnUnderLookup() throws Exception
	{
