import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/** The chat lines are RuneLite's own test fixtures for these encounters. */
public class KillLogTest
{
	private Client client;
	private ConfigManager configManager;
	private KillLog log;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		configManager = mock(ConfigManager.class);
		log = new KillLog(configManager);
	}

	private void game(int tick, String message)
	{
		log.chat(client, ChatMessageType.GAMEMESSAGE, message, tick);
	}

	private void kept(String key, String tag, double seconds)
	{
		verify(configManager).setRSProfileConfiguration("killclog", "livepb." + key, seconds);
		verify(configManager).setRSProfileConfiguration("killclog", "livepbtag." + key, tag);
	}

	@Test
	public void theNightmaresTeamSizeComesFromItsMessage()
	{
		game(1, "Your Nightmare kill count is: <col=ff0000>1130</col>");
		game(1, "Team size: <col=ff0000>5 players</col> Fight duration: <col=ff0000>3:28</col> (new personal best)");
		kept("nightmare 5 players", "208.0|5||kill|1130", 208.0);

		// Not a new PB: the game's PB for that size, without this kill's count.
		game(9, "Your Nightmare kill count is: <col=ff0000>1,131</col>");
		game(9, "Team size: <col=ff0000>Solo</col> Fight duration: <col=ff0000>10:47</col>. Personal best: 8:44");
		kept("nightmare solo", "524.0|1||kill|", 524.0);
	}

	@Test
	public void theRaidsTakeTheirTeamSizeAndTheirChallengeTime()
	{
		log.chat(client, ChatMessageType.FRIENDSCHATNOTIFICATION, "<col=ef20ff>Congratulations - your raid is complete!</col><br>"
			+ "Team size: <col=ff0000>24+ players</col> Duration:</col> <col=ff0000>37:04.20</col> (new personal best)</col>>", 1);
		game(1, "Your completed Chambers of Xeric count is: <col=ff0000>51</col>.");
		kept("chambers of xeric 24+ players", "2224.2|||overall|51", 2224.2);

		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P0)).thenReturn(1);
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P1)).thenReturn(15);
		game(5, "Wave 'The Final Challenge' (Normal Mode) complete!<br>Duration: <col=ff0000>2:42.0</col><br>"
			+ "Theatre of Blood completion time: <col=ff0000>17:00.20</col> (new personal best)");
		game(5, "Theatre of Blood total completion time: <col=ff0000>24:40.20</col>. Personal best: 20:45.00");
		game(5, "Your completed Theatre of Blood count is: <col=ff0000>73</col>.");
		kept("theatre of blood 2 players", "1020.2|2||challenge|73", 1020.2);

		when(client.getVarbitValue(VarbitID.TOA_CLIENT_P0)).thenReturn(1);
		when(client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL)).thenReturn(300);
		game(9, "Challenge complete: The Wardens. Duration: <col=ef1020>8:30</col><br>"
			+ "Tombs of Amascut challenge completion time: <col=ef1020>8:31</col> (new personal best)");
		game(9, "Tombs of Amascut total completion time: <col=ef1020>0:01</col> (new personal best)");
		game(9, "Your completed Tombs of Amascut count is: <col=ff0000>1</col>.");
		kept("tombs of amascut solo", "511.0|1|300|challenge|1", 511.0);

		// A PB set earlier: its raid level and kill count aren't this run's.
		game(20, "Challenge complete: The Wardens. Duration: <col=ef1020>9:40</col><br>"
			+ "Tombs of Amascut: Expert Mode challenge completion time: <col=ef1020>9:40</col>. Personal best: 8:31");
		game(20, "Your completed Tombs of Amascut: Expert Mode count is: <col=ff0000>2</col>.");
		kept("tombs of amascut expert mode solo", "511.0|1||challenge|", 511.0);
	}

	@Test
	public void aTimeBeforeItsKillCountAndAPbAlreadyKept()
	{
		game(1, "Subdued in <col=ef1020>6:35</col> (new personal best).");
		game(2, "Your Tempoross kill count is: <col=ff0000>60</col>.");
		kept("tempoross", "395.0|||kill|60", 395.0);

		doReturn(55.8).when(configManager).getRSProfileConfiguration("killclog", "livepb.zulrah", double.class);
		game(7, "Your Zulrah kill count is: <col=ff0000>5</col>.");
		game(7, "Fight duration: <col=ff0000>0:59.20</col>. Personal best: 0:55.80");
		verify(configManager, never()).setRSProfileConfiguration("killclog", "livepb.zulrah", 55.8);
	}

	@Test
	public void aTimeNeverPairsWithAnotherKillsCount()
	{
		game(1, "Your Vorkath kill count is: <col=ff0000>500</col>.");
		game(4, "Fight duration: <col=ff0000>1:02.40</col> (new personal best).");
		game(9, "Fight duration: <col=ff0000>1:05.40</col>. Personal best: 1:02.40");
		game(12, "Your Vorkath kill count is: <col=ff0000>501</col>.");
		verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());
	}

	@Test
	public void aPartyThatChangesBeforeTheKillCountLeavesTheTimeUnlabeled()
	{
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P0)).thenReturn(1);
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P1)).thenReturn(15);
		game(10, "Wave 'The Final Challenge' (Normal Mode) complete!<br>Duration: <col=ff0000>2:42.0</col><br>"
			+ "Theatre of Blood completion time: <col=ff0000>17:00.20</col> (new personal best)");
		// The second player leaves before the kill count: the duo time must not read as a solo one.
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P1)).thenReturn(0);
		game(12, "Your completed Theatre of Blood count is: <col=ff0000>73</col>.");
		kept("theatre of blood", "1020.2|||challenge|73", 1020.2);
		verify(configManager, never()).setRSProfileConfiguration(eq("killclog"), eq("livepb.theatre of blood solo"), any());
	}

	@Test
	public void anotherAccountsKillCountNeverPairsWithATime()
	{
		when(client.getAccountHash()).thenReturn(1L);
		game(1, "Fight duration: <col=ff0000>1:02.40</col> (new personal best).");
		when(client.getAccountHash()).thenReturn(2L);
		game(2, "Your Vorkath kill count is: <col=ff0000>500</col>.");
		verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());
	}

	@Test
	public void aLogoutDropsAKillHalfSeen()
	{
		game(1, "Fight duration: <col=ff0000>1:02.40</col> (new personal best).");
		log.reset();
		game(2, "Your Vorkath kill count is: <col=ff0000>500</col>.");
		verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());
	}

	@Test
	public void titansAndYamaCountTheInstanceOnlyOnANewPb()
	{
		WorldView view = mock(WorldView.class);
		IndexedObjectSet<?> players = mock(IndexedObjectSet.class);
		// A fresh stream per call, as the client's own player set gives.
		doAnswer(i -> Stream.of(mock(Player.class), mock(Player.class))).when(players).stream();
		doReturn(players).when(view).players();
		when(client.getTopLevelWorldView()).thenReturn(view);

		game(1, "Your Yama success count is: <col=ff0000>12</col>.");
		game(1, "Fight duration: <col=ff0000>2:31.80</col>. Personal best: 2:10.20");
		verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());

		game(9, "Your Yama success count is: <col=ff0000>13</col>.");
		game(9, "Fight duration: <col=ff0000>2:04.20</col> (new personal best).");
		kept("yama 2 players", "124.2|2||kill|13", 124.2);
	}

	private void inInstance(int... counts)
	{
		WorldView view = mock(WorldView.class);
		IndexedObjectSet<?> players = mock(IndexedObjectSet.class);
		int[] call = {0};
		doAnswer(i -> Stream.generate(() -> mock(Player.class)).limit(counts[Math.min(call[0]++, counts.length - 1)]))
			.when(players).stream();
		doReturn(players).when(view).players();
		when(client.getTopLevelWorldView()).thenReturn(view);
	}

	private void archive(int tick, String total, int kc)
	{
		game(tick, "Challenge complete: Ocellus. Duration: <col=ef1020>2:25.80</col>. Total: <col=ef1020>2:25.80</col>"
			+ " (new personal best)");
		game(tick, "The Fractured Archive: Total completion time: <col=ef1020>" + total);
		game(tick, "Your completed Fractured Archive count is: <col=ff0000>" + kc + "</col>.");
	}

	@Test
	public void theFracturedArchivesTotalIsItsRecordAndTheInstanceGivesItsTeam()
	{
		inInstance(3);
		archive(1, "2:54.60</col>. Personal best: 0:00.60", 3);
		// One PB at any team size: a run that didn't set it can't say which size did.
		verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());

		archive(9, "2:25.80</col> (new personal best)", 4);
		kept("fractured archive 3 players", "145.8|3||overall|4", 145.8);
	}

	@Test
	public void theFracturedArchiveCountsASoloRunAsSoloAndNoMoreThanEight()
	{
		inInstance(1);
		archive(1, "2:25.80</col> (new personal best)", 1);
		kept("fractured archive solo", "145.8|1||overall|1", 145.8);

		inInstance(11);
		archive(9, "2:20.40</col> (new personal best)", 2);
		kept("fractured archive 8 players", "140.4|8||overall|2", 140.4);
	}

	@Test
	public void aRoomTimeAloneNeverKeysTheFracturedArchive()
	{
		inInstance(2);
		game(1, "Challenge complete: Ocellus. Duration: <col=ef1020>2:25.80</col>. Total: <col=ef1020>2:25.80</col>"
			+ " (new personal best)");
		game(1, "Your completed Fractured Archive count is: <col=ff0000>1</col>.");
		verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());
	}

	@Test
	public void aPlayerWhoLeavesBeforeTheCountLeavesTheArchiveUnkept()
	{
		inInstance(4, 3);
		archive(1, "2:25.80</col> (new personal best)", 1);
		verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());
	}

	@Test
	public void aNewPbRetiresTheLogPagesOlderReading()
	{
		page("zulrah", 60.0);
		game(1, "Your Zulrah kill count is: <col=ff0000>812</col>.");
		game(1, "Fight duration: <col=ff0000>0:58.20</col> (new personal best)");
		kept("zulrah", "58.2|||kill|812", 58.2);
		verify(configManager).unsetRSProfileConfiguration("killclog", "pagepb.zulrah");

		// A team size's kill leaves the page's plain reading alone.
		page("nightmare", 200.0);
		game(17, "Your Nightmare kill count is: <col=ff0000>1130</col>");
		game(17, "Team size: <col=ff0000>5 players</col> Fight duration: <col=ff0000>3:28</col> (new personal best)");
		verify(configManager, times(1)).unsetRSProfileConfiguration(anyString(), anyString());
	}

	private PbRecord kept(double seconds, String tag)
	{
		ConfigManager config = mock(ConfigManager.class);
		StoredPbs.stub(config, new Object[][]{{"killclog", "rsprofile.p1", "livepb.nightmare 5 players", seconds}});
		when(config.getConfiguration("killclog", "rsprofile.p1", "livepbtag.nightmare 5 players")).thenReturn(tag);
		return new PersonalBests(config, List.of("rsprofile.p1")).records("Nightmare").get("nightmare 5 players");
	}

	@Test
	public void theSyncReadsTheLabelsOfTheKeptTime()
	{
		PbRecord pb = kept(208.0, "208.0|5||kill|1130");
		assertEquals(PbRecord.Source.LIVE, pb.source);
		assertEquals(Integer.valueOf(5), pb.team);
		assertNull(pb.scale);
		assertEquals("kill", pb.timer);
		assertEquals(Integer.valueOf(1130), pb.kc);

		// A label kept for another time names nothing.
		PbRecord other = kept(200.4, "208.0|5||kill|1130");
		assertNull(other.team);
		assertNull(other.kc);
	}

	@Test
	public void aLabelThatDoesntReadIsSkippedAndTheTimeStillSyncs()
	{
		PbRecord pb = kept(208.0, "208.0|five||kill|1130");
		assertEquals(PbRecord.Source.LIVE, pb.source);
		assertEquals(208.0, pb.seconds, 0);
		assertNull(pb.team);
		assertNull(pb.timer);
		assertNull(kept(208.0, "x|5||kill|1130").team);
	}

	/** The log page's reading of a boss, as ClogPbs keeps it. */
	private void page(String boss, double seconds)
	{
		doReturn(seconds).when(configManager).getRSProfileConfiguration("killclog", "pagepb." + boss, double.class);
	}

	@Test
	public void aKillStatingAFasterRecordRetiresAnOlderPageReadingThoughItSetNoNewPb()
	{
		// Read from the page at 1:05; a faster 1:00 was set since (another client, or a release before this rule).
		page("zulrah", 65.0);
		doReturn(60.0).when(configManager).getRSProfileConfiguration("killclog", "livepb.zulrah", double.class);
		game(1, "Your Zulrah kill count is: <col=ff0000>900</col>.");
		game(1, "Fight duration: <col=ff0000>1:12.00</col>. Personal best: 1:00.00");
		verify(configManager).unsetRSProfileConfiguration("killclog", "pagepb.zulrah");
	}

	@Test
	public void theSameRecordWithoutItsTenthsKeepsThePageReading()
	{
		// Precise timing off: the kill says 1:05, the page holds the 64.8 it rounds from.
		page("zulrah", 64.8);
		game(1, "Your Zulrah kill count is: <col=ff0000>900</col>.");
		game(1, "Fight duration: <col=ff0000>1:12</col>. Personal best: 1:05");
		page("vorkath", 60.0);
		game(9, "Your Vorkath kill count is: <col=ff0000>50</col>.");
		game(9, "Fight duration: <col=ff0000>1:12.00</col>. Personal best: 1:00.00");
		verify(configManager, never()).unsetRSProfileConfiguration(anyString(), anyString());
	}

	@Test
	public void aRecordIsTheSameWithOrWithoutItsTenths()
	{
		assertEquals(true, PbRecord.sameRecord(64.8, 65.0));
		assertEquals(true, PbRecord.sameRecord(65.0, 64.8));
		assertEquals(true, PbRecord.sameRecord(60.0, 60.0));
		assertEquals(false, PbRecord.sameRecord(65.0, 60.0));
		assertEquals(false, PbRecord.sameRecord(65.4, 64.8));
	}

	@Test
	public void theSameRecordStatedWithoutItsTenthsKeepsTheKeptTimeAndItsKillCount()
	{
		doReturn(55.4).when(configManager).getRSProfileConfiguration("killclog", "livepb.zulrah", double.class);
		game(1, "Your Zulrah kill count is: <col=ff0000>900</col>.");
		game(1, "Fight duration: <col=ff0000>1:12</col>. Personal best: 0:55");
		verify(configManager, never()).setRSProfileConfiguration(eq("killclog"), eq("livepb.zulrah"), any());
		verify(configManager, never()).setRSProfileConfiguration(eq("killclog"), eq("livepbtag.zulrah"), any());

		// A whole second kept, then the record told to the tenth: the exact time is kept.
		doReturn(55.0).when(configManager).getRSProfileConfiguration("killclog", "livepb.vorkath", double.class);
		game(9, "Your Vorkath kill count is: <col=ff0000>50</col>.");
		game(9, "Fight duration: <col=ff0000>1:12.00</col>. Personal best: 0:55.20");
		verify(configManager).setRSProfileConfiguration("killclog", "livepb.vorkath", 55.2);
	}

	@Test
	public void theSameRecordToldMoreExactlyKeepsTheKillCountThatSetIt()
	{
		doReturn(55.0).when(configManager).getRSProfileConfiguration("killclog", "livepb.vorkath", double.class);
		when(configManager.getRSProfileConfiguration("killclog", "livepbtag.vorkath")).thenReturn("55.0|||kill|50");
		game(9, "Your Vorkath kill count is: <col=ff0000>90</col>.");
		game(9, "Fight duration: <col=ff0000>1:12.00</col>. Personal best: 0:55.20");
		verify(configManager).setRSProfileConfiguration("killclog", "livepbtag.vorkath", "55.2|||kill|50");
	}

	@Test
	public void aRaidWhosePartyChangedLeavesTheFasterPageReadingAlone()
	{
		// The page's 15:00 is faster than this 17:00.20; the party changed before the kill count, so no size is known.
		page("theatre of blood", 900.0);
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P0)).thenReturn(1);
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P1)).thenReturn(15);
		game(10, "Wave 'The Final Challenge' (Normal Mode) complete!<br>Duration: <col=ff0000>2:42.0</col><br>"
			+ "Theatre of Blood completion time: <col=ff0000>17:00.20</col> (new personal best)");
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P1)).thenReturn(0);
		game(12, "Your completed Theatre of Blood count is: <col=ff0000>73</col>.");
		verify(configManager, never()).unsetRSProfileConfiguration("killclog", "pagepb.theatre of blood");
	}

	@Test
	public void aTeamSizesFasterRecordRetiresTheRaidPagesOlderReadingAndASlowerOneLeavesIt()
	{
		// The raid page shows the fastest time of any team size: 38:20 is older than this 37:04.20.
		page("chambers of xeric", 2300.0);
		raid(1, 51);
		verify(configManager).unsetRSProfileConfiguration("killclog", "pagepb.chambers of xeric");

		// 35:00 on the page is another size's faster record: this size's slower one leaves it.
		page("chambers of xeric", 2100.0);
		raid(9, 52);
		verify(configManager, times(1)).unsetRSProfileConfiguration("killclog", "pagepb.chambers of xeric");
	}

	private void raid(int tick, int kc)
	{
		log.chat(client, ChatMessageType.FRIENDSCHATNOTIFICATION, "<col=ef20ff>Congratulations - your raid is complete!</col><br>"
			+ "Team size: <col=ff0000>24+ players</col> Duration:</col> <col=ff0000>37:04.20</col> (new personal best)</col>>", tick);
		game(tick, "Your completed Chambers of Xeric count is: <col=ff0000>" + kc + "</col>.");
	}

	@Test
	public void theGrotesqueGuardiansKillCountArrivesAfterTheDeathAnimation()
	{
		// RuneLite's fixture: the time, then the kill count six ticks later; ten ticks still pairs.
		game(100, "Fight duration: <col=ff0000>1:36.40</col> (new personal best)");
		game(106, "Your Grotesque Guardians kill count is: <col=ff0000>179</col>.");
		kept("grotesque guardians", "96.4|||kill|179", 96.4);
		game(300, "Fight duration: <col=ff0000>1:30.00</col> (new personal best)");
		game(310, "Your Grotesque Guardians kill count is: <col=ff0000>180</col>.");
		kept("grotesque guardians", "90.0|||kill|180", 90.0);
		// A kill count in the client's first ticks, with no time at all, is no kill's time.
		KillLog fresh = new KillLog(configManager);
		fresh.chat(client, ChatMessageType.GAMEMESSAGE, "Your Grotesque Guardians kill count is: <col=ff0000>181</col>.", 7);
		verify(configManager, never()).setRSProfileConfiguration("killclog", "livepb.grotesque guardians", 0.0);
	}

	@Test
	public void onlyTheGuardiansWaitLongForTheirKillCount()
	{
		// Another boss's kill count that late is another kill's.
		game(100, "Fight duration: <col=ff0000>1:02.40</col> (new personal best)");
		game(106, "Your Vorkath kill count is: <col=ff0000>500</col>.");
		// And the Guardians' own time stops waiting after ten ticks.
		game(200, "Fight duration: <col=ff0000>1:36.40</col> (new personal best)");
		game(211, "Your Grotesque Guardians kill count is: <col=ff0000>180</col>.");
		verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());
	}
}

package com.killclog;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Parsing tests for the killclog.com first-party read leg: sync-index
 * membership, proof-view responses, pb caching, and timestamp conversion.
 * Network behaviour is not exercised.
 */
public class KillclogServiceTest
{
	private KillclogService service;

	@Before
	public void setUp()
	{
		service = new KillclogService(null, new Gson(), null);
	}

	@Test
	public void testParseSyncIndexLowercasesNames()
	{
		Set<String> names = service.parseSyncIndex(
			"{\"schema\":1,\"count\":2,\"names\":[\"420 kc\",\"Fast 07\"]}");
		assertNotNull(names);
		assertEquals(2, names.size());
		assertTrue(names.contains("420 kc"));
		assertTrue(names.contains("fast 07"));
	}

	@Test
	public void aPlayerSyncsToKillClogWhenTheSyncListNamesThem() throws Exception
	{
		assertFalse("no list yet, no answer", service.isSynced("420 kc"));
		Field index = KillclogService.class.getDeclaredField("syncIndex");
		index.setAccessible(true);
		index.set(service, service.parseSyncIndex("{\"names\":[\"420 kc\"]}"));
		assertTrue("as the Kill Clog lookup keys it, whatever capitals", service.isSynced("420 KC"));
		// Whatever spelling Jagex accepts, on either side: the list's "am_trick" is the lookup's "am trick".
		assertTrue(service.isSynced("420_kc"));
		assertTrue(service.isSynced("420-KC"));
		index.set(service, service.parseSyncIndex("{\"names\":[\"am_trick\"]}"));
		assertTrue(service.isSynced("Am Trick"));
		assertFalse(service.isSynced("Marni"));
		assertFalse(service.isSynced(null));
	}

	@Test
	public void theActiveLeagueIsOnlyEverAPlainSlug()
	{
		service.parseSyncIndex("{\"names\":[],\"active_league\":\"demonic-pacts\"}");
		assertEquals("demonic-pacts", service.activeLeague());
		for (String unsafe : new String[]{"main", "../etc", "Demonic-Pacts", "a/b", "", "x".repeat(41)})
		{
			service.parseSyncIndex("{\"names\":[],\"active_league\":\"" + unsafe + "\"}");
			assertNull(unsafe, service.activeLeague());
		}
		service.parseSyncIndex("{\"names\":[],\"active_league\":null}");
		assertNull(service.activeLeague());
		service.parseSyncIndex("{\"names\":[]}");
		assertNull(service.activeLeague());
	}

	@Test
	public void aLeaguesPbProfileIsOnlyEverItsOwn()
	{
		service.parseSyncIndex("{\"names\":[],\"active_league\":\"demonic-pacts\",\"active_league_profile\":\"DEMONIC_PACTS_LEAGUE\"}");
		assertEquals("DEMONIC_PACTS_LEAGUE", service.leagueProfileType("demonic-pacts"));
		assertNull("another League never borrows it", service.leagueProfileType("raging-echoes"));
		service.parseSyncIndex("{\"names\":[],\"active_league\":\"demonic-pacts\"}");
		assertNull("RuneLite does not know the League yet", service.leagueProfileType("demonic-pacts"));
		service.parseSyncIndex("{\"names\":[],\"active_league\":\"../x\",\"active_league_profile\":\"DEMONIC_PACTS_LEAGUE\"}");
		assertNull(service.leagueProfileType("demonic-pacts"));
	}

	@Test
	public void aLeaguesLogAndPbsComeFromItsOwnViewAndStayApart() throws Exception
	{
		List<String> paths = new java.util.ArrayList<>();
		okhttp3.OkHttpClient http = new okhttp3.OkHttpClient.Builder().addInterceptor(chain ->
		{
			String path = chain.request().url().encodedPath();
			paths.add(path);
			boolean league = path.endsWith("/proof-view/demonic-pacts");
			String body = "{\"rsn\":\"420 kc\",\"pbs\":{\"Zulrah\":" + (league ? "61.2" : "58.2") + "},"
				+ "\"clog\":{\"items_by_category\":{\"zulrah\":[{\"item_id\":" + (league ? 2 : 1) + ",\"quantity\":1}]}}}";
			return new okhttp3.Response.Builder().request(chain.request()).protocol(okhttp3.Protocol.HTTP_1_1).code(200)
				.message("OK").body(okhttp3.ResponseBody.create(okhttp3.MediaType.get("application/json"), body)).build();
		}).build();
		service = new KillclogService(http, new Gson(), null);
		Set<String> index = java.util.concurrent.ConcurrentHashMap.newKeySet();
		index.add("420 kc");
		setField("syncIndex", index);
		setField("indexFetchedAt", System.currentTimeMillis());

		ClogResult league = service.lookupClog("420 Kc", "demonic-pacts").join();
		ClogResult main = service.lookupClog("420 Kc").join();

		assertEquals(2, paths.size());
		assertTrue(paths.get(0), paths.get(0).endsWith("/player/420%20Kc/proof-view/demonic-pacts"));
		assertTrue(paths.get(1), paths.get(1).endsWith("/player/420%20Kc/proof-view"));
		assertEquals(2, league.getObtainedItems().get("zulrah").get(0).getId());
		assertEquals(1, main.getObtainedItems().get("zulrah").get(0).getId());
		assertEquals(PersonalBests.formatSeconds(61.2), service.pbText(KillclogService.modeKey("demonic-pacts", "420 KC"), "Zulrah"));
		assertEquals(PersonalBests.formatSeconds(58.2), service.pbText("420 kc", "Zulrah"));
	}

