	<T> T listener(Class<T> type)
	{
		return type.cast(Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{type},
			(proxy, method, args) ->
			{
				if (!SwingUtilities.isEventDispatchThread()) throw new AssertionError("callback outside EDT");
