		store.put("chambers of xeric solo", 1800.0);
		store.put("chambers of xeric 3 players", 1500.0);
		// The alt spelling holds the faster time for the same variant: it
		// must merge into the canonical key, not appear as its own entry.
		store.put("the corrupted gauntlet", 460.0);
		store.put("corrupted gauntlet", 452.5);

		java.util.Map<String, Double> cox =
			PersonalBests.variantSeconds(store, "Chambers of Xeric");
		assertEquals(2, cox.size());
		assertEquals(1800.0, cox.get("chambers of xeric solo"), 0.001);
		assertEquals(1500.0, cox.get("chambers of xeric 3 players"), 0.001);
		// No collapsed entry: the split IS the point.
		assertFalse(cox.containsKey("chambers of xeric"));

		java.util.Map<String, Double> gauntlet =
			PersonalBests.variantSeconds(store, "The Corrupted Gauntlet");
		assertEquals(1, gauntlet.size());
		assertEquals(452.5, gauntlet.get("the corrupted gauntlet"), 0.001);
	}

	@Test
	public void everyLanesSpellingReachesOneName()
	{
		assertEquals("chambers of xeric challenge mode", PersonalBests.encounter("Chambers of Xeric: Challenge Mode"));
		assertEquals("theatre of blood hard mode", PersonalBests.encounter("theatre of blood hard mode"));
		assertEquals("corrupted gauntlet", PersonalBests.encounter("The Corrupted Gauntlet"));
		assertEquals("lunar chest", PersonalBests.encounter("Lunar Chests"));
		assertEquals("tztok-jad", PersonalBests.encounter("TzHaar Fight Cave"));
		// The sync's name never moves: the server files every time under it.
		assertEquals("the corrupted gauntlet", PersonalBests.syncBase("The Corrupted Gauntlet"));
		assertEquals("theatre of blood hard mode", PersonalBests.syncBase("Theatre of Blood: Hard Mode"));
	}

	@Test
	public void everyPanelBossReadsTheKeyRuneLiteStoresItUnder() throws Exception
	{
		// RuneLite's chat commands file a boss's time under longBossName's answer for the name, lowercased.
		java.lang.reflect.Method store = net.runelite.client.plugins.chatcommands.ChatCommandsPlugin.class
			.getDeclaredMethod("longBossName", String.class);
		store.setAccessible(true);
		java.util.Set<String> names = new java.util.HashSet<>();
		for (net.runelite.client.hiscore.HiscoreSkill boss : PanelData.BOSSES)
		{
			String key = ((String) store.invoke(null, boss.getName().toLowerCase(java.util.Locale.ROOT)))
				.toLowerCase(java.util.Locale.ROOT);
			assertEquals(boss.getName(), PersonalBests.encounter(boss.getName()), PersonalBests.encounter(key));
			assertTrue("two bosses share a name: " + boss.getName(), names.add(PersonalBests.encounter(boss.getName())));
		}
	}
}

package com.killclog;

import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.client.game.ChatIconManager;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.clearInvocations;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

public class PlayerClansTest
{
	private final Client client = mock(Client.class);
	private final ChatIconManager icons = mock(ChatIconManager.class);
	private final RuneProfileService runeProfile = mock(RuneProfileService.class);
	private boolean settled = true;
	private boolean shared = true;
	private final PlayerClans clans = new PlayerClans(client, icons, runeProfile, () -> settled, () -> shared);

	@Test
	public void theCardReadsYourClanWithoutTouchingTheClient()
	{
		// The card is built on Swing's thread, where RuneLite asserts that clan state is read on its own
		// thread (a dev client stops the card there). The tick's snapshot carries everything it needs.
		ClanTitle title = new ClanTitle(100, "Administrator");
		BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		youAreIn("420 kc", "Clogged", title);
		when(icons.getRankImage(title)).thenReturn(image);

		clans.refreshClientSnapshot();
		clearInvocations(client);

		assertEquals("Clogged", clans.name("420_kc", null));
		assertSame(image, clans.icon("420 KC", null));
		verifyNoInteractions(client);

		// Share Clan off: your own card shows none too, title and all.
		shared = false;
		assertNull(clans.name("420 kc", null));
		assertNull(clans.icon("420 kc", null));
	}

	@Test
	public void yourClanStandsWithoutItsChatChannel()
	{
		// Membership is in the clan's settings: a player who left the clan's chat channel is still in the clan.
		ClanTitle title = new ClanTitle(100, "Administrator");
		Player you = mock(Player.class);
		when(you.getName()).thenReturn("420 kc");
		ClanMember member = mock(ClanMember.class);
		when(member.getRank()).thenReturn(ClanRank.ADMINISTRATOR);
		ClanSettings settings = mock(ClanSettings.class);
		when(settings.getName()).thenReturn("Clogged");
		when(settings.findMember("420 kc")).thenReturn(member);
		when(settings.titleForRank(ClanRank.ADMINISTRATOR)).thenReturn(title);
		when(client.getLocalPlayer()).thenReturn(you);
		when(client.getClanSettings()).thenReturn(settings);
		BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		when(icons.getRankImage(title)).thenReturn(image);

		clans.refreshClientSnapshot();

		assertEquals("Clogged", clans.name("420 kc", null));
		assertSame(image, clans.icon("420 kc", null));
	}

	@Test
	public void anyoneElsesClanComesFromRuneProfile()
	{
		youAreIn("420 kc", "Clogged", new ClanTitle(100, "Administrator"));
		when(runeProfile.clan("based batt")).thenReturn("Another Clan");
		clans.refreshClientSnapshot();
		assertEquals("Another Clan", clans.name("based batt", null));
	}

	@Test
	public void afterLogoutYourOwnNameNoLongerReadsAsYours()
	{
		youAreIn("420 kc", "Clogged", new ClanTitle(100, "Administrator"));
		clans.refreshClientSnapshot();
		clans.clearClientSnapshot();
		assertNull(clans.name("420 kc", null));
		assertNull(clans.icon("420 kc", null));
	}

	@Test
	public void anotherPlayersOwnSyncNamesTheirClanBeforeRuneProfile()
	{
		when(runeProfile.clan("A q p Weed")).thenReturn("Old Clan");
		when(runeProfile.clanTitle("A q p Weed")).thenReturn(new ClanTitle(12, "Old"));
		ClogResult synced = new ClogResult("A q p Weed", java.util.Collections.emptyMap(),
			java.util.Collections.emptyMap(), java.util.Collections.emptyMap(), null, AccountType.IRONMAN);
		ClanTitle recruit = new ClanTitle(24, "Recruit");
		synced.setSyncedClan("Iron Clan");
		synced.setSyncedClanKnown(true);
		synced.setSyncedClanTitle(recruit);
		BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		when(icons.getRankImage(recruit)).thenReturn(image);

		assertEquals("Iron Clan", clans.name("A q p Weed", synced));
		assertSame(image, clans.icon("A q p Weed", synced));
		assertEquals("without their sync, RuneProfile's", "Old Clan", clans.name("A q p Weed", null));
	}

	@Test
	public void yourSyncCarriesYourClanOrNoneOnlyOnceTheWorldHasSettled()
	{
		youAreIn("420 kc", "Clogged", new ClanTitle(100, "Administrator"));
		ClanMember member = mock(ClanMember.class);
		when(member.getRank()).thenReturn(ClanRank.ADMINISTRATOR);
		when(client.getClanSettings().getName()).thenReturn("Clogged");
		when(client.getClanSettings().findMember("420 kc")).thenReturn(member);

		settled = false;
		clans.refreshClientSnapshot();
		assertNull("before the world settles the game hasn't said", clans.forSync("420 kc"));

		settled = true;
		clans.refreshClientSnapshot();
		assertEquals("Clogged", clans.forSync("420 kc").clan);
		assertEquals(100, clans.forSync("420 kc").title.getId());

		when(client.getClanSettings()).thenReturn(null);
		when(client.getClanChannel()).thenReturn(null);
		clans.refreshClientSnapshot();
		assertNull("in no clan, the sync says none", clans.forSync("420 kc").clan);

		clans.clearClientSnapshot();
		assertNull(clans.forSync("420 kc"));
	}

	private void youAreIn(String name, String clanName, ClanTitle title)
	{
		Player you = mock(Player.class);
		when(you.getName()).thenReturn(name);
		ClanChannelMember member = mock(ClanChannelMember.class);
		when(member.getRank()).thenReturn(ClanRank.ADMINISTRATOR);
		ClanChannel channel = mock(ClanChannel.class);
		when(channel.getName()).thenReturn(clanName);
		when(channel.findMember(name)).thenReturn(member);
		ClanSettings settings = mock(ClanSettings.class);
		when(settings.titleForRank(ClanRank.ADMINISTRATOR)).thenReturn(title);
		when(client.getLocalPlayer()).thenReturn(you);
		when(client.getClanChannel()).thenReturn(channel);
		when(client.getClanSettings()).thenReturn(settings);
	}
}

package com.killclog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.zip.CRC32;
import javax.imageio.ImageIO;
import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class PlayerPortraitsTest
{
	private static ClogResult clog(String name, boolean killclog)
	{
		return new ClogResult(name, Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(),
			null, null).withSources(!killclog, false, killclog);
	}

	private static OkHttpClient client()
	{
		OkHttpClient client = mock(OkHttpClient.class);
		when(client.newCall(any(Request.class))).thenReturn(mock(Call.class));
		return client;
	}

	private static List<Request> requests(OkHttpClient client, int count)
	{
		ArgumentCaptor<Request> request = ArgumentCaptor.forClass(Request.class);
		verify(client, times(count)).newCall(request.capture());
		return request.getAllValues();
	}

	private static byte[] png(int width, int height) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		ImageIO.write(new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB), "png", out);
		return out.toByteArray();
	}

	/** Answer the request out for a name, for the lookup it was sent for, as its completed call would. */
	private static void answer(PlayerPortraits portraits, String name, int code, byte[] bytes, String etag)
	{
		Integer generation = TestViews.askedFor(portraits, name);
		portraits.onResponse(name, generation != null ? generation : 0, code, bytes, etag);
	}

	/** A PNG signature and header claiming {@code side} x {@code side}, with no image data behind it. */
	private static byte[] headerOnlyPng(int side)
	{
		ByteBuffer ihdr = ByteBuffer.allocate(17).put("IHDR".getBytes()).putInt(side).putInt(side)
			.put(new byte[] {8, 6, 0, 0, 0});
		CRC32 crc = new CRC32();
		crc.update(ihdr.array());
		return ByteBuffer.allocate(8 + 4 + 17 + 4)
			.put(new byte[] {(byte) 0x89, 'P', 'N', 'G', '\r', '\n', 0x1a, '\n'})
			.putInt(13).put(ihdr.array()).putInt((int) crc.getValue()).array();
	}

	@Test
	public void onlyAKillClogSyncerIsAskedAbout()
	{
		OkHttpClient client = client();
		PlayerPortraits portraits = new PlayerPortraits(client);
		portraits.lookedUp(clog("Lynx Titan", false));
		portraits.lookedUp(null);
		assertNull(portraits.forSummary(clog("Lynx Titan", false)));
		verify(client, never()).newCall(any(Request.class));

		portraits.lookedUp(clog("420 kc", true));
		portraits.lookedUp(clog("420_KC", true));
		Request request = requests(client, 1).get(0);
		assertEquals("https://killclog.com/api/player/420%20kc/portrait/large", request.url().toString());
		assertEquals(HttpUtil.USER_AGENT, request.header("User-Agent"));
		assertNull("nothing held yet, so nothing to re-check", request.header("If-None-Match"));
	}

	@Test
	public void theLocalPlayersOwnLogAsksToo()
	{
		OkHttpClient client = client();
		new PlayerPortraits(client).lookedUp(clog("420 kc", false).withLocalSource(true));
		requests(client, 1);
	}

	@Test
	public void aPortraitShowsOnlyOnceTheServerConfirmsItForTheLookup() throws IOException
	{
		OkHttpClient client = client();
		PlayerPortraits portraits = new PlayerPortraits(client);
		String key = PlayerPortraits.key("420 kc");
		portraits.lookedUp(clog("420 kc", true));
		assertNull("not before the answer", portraits.forSummary(clog("420 kc", true)));
		answer(portraits, key, 200, png(56, 80), "\"v1\"");
		BufferedImage shown = portraits.forSummary(clog("420 kc", true));
		assertNotNull(shown);
		assertEquals(56, shown.getWidth());

		// The next lookup withholds it until the server answers again; unchanged is a bodiless 304.
		portraits.lookedUp(clog("420 kc", true));
		assertNull(portraits.forSummary(clog("420 kc", true)));
		assertEquals("\"v1\"", requests(client, 2).get(1).header("If-None-Match"));
		answer(portraits, key, 304, null, "\"v1\"");
		assertSame(shown, portraits.forSummary(clog("420 kc", true)));
	}

	@Test
	public void aWithdrawalIsGoneFromTheNextLookup() throws IOException
	{
		for (int code : new int[] {404, 451})
		{
			PlayerPortraits portraits = new PlayerPortraits(client());
			String key = PlayerPortraits.key("420 kc");
			portraits.lookedUp(clog("420 kc", true));
			answer(portraits, key, 200, png(56, 80), "\"v1\"");
			assertNotNull(portraits.forSummary(clog("420 kc", true)));
			portraits.lookedUp(clog("420 kc", true));
			answer(portraits, key, code, null, null);
			assertNull(String.valueOf(code), portraits.forSummary(clog("420 kc", true)));
		}
	}

	@Test
	public void aFailedReCheckWithholdsTheHeldPortrait() throws IOException
	{
		PlayerPortraits portraits = new PlayerPortraits(client());
		String key = PlayerPortraits.key("420 kc");
		portraits.lookedUp(clog("420 kc", true));
		answer(portraits, key, 200, png(56, 80), "\"v1\"");
		portraits.lookedUp(clog("420 kc", true));
		answer(portraits, key, 503, null, null);
		assertNull("an old answer doesn't vouch for it", portraits.forSummary(clog("420 kc", true)));
		answer(portraits, key, -1, null, null);
		assertNull(portraits.forSummary(clog("420 kc", true)));
	}

	@Test
	public void aMissIsNotAskedAgainStraightAwayButSoonerThanAProviderMiss()
	{
		OkHttpClient client = client();
		PlayerPortraits portraits = new PlayerPortraits(client);
		String key = PlayerPortraits.key("CBC");
		answer(portraits, key, 404, null, null);
		portraits.lookedUp(clog("CBC", true));
		assertNull(portraits.forSummary(clog("CBC", true)));
		verify(client, never()).newCall(any(Request.class));
		// Past the portrait's minute, though well inside a provider miss's hour.
		portraits.lane.notFound.put(key, System.currentTimeMillis() - PlayerPortraits.NOT_FOUND_TTL_MS - 1);
		portraits.lookedUp(clog("CBC", true));
		requests(client, 1);
	}

	@Test
	public void publishingAsksForTheNewCharacterAtOnceWhateverMissCameBefore() throws IOException
	{
		OkHttpClient client = client();
		PlayerPortraits portraits = new PlayerPortraits(client);
		String key = PlayerPortraits.key("Sexy Kyle");
		ClogResult own = clog("Sexy Kyle", false).withLocalSource(true);
		// Their own summary asked before they published: no character yet, and the miss rests.
		portraits.lookedUp(own);
		answer(portraits, key, 404, null, null);
		assertNull(portraits.forSummary(own));
		requests(client, 1);

		portraits.published("Sexy Kyle");
		requests(client, 2);
		answer(portraits, key, 200, png(56, 80), "\"v1\"");
		assertNotNull(portraits.forSummary(own));
	}

	@Test
	public void overlappingLookupsTrustOnlyTheLatestAnswer() throws IOException
	{
		OkHttpClient client = client();
		PlayerPortraits portraits = new PlayerPortraits(client);
		portraits.lookedUp(clog("420 kc", true));
		answer(portraits, "420 kc", 200, png(56, 80), "\"v1\"");
		assertNotNull(portraits.forSummary(clog("420 kc", true)));

		// A second lookup's check is out when a third lands: one request at a time, nothing new yet.
		portraits.lookedUp(clog("420 kc", true));
		portraits.lookedUp(clog("420 kc", true));
		requests(client, 2);
		// The second lookup's "unchanged" doesn't vouch for the third; a fresh check goes out for it.
		answer(portraits, "420 kc", 304, null, "\"v1\"");
		assertNull(portraits.forSummary(clog("420 kc", true)));
		requests(client, 3);
		// The player withdrew meanwhile: the latest answer is the one that counts.
		answer(portraits, "420 kc", 404, null, null);
		assertNull(portraits.forSummary(clog("420 kc", true)));
	}

	@Test
	public void aNewPortraitFromAnOlderLookupWaitsForTheLatestCheck() throws IOException
	{
		OkHttpClient client = client();
		PlayerPortraits portraits = new PlayerPortraits(client);
		portraits.lookedUp(clog("CBC", true));
		portraits.lookedUp(clog("CBC", true));
		answer(portraits, "CBC", 200, png(62, 80), "\"v2\"");
		assertNull("held, but not confirmed for the latest lookup", portraits.forSummary(clog("CBC", true)));
		assertEquals("\"v2\"", requests(client, 2).get(1).header("If-None-Match"));
		answer(portraits, "CBC", 304, null, "\"v2\"");
		assertNotNull(portraits.forSummary(clog("CBC", true)));
	}

	@Test
	public void lookupCountsStayBounded()
	{
		PlayerPortraits portraits = new PlayerPortraits(client());
		for (int i = 0; i < PlayerPortraits.MAX_GENERATIONS + 50; i++)
		{
			portraits.lookedUp(clog("player " + i, true));
			answer(portraits, "player " + i, 404, null, null);
		}
		assertTrue(TestViews.countedLookups(portraits) <= PlayerPortraits.MAX_GENERATIONS + 1);
	}

	@Test
	public void onlyASmallPngIsDecoded() throws IOException
	{
		assertNotNull(PlayerPortraits.decode(png(96, 80)));
		assertNotNull(PlayerPortraits.decode(png(256, 256)));
		assertNull(PlayerPortraits.decode(png(257, 80)));
		// A header claiming a huge image is refused before any pixels are allocated.
		assertNull(PlayerPortraits.decode(headerOnlyPng(16384)));
		// Other formats are refused outright, whatever the decoder could make of them.
		ByteArrayOutputStream gif = new ByteArrayOutputStream();
		ImageIO.write(new BufferedImage(8, 8, BufferedImage.TYPE_INT_RGB), "gif", gif);
		assertNull(PlayerPortraits.decode(gif.toByteArray()));
		assertNull(PlayerPortraits.decode("not a png".getBytes()));
		assertNull(PlayerPortraits.decode(Arrays.copyOf(png(56, 80), 40)));
		assertNull(PlayerPortraits.decode(new byte[0]));
		assertNull(PlayerPortraits.decode(null));
		assertNull(PlayerPortraits.decode(new byte[PlayerPortraits.MAX_BYTES + 1]));
	}

	@Test
	public void everySpellingOfANameIsOnePlayer()
	{
		assertEquals("ye ol buck", PlayerPortraits.key(" Ye_Ol-Buck "));
		assertEquals(PlayerPortraits.key("420 kc"), PlayerPortraits.key("420_KC"));
	}

	@Test
	public void aPublishOutranksACheckSentBeforeIt()
	{
		OkHttpClient client = client();
		PlayerPortraits portraits = new PlayerPortraits(client);
		portraits.lookedUp(clog("Zezima", true));
		Integer beforePublish = TestViews.askedFor(portraits, "Zezima");
		assertNotNull(beforePublish);

		// The check already out answers 404 for the character before the publish: it asks again at once.
		portraits.published("Zezima");
		portraits.onResponse("Zezima", beforePublish, 404, null, null);
		assertEquals(Integer.valueOf(beforePublish + 1), TestViews.askedFor(portraits, "Zezima"));
		requests(client, 2);
	}
}

package com.killclog;

import com.google.gson.Gson;
import java.io.File;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class PluginFolderTest
{
	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void testsNeverSeeTheRealRuneliteFolder()
	{
		assertTrue(net.runelite.client.RuneLite.RUNELITE_DIR.getPath()
			.replace(File.separatorChar, '/').contains("/build/test-home/"));
	}

	@Test
	public void windowsDeviceNamesTakeASafeFileName()
	{
		assertEquals("+con.json", LocalClogCache.fileName("Con"));
		assertEquals("+com1.json", LocalClogCache.fileName("COM1"));
		assertEquals("+lpt9.json", LocalClogCache.fileName("lpt9"));
		assertEquals("com10.json", LocalClogCache.fileName("Com10"));
		assertEquals("cone.json", LocalClogCache.fileName("Cone"));
		assertEquals("sir_con.json", LocalClogCache.fileName("Sir Con"));
	}

	@Test
	public void aDeviceNamedLookupSavesAndLoads() throws Exception
	{
		File logs = temporaryFolder.newFolder();
		LocalClogCache cache = LocalClogCacheTest.onDisk(logs);
		assertTrue(StoreLogin.activate(cache, "Main", 77L));
		cache.cacheResult(LocalClogCacheTest.clog("Con", LocalClogCacheTest.categoryItems("hats", 1),
			LocalClogCacheTest.obtainedItems("hats", 1)));
		assertTrue(new File(logs, "lookups/+con.json").isFile());
		LocalClogCache reloaded = LocalClogCacheTest.onDisk(logs);
		assertTrue(StoreLogin.activate(reloaded, "Main", 77L));
		assertTrue(reloaded.hasDataFor("Con"));
	}

	@Test
	public void aSessionWithoutAFolderStaysInMemory()
	{
		LocalClogCache cache = new LocalClogCache(new Gson(), new InlineScheduledExecutorService());
		cache.open(() ->
		{
			throw new java.io.IOException("refused");
		});
		assertNull(cache.folder().join());
		assertTrue(StoreLogin.activate(cache, "Tester", 77L));
		cache.cacheFirstPartyResult(LocalClogCacheTest.clog("Tester", LocalClogCacheTest.categoryItems("hats", 1, 2),
			LocalClogCacheTest.obtainedItems("hats", 1)));
		assertTrue(cache.hasFirstPartyDataFor("Tester"));
		assertFalse("a lookup reads no disk", cache.hasDataFor("Someone Else"));

		LocalCaCache ca = new LocalCaCache(new Gson(), new InlineScheduledExecutorService());
		ca.open(null);
		ca.serve(new Session(1, "Tester", 1L));
		ca.cacheResult("Tester", 77L, Map.of(CombatAchievementTier.EASY, 1));
		assertEquals(1, ca.getCached("Tester").getTotalPoints());
	}

	@Test
	public void aMemoryOnlySessionSavesNothingAndRetriesNothing()
	{
		int[] tasks = {0};
		LocalCaCache ca = new LocalCaCache(new Gson(), new java.util.concurrent.ScheduledThreadPoolExecutor(1)
		{
			@Override
			public void execute(Runnable command)
			{
				tasks[0]++;
				command.run();
			}
		});
		ca.open(null);
		ca.serve(new Session(1, "Tester", 1L));
		ca.cacheResult("Tester", 77L, Map.of(CombatAchievementTier.EASY, 1));
		int afterFirst = tasks[0];
		// The same counts read again are already held: no write queued, so no warning each read.
		ca.cacheResult("Tester", 77L, Map.of(CombatAchievementTier.EASY, 1));
		assertEquals(afterFirst, tasks[0]);
		assertEquals(1, ca.getCached("Tester").getTotalPoints());
		assertFalse("a plain varp change is not a CA total", new LocalCaReader().isCaVarbit(-1));
	}
}

