		AtomicInteger requests = new AtomicInteger();
		service = new RuneProfileService(cannedClient(404, "{}", requests), new Gson(), null);
		summaryCache().put("a q p weed", new RuneProfileService.RuneProfileSummary(AccountType.IRONMAN, null,
			"Iron Clan", new ClanTitle(24, "Recruit")));
		longCache("summaryFetchTimes").put("a q p weed", System.currentTimeMillis() - 66 * 60 * 1000);
		service.lookup("a q p weed").get(5, TimeUnit.SECONDS);
		assertEquals(1, requests.get());
		assertNull(service.clan("A q p Weed"));
		assertFalse(service.hasProfile("A q p Weed"));

		// Held under another spelling of the same name, the 404 clears that one too.
		service = new RuneProfileService(cannedClient(404, "{}", requests), new Gson(), null);
		summaryCache().put("a_q_p_weed", new RuneProfileService.RuneProfileSummary(AccountType.IRONMAN, null,
			"Iron Clan", new ClanTitle(24, "Recruit")));
		longCache("summaryFetchTimes").put("a_q_p_weed", System.currentTimeMillis() - 66 * 60 * 1000);
		service.lookup("a q p weed").get(5, TimeUnit.SECONDS);
		assertNull("no spelling keeps the gone profile's clan", service.clan("A q p Weed"));
		assertNull(service.getCachedAccountType("A q p Weed"));

		// A new answer replaces what another spelling held, so the older one's clan and type never stand for it.
		service = new RuneProfileService(cannedClient(200, "{\"accountType\":{\"id\":0,\"key\":\"normal\"},"
			+ "\"clan\":{\"name\":\"New Clan\",\"rank\":40,\"icon\":24,\"title\":\"Recruit\"}}", requests), new Gson(), null);
		summaryCache().put("a_q_p_weed", new RuneProfileService.RuneProfileSummary(AccountType.IRONMAN, null,
			"Old Clan", new ClanTitle(24, "Recruit")));
		longCache("summaryFetchTimes").put("a_q_p_weed", System.currentTimeMillis() - 66 * 60 * 1000);
		service.lookup("a q p weed").get(5, TimeUnit.SECONDS);
		assertEquals("New Clan", service.clan("a q p weed"));
		assertEquals("New Clan", service.clan("A_q_p_Weed"));
		assertEquals(AccountType.REGULAR, service.getCachedAccountType("a_q_p_weed"));
	}

	@Test
	public void twoSpellingsAnsweringAtOnceLeaveOneAnswer() throws Exception
	{
		// Asked together, two spellings of one name are one lookup: one request, and one answer held for both.
		AtomicInteger requests = new AtomicInteger();
		CountDownLatch release = new CountDownLatch(1);
		OkHttpClient client = clanClient(chain ->
		{
			requests.incrementAndGet();
			release.await(5, TimeUnit.SECONDS);
		});
		service = new RuneProfileService(client, new Gson(), null);
		CompletableFuture<?> spaced = service.lookup("a q p weed");
		CompletableFuture<?> underscored = service.lookup("a_q_p_weed");
		release.countDown();
		CompletableFuture.allOf(underscored, spaced).get(5, TimeUnit.SECONDS);
		assertEquals(1, requests.get());
		assertEquals(1, summaryCache().size());
		assertEquals("New Clan", service.clan("A_q_p_Weed"));

		// Answers for two keys that are one name, landing together many times over: clearing the other spellings and
		// storing the new answer is one step, so the name is never left holding both (and an older answer standing for
		// it). Lookups can't start two such flights, so they're started directly.
		Method start = RuneProfileService.class.getDeclaredMethod("startSummaryLookup", String.class, String.class);
		start.setAccessible(true);
		for (int round = 0; round < 200; round++)
		{
			CountDownLatch bothAsked = new CountDownLatch(2);
			service = new RuneProfileService(clanClient(chain ->
			{
				bothAsked.countDown();
				bothAsked.await(5, TimeUnit.SECONDS);
			}), new Gson(), null);
			CompletableFuture<?> first = (CompletableFuture<?>) start.invoke(service, "a_q_p_weed", "a_q_p_weed");
			CompletableFuture<?> second = (CompletableFuture<?>) start.invoke(service, "a q p weed", "a q p weed");
			CompletableFuture.allOf(first, second).get(5, TimeUnit.SECONDS);
			assertEquals("round " + round, 1, summaryCache().size());
		}
	}

	/** Answers every RuneProfile summary with a clan named for the spelling asked, after {@code before} runs. */
	private static OkHttpClient clanClient(InterruptibleStep before)
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				try
				{
					before.run(chain);
				}
				catch (InterruptedException e)
				{
					Thread.currentThread().interrupt();
				}
				String clan = chain.request().url().toString().contains("_") ? "Old Clan" : "New Clan";
				return new Response.Builder()
					.request(chain.request())
					.protocol(Protocol.HTTP_1_1)
					.code(200)
					.message("canned")
					.body(ResponseBody.create(MediaType.parse("application/json"),
						"{\"clan\":{\"name\":\"" + clan + "\",\"rank\":40,\"icon\":24,\"title\":\"Recruit\"}}"))
					.build();
			})
			.build();
	}

	private interface InterruptibleStep
	{
		void run(okhttp3.Interceptor.Chain chain) throws InterruptedException;
	}

	private static OkHttpClient cannedClient(int code, String body, AtomicInteger requests)
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requests.incrementAndGet();
				return new Response.Builder()
					.request(chain.request())
					.protocol(Protocol.HTTP_1_1)
					.code(code)
					.message("canned")
					.body(ResponseBody.create(MediaType.parse("application/json"), body))
					.build();
			})
			.build();
	}

	private void awaitProfile(String player, boolean expected) throws InterruptedException
	{
		long deadline = System.currentTimeMillis() + 5000;
		while (service.hasProfile(player) != expected && System.currentTimeMillis() < deadline)
		{
			Thread.sleep(10);
		}
		assertEquals(expected, service.hasProfile(player));
	}

	@Test
	public void testAllZeroClogIsHealthyNegativeAndKeepsAccountIdentity() throws Exception
	{
		AtomicInteger summaryRequests = new AtomicInteger();
		AtomicInteger clogRequests = new AtomicInteger();
		CountDownLatch clogStarted = new CountDownLatch(1);
		CountDownLatch releaseClog = new CountDownLatch(1);
		String summaryJson = "{\"accountType\":{\"id\":6,"
			+ "\"key\":\"unranked_group_ironman\",\"name\":\"Unranked Group Ironman\"},"
			+ "\"combatAchievements\":[]}";
		String zeroClogJson = "{\"obtained\":0,\"total\":1717,\"tabs\":["
			+ "{\"name\":\"Bosses\",\"pages\":["
			+ "{\"name\":\"Cerberus\",\"items\":["
			+ "{\"id\":1,\"name\":\"Primordial crystal\",\"quantity\":0}"
			+ "]}"
			+ "]}"
			+ "]}";
		OkHttpClient client = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				boolean clog = chain.request().url().encodedPath().endsWith("/collection-log");
				String body = clog ? zeroClogJson : summaryJson;
				(clog ? clogRequests : summaryRequests).incrementAndGet();
				if (clog)
				{
					clogStarted.countDown();
					try
					{
						if (!releaseClog.await(5, TimeUnit.SECONDS))
						{
							throw new IOException("Timed out waiting to release clog response");
						}
					}
					catch (InterruptedException e)
					{
						Thread.currentThread().interrupt();
						throw new IOException(e);
					}
				}
				return new Response.Builder()
					.request(chain.request())
					.protocol(Protocol.HTTP_1_1)
					.code(200)
					.message("OK")
					.body(ResponseBody.create(MediaType.parse("application/json"), body))
					.build();
			})
			.build();
		service = new RuneProfileService(client, new Gson(), null);

		try
		{
			service.lookup("BigWhiteCroc").join();
			assertEquals(AccountType.UNRANKED_GROUP_IRONMAN,
				service.getCachedAccountType("BigWhiteCroc"));

			ClogResult stale = new ClogResult("BigWhiteCroc", Collections.emptyMap(),
				Collections.emptyMap(), Collections.emptyMap(), null, null);
			clogCache().put("bigwhitecroc", stale);
			longCache("clogFetchTimes").put("bigwhitecroc", 0L);
			longCache("clogFailures").put("bigwhitecroc", 0L);
			recordBreakerFailure();
			recordBreakerFailure();
			assertTrue(hasRecentFailure());

			CompletableFuture<ClogResult> lookup = service.lookupClog("BigWhiteCroc");
			assertTrue(clogStarted.await(5, TimeUnit.SECONDS));
			releaseClog.countDown();
			assertNull(lookup.join());
			assertFalse(clogCache().containsKey("bigwhitecroc"));
			assertFalse(longCache("clogFetchTimes").containsKey("bigwhitecroc"));
			assertFalse(longCache("clogFailures").containsKey("bigwhitecroc"));
			assertNotNull(longCache("clogNotFoundTimes").get("bigwhitecroc"));
			assertEquals(AccountType.UNRANKED_GROUP_IRONMAN,
				service.getCachedAccountType("BigWhiteCroc"));

			// The negative cache serves the second lookup without another request.
			assertNull(service.lookupClog("BigWhiteCroc").join());
			assertEquals(1, summaryRequests.get());
			assertEquals(1, clogRequests.get());
			for (long failure : recentFailures())
			{
				assertEquals(0L, failure);
			}
		}
		finally
		{
			client.dispatcher().executorService().shutdownNow();
			client.connectionPool().evictAll();
		}
	}

