	@Test
	public void addedActivityPetsRemainVisibleButCountOnceOnEachComparisonSide()
	{
		ClogResult catalog = mappedCatalog();
		Skill[] skills = {Skill.MINING, Skill.FISHING, Skill.HUNTER, Skill.HUNTER};
		int[] pets = {23760, 25602, 28962, 13071};
		String[] categories = {"zalcano", "tempoross", "hunter_guild", "chompy_bird_hunting"};
		int[] petTotals = {2, 2, 5, 5};
		for (int i = 0; i < pets.length; i++)
		{
			Map<String, List<ClogResult.ClogItem>> obtained = new HashMap<>();
			obtained.put(categories[i], Arrays.asList(new ClogResult.ClogItem(pets[i], 3, null)));
			obtained.put("all_pets", Arrays.asList(new ClogResult.ClogItem(pets[i], 3, null)));
			ClogResult owner = new ClogResult("Owner", obtained, catalog.getCategoryItems(),
				Collections.emptyMap(), null, null);
			List<SkillClogSection> blue = SkillClogSection.forSkill(skills[i], owner, catalog, catalog);
			List<SkillClogSection> red = SkillClogSection.forSkill(skills[i], catalog, owner, catalog);
			assertEquals(petTotals[i], blue.get(0).itemIds().size());
			assertTrue(blue.get(0).itemIds().contains(pets[i]));
			assertEquals(Integer.valueOf(3), blue.get(0).primary().obtainedCounts().get(pets[i]));
			final String category = categories[i];
			SkillClogSection activity = blue.stream().filter(section -> section.isCategory(category))
				.findFirst().orElseThrow(AssertionError::new);
			assertTrue(activity.itemIds().contains(pets[i]));
			assertEquals(Integer.valueOf(3), activity.primary().obtainedCounts().get(pets[i]));
			assertEquals(1, SkillClogSection.combinedProgress(blue).obtained());
			assertEquals(0, SkillClogSection.combinedProgress(red).obtained());
			assertEquals(SkillClogSection.combinedProgress(blue).total(),
				SkillClogSection.combinedProgress(red).total());
		}
		assertTrue(SkillClogSection.forSkill(Skill.RANGED, null, null, catalog).stream()
			.anyMatch(section -> section.isCategory("chompy_bird_hunting")));
	}

	@Test
	public void everySkillTooltipMeasuresAndPaintsInSoloAndComparisonModes()
	{
		ClogResult catalog = mappedCatalog();
		for (Skill skill : SkillGridOrder.skills())
		{
			List<SkillClogSection> sections = SkillClogSection.forSkill(
				skill, null, null, catalog);
			SkillTooltip solo = new SkillTooltip();
			solo.setData(skill, null, false, sections, null);
			Dimension soloSize = solo.getPreferredSize();
			assertTrue(skill.getName() + " solo tooltip is too wide: " + soloSize,
				soloSize.width <= 300);
			assertTrue(skill.getName() + " solo tooltip is too tall: " + soloSize,
				soloSize.height <= 720);
			paint(solo);

			SkillTooltip leftSide = new SkillTooltip();
			leftSide.setData(skill, null, false, sections, null);
			SkillTooltip rightSide = new SkillTooltip();
			rightSide.setData(skill, null, false, sections, null);
			SideBySideTooltip comparison = new SideBySideTooltip(
				"Blue", leftSide, "Red", rightSide);
			Dimension compareSize = comparison.getPreferredSize();
			// Absolute caps: the doublewide card must fit a fixed-mode client.
			assertTrue(skill.getName() + " comparison tooltip is too wide: " + compareSize,
				compareSize.width <= 650);
			assertTrue(skill.getName() + " comparison tooltip is too tall: " + compareSize,
				compareSize.height <= 800);
			comparison.setSize(compareSize);
			comparison.doLayout();
			paint(comparison);
			assertMeasuredSectionHeightMatchesPaint(skill, sections);
		}
	}

	@Test
	public void aDenseSkillLogKeepsFullSizeSpritesAndScrollsInstead() throws Exception
	{
		SkillTooltip fits = card(10);
		SkillTooltip dense = card(90);
		int window = ClogTabTooltip.VISIBLE_ROWS * NativeTooltip.LINE_HEIGHT;
		// Ninety items at full size run far past the window; the card stops at it.
		assertTrue(dense.getPreferredSize().height - fits.getPreferredSize().height < window);
		paint(dense);
		paint(fits);
		java.lang.reflect.Field field = SkillTooltip.class.getDeclaredField("scroll");
		field.setAccessible(true);
		CardBody.Scroll scroll = (CardBody.Scroll) field.get(dense);
		wheel(dense, 2);
		assertEquals("two notches, two sprite rows", 2 * SkillClogSectionRenderer.CELL_SIZE, scroll.offset());
		wheel(dense, -9);
		assertEquals(0, scroll.offset());
		CardBody.Scroll still = (CardBody.Scroll) field.get(fits);
		wheel(fits, 3);
		assertEquals("a log that fits never moves", 0, still.offset());
	}

	private static SkillTooltip card(int items)
	{
		SkillTooltip card = new SkillTooltip();
		card.setData(Skill.SLAYER, null, false, SkillClogSection.forSkill(
			Skill.SLAYER, null, null, clog(ids(1, items), Collections.emptyList())), null);
		return card;
	}

	private static void wheel(SkillTooltip card, int notches)
	{
		for (java.awt.event.MouseWheelListener listener : card.getMouseWheelListeners())
		{
			listener.mouseWheelMoved(new java.awt.event.MouseWheelEvent(card, java.awt.event.MouseEvent.MOUSE_WHEEL,
				0, 0, 5, card.getHeight() - 10, 0, false, java.awt.event.MouseWheelEvent.WHEEL_UNIT_SCROLL, 3, notches));
		}
	}

