/** The real panel's summary cells hand their modals the right player's data. */
public class TraySummaryWiringTest
{
	private SkillDisplay skillDisplay = SkillDisplay.FIXED;
	private TooltipMode mode = TooltipMode.CLICK;
	private int previewsDismissed;
	private final KillClogConfig config = new KillClogConfig()
	{
		// These check the outline; the default is now Tint.
		@Override
		public HoverStyle hoverStyle()
		{
			return HoverStyle.OUTLINE;
		}

		@Override
		public TooltipMode tooltipMode()
		{
			return mode;
		}

		@Override
		public SkillDisplay skillDisplay()
		{
			return skillDisplay;
		}
	};
	private final List<JToolTip> pinned = new ArrayList<>();
	private final List<JComponent> pinnedOn = new ArrayList<>();
	private KillClogPanel panel;
	private Cells cells;
	private JLabel clues;

	@Before
	public void createPanel() throws Exception
	{
		ClogService catalog = mock(ClogService.class);
		when(catalog.warmCatalog()).thenReturn(new CompletableFuture<>());
		SpriteManager sprites = mock(SpriteManager.class);
		doAnswer(invocation ->
		{
			Consumer<BufferedImage> callback = invocation.getArgument(2);
			callback.accept(new BufferedImage(25, 25, BufferedImage.TYPE_INT_ARGB));
			return null;
		}).when(sprites).getSpriteAsync(anyInt(), anyInt(), ArgumentMatchers.<Consumer<BufferedImage>>any());
		ClientThread clientThread = mock(ClientThread.class);
		ItemManager items = mock(ItemManager.class);
		when(items.getImage(anyInt(), anyInt(), anyBoolean())).thenAnswer(invocation ->
			new AsyncBufferedImage(clientThread, 36, 32, BufferedImage.TYPE_INT_ARGB));
		edt(() ->
		{
			panel = new KillClogPanel(mock(HiscoreService.class), catalog,
				mock(RuneProfileService.class), mock(KillclogService.class),
				config, mock(ConfigManager.class), sprites,
				items, clientThread, new SkillIconManager(), mock(Client.class), mock(PlayerPortraits.class));
			cells = field(panel, "cells", Cells.class);
			clues = cells.getActivityLabels().get(HiscoreSkill.CLUE_SCROLL_ALL);
			// Nothing here is on a screen, so the pin is recorded instead of shown.
			TooltipController controller = new TooltipController(config)
			{
				@Override
				void pinTooltip(JComponent source, JPanel cell, JToolTip tip)
				{
					pinnedOn.add(source);
					pinned.add(tip);
				}

				@Override
				void dismissHoverPreview(MouseEvent event)
				{
					previewsDismissed++;
				}
			};
			set(cells, "tooltipController", controller);
			// The panel registers its cells with the one controller it has; the stand-in takes the clue cell over.
			controller.addCellHoverEffect((JPanel) clues.getParent(), clues);
		});
	}

	@After
	public void stopPanel() throws Exception
	{
		edt(panel::shutdown);
	}

	@Test
	public void aClosedTraysToggleSitsUnderTheInfoBarAndAnOpenOnesUnderTheTray() throws Exception
	{
		ActivitiesTray[] tray = new ActivitiesTray[1];
		JPanel[] homes = new JPanel[2];
		edt(() ->
		{
			tray[0] = field(panel, "activitiesTray", ActivitiesTray.class);
			homes[0] = field(panel, "trayToggle", JPanel.class);
			homes[1] = field(panel, "anchoredTop", JPanel.class);
			assertSame("open, under the tray", homes[0], tray[0].getSeparator().getParent());
			tray[0].toggle();
			assertSame("it moves up only once the tray has slid shut", homes[0], tray[0].getSeparator().getParent());
		});
		Thread.sleep(400);
		edt(() ->
		{
			assertSame(homes[1], tray[0].getSeparator().getParent());
			tray[0].toggle();
			assertSame(homes[0], tray[0].getSeparator().getParent());
		});
	}

	@Test
	public void theClueSummaryReadsEachLineFromItsOwnPage() throws Exception
	{
		edt(() ->
		{
			seedSelf(clog("Seeded", 1, true));
			ClueSummaryTooltip tip = (ClueSummaryTooltip) clues.createToolTip();
			int[] obtained = field(tip, "obtained", int[].class);
			int[] total = field(tip, "total", int[].class);
			// Only the hard page is in this log: line 4, and nothing on its neighbours.
			assertEquals(2, obtained[4]);
			assertEquals(PanelData.THIRD_AGE_ITEMS.length + 1, total[4]);
			assertEquals(-1, obtained[3]);
			assertEquals(-1, obtained[5]);
			// The Mimic's one slot is the 3rd age ring, which this player has.
			assertEquals(1, obtained[7]);
			assertEquals(1, total[7]);

			seedSelf(clog("Seeded", 1, false));
			tip = (ClueSummaryTooltip) clues.createToolTip();
			assertEquals(0, field(tip, "obtained", int[].class)[7]);
		});
	}

	@Test
	public void everyRareRowOpensItsOwnCollectionOnTheCluesCell() throws Exception
	{
		edt(() ->
		{
			seedSelf(clog("Seeded", 1, true));
			for (int row = 0; row < PanelData.RARE_NAMES.length; row++)
			{
				ClueSummaryTooltip tip = (ClueSummaryTooltip) clues.createToolTip();
				openRare(tip, row);
				assertEquals(row + 1, pinned.size());
				assertSame(clues, pinnedOn.get(row));
				assertEquals(PanelData.RARE_NAMES[row], ((TitleTooltip) pinned.get(row)).getTitle());
			}
			// A pinned summary was already closed by the press; there is no preview to take down.
			assertEquals(0, previewsDismissed);
		});
	}

	@Test
	public void aRareRowTakesTheHoverPreviewDownAndKeepsTheCellOutlined() throws Exception
	{
		edt(() ->
		{
			seedSelf(clog("Seeded", 1, true));
			JPanel cell = (JPanel) clues.getParent();
			assertTrue(!(cell.getBorder() instanceof MatteBorder));

			mode = TooltipMode.HOVER;
			openRare((ClueSummaryTooltip) clues.createToolTip(), 1);
			// The preview is a window of its own: it goes the way any press takes it down.
			assertEquals(1, previewsDismissed);
			assertEquals(1, pinned.size());
			// The summary's closing cleared the cell's outline; the new modal's cell has it back.
			assertTrue(cell.getBorder() instanceof MatteBorder);
		});
	}

	@Test
	public void aComparisonPairShowsEachPlayersOwnClueProgress() throws Exception
	{
		edt(() ->
		{
			seedSelf(clog("Seeded", 1, false));
			seedRival(clog("Rival", 3, true));
			List<ClueSummaryTooltip> cards = new ArrayList<>();
			JToolTip pair = clues.createToolTip();
			for (Component child : pair.getComponents())
			{
				if (child instanceof ClueSummaryTooltip)
				{
					cards.add((ClueSummaryTooltip) child);
				}
			}
			assertEquals(2, cards.size());
			ClueSummaryTooltip blue = cards.get(0);
			ClueSummaryTooltip red = cards.get(1);
			assertEquals(1, field(blue, "obtained", int[].class)[4]);
			assertEquals(4, field(red, "obtained", int[].class)[4]);
			assertEquals(0, field(blue, "obtained", int[].class)[7]);
			assertEquals(1, field(red, "obtained", int[].class)[7]);
			// 3rd Age is the first rare row, and the Mimic's ring is not part of that set.
			assertEquals(1, field(blue, "rareObtained", int[].class)[0]);
			assertEquals(3, field(red, "rareObtained", int[].class)[0]);

			// Either side's row opens the pair, not one player's modal.
			openRare(red, 0);
			assertTrue(pinned.get(0) instanceof SideBySideTooltip);
		});
	}

	@Test
	public void theCombatSummaryCarriesThePlayersPvpScores() throws Exception
	{
		edt(() ->
		{
			seedSelf(clog("Seeded", 1, false));
			PvmSummaryTooltip tip = (PvmSummaryTooltip) panel.combatCell().createToolTip();
			PvpSummaryRows rows = field(tip, "pvpRows", PvpSummaryRows.class);
			assertArrayEquals(new int[]{-1, 1_234_567, -1, 42, -1}, field(rows, "scores", int[].class));
		});
	}

	@Test
	public void theSkillGridSitsWhereTheSettingSaysItDoes() throws Exception
	{
		edt(() ->
		{
			JPanel fixed = field(panel, "fixedSkillsHost", JPanel.class);
			JPanel tray = field(panel, "traySkillsHost", JPanel.class);
			assertEquals(1, fixed.getComponentCount());
			assertEquals(0, tray.getComponentCount());

			skillDisplay = SkillDisplay.TRAY;
			panel.onConfigChanged("skillDisplay");
			assertEquals(0, fixed.getComponentCount());
			assertEquals(1, tray.getComponentCount());
		});
	}

	@Test
	public void theRareCollectionsLineUpWithTheirItemLists()
	{
		assertArrayEquals(new String[]{PanelData.CLOG_THIRD_AGE, PanelData.CLOG_GILDED,
			PanelData.RARE_HARD, PanelData.RARE_ELITE, PanelData.RARE_MASTER}, PanelData.RARE_KEYS);
		assertSame(PanelData.THIRD_AGE_ITEMS, PanelData.RARE_ITEMS[0]);
		assertSame(PanelData.GILDED_ITEMS, PanelData.RARE_ITEMS[1]);
		assertSame(PanelData.HARD_RARE_ITEMS, PanelData.RARE_ITEMS[2]);
		assertSame(PanelData.ELITE_RARE_ITEMS, PanelData.RARE_ITEMS[3]);
		assertSame(PanelData.MASTER_RARE_ITEMS, PanelData.RARE_ITEMS[4]);
		assertEquals(PanelData.RARE_KEYS.length, PanelData.RARE_NAMES.length);
		assertEquals(PanelData.RARE_KEYS.length, PanelData.RARE_ICON_ITEM_IDS.length);
		assertEquals(PanelData.RARE_KEYS.length, ClueSummaryTooltip.RARE_LABELS.length);
	}

	@SuppressWarnings("unchecked")
	private static void openRare(ClueSummaryTooltip tip, int row)
	{
		MouseEvent press = new MouseEvent(tip, MouseEvent.MOUSE_PRESSED, 0L, 0, 5, 5, 1, false, MouseEvent.BUTTON1);
		((ObjIntConsumer<MouseEvent>) field(tip, "onOpenRare", ObjIntConsumer.class)).accept(press, row);
	}

	private void seedSelf(ClogResult clog)
	{
		HiscoreResult hiscore = hiscore();
		field(panel, "lookupSession", LookupSession.class).adoptState(hiscore, clog, null, "Seeded");
		cells.renderHiscore(hiscore);
		cells.renderClog(clog);
		cells.rebuildPrimaryTooltips();
	}

	private void seedRival(ClogResult clog)
	{
		try
		{
			ComparisonController comparison = field(panel, "comparison", ComparisonController.class);
			Constructor<?> ctor = Class.forName("com.killclog.ComparisonController$ComparedPlayer")
				.getDeclaredConstructors()[0];
			ctor.setAccessible(true);
			set(comparison, "compared", ctor.newInstance(1, hiscore(), clog, null, "Rival", null));
			set(comparison, "comparisonMode", true);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private static HiscoreResult hiscore()
	{
		Map<String, Integer> activities = new HashMap<>();
		activities.put(HiscoreSkill.CLUE_SCROLL_HARD.getName(), 3);
		activities.put(HiscoreSkill.CLUE_SCROLL_ALL.getName(), 3);
		activities.put("Soul Wars Zeal", 1_234_567);
		activities.put("Bounty Hunter - Hunter", 42);
		return TestViews.hiscore(AccountType.REGULAR, new HashMap<>(), Collections.emptyMap(),
			activities, Collections.emptyMap(), Collections.emptyMap(), 0, 0L, 0, 0);
	}

	/** A hard clue page of the 3rd age set plus its ring; the player owns some pieces and maybe the ring. */
	private static ClogResult clog(String name, int thirdAge, boolean ring)
	{
		List<Integer> page = new ArrayList<>();
		List<ClogResult.ClogItem> owned = new ArrayList<>();
		for (int id : PanelData.THIRD_AGE_ITEMS)
		{
			if (id != PanelData.THIRD_AGE_RING_ITEM_ID)
			{
				page.add(id);
				if (owned.size() < thirdAge)
				{
					owned.add(new ClogResult.ClogItem(id, 1, null));
				}
			}
		}
		page.add(PanelData.THIRD_AGE_RING_ITEM_ID);
		if (ring)
		{
			owned.add(new ClogResult.ClogItem(PanelData.THIRD_AGE_RING_ITEM_ID, 1, null));
		}
		Map<String, List<ClogResult.ClogItem>> obtained = new HashMap<>();
		obtained.put("hard_treasure_trails", owned);
		Map<String, List<Integer>> categories = new HashMap<>();
		categories.put("hard_treasure_trails", page);
		return new ClogResult(name, obtained, categories, new HashMap<>(), null, null);
	}

	private static <T> T field(Object target, String name, Class<T> type)
	{
		try
		{
			return type.cast(declared(target, name).get(target));
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private static void set(Object target, String name, Object value)
	{
		try
		{
			declared(target, name).set(target, value);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private static Field declared(Object target, String name) throws NoSuchFieldException
	{
		for (Class<?> type = target.getClass(); type != null; type = type.getSuperclass())
		{
			try
			{
				Field field = type.getDeclaredField(name);
				field.setAccessible(true);
				return field;
			}
			catch (NoSuchFieldException e)
			{
				// Keep climbing: the field may belong to a parent.
			}
		}
		throw new NoSuchFieldException(name);
	}

	private static void edt(Runnable action) throws Exception
	{
		SwingUtilities.invokeAndWait(action);
	}
}

package com.killclog;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class UnrankedTooltipTest
{
	private static HiscoreResult result(int rank)
	{
		return RankSelectorTest.result(AccountType.IRONMAN, HiscoreTable.STANDARD, rank, 10000);
	}

	private static String rankText(TitleTooltip tip) throws Exception
	{
		return TestViews.headerLine(tip, "rank", "value");
	}

	private static TitleTooltip tooltip(TooltipData data, HiscoreResult result, boolean enabled)
	{
		TitleTooltip tip = new ImgTooltip(5);
		tip.setTitle("Alchemical Hydra");
		ClogHelper.configureRank(tip, data, result, enabled);
		return tip;
	}

	@Test
	public void knownMissingRankIsUnrankedButAbsentLeaderboardIsNot() throws Exception
	{
		HiscoreResult nativeResult = result(10);
		HiscoreResult unranked = nativeResult.withRanks(result(-1));
		TooltipData synced = TooltipData.builder().name("Alchemical Hydra")
			.obtainedCount(3).totalItems(11).rank(-1).kc(1420).build();
		assertTrue(unranked.isRankDataAvailable());
		assertEquals(123, unranked.getKc("Zulrah"));
		assertEquals("Unranked", rankText(tooltip(synced, unranked, true)));
		assertNull(rankText(tooltip(synced, nativeResult.withRanks(null), true)));
		assertFalse(nativeResult.withRanks(null).isRankDataAvailable());
		assertNull(rankText(tooltip(synced, null, true)));
		assertNull(rankText(tooltip(synced, unranked, false)));
		assertNull(rankText(tooltip(synced.toBuilder().rankTracked(false).build(), unranked, true)));
		assertNull(rankText(tooltip(null, unranked, true)));
		assertEquals("12,345", rankText(tooltip(synced.toBuilder().rank(12345).build(), result(12345), true)));
	}

	@Test
	public void unsyncedKeepsItsPlayerSignalAndCatalogOnlyRules() throws Exception
	{
		TooltipData knownKills = TooltipData.builder().rank(-1).statLabel("Kills: ").statValue(42).build();
		assertEquals("Unranked", rankText(tooltip(knownKills, result(-1), true)));
		assertNull(rankText(tooltip(knownKills, result(1).withRanks(null), true)));
		assertNull(rankText(tooltip(knownKills.toBuilder().statValue(-1).build(), result(-1), true)));
	}

	@Test
	public void skillsDistinguishUnrankedFromLoadingAndDormant()
	{
		assertEquals("Unranked", SkillTooltip.Stats.from(Skill.ATTACK, result(-1), false).rankText());
		assertEquals("--", SkillTooltip.Stats.from(Skill.ATTACK, result(10).withRanks(null), false).rankText());
		assertEquals("--", SkillTooltip.Stats.from(Skill.ATTACK, null, false).rankText());
		assertEquals("12,345", SkillTooltip.Stats.from(Skill.ATTACK, result(12345), false).rankText());
	}

	@Test
	public void clueSummaryDoesNotCallPendingRanksUnranked() throws Exception
	{
		ClueSummaryTooltip tip = new ClueSummaryTooltip();
		tip.setData(result(10).withRanks(null), true);
		assertNull(rankText(tip));
		tip = new ClueSummaryTooltip();
		tip.setData(result(-1), true);
		assertEquals("Unranked", rankText(tip));
		tip = new ClueSummaryTooltip();
		tip.setData(result(-1), false);
		assertNull(rankText(tip));
	}

	@Test
	public void comparisonRendersTheSameUnrankedLineAsSolo() throws Exception
	{
		TooltipData data = TooltipData.builder().obtainedCount(3).totalItems(11).build();
		TitleTooltip blue = tooltip(data, result(-1), true);
		TitleTooltip red = tooltip(data.toBuilder().rank(12345).build(), result(12345), true);
		blue.setInfoLine("KC: ", "1420", java.awt.Color.WHITE);
		red.setInfoLine("KC: ", "1420", java.awt.Color.WHITE);
		SideBySideTooltip pair = new SideBySideTooltip("Unranked", blue, "Ranked", red);
		assertEquals("Unranked", rankText(blue));
		assertEquals("12,345", rankText(red));
		Dimension size = pair.getPreferredSize();
		assertTrue(size.width <= 765);
		pair.setSize(size);
		BufferedImage preview = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = preview.createGraphics();
		pair.paint(graphics);
		graphics.dispose();
		File output = new File("build/reports/unranked-tooltip-preview.png");
		assertTrue(output.getParentFile().isDirectory() || output.getParentFile().mkdirs());
		assertTrue(ImageIO.write(preview, "png", output));
	}
}

package com.killclog;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class UnsyncedClogCatalogTest
{
	@Test
	public void testCatalogCopyIsCoherentAndCachedPerGeneration()
	{
		// The catalog must serve categories and item names from one parse:
		// a reparse between two reads once paired pieces of two generations.
		ClogIndex index = new ClogIndex();
		index.publishForTest(
			Collections.singletonMap("vorkath", java.util.Arrays.asList(1, 2)),
			twoNames());

		UnsyncedClogCatalog catalog = new UnsyncedClogCatalog(null);
		catalog.setClogIndex(index);

		ClogResult first = catalog.result();
		assertNotNull(first);
		assertTrue(first.getCategoryItems().containsKey("vorkath"));
		assertEquals(2, first.getCategoryItems().get("vorkath").size());
		assertTrue(first.getObtainedItems().get("vorkath").isEmpty());

		// Same generation serves the cached build.
		assertSame(first, catalog.result());

		// A reparse moves the generation; the catalog rebuilds coherently.
		index.publishForTest(
			Collections.singletonMap("zulrah", Collections.singletonList(3)),
			Collections.singletonMap(3, "Tanzanite fang"));
		ClogResult rebuilt = catalog.result();
		assertNotNull(rebuilt);
		assertNotSame(first, rebuilt);
		assertTrue(rebuilt.getCategoryItems().containsKey("zulrah"));
		assertFalse(rebuilt.getCategoryItems().containsKey("vorkath"));
	}

	@Test
	public void testAtomicCopyCarriesBothHalves()
	{
		ClogIndex index = new ClogIndex();
		Map<String, List<Integer>> cats = new HashMap<>();
		cats.put("vorkath", java.util.Arrays.asList(1, 2));
		index.publishForTest(cats, twoNames());

		ClogIndex.CatalogCopy copy = index.copyCatalog();
		assertNotNull(copy);
		assertEquals(2, copy.categoryItems.get("vorkath").size());
		assertEquals("Dragonbone necklace", copy.itemNames.get(1));
		assertSame(copy.generation, index.generation());

		index.clear();
		assertNull(index.generation());
		assertNull(index.copyCatalog());
	}

	private static Map<Integer, String> twoNames()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(1, "Dragonbone necklace");
		names.put(2, "Skeletal visage");
		return names;
	}
}

package com.killclog;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Virtual level display math for the skill summaries. When Kill Clog's setting
 * is on, levels come from xp via Experience.getLevelForXp (cap 126).
 */
public class VirtualLevelsTest
{
	@Test
	public void killClogVirtualLevelsDefaultOn()
	{
		KillClogConfig config = new KillClogConfig()
		{
		};
		assertTrue(config.virtualLevels());
	}

	@Test
	public void offMeansHiscoreLevelUntouched()
	{
		assertEquals(99, ClogHelper.displayLevel(99, 200_000_000L, false));
	}

	@Test
	public void exactly13mXpStaysNinetyNine()
	{
		// 13,034,431 is the level 99 threshold; virtual only grows past it.
		assertEquals(99, ClogHelper.displayLevel(99, 13_034_431L, true));
	}

	@Test
	public void maxXpIsVirtual126()
	{
		assertEquals(126, ClogHelper.displayLevel(99, 200_000_000L, true));
	}

	@Test
	public void midVirtualRangeComputesFromXp()
	{
		// 14,391,160 xp is the level 100 threshold.
		assertEquals(100, ClogHelper.displayLevel(99, 14_391_160L, true));
	}

	@Test
	public void unrankedSkillKeepsHiscoreValue()
	{
		// No xp on record: never invent a virtual level.
		assertEquals(-1, ClogHelper.displayLevel(-1, -1L, true));
		assertEquals(85, ClogHelper.displayLevel(85, 0L, true));
	}

	@Test
	public void belowNinetyNineIsIdenticalEitherWay()
	{
		// getLevelForXp agrees with the hiscore level below 99, so the
		// toggle changes nothing for unmaxed skills.
		long xp70 = 737_627L;
		assertEquals(ClogHelper.displayLevel(70, xp70, false),
			ClogHelper.displayLevel(70, xp70, true));
	}

	@Test
	public void virtualTotalSumsFromXp()
	{
		// All 24 skills at 200m xp: 24 x 126 = 3024 virtual, 2376 real.
		HiscoreResult result = allMaxed();
		assertEquals(2376, ClogHelper.displayTotalLevel(result, false));
		assertEquals(3024, ClogHelper.displayTotalLevel(result, true));
	}

	@Test
	public void virtualTotalNeverDropsBelowRealTotal()
	{
		// A result whose per-skill maps are empty (hiscores hid the skills)
		// still shows at least the real total the overall row carried.
		HiscoreResult result = TestViews.hiscore(AccountType.REGULAR, HiscoreTable.STANDARD,
			java.util.Map.of(), java.util.Map.of(), java.util.Map.of(), java.util.Map.of(),
			java.util.Map.of(), java.util.Map.of(), java.util.Map.of(),
			1500, 10_000_000L, 100, 1);
		assertEquals(1500, ClogHelper.displayTotalLevel(result, true));
	}

	private static HiscoreResult allMaxed()
	{
		java.util.Map<String, Integer> levels = new java.util.LinkedHashMap<>();
		java.util.Map<String, Long> xps = new java.util.LinkedHashMap<>();
		for (net.runelite.api.Skill s : net.runelite.api.Skill.values())
		{
			levels.put(s.getName().toLowerCase(), 99);
			xps.put(s.getName().toLowerCase(), 200_000_000L);
		}
		return TestViews.hiscore(AccountType.REGULAR, HiscoreTable.STANDARD,
			java.util.Map.of(), java.util.Map.of(), java.util.Map.of(), java.util.Map.of(),
			levels, java.util.Map.of(), xps,
			2376, 4_800_000_000L, 126, 1);
	}
}

package com.killclog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;

public class WorldSessionTest
{
	private final AtomicReference<String> mode = new AtomicReference<>();
	private final AtomicReference<String> active = new AtomicReference<>();
	private final LocalClogCache main = mock(LocalClogCache.class);
	private final List<String> openedFor = new ArrayList<>();
	private final List<LocalClogCache> wired = new ArrayList<>();
	private final WorldSession session = new WorldSession(mode::get, active::get, () -> main, game ->
	{
		openedFor.add(game);
		return mock(LocalClogCache.class);
	}, wired::add);
	private final List<String> shown = new ArrayList<>();
	private final WorldSession.Shown panel = (league, log, running) ->
		shown.add(league + " " + (log != null ? "log" : "-") + " " + running);

	@Test
	public void aMainWorldSettlesOnItsTenthTickAlone()
	{
		mode.set(GameMode.MAIN);
		for (int i = 1; i < WorldSession.SETTLED_TICKS; i++)
		{
			assertFalse(session.tick());
		}
		assertTrue(session.tick());
		assertTrue(session.mainSettled());
		assertFalse("only the tick it settles on", session.tick());
	}

	@Test
	public void anUnknownWorldOrAnUnsettleStartsTheCountOver()
	{
		mode.set(GameMode.MAIN);
		for (int i = 0; i < 5; i++)
		{
			session.tick();
		}
		mode.set(null);
		assertFalse(session.tick());
		assertFalse(session.settled());

		mode.set(GameMode.MAIN);
		for (int i = 0; i < 5; i++)
		{
			session.tick();
		}
		session.unsettle();
		for (int i = 1; i < WorldSession.SETTLED_TICKS; i++)
		{
			assertFalse(session.tick());
		}
		assertTrue(session.tick());
	}

	@Test
	public void aLeagueWorldSettlesWithoutTheMainGamesSignal()
	{
		mode.set("leagues-vi");
		for (int i = 0; i < WorldSession.SETTLED_TICKS + 2; i++)
		{
			assertFalse(session.tick());
		}
		assertTrue(session.settled());
		assertFalse(session.mainSettled());
	}

	@Test
	public void aLeaguesStoreOpensOnceAndClosesWhenAnotherRuns()
	{
		assertSame(main, session.cacheFor(GameMode.MAIN));
		LocalClogCache first = session.cacheFor("leagues-v");
		assertSame(first, session.cacheFor("leagues-v"));
		assertEquals(Collections.singletonList("leagues-v"), openedFor);
		assertEquals(Collections.singletonList(first), wired);

		LocalClogCache second = session.cacheFor("leagues-vi");
		verify(first).close();
		verify(second, never()).close();
		assertEquals(Arrays.asList(first, second), wired);

		session.close();
		verify(second).close();
		// Forgotten once closed: the same League opens a fresh store.
		assertNotSame(second, session.cacheFor("leagues-vi"));
	}

	@Test
	public void capturesGoToTheWorldsOwnGame()
	{
		assertNull(session.captureCache());
		mode.set(GameMode.MAIN);
		assertSame(main, session.captureCache());
		mode.set("leagues-vi");
		assertSame(session.cacheFor("leagues-vi"), session.captureCache());
	}

	@Test
	public void thePanelHearsOnlyOfAChangeAndShowAgainForcesTheNext()
	{
		mode.set(GameMode.MAIN);
		session.follow(panel);
		session.follow(panel);
		assertEquals(Collections.singletonList("null - null"), shown);

		session.showAgain();
		session.follow(panel);
		assertEquals(2, shown.size());

		mode.set("leagues-vi");
		active.set("leagues-vi");
		session.follow(panel);
		assertEquals("leagues-vi log leagues-vi", shown.get(2));
	}

	@Test
	public void aLogoutAfterALeagueStartsHandsBackTheMainGame()
	{
		mode.set(GameMode.MAIN);
		session.follow(panel);
		// The League starts while the player stands on a main world: the panel hears of it.
		active.set("leagues-vi");
		session.follow(panel);
		mode.set(null);
		session.follow(panel);
		assertEquals(Arrays.asList("null - null", "null - leagues-vi", "null - leagues-vi"), shown);
	}
}
